public class SpanishStemmer extends SnowballProgram {
    private static final String[] suffixes = { "ando", "iendo", "ar", "er", "ir", "amente", "amente", "ción", "sión" };
    private static final String[] pronouns = { "me", "te", "se", "nos", "os", "le", "les" };

    private String current;

    public SpanishStemmer() {
        current = "";
    }

    public boolean stem() {
        current = getCurrent();
        if (current.length() <= 2) {
            return false;
        }
        processSuffixes();
        processPronouns();
        return true;
    }

    private void processSuffixes() {
        for (String suffix : suffixes) {
            if (current.endsWith(suffix)) {
                current = current.substring(0, current.length() - suffix.length());
                break;
            }
        }
    }

    private void processPronouns() {
        for (String pronoun : pronouns) {
            if (current.endsWith(pronoun)) {
                current = current.substring(0, current.length() - pronoun.length());
                break;
            }
        }
    }

    public String getCurrent() {
        return current;
    }

    public void setCurrent(String value) {
        current = value;
    }
}

