class DifferenceEngineTest {

    private DifferenceEngine differenceEngine;
    private AttributeType attributeType1;
    private AttributeType attributeType2;
    private ObjectClass objectClass1;
    private ObjectClass objectClass2;

    @BeforeEach
    void setUp() {
        differenceEngine = new DifferenceEngine();
        attributeType1 = new AttributeType("name", "String", true, false);
        attributeType2 = new AttributeType("name", "String", false, false);
        objectClass1 = new ObjectClass("Person", true);
        objectClass2 = new ObjectClass("Person", false);
    }

    @Test
    void testAddAlias() {
        attributeType1.addAlias("nickname");
        Difference difference = differenceEngine.compare(attributeType1, attributeType2);
        assertTrue(difference.hasChanges());
        assertEquals(DifferenceType.ADD_ALIAS, difference.getType());
    }

    @Test
    void testModifyDescription() {
        attributeType1.setDescription("A person's name");
        attributeType2.setDescription("A person's full name");
        Difference difference = differenceEngine.compare(attributeType1, attributeType2);
        assertTrue(difference.hasChanges());
        assertEquals(DifferenceType.MODIFY_DESCRIPTION, difference.getType());
    }

    @Test
    void testChangeEqualityOID() {
        attributeType1.setEqualityOID("1.2.840.113556.1.4.7000.1");
        attributeType2.setEqualityOID("1.2.840.113556.1.4.7000.2");
        Difference difference = differenceEngine.compare(attributeType1, attributeType2);
        assertTrue(difference.hasChanges());
        assertEquals(DifferenceType.CHANGE_EQUALITY_OID, difference.getType());
    }

    @Test
    void testAddMandatoryAttribute() {
        objectClass1.addMandatoryAttribute(attributeType1);
        objectClass2.addMandatoryAttribute(attributeType2);
        Difference difference = differenceEngine.compare(objectClass1, objectClass2);
        assertTrue(difference.hasChanges());
        assertEquals(DifferenceType.ADD_MANDATORY_ATTRIBUTE, difference.getType());
    }

    @Test
    void testRemoveOptionalAttribute() {
        objectClass1.addOptionalAttribute(attributeType1);
        objectClass2.removeOptionalAttribute(attributeType1);
        Difference difference = differenceEngine.compare(objectClass1, objectClass2);
        assertTrue(difference.hasChanges());
        assertEquals(DifferenceType.REMOVE_OPTIONAL_ATTRIBUTE, difference.getType());
    }

    @Test
    void testChangeOrdering() {
        attributeType1.setOrdering(true);
        attributeType2.setOrdering(false);
        Difference difference = differenceEngine.compare(attributeType1, attributeType2);
        assertTrue(difference.hasChanges());
        assertEquals(DifferenceType.CHANGE_ORDERING, difference.getType());
    }

    @Test
    void testChangeSyntax() {
        attributeType1.setSyntax("1.3.6.1.4.1.1466.115.121.1.15");
        attributeType2.setSyntax("1.3.6.1.4.1.1466.115.121.1.36");
        Difference difference = differenceEngine.compare(attributeType1, attributeType2);
        assertTrue(difference.hasChanges());
        assertEquals(DifferenceType.CHANGE_SYNTAX, difference.getType());
    }

    @Test
    void testNoDifference() {
        Difference difference = differenceEngine.compare(attributeType1, attributeType1);
        assertFalse(difference.hasChanges());
    }
}

