public class DupsCursor extends AbstractCursor {
    private static final Logger logger = Logger.getLogger(DupsCursor.class.getName());
    private DupsContainerCursor containerCursor;
    private boolean isClosed = false;

    public DupsCursor(JdbmTable table) {
        super(table);
        this.containerCursor = new DupsContainerCursor(table);
    }

    public boolean moveToKey(Object key) {
        if (isClosed) {
            logger.warning("Attempted to move to key on a closed cursor.");
            return false;
        }
        logger.info("Moving to key: " + key);
        boolean result = containerCursor.moveToKey(key);
        if (result) {
            logger.info("Successfully moved to key: " + key);
        } else {
            logger.warning("Failed to move to key: " + key);
        }
        return result;
    }

    public boolean moveToValue(Object value) {
        if (isClosed) {
            logger.warning("Attempted to move to value on a closed cursor.");
            return false;
        }
        logger.info("Moving to value: " + value);
        boolean result = containerCursor.moveToValue(value);
        if (result) {
            logger.info("Successfully moved to value: " + value);
        } else {
            logger.warning("Failed to move to value: " + value);
        }
        return result;
    }

    public boolean hasNext() {
        if (isClosed) {
            logger.warning("Checked hasNext on a closed cursor.");
            return false;
        }
        boolean result = containerCursor.hasNext();
        logger.info("hasNext: " + result);
        return result;
    }

    public Tuple current() {
        if (isClosed) {
            logger.warning("Attempted to access current on a closed cursor.");
            return null;
        }
        Tuple currentTuple = containerCursor.current();
        logger.info("Current tuple: " + currentTuple);
        return currentTuple;
    }

    public void close() {
        if (!isClosed) {
            logger.info("Closing DupsCursor.");
            containerCursor.close();
            isClosed = true;
        } else {
            logger.warning("Attempted to close an already closed cursor.");
        }
    }
}

