        this.recordingDao = recordingDao;
        this.webSocketNotifier = webSocketNotifier;
    }

    public void startRecording(String clientId, String streamType) {
        Recording recording = new Recording();
        recording.setClientId(clientId);
        recording.setStreamType(streamType);
        recording.setStartTime(System.currentTimeMillis());
        activeRecordings.put(clientId, recording);
        recordingDao.save(recording);
        webSocketNotifier.notifyStart(recording);
    }

    public void stopRecording(String clientId) {
        Recording recording = activeRecordings.get(clientId);
        if (recording != null) {
            recording.setEndTime(System.currentTimeMillis());
            activeRecordings.remove(clientId);
            recordingDao.update(recording);
            initiateConversion(recording);
            webSocketNotifier.notifyStop(recording);
        }
