public class EJBQLConditionTranslator extends EJBQLBaseVisitor<String> {
    private EJBQLTranslationContext context;

    public EJBQLConditionTranslator(EJBQLTranslationContext context) {
        this.context = context;
    }

    @Override
    public String visitAggregateFunction(EJBQLParser.AggregateFunctionContext ctx) {
        String functionName = ctx.getChild(0).getText();
        String operand = visit(ctx.operand());
        context.append(functionName + "(" + operand + ")");
        return context.getQuery();
    }

    @Override
    public String visitConditionalOperator(EJBQLParser.ConditionalOperatorContext ctx) {
        String left = visit(ctx.left);
        String right = visit(ctx.right);
        String operator = ctx.operator.getText();
        context.append(left + " " + operator + " " + right);
        return context.getQuery();
    }

    @Override
    public String visitComparisonOperator(EJBQLParser.ComparisonOperatorContext ctx) {
        String left = visit(ctx.left);
        String right = visit(ctx.right);
        String operator = ctx.operator.getText();
        context.append(left + " " + operator + " " + right);
        return context.getQuery();
    }

    @Override
    public String visitSubquery(EJBQLParser.SubqueryContext ctx) {
        String subquery = visit(ctx.query());
        context.append("(" + subquery + ")");
        return context.getQuery();
    }

    @Override
    public String visitMultiColumnOperand(EJBQLParser.MultiColumnOperandContext ctx) {
        StringBuilder columns = new StringBuilder();
        for (EJBQLParser.ColumnContext column : ctx.columns) {
            if (columns.length() > 0) {
                columns.append(", ");
            }
            columns.append(visit(column));
        }
        context.append(columns.toString());
        return context.getQuery();
    }

    @Override
    public String visitInputParameter(EJBQLParser.InputParameterContext ctx) {
        String parameter = ctx.getText();
        context.append(":" + parameter);
        return context.getQuery();
    }

    @Override
    public String visitLiteral(EJBQLParser.LiteralContext ctx) {
        String literal = ctx.getText();
        context.append(literal);
        return context.getQuery();
    }

    @Override
    public String visitFunction(EJBQLParser.FunctionContext ctx) {
        String functionName = ctx.getChild(0).getText();
        String argument = visit(ctx.argument());
        context.append(functionName + "(" + argument + ")");
        return context.getQuery();
    }

    @Override
    public String visitCurrentDate(EJBQLParser.CurrentDateContext ctx) {
        context.append("CURRENT_DATE");
        return context.getQuery();
    }

    @Override
    public String visitAbsFunction(EJBQLParser.AbsFunctionContext ctx) {
        String operand = visit(ctx.operand());
        context.append("ABS(" + operand + ")");
        return context.getQuery();
    }

    @Override
    public String visitTrimFunction(EJBQLParser.TrimFunctionContext ctx) {
        String operand = visit(ctx.operand());
        context.append("TRIM(" + operand + ")");
        return context.getQuery();
    }
}

public abstract class ParserBase {
    protected String baseUri;
    protected Map<String, String> prefixes;
    protected int blankNodeCounter;

    public ParserBase() {
        this.prefixes = new HashMap<>();
        this.blankNodeCounter = 0;
    }

    public void setBaseUri(String baseUri) {
        this.baseUri = baseUri;
    }

    public String getBaseUri() {
        return baseUri;
    }

    public void addPrefix(String prefix, String uri) {
        prefixes.put(prefix, uri);
    }

    public String resolveIri(String iri) throws IllegalArgumentException {
        if (iri.startsWith("<") && iri.endsWith(">")) {
            return iri.substring(1, iri.length() - 1);
        } else if (iri.contains(":")) {
            String[] parts = iri.split(":", 2);
            String prefix = parts[0];
            String localName = parts[1];
            String uri = prefixes.get(prefix);
            if (uri == null) {
                throw new IllegalArgumentException("Undefined prefix: " + prefix);
            }
            return uri + localName;
        } else {
            return baseUri + iri;
        }
    }

    public String createBlankNode() {
        return "_:b" + (blankNodeCounter++);
    }

    public String createBooleanLiteral(boolean value) {
        return value ? "true" : "false";
    }

    public String createIntegerLiteral(int value) {
        return Integer.toString(value);
    }

    public String createDoubleLiteral(double value) {
        return Double.toString(value);
    }

    public String createDecimalLiteral(String value) {
        return value + "^^<http://www.w3.org/2001/XMLSchema#decimal>";
    }

    protected String handleEscapeSequences(String input) {
        return input.replace("\\n", "\n")
                    .replace("\\t", "\t")
                    .replace("\\\"", "\"")
                    .replace("\\\\", "\\");
    }

    protected void handleError(String message) throws ParsingException {
        throw new ParsingException(message);
    }

    public static class ParsingException extends Exception {
        public ParsingException(String message) {
            super(message);
        }
    }
}

