public class Base64 {
    private static final String STANDARD = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    private static final String URL_SAFE = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    private static final int CHUNK_SIZE = 76;

    public static String encode(byte[] data, boolean urlSafe, boolean chunked) {
        String base64String = urlSafe ? Base64.getUrlEncoder().encodeToString(data) : Base64.getEncoder().encodeToString(data);
        if (chunked) {
            return chunkInLines(base64String);
        }
        return base64String;
    }

    public static byte[] decode(String base64String) {
        return Base64.getDecoder().decode(base64String);
    }

    public static boolean isValidBase64(byte[] data) {
        try {
            Base64.getDecoder().decode(data);
            return true;
        } catch (IllegalArgumentException e) {
            return false;
        }
    }

    public static boolean isValidBase64(String base64String) {
        return isValidBase64(base64String.getBytes(StandardCharsets.UTF_8));
    }

    private static String chunkInLines(String base64String) {
        StringBuilder chunkedString = new StringBuilder();
        for (int i = 0; i < base64String.length(); i += CHUNK_SIZE) {
            int end = Math.min(i + CHUNK_SIZE, base64String.length());
            chunkedString.append(base64String, i, end).append(System.lineSeparator());
        }
        return chunkedString.toString().trim();
    }

    public static String encodeInt(int value) {
        return encode(Integer.toString(value).getBytes(StandardCharsets.UTF_8), false, false);
    }

    public static int decodeInt(String base64String) {
        String decodedString = new String(decode(base64String), StandardCharsets.UTF_8);
        return Integer.parseInt(decodedString);
    }
}

