class FieldRotationDfpTest {

    @Test
    public void testIdentityRotation() {
        FieldRotation rotation = new FieldRotation(1.0, 0.0, 0.0, 0.0);
        DfpVector vector = new DfpVector(1.0, 0.0, 0.0);
        DfpVector result = rotation.apply(vector);
        assertEquals(vector, result);
    }

    @Test
    public void testAxisAngleRotation() {
        FieldRotation rotation = new FieldRotation(Math.PI / 2, 0.0, 0.0, 1.0);
        DfpVector vector = new DfpVector(1.0, 0.0, 0.0);
        DfpVector expected = new DfpVector(0.0, 1.0, 0.0);
        DfpVector result = rotation.apply(vector);
        assertEquals(expected, result);
    }

    @Test
    public void testInversion() {
        FieldRotation rotation = new FieldRotation(Math.PI / 2, 0.0, 0.0, 1.0);
        FieldRotation inverted = rotation.invert();
        DfpVector vector = new DfpVector(1.0, 0.0, 0.0);
        DfpVector result = inverted.apply(rotation.apply(vector));
        assertEquals(vector, result);
    }

    @Test
    public void testComposition() {
        FieldRotation rotation1 = new FieldRotation(Math.PI / 2, 0.0, 0.0, 1.0);
        FieldRotation rotation2 = new FieldRotation(Math.PI / 2, 0.0, 1.0, 0.0);
        FieldRotation composed = rotation1.compose(rotation2);
        DfpVector vector = new DfpVector(1.0, 0.0, 0.0);
        DfpVector expected = composed.apply(vector);
        DfpVector result = rotation2.apply(rotation1.apply(vector));
        assertEquals(expected, result);
    }

    @Test
    public void testSingularityHandling() {
        FieldRotation rotation = new FieldRotation(Math.PI, 0.0, 1.0, 0.0);
        DfpVector vector = new DfpVector(1.0, 0.0, 0.0);
        DfpVector result = rotation.apply(vector);
        assertNotEquals(vector, result);
    }
}

