public class BeanProcessor implements Processor {
    private final Object bean;
    private Method method;
    private boolean multiParameterArray;

    public BeanProcessor(Object bean) {
        this.bean = bean;
    }

    public BeanProcessor(Object bean, Method method) {
        this.bean = bean;
        this.method = method;
    }

    public BeanProcessor(Object bean, Method method, boolean multiParameterArray) {
        this.bean = bean;
        this.method = method;
        this.multiParameterArray = multiParameterArray;
    }

    @Override
    public void process(Exchange exchange) throws Exception {
        Object[] parameters = prepareParameters(exchange);
        try {
            Object result = invokeMethod(parameters);
            exchange.getIn().setBody(result);
        } catch (Exception e) {
            handleError(exchange, e);
        }
    }

    private Object[] prepareParameters(Exchange exchange) {
        // Logic to prepare parameters from exchange
        return new Object[0]; // Placeholder
    }

    private Object invokeMethod(Object[] parameters) throws Exception {
        if (multiParameterArray) {
            return method.invoke(bean, new Object[]{parameters});
        } else {
            return method.invoke(bean, parameters);
        }
    }

    private void handleError(Exchange exchange, Exception e) {
        exchange.setException(e);
    }

    public void setMethod(Method method) {
        this.method = method;
    }

    public void setMultiParameterArray(boolean multiParameterArray) {
        this.multiParameterArray = multiParameterArray;
    }

    public void start() {
        // Logic to start processor
    }

    public void stop() {
        // Logic to stop processor
    }
}

class Base64InputStreamTest {

    @Test
    void testEncoding() throws IOException {
        String original = "Hello, World!";
        byte[] encoded = Base64.getEncoder().encode(original.getBytes());
        assertArrayEquals(encoded, Base64.getEncoder().encode(original.getBytes()));
    }

    @Test
    void testDecoding() throws IOException {
        String original = "Hello, World!";
        byte[] encoded = Base64.getEncoder().encode(original.getBytes());
        byte[] decoded = Base64.getDecoder().decode(encoded);
        assertEquals(original, new String(decoded));
    }

    @Test
    void testRead() throws IOException {
        String original = "Hello, World!";
        InputStream inputStream = new ByteArrayInputStream(Base64.getEncoder().encode(original.getBytes()));
        Base64InputStream base64InputStream = new Base64InputStream(inputStream);

        byte[] buffer = new byte[1024];
        int bytesRead = base64InputStream.read(buffer);

        assertNotEquals(-1, bytesRead);
        assertEquals(original, new String(buffer, 0, bytesRead));
    }

    @Test
    void testSkip() throws IOException {
        String original = "Hello, World!";
        InputStream inputStream = new ByteArrayInputStream(Base64.getEncoder().encode(original.getBytes()));
        Base64InputStream base64InputStream = new Base64InputStream(inputStream);

        long skipped = base64InputStream.skip(5);
        assertEquals(5, skipped);

        byte[] buffer = new byte[1024];
        int bytesRead = base64InputStream.read(buffer);
        assertNotEquals(-1, bytesRead);
        assertEquals(original.substring(5), new String(buffer, 0, bytesRead));
    }

    @Test
    void testAvailable() throws IOException {
        String original = "Hello, World!";
        InputStream inputStream = new ByteArrayInputStream(Base64.getEncoder().encode(original.getBytes()));
        Base64InputStream base64InputStream = new Base64InputStream(inputStream);

        int availableBytes = base64InputStream.available();
        assertTrue(availableBytes > 0);
    }

    @Test
    void testEdgeCaseEmptyInput() throws IOException {
        InputStream inputStream = new ByteArrayInputStream(new byte[0]);
        Base64InputStream base64InputStream = new Base64InputStream(inputStream);

        assertEquals(-1, base64InputStream.read());
    }

    @Test
    void testErrorHandling() {
        assertThrows(IllegalArgumentException.class, () -> {
            new Base64InputStream(null);
        });
    }
}

