        this.schemaDao = schemaDao;
        this.schemaBinder = schemaBinder;
    }

    public void createSchema(SchemaDto schemaDto) {
        if (!isAuthorized()) {
            throw new UnauthorizedException("User not authorized to create schema");
        }
        Schema schema = schemaBinder.toEntity(schemaDto);
        schemaDao.save(schema);
    }

    public SchemaDto readSchema(Long id) {
        if (!isAuthorized()) {
            throw new UnauthorizedException("User not authorized to read schema");
        }
        Schema schema = schemaDao.findById(id)
                .orElseThrow(() -> new SchemaNotFoundException("Schema not found"));
        return schemaBinder.toDto(schema);
    }

    public void updateSchema(Long id, SchemaDto schemaDto) {
        if (!isAuthorized()) {
            throw new UnauthorizedException("User not authorized to update schema");
        }
        Schema schema = schemaDao.findById(id)
                .orElseThrow(() -> new SchemaNotFoundException("Schema not found"));
        schemaBinder.updateEntity(schema, schemaDto);
        schemaDao.save(schema);
    }

    public void deleteSchema(Long id) {
        if (!isAuthorized()) {
            throw new UnauthorizedException("User not authorized to delete schema");
        }
        if (!schemaDao.existsById(id)) {
            throw new SchemaNotFoundException("Schema not found");
        }
        schemaDao.deleteById(id);
    }

    public List<SchemaDto> listSchemas() {
        if (!isAuthorized()) {
            throw new UnauthorizedException("User not authorized to list schemas");
        }
        List<Schema> schemas = schemaDao.findAll();
