class MapTaskToNetworkFunctionTest {

    @Test
    public void testEmptyTask() {
        MapTask task = new MapTask();
        Network network = MapTaskToNetworkFunction.convert(task);
        assertTrue(network.isDirected());
        assertFalse(network.hasSelfLoops());
        assertTrue(network.getEdges().isEmpty());
        assertTrue(network.getNodes().isEmpty());
    }

    @Test
    public void testReadWriteInstructions() {
        MapTask task = new MapTask();
        task.addReadInstruction("input.txt");
        task.addWriteInstruction("output.txt");
        Network network = MapTaskToNetworkFunction.convert(task);
        assertEquals(2, network.getNodes().size());
        assertTrue(network.getEdges().stream().anyMatch(edge -> edge.getSource().equals("input.txt") && edge.getTarget().equals("output.txt")));
    }

    @Test
    public void testParallelProcessingWithParDo() {
        MapTask task = new MapTask();
        task.addParDoInstruction("processElement");
        Network network = MapTaskToNetworkFunction.convert(task);
        assertTrue(network.isDirected());
        assertTrue(network.allowsParallelEdges());
        assertFalse(network.hasSelfLoops());
        assertEquals(3, network.getNodes().size()); // Assuming 1 for input, 1 for processing, 1 for output
    }

    @Test
    public void testFlattenOperation() {
        MapTask task = new MapTask();
        task.addFlattenInstruction("flattenedOutput");
        Network network = MapTaskToNetworkFunction.convert(task);
        assertTrue(network.isDirected());
        assertFalse(network.hasSelfLoops());
        assertEquals(2, network.getNodes().size()); // Assuming 1 for input and 1 for flattened output
    }

    @Test
    public void testMultipleOutputs() {
        MapTask task = new MapTask();
        task.addMultipleOutputInstruction("output1");
        task.addMultipleOutputInstruction("output2");
        Network network = MapTaskToNetworkFunction.convert(task);
        assertTrue(network.isDirected());
        assertFalse(network.hasSelfLoops());
        assertEquals(3, network.getNodes().size()); // 1 for input, 2 for outputs
        assertEquals(2, network.getEdges().size()); // Assuming 1 edge for each output
    }

    @Test
    public void testNetworkStructure() {
        MapTask task = new MapTask();
        task.addReadInstruction("input.txt");
        task.addWriteInstruction("output.txt");
        task.addParDoInstruction("processElement");
        Network network = MapTaskToNetworkFunction.convert(task);
        assertEquals(3, network.getNodes().size());
        assertEquals(2, network.getEdges().size());
        assertTrue(network.getNodes().contains("input.txt"));
        assertTrue(network.getNodes().contains("processElement"));
        assertTrue(network.getNodes().contains("output.txt"));
    }
}

