public abstract class BaseDataStreamMarshaller implements DataStreamMarshaller {

    protected OpenWireFormat wireFormat;

    public BaseDataStreamMarshaller(OpenWireFormat wireFormat) {
        this.wireFormat = wireFormat;
    }

    public void tightMarshal(Object object, OutputStream output) throws IOException {
        // Implementation for tight marshaling
        if (object instanceof Long) {
            output.write((byte) 1);
            output.writeLong((Long) object);
        } else if (object instanceof byte[]) {
            output.write((byte) 2);
            byte[] bytes = (byte[]) object;
            output.writeInt(bytes.length);
            output.write(bytes);
        } else if (object instanceof String) {
            output.write((byte) 3);
            String str = (String) object;
            byte[] bytes = str.getBytes("UTF-8");
            output.writeInt(bytes.length);
            output.write(bytes);
        } else {
            throw new IOException("Unsupported type for tight marshaling: " + object.getClass());
        }
    }

    public Object tightUnmarshal(InputStream input) throws IOException {
        byte type = (byte) input.read();
        switch (type) {
            case 1:
                return input.readLong();
            case 2:
                int length = input.readInt();
                byte[] bytes = new byte[length];
                input.read(bytes);
                return bytes;
            case 3:
                length = input.readInt();
                bytes = new byte[length];
                input.read(bytes);
                return new String(bytes, "UTF-8");
            default:
                throw new IOException("Unsupported type for tight unmarshaling: " + type);
        }
    }

    public void looseMarshal(Object object, OutputStream output) throws IOException {
        // Implementation for loose marshaling
        // Similar to tightMarshal but with different logic
    }

