public class TextExtractor {
    private StringBuilder textBuffer;
    private List<String> metadata;
    private Map<String, String> metadataMap;
    private boolean isBold;
    private boolean isItalic;
    private int listLevel;

    public TextExtractor() {
        this.textBuffer = new StringBuilder();
        this.metadata = new ArrayList<>();
        this.metadataMap = new HashMap<>();
        this.isBold = false;
        this.isItalic = false;
        this.listLevel = 0;
    }

    public String extract(InputStream inputStream, Charset charset) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream, charset))) {
            String line;
            while ((line = reader.readLine()) != null) {
                parseLine(line);
            }
        }
        return toXhtml();
    }

    private void parseLine(String line) {
        // Simplified parsing logic for RTF control words
        if (line.startsWith("{\\rtf")) {
            // Handle RTF header
        } else if (line.startsWith("\\b")) {
            isBold = true;
        } else if (line.startsWith("\\b0")) {
            isBold = false;
        } else if (line.startsWith("\\i")) {
            isItalic = true;
        } else if (line.startsWith("\\i0")) {
            isItalic = false;
        } else if (line.startsWith("\\listtext")) {
            listLevel++;
        } else if (line.startsWith("\\pard")) {
            listLevel = 0; // Reset list level
        } else {
            textBuffer.append(line).append(" ");
        }
    }

    private String toXhtml() {
        StringBuilder xhtml = new StringBuilder();
        xhtml.append("<div>");
        if (isBold) {
            xhtml.append("<strong>");
        }
        if (isItalic) {
            xhtml.append("<em>");
        }
        xhtml.append(textBuffer.toString().trim());
        if (isItalic) {
            xhtml.append("</em>");
        }
        if (isBold) {
            xhtml.append("</strong>");
        }
        xhtml.append("</div>");
        return xhtml.toString();
    }

    public Map<String, String> getMetadata() {
        return metadataMap;
    }

    public void addMetadata(String key, String value) {
        metadataMap.put(key, value);
    }
}

