public abstract class AbstractNativeSessionManager extends AbstractSessionManager implements NativeSessionManager, EventBusAware {
    private EventBus eventBus;
    private List<SessionListener> sessionListeners = new ArrayList<>();

    public void startSession(String sessionId) {
        // Logic to start a session
        notifySessionStarted(sessionId);
    }

    public void stopSession(String sessionId) {
        // Logic to stop a session
        notifySessionStopped(sessionId);
    }

    public void expireSession(String sessionId) {
        // Logic to expire a session
        notifySessionExpired(sessionId);
    }

    public void addSessionListener(SessionListener listener) {
        sessionListeners.add(listener);
    }

    public void removeSessionListener(SessionListener listener) {
        sessionListeners.remove(listener);
    }

    protected void notifySessionStarted(String sessionId) {
        for (SessionListener listener : sessionListeners) {
            listener.onSessionStarted(sessionId);
        }
        eventBus.publish(new SessionEvent(sessionId, SessionEventType.STARTED));
    }

    protected void notifySessionStopped(String sessionId) {
        for (SessionListener listener : sessionListeners) {
            listener.onSessionStopped(sessionId);
        }
        eventBus.publish(new SessionEvent(sessionId, SessionEventType.STOPPED));
    }

    protected void notifySessionExpired(String sessionId) {
        for (SessionListener listener : sessionListeners) {
            listener.onSessionExpired(sessionId);
        }
        eventBus.publish(new SessionEvent(sessionId, SessionEventType.EXPIRED));
    }

    public abstract Session createSession(String sessionId);

    public abstract Session getSession(String sessionId);

    public void setEventBus(EventBus eventBus) {
        this.eventBus = eventBus;
    }

    public EventBus getEventBus() {
        return eventBus;
    }
}

public class ClassUtil {

    private static final Map<Class<?>, Class<?>> primitiveToWrapperMap = new HashMap<>();

    static {
        primitiveToWrapperMap.put(boolean.class, Boolean.class);
        primitiveToWrapperMap.put(byte.class, Byte.class);
        primitiveToWrapperMap.put(char.class, Character.class);
        primitiveToWrapperMap.put(double.class, Double.class);
        primitiveToWrapperMap.put(float.class, Float.class);
        primitiveToWrapperMap.put(int.class, Integer.class);
        primitiveToWrapperMap.put(long.class, Long.class);
        primitiveToWrapperMap.put(short.class, Short.class);
    }

    public static Class<?> getWrapperClass(Class<?> primitiveClass) {
        return primitiveToWrapperMap.getOrDefault(primitiveClass, primitiveClass);
    }

    public static <T> T createInstance(Class<T> clazz) {
        try {
            return clazz.getDeclaredConstructor().newInstance();
        } catch (InstantiationException | IllegalAccessException | NoSuchMethodException | InvocationTargetException e) {
            throw new RuntimeException("Unable to create instance of class: " + clazz.getName(), e);
        }
    }

    public static Class<?> getClassByName(String className) {
        try {
            return Class.forName(className);
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Class not found: " + className, e);
        }
    }

    public static boolean isFinal(Class<?> clazz) {
        return Modifier.isFinal(clazz.getModifiers());
    }

    public static boolean isAbstract(Class<?> clazz) {
        return Modifier.isAbstract(clazz.getModifiers());
    }

    public static boolean isInterface(Class<?> clazz) {
        return clazz.isInterface();
    }

    public static Method[] getDeclaredMethods(Class<?> clazz) {
        return clazz.getDeclaredMethods();
    }

    public static boolean isFinalMethod(Method method) {
        return Modifier.isFinal(method.getModifiers());
    }

    public static Class<?>[] getMethodParameterTypes(Method method) {
        return method.getParameterTypes();
    }

    public static Class<?> getMethodReturnType(Method method) {
        return method.getReturnType();
    }

    public static Class<?>[] getMethodExceptionTypes(Method method) {
        return method.getExceptionTypes();
    }

    public static Class<?> getSuperclass(Class<?> clazz) {
        return clazz.getSuperclass();
    }

    public static boolean isAssignable(Class<?> from, Class<?> to) {
        return to.isAssignableFrom(from);
    }

    public static Field[] getDeclaredFields(Class<?> clazz) {
        return clazz.getDeclaredFields();
    }

    public static boolean isObjectMethod(Method method) {
        return method.getDeclaringClass() == Object.class;
    }

    public static boolean isMethodOverride(Method method, Class<?> superClass) {
        try {
            Method superMethod = superClass.getDeclaredMethod(method.getName(), method.getParameterTypes());
            return !isFinalMethod(superMethod);
        } catch (NoSuchMethodException e) {
            return false;
        }
    }

    public static boolean isGenericType(Class<?> clazz) {
        return clazz.getTypeParameters().length > 0;
    }

    public static boolean isParameterizedType(Type type) {
        return type instanceof ParameterizedType;
    }

    public static boolean isTypeVariable(Type type) {
        return type instanceof TypeVariable;
    }
}

