public class EncTicketPart implements Asn1Object {
    private static final Logger logger = Logger.getLogger(EncTicketPart.class.getName());

    private int flags;
    private byte[] encryptionKey;
    private String clientRealm;
    private String clientName;
    private byte[] transitedEncoding;
    private long authTime;
    private long startTime;
    private long endTime;
    private long renewalTime;
    private List<String> clientAddresses;
    private byte[] authorizationData;

    public int getFlags() {
        return flags;
    }

    public void setFlags(int flags) {
        this.flags = flags;
    }

    public byte[] getEncryptionKey() {
        return encryptionKey;
    }

    public void setEncryptionKey(byte[] encryptionKey) {
        this.encryptionKey = encryptionKey;
    }

    public String getClientRealm() {
        return clientRealm;
    }

    public void setClientRealm(String clientRealm) {
        this.clientRealm = clientRealm;
    }

    public String getClientName() {
        return clientName;
    }

    public void setClientName(String clientName) {
        this.clientName = clientName;
    }

    public byte[] getTransitedEncoding() {
        return transitedEncoding;
    }

    public void setTransitedEncoding(byte[] transitedEncoding) {
        this.transitedEncoding = transitedEncoding;
    }

    public long getAuthTime() {
        return authTime;
    }

    public void setAuthTime(long authTime) {
        this.authTime = authTime;
    }

    public long getStartTime() {
        return startTime;
    }

    public void setStartTime(long startTime) {
        this.startTime = startTime;
    }

    public long getEndTime() {
        return endTime;
    }

    public void setEndTime(long endTime) {
        this.endTime = endTime;
    }

    public long getRenewalTime() {
        return renewalTime;
    }

    public void setRenewalTime(long renewalTime) {
        this.renewalTime = renewalTime;
    }

    public List<String> getClientAddresses() {
        return clientAddresses;
    }

    public void setClientAddresses(List<String> clientAddresses) {
        this.clientAddresses = clientAddresses;
    }

    public byte[] getAuthorizationData() {
        return authorizationData;
    }

    public void setAuthorizationData(byte[] authorizationData) {
        this.authorizationData = authorizationData;
    }

    public int computeLength() {
        int length = 0;
        length += Integer.BYTES; // flags
        length += encryptionKey.length; // encryptionKey
        length += clientRealm.length(); // clientRealm
        length += clientName.length(); // clientName
        length += transitedEncoding.length; // transitedEncoding
        length += Long.BYTES * 4; // authTime, startTime, endTime, renewalTime
        length += clientAddresses.stream().mapToInt(String::length).sum(); // clientAddresses
        length += authorizationData.length; // authorizationData
        logger.info("Computed length: " + length);
        return length;
    }

    public ByteBuffer encode() {
        ByteBuffer buffer = ByteBuffer.allocate(computeLength());
        buffer.putInt(flags);
        buffer.put(encryptionKey);
        buffer.put(clientRealm.getBytes());
        buffer.put(clientName.getBytes());
        buffer.put(transitedEncoding);
        buffer.putLong(authTime);
        buffer.putLong(startTime);
        buffer.putLong(endTime);
        buffer.putLong(renewalTime);
        for (String address : clientAddresses) {
            buffer.put(address.getBytes());
        }
        buffer.put(authorizationData);
        logger.info("Encoded ticket part.");
        return buffer;
    }

    @Override
    public String toString() {
        return "EncTicketPart{" +
                "flags=" + flags +
                ", clientRealm='" + clientRealm + '\'' +
                ", clientName='" + clientName + '\'' +
                ", authTime=" + authTime +
                ", startTime=" + startTime +
                ", endTime=" + endTime +
                ", renewalTime=" + renewalTime +
                ", clientAddresses=" + clientAddresses +
                '}';
    }
}

