public class ConvertUtilsBean {
    private static final Logger logger = Logger.getLogger(ConvertUtilsBean.class.getName());
    private Map<Class<?>, Converter<?>> converters = new HashMap<>();

    public ConvertUtilsBean() {
        // Register default converters
        registerDefaultConverters();
    }

    private void registerDefaultConverters() {
        // Register default converters for primitive and standard types
        registerConverter(String.class, new StringConverter());
        registerConverter(Integer.class, new IntegerConverter());
        // Add more default converters as needed
    }

    public <T> void registerConverter(Class<T> type, Converter<T> converter) {
        converters.put(type, converter);
        logger.info("Registered converter for type: " + type.getName());
    }

    public <T> void deregisterConverter(Class<T> type) {
        converters.remove(type);
        logger.info("Deregistered converter for type: " + type.getName());
    }

    @SuppressWarnings("unchecked")
    public <T> T convert(Object value, Class<T> targetType) {
        if (value == null) {
            return null;
        }
        Converter<T> converter = (Converter<T>) converters.get(targetType);
        if (converter == null) {
            throw new IllegalArgumentException("No converter registered for type: " + targetType.getName());
        }
        T result = converter.convert(value);
        logger.info("Converted value: " + value + " to type: " + targetType.getName());
        return result;
    }

    @Deprecated
    public void setDefaultString(String defaultValue) {
        // Deprecated method for setting default string value
        logger.warning("setDefaultString is deprecated.");
    }

    @Deprecated
    public void setDefaultInteger(Integer defaultValue) {
        // Deprecated method for setting default integer value
        logger.warning("setDefaultInteger is deprecated.");
    }

    // Converter interface
    public interface Converter<T> {
        T convert(Object value);
    }

    // Example converters
    public static class StringConverter implements Converter<String> {
        public String convert(Object value) {
            return value.toString();
        }
    }

    public static class IntegerConverter implements Converter<Integer> {
        public Integer convert(Object value) {
            return Integer.valueOf(value.toString());
        }
    }
}

