public class HighlighterTest extends TestCase implements Formatter {

    private RAMDirectory ramDirectory;
    private IndexWriter indexWriter;
    private StandardAnalyzer analyzer;

    @Override
    protected void setUp() throws Exception {
        ramDirectory = new RAMDirectory();
        analyzer = new StandardAnalyzer();
        IndexWriterConfig config = new IndexWriterConfig(analyzer);
        indexWriter = new IndexWriter(ramDirectory, config);
    }

    @Override
    protected void tearDown() throws Exception {
        indexWriter.close();
        ramDirectory.close();
    }

    @Test
    public void testHighlightingDefaultField() throws Exception {
        addDocument("This is a test document for highlighting.");
        String queryStr = "highlighting";
        Query query = new QueryParser("content", analyzer).parse(queryStr);
        String[] fragments = highlight(query);
        assertEquals(1, fragments.length);
        assertTrue(fragments[0].contains("<b>highlighting</b>"));
    }

    @Test
    public void testHighlightingNamedField() throws Exception {
        addDocument("Another test for named field highlighting.");
        String queryStr = "named";
        Query query = new QueryParser("title", analyzer).parse(queryStr);
        String[] fragments = highlight(query);
        assertEquals(1, fragments.length);
        assertTrue(fragments[0].contains("<b>named</b>"));
    }

    @Test
    public void testPhraseQueryHighlighting() throws Exception {
        addDocument("Highlighting is a great feature for search.");
        String queryStr = "\"great feature\"";
        Query query = new QueryParser("content", analyzer).parse(queryStr);
        String[] fragments = highlight(query);
        assertEquals(1, fragments.length);
        assertTrue(fragments[0].contains("<b>great</b> <b>feature</b>"));
    }

    @Test
    public void testFuzzyQueryHighlighting() throws Exception {
        addDocument("Fuzzy search is interesting.");
        String queryStr = "fuzzy~";
        Query query = new QueryParser("content", analyzer).parse(queryStr);
        String[] fragments = highlight(query);
        assertEquals(1, fragments.length);
        assertTrue(fragments[0].contains("<b>Fuzzy</b>"));
    }

    @Test
    public void testWildcardQueryHighlighting() throws Exception {
        addDocument("Wildcard search can be powerful.");
        String queryStr = "wild*";
        Query query = new QueryParser("content", analyzer).parse(queryStr);
        String[] fragments = highlight(query);
        assertEquals(1, fragments.length);
        assertTrue(fragments[0].contains("<b>wildcard</b>"));
    }

    @Test
    public void testRangeQueryHighlighting() throws Exception {
        addDocument("Range queries are useful.");
        String queryStr = "[a TO z]";
        Query query = new QueryParser("content", analyzer).parse(queryStr);
        String[] fragments = highlight(query);
        assertEquals(1, fragments.length);
        assertTrue(fragments[0].contains("Range"));
    }

    private void addDocument(String content) throws Exception {
        Document doc = new Document();
        doc.add(new TextField("content", content, Field.Store.YES));
        indexWriter.addDocument(doc);
    }

    private String[] highlight(Query query) throws Exception {
        IndexSearcher searcher = new IndexSearcher(DirectoryReader.open(ramDirectory));
        Highlighter highlighter = new Highlighter(new QueryScorer(query));
        ScoreDoc[] hits = searcher.search(query, 10).scoreDocs;
        String[] fragments = new String[hits.length];
        for (int i = 0; i < hits.length; i++) {
            Document doc = searcher.doc(hits[i].doc);
            String text = doc.get("content");
            fragments[i] = highlighter.getBestFragment(analyzer, "content", text);
        }
        return fragments;
    }

    @Override
    public String format(String input) {
        return "<b>" + input + "</b>";
    }
}

