class OpenLdapAclParserTest {

    @Test
    void testParseEmptyString() {
        assertThrows(ParseException.class, () -> {
            OpenLdapAclParser.parse("");
        });
    }

    @Test
    void testParseWildcardAccess() throws ParseException {
        String acl = "access to * by * read";
        Acl parsedAcl = OpenLdapAclParser.parse(acl);
        assertEquals("access to *", parsedAcl.getAccess());
        assertEquals("by *", parsedAcl.getBy());
        assertEquals("read", parsedAcl.getRights());
    }

    @Test
    void testValidDistinguishedName() throws ParseException {
        String acl = "access to dn.subtree=\"cn=admin,dc=example,dc=com\" by * read";
        Acl parsedAcl = OpenLdapAclParser.parse(acl);
        assertEquals("dn.subtree=\"cn=admin,dc=example,dc=com\"", parsedAcl.getAccess());
    }

    @Test
    void testInvalidDistinguishedName() {
        String acl = "access to dn.subtree=\"cn=admin,dc=example,dc=com";
        assertThrows(ParseException.class, () -> {
            OpenLdapAclParser.parse(acl);
        });
    }

    @Test
    void testDistinguishedNameWithoutQuotes() throws ParseException {
        String acl = "access to dn.subtree=cn=admin,dc=example,dc=com by * read";
        Acl parsedAcl = OpenLdapAclParser.parse(acl);
        assertEquals("dn.subtree=cn=admin,dc=example,dc=com", parsedAcl.getAccess());
    }

    @Test
    void testDifferentDnScopes() throws ParseException {
        String aclExact = "access to dn.exact=\"cn=admin,dc=example,dc=com\" by * read";
        String aclOneLevel = "access to dn.one=\"ou=users,dc=example,dc=com\" by * read";
        String aclBase = "access to dn.base=\"dc=example,dc=com\" by * read";
        String aclSubtree = "access to dn.subtree=\"dc=example,dc=com\" by * read";

        assertEquals("dn.exact=\"cn=admin,dc=example,dc=com\"", OpenLdapAclParser.parse(aclExact).getAccess());
        assertEquals("dn.one=\"ou=users,dc=example,dc=com\"", OpenLdapAclParser.parse(aclOneLevel).getAccess());
        assertEquals("dn.base=\"dc=example,dc=com\"", OpenLdapAclParser.parse(aclBase).getAccess());
        assertEquals("dn.subtree=\"dc=example,dc=com\"", OpenLdapAclParser.parse(aclSubtree).getAccess());
    }

    @Test
    void testValidFilterExpression() throws ParseException {
        String acl = "access to * by dn.regex=\"uid=.*,ou=users,dc=example,dc=com\" read";
        Acl parsedAcl = OpenLdapAclParser.parse(acl);
        assertEquals("by dn.regex=\"uid=.*,ou=users,dc=example,dc=com\"", parsedAcl.getBy());
    }

    @Test
    void testMalformedAclString() {
        String acl = "access to * by *";
        assertThrows(ParseException.class, () -> {
            OpenLdapAclParser.parse(acl);
        });
    }
}

public class KpStemmer extends SnowballProgram {
    private static final String[] suffixes = { "en", "e", "s", "er", "ing", "lijk", "heid", "ing", "te", "de" };
    private int cursor;
    private String currentWord;

    public KpStemmer() {
        this.cursor = 0;
        this.currentWord = "";
    }

    public void setCurrentWord(String word) {
        this.currentWord = word;
        this.cursor = word.length();
    }

    public String getStem() {
        stem();
        return currentWord;
    }

    private void stem() {
        if (cursor > 0) {
            applyRules();
        }
    }

    private void applyRules() {
        for (String suffix : suffixes) {
            if (currentWord.endsWith(suffix) && cursor >= suffix.length()) {
                currentWord = currentWord.substring(0, cursor - suffix.length());
                cursor -= suffix.length();
                break;
            }
        }
        // Additional rules can be added here
    }

    private boolean isVowel(char c) {
        return "aeiou".indexOf(c) >= 0;
    }

    private boolean isConsonant(char c) {
        return !isVowel(c);
    }

    // More methods can be added to handle specific patterns and conditions
}

