public class NodeTypeImpl extends AbstractNodeType implements NodeType, NodeTypeDefinition {

    private List<NodeType> supertypes;
    private List<NodeDefinition> childNodeDefinitions;
    private List<PropertyDefinition> propertyDefinitions;

    public NodeTypeImpl(String name) {
        super(name);
        this.supertypes = new ArrayList<>();
        this.childNodeDefinitions = new ArrayList<>();
        this.propertyDefinitions = new ArrayList<>();
    }

    @Override
    public boolean includesNodeType(String nodeTypeName) {
        for (NodeType supertype : supertypes) {
            if (supertype.getName().equals(nodeTypeName) || supertype.includesNodeType(nodeTypeName)) {
                return true;
            }
        }
        return false;
    }

    @Override
    public boolean isDerivedFrom(String nodeTypeName) {
        for (NodeType supertype : supertypes) {
            if (supertype.getName().equals(nodeTypeName) || supertype.isDerivedFrom(nodeTypeName)) {
                return true;
            }
        }
        return false;
    }

    public NodeDefinition getAutoCreatedNodeDefinition() {
        for (NodeDefinition definition : childNodeDefinitions) {
            if (definition.isAutoCreated()) {
                return definition;
            }
        }
        return null;
    }

    public PropertyDefinition getMandatoryPropertyDefinition() {
        for (PropertyDefinition definition : propertyDefinitions) {
            if (definition.isMandatory()) {
                return definition;
            }
        }
        return null;
    }

    public void addChildNodeDefinition(NodeDefinition definition) {
        if (definition == null) {
            logError("Attempted to add a null child node definition.");
            return;
        }
        childNodeDefinitions.add(definition);
    }

    public void removeChildNodeDefinition(NodeDefinition definition) {
        if (!childNodeDefinitions.remove(definition)) {
            logError("Attempted to remove a non-existent child node definition.");
        }
    }

    public void validatePropertySetting(Property property) {
        for (PropertyDefinition definition : propertyDefinitions) {
            if (definition.getName().equals(property.getName()) && !definition.isValid(property)) {
                logError("Invalid property setting for: " + property.getName());
                throw new IllegalArgumentException("Invalid property setting.");
            }
        }
    }

    private void logError(String message) {
        // Placeholder for logging logic
        System.err.println("Error: " + message);
    }

    // Getters and setters for supertypes, childNodeDefinitions, and propertyDefinitions
}

