public class WebClient implements Serializable, MessageListener, SessionActivation {
    private static final long serialVersionUID = 1L;

    private Connection connection;
    private Session session;
    private MessageProducer producer;
    private MessageConsumer consumer;
    private String connectionFactoryName;
    private String destinationName;
    private int deliveryMode;

    public WebClient(String connectionFactoryName, String destinationName, int deliveryMode) {
        this.connectionFactoryName = connectionFactoryName;
        this.destinationName = destinationName;
        this.deliveryMode = deliveryMode;
    }

    public void activate() {
        try {
            ConnectionFactory factory = getConnectionFactory();
            connection = factory.createConnection();
            session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
            Destination destination = session.createQueue(destinationName);
            producer = session.createProducer(destination);
            consumer = session.createConsumer(destination);
            consumer.setMessageListener(this);
            connection.start();
        } catch (JMSException e) {
            e.printStackTrace();
        }
    }

    public void passivate() {
        try {
            if (consumer != null) consumer.close();
            if (producer != null) producer.close();
            if (session != null) session.close();
            if (connection != null) connection.close();
        } catch (JMSException e) {
            e.printStackTrace();
        }
    }

    public void sendMessage(String messageText) {
        try {
            TextMessage message = session.createTextMessage(messageText);
            producer.send(message, deliveryMode, Message.DEFAULT_PRIORITY, Message.DEFAULT_TIME_TO_LIVE);
        } catch (JMSException e) {
            e.printStackTrace();
        }
    }

    @Override
    public void onMessage(Message message) {
        // Handle incoming messages
    }

    private ConnectionFactory getConnectionFactory() {
