public class FieldSortedHitQueue {
    private final List<SortField> sortFields;
    private final PriorityQueue<FieldDoc> queue;
    private float maxScore;

    public FieldSortedHitQueue(List<SortField> sortFields, int size) {
        this.sortFields = sortFields;
        this.queue = new PriorityQueue<>(size, new FieldDocComparator(sortFields));
        this.maxScore = Float.NEGATIVE_INFINITY;
    }

    public void insert(FieldDoc fieldDoc) {
        if (fieldDoc.score > maxScore) {
            maxScore = fieldDoc.score;
        }
        queue.offer(fieldDoc);
        if (queue.size() > queue.capacity()) {
            queue.poll();
        }
    }

    public float getMaxScore() {
        return maxScore;
    }

    public List<FieldDoc> getFieldDocs() {
        return new ArrayList<>(queue);
    }

    private static class FieldDocComparator implements Comparator<FieldDoc> {
        private final List<SortField> sortFields;

        public FieldDocComparator(List<SortField> sortFields) {
            this.sortFields = sortFields;
        }

        @Override
        public int compare(FieldDoc doc1, FieldDoc doc2) {
            for (SortField sortField : sortFields) {
                int cmp = sortField.compare(doc1, doc2);
                if (cmp != 0) {
                    return cmp;
                }
            }
            return 0;
        }
    }
}

