public abstract class BaseDataStreamMarshaller implements DataStreamMarshaller {

    protected abstract void marshal(Object obj, OutputStream outputStream) throws IOException;

    protected abstract Object unmarshal(InputStream inputStream) throws IOException;

    protected void marshalLong(long value, OutputStream outputStream) throws IOException {
        outputStream.write((int) (value >>> 56));
        outputStream.write((int) (value >>> 48));
        outputStream.write((int) (value >>> 40));
        outputStream.write((int) (value >>> 32));
        outputStream.write((int) (value >>> 24));
        outputStream.write((int) (value >>> 16));
        outputStream.write((int) (value >>> 8));
        outputStream.write((int) value);
    }

    protected long unmarshalLong(InputStream inputStream) throws IOException {
        long value = 0;
        for (int i = 0; i < 8; i++) {
            value = (value << 8) | (inputStream.read() & 0xFF);
        }
        return value;
    }

    protected void marshalString(String value, OutputStream outputStream) throws IOException {
        byte[] bytes = value.getBytes("UTF-8");
        marshalLong(bytes.length, outputStream);
        outputStream.write(bytes);
    }

    protected String unmarshalString(InputStream inputStream) throws IOException {
        long length = unmarshalLong(inputStream);
        byte[] bytes = new byte[(int) length];
        inputStream.read(bytes);
        return new String(bytes, "UTF-8");
    }

    protected void marshalByteArray(byte[] array, OutputStream outputStream) throws IOException {
        marshalLong(array.length, outputStream);
        outputStream.write(array);
    }

    protected byte[] unmarshalByteArray(InputStream inputStream) throws IOException {
        long length = unmarshalLong(inputStream);
        byte[] array = new byte[(int) length];
        inputStream.read(array);
        return array;
    }

    protected void marshalThrowable(Throwable throwable, OutputStream outputStream) throws IOException {
        marshalString(throwable.getClass().getName(), outputStream);
        marshalString(throwable.getMessage(), outputStream);
        // Stack trace serialization omitted for brevity
    }

    protected Throwable unmarshalThrowable(InputStream inputStream) throws IOException {
        String className = unmarshalString(inputStream);
        String message = unmarshalString(inputStream);
        // Stack trace deserialization omitted for brevity
        return new Throwable(message); // Simplified for demonstration
    }
}

