public class GroupTest extends AbstractUserTest {

    @Test
    public void testAddMember() {
        Group group = new Group("Test Group");
        User user = new User("testUser");

        group.addMember(user);

        assertTrue(group.hasMember(user), "User should be a member of the group");
        assertEquals(1, group.getMemberCount(), "Group should have one member");
    }

    @Test
    public void testRemoveMember() {
        Group group = new Group("Test Group");
        User user = new User("testUser");

        group.addMember(user);
        group.removeMember(user);

        assertFalse(group.hasMember(user), "User should not be a member of the group");
        assertEquals(0, group.getMemberCount(), "Group should have no members");
    }

    @Test
    public void testMembershipStatus() {
        Group group = new Group("Test Group");
        User user = new User("testUser");

        assertFalse(group.hasMember(user), "User should not be a member initially");

        group.addMember(user);

        assertTrue(group.hasMember(user), "User should be a member after adding");
    }

    @Test
    public void testIndirectMembership() {
        Group groupA = new Group("Group A");
        Group groupB = new Group("Group B");
        User user = new User("testUser");

        groupA.addMember(user);
        groupB.addMember(groupA);

        assertTrue(groupB.hasMember(user), "User should be indirectly a member of Group B");
    }

    @Test
    public void testSelfMembershipNotAllowed() {
        Group group = new Group("Test Group");

        assertThrows(IllegalArgumentException.class, () -> {
            group.addMember(group);
        }, "Group should not be able to add itself as a member");
    }
}

