    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof MemberImpl)) return false;
        MemberImpl member = (MemberImpl) o;
        return tcpPort == member.tcpPort &&
                securePort == member.securePort &&
                udpPort == member.udpPort &&
                Objects.equals(hostname, member.hostname) &&
                Objects.equals(uniqueId, member.uniqueId);
