                "hostname='" + hostname + '\'' +
                ", tcpPort=" + tcpPort +
                ", securePort=" + securePort +
                ", udpPort=" + udpPort +
                ", uniqueId='" + uniqueId + '\'' +
                ", state=" + state +
                '}';
    }
