public class Util {

    public static String accessFlagsToString(int flags) {
        StringBuilder result = new StringBuilder();
        if ((flags & 0x0001) != 0) result.append("public ");
        if ((flags & 0x0002) != 0) result.append("private ");
        if ((flags & 0x0004) != 0) result.append("protected ");
        if ((flags & 0x0010) != 0) result.append("static ");
        if ((flags & 0x0020) != 0) result.append("final ");
        if ((flags & 0x0400) != 0) result.append("abstract ");
        return result.toString().trim();
    }

    public static int stringToAccessFlags(String access) {
        int flags = 0;
        if (access.contains("public")) flags |= 0x0001;
        if (access.contains("private")) flags |= 0x0002;
        if (access.contains("protected")) flags |= 0x0004;
        if (access.contains("static")) flags |= 0x0010;
        if (access.contains("final")) flags |= 0x0020;
        if (access.contains("abstract")) flags |= 0x0400;
        return flags;
    }

    public static boolean hasMethodBody(int flags) {
        return (flags & 0x0400) == 0; // abstract methods do not have a body
    }

    public static String descriptorToString(String descriptor) {
        // Simplified conversion for demonstration
        return descriptor.replace("I", "int")
                         .replace("Z", "boolean")
                         .replace("V", "void");
    }

    public static String[] parseMethodParameters(String descriptor) {
        // Simplified parsing for demonstration
        return descriptor.substring(1, descriptor.indexOf(')')).split(",");
    }

    public static int getPrimitiveTypeCode(String type) {
        switch (type) {
            case "int": return 1;
            case "boolean": return 2;
            case "void": return 3;
            default: return 0;
        }
    }

    public static String padString(String str, int length) {
        while (str.length() < length) {
            str = " " + str;
        }
        return str;
    }

    public static byte[] intToByteArray(int value) {
        return new byte[] {
            (byte) (value >> 24),
            (byte) (value >> 16),
            (byte) (value >> 8),
            (byte) value
        };
    }

    public static int byteArrayToInt(byte[] bytes) {
        return (bytes[0] << 24) | (bytes[1] << 16) | (bytes[2] << 8) | (bytes[3]);
    }

    public static String charToUnicode(char c) {
        return String.format("\\u%04x", (int) c);
    }

    public static void main(String[] args) {
        System.out.println(accessFlagsToString(0x0001 | 0x0010)); // public static
        System.out.println(stringToAccessFlags("public static")); // 17
        System.out.println(hasMethodBody(0x0400)); // false
        System.out.println(descriptorToString("I")); // int
        System.out.println(getPrimitiveTypeCode("boolean")); // 2
        System.out.println(padString("test", 10)); // "      test"
        System.out.println(byteArrayToInt(intToByteArray(123456))); // 123456
        System.out.println(charToUnicode('A')); // \u0041
    }
}

