public class OraAddAction extends DatabaseAddAction {

    private String tableName;
    private Map<String, Object> data;
    private Connection connection;

    public OraAddAction(String tableName, Map<String, Object> data) {
        this.tableName = tableName;
        this.data = data;
        this.connection = null;
    }

    public void execute() {
        try {
            connection = getConnection();
            connection.setAutoCommit(false);
            String sql = generateInsertSQL();
            try (PreparedStatement preparedStatement = connection.prepareStatement(sql)) {
                setParameters(preparedStatement);
                preparedStatement.executeUpdate();
                connection.commit();
            } catch (SQLException e) {
                connection.rollback();
                handleError(e);
            }
        } catch (SQLException e) {
            handleError(e);
        } finally {
            closeConnection();
        }
    }

    private String generateInsertSQL() {
        StringBuilder sql = new StringBuilder("INSERT INTO " + tableName + " (");
        StringBuilder placeholders = new StringBuilder(" VALUES (");
        for (String key : data.keySet()) {
            sql.append(key).append(", ");
            placeholders.append("?, ");
        }
        sql.setLength(sql.length() - 2); // Remove last comma and space
        placeholders.setLength(placeholders.length() - 2); // Remove last comma and space
        sql.append(")").append(placeholders).append(")");
        return sql.toString();
    }

    private void setParameters(PreparedStatement preparedStatement) throws SQLException {
        int index = 1;
        for (Object value : data.values()) {
            preparedStatement.setObject(index++, value);
        }
    }

    private void handleError(SQLException e) {
        // Log error and handle exception
        System.err.println("Database error: " + e.getMessage());
    }

    private void closeConnection() {
        if (connection != null) {
            try {
                connection.close();
            } catch (SQLException e) {
                System.err.println("Error closing connection: " + e.getMessage());
            }
        }
    }
}

