public class BPTreeNode extends BPTreePage {
    private List<BPTreePage> children;
    private List<Record> records;
    private boolean isLeaf;
    private int maxKeys;

    public BPTreeNode(int maxKeys, boolean isLeaf) {
        this.maxKeys = maxKeys;
        this.isLeaf = isLeaf;
        this.children = new ArrayList<>();
        this.records = new ArrayList<>();
    }

    public boolean isLeaf() {
        return isLeaf;
    }

    public List<Record> getRecords() {
        return records;
    }

    public List<BPTreePage> getChildren() {
        return children;
    }

    public void insert(Record record) {
        if (isLeaf) {
            insertInLeaf(record);
        } else {
            insertInInternal(record);
        }
    }

    private void insertInLeaf(Record record) {
        records.add(record);
        records.sort(Record::compareTo);
        if (records.size() > maxKeys) {
            split();
        }
    }

    private void insertInInternal(Record record) {
        int index = findChildIndex(record);
        BPTreeNode child = (BPTreeNode) children.get(index);
        child.insert(record);
        if (child.getRecords().size() > maxKeys) {
            splitChild(index);
        }
    }

    private int findChildIndex(Record record) {
        for (int i = 0; i < records.size(); i++) {
            if (record.compareTo(records.get(i)) < 0) {
                return i;
            }
        }
        return records.size();
    }

    private void split() {
        BPTreeNode newNode = new BPTreeNode(maxKeys, isLeaf);
        int midIndex = records.size() / 2;

        newNode.records.addAll(records.subList(midIndex, records.size()));
        records = new ArrayList<>(records.subList(0, midIndex));

        if (!isLeaf) {
            newNode.children.addAll(children.subList(midIndex + 1, children.size()));
            children = new ArrayList<>(children.subList(0, midIndex + 1));
        }

        // Logic to promote the middle key to the parent node
        // This part would typically involve notifying the parent node
    }

    private void splitChild(int index) {
        BPTreeNode child = (BPTreeNode) children.get(index);
        BPTreeNode newChild = new BPTreeNode(maxKeys, child.isLeaf);

        int midIndex = child.records.size() / 2;
        newChild.records.addAll(child.records.subList(midIndex, child.records.size()));
        child.records = new ArrayList<>(child.records.subList(0, midIndex));

        if (!child.isLeaf) {
            newChild.children.addAll(child.children.subList(midIndex + 1, child.children.size()));
            child.children = new ArrayList<>(child.children.subList(0, midIndex + 1));
        }

        children.add(index + 1, newChild);
        // Logic to promote the middle key to the parent node
    }

    public void delete(Record record) {
        if (isLeaf) {
            records.remove(record);
        } else {
            deleteFromInternal(record);
        }
    }

    private void deleteFromInternal(Record record) {
        int index = findChildIndex(record);
        BPTreeNode child = (BPTreeNode) children.get(index);
        child.delete(record);
        // Logic for rebalancing or merging if necessary
    }

    public void logAction(String action) {
        System.out.println("Action: " + action + " on node with records: " + records);
    }

    public boolean checkIntegrity() {
        // Logic to check the integrity of the node
        return true;
    }
}

