public class Property implements Comparable<Property> {
    public enum PropertyType {
        SIMPLE, STRUCTURE, BAG, SEQ, ALT, COMPOSITE
    }

    public enum ValueType {
        BOOLEAN, INTEGER, TEXT
    }

