    private String name;
    private PropertyType propertyType;
    private ValueType valueType;
    private boolean multiValue;
    private List<String> closedChoices;
    private List<String> openChoices;
    private List<Property> compositeProperties;

    public Property(String name, PropertyType propertyType, ValueType valueType, boolean multiValue) {
        this.name = name;
        this.propertyType = propertyType;
        this.valueType = valueType;
        this.multiValue = multiValue;
        this.closedChoices = new ArrayList<>();
        this.openChoices = new ArrayList<>();
        this.compositeProperties = new ArrayList<>();
        propertiesMap.put(name, this);
    }

    public static Property getProperty(String name) {
        return propertiesMap.get(name);
    }

    public void addClosedChoice(String choice) {
        closedChoices.add(choice);
    }

