        openChoices.add(choice);
    }

    public void addCompositeProperty(Property property) {
        compositeProperties.add(property);
    }

    public boolean isMultiValuePermitted() {
        return multiValue && (propertyType == PropertyType.BAG || propertyType == PropertyType.SEQ);
    }

    public String getName() {
        return name;
    }

    public PropertyType getPropertyType() {
        return propertyType;
    }

    public ValueType getValueType() {
        return valueType;
    }

