public class ModelerLogger {
    public enum LogLevel {
        TRACE, DEBUG, INFO, WARNING, ERROR
    }

    private LogLevel currentLogLevel = LogLevel.INFO;

    public void setLogLevel(LogLevel level) {
        this.currentLogLevel = level;
    }

    public void trace(String message) {
        log(LogLevel.TRACE, message);
    }

    public void debug(String message) {
        log(LogLevel.DEBUG, message);
    }

    public void info(String message) {
        log(LogLevel.INFO, message);
    }

    public void warning(String message) {
        log(LogLevel.WARNING, message);
    }

    public void error(String message) {
        log(LogLevel.ERROR, message);
    }

    public void log(LogLevel level, String message) {
        if (isLogLevelEnabled(level)) {
            System.err.println(formatMessage(level, message));
        }
    }

    public void log(LogLevel level, String message, Throwable throwable) {
        if (isLogLevelEnabled(level)) {
            System.err.println(formatMessage(level, message) + " - " + throwable.getMessage());
        }
    }

    private boolean isLogLevelEnabled(LogLevel level) {
        return level.ordinal() >= currentLogLevel.ordinal();
    }

    private String formatMessage(LogLevel level, String message) {
        String timestamp = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date());
        String threadName = Thread.currentThread().getName();
        return String.format("[%s] [%s] [%s] %s", timestamp, threadName, level, message);
    }
}

