class TestFetchFile {

    private static final String TARGET_DIR = "targetDir";
    private static final String SOURCE_FILE = "source.txt";
    private static final String TARGET_FILE = TARGET_DIR + "/target.txt";

    @BeforeAll
    static void setUp() {
        new File(TARGET_DIR).mkdirs();
    }

    @BeforeEach
    void cleanTargetDirectory() {
        File targetDir = new File(TARGET_DIR);
        for (File file : targetDir.listFiles()) {
            file.delete();
        }
    }

    @Test
    void testFileNotFound() {
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, TARGET_FILE);
        assertThrows(FileNotFoundException.class, fetchFile::fetch);
    }

    @Test
    void testSuccessfulFileFetch() throws IOException {
        createSourceFile("Hello, World!");
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, TARGET_FILE);
        fetchFile.fetch();
        assertEquals("Hello, World!", new String(Files.readAllBytes(Paths.get(TARGET_FILE))));
    }

    @Test
    void testFileDeletionOnCompletion() throws IOException {
        createSourceFile("Hello, World!");
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, TARGET_FILE);
        fetchFile.fetch();
        assertFalse(new File(SOURCE_FILE).exists());
    }

    @Test
    void testFileMovingWithExistingTargetDirectory() throws IOException {
        createSourceFile("Hello, World!");
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, TARGET_FILE);
        fetchFile.move();
        assertTrue(new File(TARGET_FILE).exists());
    }

    @Test
    void testFileMovingWithMissingTargetDirectory() throws IOException {
        String newTargetDir = "newTargetDir";
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, newTargetDir + "/target.txt");
        fetchFile.move();
        assertTrue(new File(newTargetDir + "/target.txt").exists());
    }

    @Test
    void testFileMovingWithTargetDirectoryNotWritable() {
        // Assuming targetDir is read-only
        File targetDir = new File(TARGET_DIR);
        targetDir.setWritable(false);
        createSourceFile("Hello, World!");
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, TARGET_DIR + "/target.txt");
        assertThrows(IOException.class, fetchFile::move);
        targetDir.setWritable(true);
    }

    @Test
    void testFileMovingWithInaccessibleParentDirectory() {
        // Simulate inaccessible parent directory
        String inaccessibleDir = "/inaccessibleDir/target.txt";
        createSourceFile("Hello, World!");
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, inaccessibleDir);
        assertThrows(IOException.class, fetchFile::move);
    }

    @Test
    void testFileMovingAndReplacingExistingFile() throws IOException {
        createSourceFile("Hello, World!");
        createTargetFile("Existing Content");
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, TARGET_FILE);
        fetchFile.move();
        assertEquals("Hello, World!", new String(Files.readAllBytes(Paths.get(TARGET_FILE))));
    }

    @Test
    void testFileMovingAndKeepingExistingFile() throws IOException {
        createTargetFile("Existing Content");
        createSourceFile("New Content");
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, TARGET_FILE);
        fetchFile.moveKeepExisting();
        assertEquals("Existing Content", new String(Files.readAllBytes(Paths.get(TARGET_FILE))));
    }

    @Test
    void testFileMovingAndFailingDueToConflict() {
        createTargetFile("Existing Content");
        createSourceFile("New Content");
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, TARGET_FILE);
        assertThrows(IOException.class, fetchFile::moveFailOnConflict);
    }

    @Test
    void testFileMovingAndRenamingOnConflict() throws IOException {
        createTargetFile("Existing Content");
        createSourceFile("New Content");
        FetchFile fetchFile = new FetchFile(SOURCE_FILE, TARGET_FILE);
        fetchFile.moveRenameOnConflict();
        assertTrue(new File(TARGET_DIR + "/target_1.txt").exists());
    }

    private void createSourceFile(String content) throws IOException {
        Files.write(Paths.get(SOURCE_FILE), content.getBytes());
    }

    private void createTargetFile(String content) throws IOException {
        Files.write(Paths.get(TARGET_FILE), content.getBytes());
    }
