public class ClusterStatusMonitor implements ClusterStatusMonitorMBean {
    private Set<String> liveInstances = new HashSet<>();
    private Set<String> disabledInstances = new HashSet<>();
    private Set<String> totalInstances = new HashSet<>();
    private Map<String, Integer> instanceMessageQueueSizes = new HashMap<>();
    private Map<String, ResourceMonitor> resourceMonitors = new HashMap<>();
    private MBeanServer mBeanServer;

    public ClusterStatusMonitor(MBeanServer mBeanServer) {
        this.mBeanServer = mBeanServer;
    }

    public void registerInstance(String instanceId) {
        totalInstances.add(instanceId);
        liveInstances.add(instanceId);
        instanceMessageQueueSizes.put(instanceId, 0);
        // Register MBean for the instance
        try {
            ObjectName objectName = new ObjectName("com.example:type=ResourceMonitor,name=" + instanceId);
            ResourceMonitor resourceMonitor = new ResourceMonitor(instanceId);
            resourceMonitors.put(instanceId, resourceMonitor);
            mBeanServer.registerMBean(resourceMonitor, objectName);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void unregisterInstance(String instanceId) {
        totalInstances.remove(instanceId);
        liveInstances.remove(instanceId);
        disabledInstances.remove(instanceId);
        instanceMessageQueueSizes.remove(instanceId);
        // Unregister MBean for the instance
        try {
            ObjectName objectName = new ObjectName("com.example:type=ResourceMonitor,name=" + instanceId);
            mBeanServer.unregisterMBean(objectName);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void disableInstance(String instanceId) {
        if (liveInstances.contains(instanceId)) {
            liveInstances.remove(instanceId);
            disabledInstances.add(instanceId);
        }
    }

    public void enableInstance(String instanceId) {
        if (disabledInstances.contains(instanceId)) {
            disabledInstances.remove(instanceId);
            liveInstances.add(instanceId);
        }
    }

    public int getNumberOfDownInstances() {
        return totalInstances.size() - liveInstances.size();
    }

    public int getTotalInstances() {
        return totalInstances.size();
    }

    public int getDisabledInstances() {
        return disabledInstances.size();
    }

    public int getMaxMessageQueueSize() {
        return instanceMessageQueueSizes.values().stream().max(Integer::compare).orElse(0);
    }

    public void updateInstanceMessageQueueSize(String instanceId, int size) {
        if (instanceMessageQueueSizes.containsKey(instanceId)) {
            instanceMessageQueueSizes.put(instanceId, size);
        }
    }

    public void updateResourceStatus(String instanceId, String status) {
        ResourceMonitor resourceMonitor = resourceMonitors.get(instanceId);
        if (resourceMonitor != null) {
            resourceMonitor.updateStatus(status);
        }
    }
}

public class FmtUtils {
    private Map<String, String> prefixMap;

    public FmtUtils() {
        this.prefixMap = new HashMap<>();
    }

    public void addPrefix(String prefix, String uri) {
        prefixMap.put(prefix, uri);
    }

    public String formatTriple(String subject, String predicate, String object) {
        return formatNode(subject) + " " + formatNode(predicate) + " " + formatNode(object) + " .";
    }

    public String formatQuad(String graph, String subject, String predicate, String object) {
        return formatNode(graph) + " " + formatNode(subject) + " " + formatNode(predicate) + " " + formatNode(object) + " .";
    }

    public String formatNode(String node) {
        if (isURI(node)) {
            return formatURI(node);
        } else if (isLiteral(node)) {
            return formatLiteral(node);
        } else {
            return formatBlankNode(node);
        }
    }

    private boolean isURI(String node) {
        return node.startsWith("http://") || node.startsWith("https://");
    }

    private boolean isLiteral(String node) {
        return node.startsWith("\"") && node.endsWith("\"");
    }

    private String formatURI(String uri) {
        for (Map.Entry<String, String> entry : prefixMap.entrySet()) {
            if (uri.startsWith(entry.getValue())) {
                return entry.getKey() + ":" + uri.substring(entry.getValue().length());
            }
        }
        return "<" + escapeURI(uri) + ">";
    }

    private String formatLiteral(String literal) {
        return escapeLiteral(literal);
    }

    private String formatBlankNode(String blankNode) {
        return "_" + blankNode;
    }

    private String escapeURI(String uri) {
        // Placeholder for escaping logic
        return uri;
    }

    private String escapeLiteral(String literal) {
        // Placeholder for escaping logic
        return literal.replace("\"", "\\\"").replace("\n", "\\n");
    }
}

