public class WrapperFactoryDefault implements WrapperFactory {
    private Map<Class<?>, EventDispatcher<?>> eventDispatchers = new HashMap<>();
    private ProxyContextHandler proxyContextHandler;

    public WrapperFactoryDefault(ProxyContextHandler proxyContextHandler) {
        this.proxyContextHandler = proxyContextHandler;
    }

    @Override
    public <T> T wrap(T domainObject, ExecutionMode executionMode) {
        // Code smell: Long method, could be refactored
        if (executionMode == ExecutionMode.EXECUTE) {
            return proxyContextHandler.createProxy(domainObject);
        } else if (executionMode == ExecutionMode.NO_EXECUTE) {
            return domainObject;
        } else if (executionMode == ExecutionMode.SKIP_RULES) {
            // Code smell: Magic string, could be replaced with an enum
            return (T) proxyContextHandler.createProxyWithSkipRules(domainObject);
        }
        return null; // Code smell: Returning null, could throw an exception
    }

    @Override
    public <T> T unwrap(T wrappedObject) {
        // Code smell: Could be more explicit in handling nulls
        return proxyContextHandler.unwrapProxy(wrappedObject);
    }

    public void addInteractionListener(Class<?> eventClass, InteractionListener<?> listener) {
        // Code smell: Method could be too long if more logic is added
        eventDispatchers.computeIfAbsent(eventClass, k -> new EventDispatcher<>()).addListener(listener);
    }

    public void dispatchEvent(Object event) {
        // Code smell: Could be more robust in handling unknown event types
        EventDispatcher<Object> dispatcher = (EventDispatcher<Object>) eventDispatchers.get(event.getClass());
        if (dispatcher != null) {
            dispatcher.dispatch(event);
        }
    }
}

