    public enum LoadBalancingStrategy {
        ROUND_ROBIN,
        RANDOM,
        STICKY,
        TOPIC_BASED
    }

    private String referenceId;
    private List<ProcessorType> outputProcessors;
    private LoadBalancingStrategy strategy;
    private int currentIndex = 0;

    public LoadBalanceType(String referenceId, LoadBalancingStrategy strategy) {
        this.referenceId = referenceId;
        this.strategy = strategy;
        this.outputProcessors = new ArrayList<>();
    }

    public String getReferenceId() {
        return referenceId;
    }

    public void setReferenceId(String referenceId) {
        this.referenceId = referenceId;
    }

    public List<ProcessorType> getOutputProcessors() {
        return outputProcessors;
    }

    public void setOutputProcessors(List<ProcessorType> outputProcessors) {
        this.outputProcessors = outputProcessors;
    }

    public void addOutputProcessor(ProcessorType processor) {
        this.outputProcessors.add(processor);
    }

    public void configureChildProcessors() {
        // Configuration logic for child processors can be implemented here
    }

    public ProcessorType getNextProcessor() {
        switch (strategy) {
            case ROUND_ROBIN:
                return roundRobin();
            case RANDOM:
                return random();
            case STICKY:
                return sticky();
            case TOPIC_BASED:
                return topicBased();
            default:
                throw new IllegalArgumentException("Unknown load balancing strategy");
        }
    }

    private ProcessorType roundRobin() {
        if (outputProcessors.isEmpty()) return null;
        ProcessorType processor = outputProcessors.get(currentIndex);
        currentIndex = (currentIndex + 1) % outputProcessors.size();
        return processor;
    }

    private ProcessorType random() {
        if (outputProcessors.isEmpty()) return null;
        Random rand = new Random();
        return outputProcessors.get(rand.nextInt(outputProcessors.size()));
    }

    private ProcessorType sticky() {
        // Implement sticky logic based on session or request context
        return outputProcessors.isEmpty() ? null : outputProcessors.get(0); // Placeholder
    }

    private ProcessorType topicBased() {
        // Implement topic-based logic
        return outputProcessors.isEmpty() ? null : outputProcessors.get(0); // Placeholder
    }

    @Override
    public String toString() {
        return "LoadBalanceType{" +
                "referenceId='" + referenceId + '\'' +
                ", strategy=" + strategy +
                ", outputProcessors=" + outputProcessors +
                '}';
    }

    public String getLabel() {
        return "Load Balancer: " + referenceId + " [" + strategy + "]";
    }
