        super(null);
        this.directory = directory;
        this.append = append;
    }

    @Override
    public void process(Exchange exchange) throws Exception {
        String targetFileName = createTargetFileName(exchange);
        File targetFile = new File(directory, targetFileName);
        ensureDirectoriesExist(targetFile);

        try (FileOutputStream fos = new FileOutputStream(targetFile, append);
             FileChannel fileChannel = fos.getChannel()) {
            InputStream inputStream = exchange.getIn().getBody(InputStream.class);
            if (inputStream != null) {
                fileChannel.transferFrom(FileChannel.open(inputStream), 0, Long.MAX_VALUE);
            }
        } catch (Exception e) {
            LOG.error("Error writing to file: {}", targetFile.getAbsolutePath(), e);
            throw e;
        }
    }

    private String createTargetFileName(Exchange exchange) {
