public class JDBCTableReader {
    private Connection connection;
    private ResultSet resultSet;
    private String tableName;
    private BodyContentHandler handler;

    public JDBCTableReader(String dbUrl, String user, String password, String tableName) throws SQLException {
        this.connection = DriverManager.getConnection(dbUrl, user, password);
        this.tableName = tableName;
        this.handler = new BodyContentHandler();
    }

    public void readData() throws SQLException {
        Statement statement = connection.createStatement();
        resultSet = statement.executeQuery("SELECT * FROM " + tableName);
        while (resultSet.next()) {
            generateXHTMLRow();
        }
    }

    private void generateXHTMLRow() throws SQLException {
        handler.startElement("tr", null);
        ResultSetMetaData metaData = resultSet.getMetaData();
        int columnCount = metaData.getColumnCount();
        for (int i = 1; i <= columnCount; i++) {
            handler.startElement("td", null);
            Object value = resultSet.getObject(i);
            if (value instanceof Blob) {
                handleBlob((Blob) value);
            } else if (value instanceof Clob) {
                handleClob((Clob) value);
            } else {
                handler.characters(value != null ? value.toString() : "NULL");
            }
            handler.endElement("td");
        }
        handler.endElement("tr");
    }

    private void handleBlob(Blob blob) throws SQLException {
        // Logic to handle BLOB data
        // Code smell: Not handling large data efficiently
        byte[] blobBytes = blob.getBytes(1, (int) blob.length());
        handler.characters(new String(blobBytes));
    }

    private void handleClob(Clob clob) throws SQLException {
        // Logic to handle CLOB data
        // Code smell: Not handling large data efficiently
        String clobData = clob.getSubString(1, (int) clob.length());
        handler.characters(clobData);
    }

    public String getColumnHeaders() throws SQLException {
        StringBuilder headers = new StringBuilder();
        ResultSetMetaData metaData = resultSet.getMetaData();
        int columnCount = metaData.getColumnCount();
        for (int i = 1; i <= columnCount; i++) {
            headers.append(metaData.getColumnName(i)).append(" ");
        }
        return headers.toString().trim();
    }

    public void reset() throws SQLException {
        if (resultSet != null) {
            resultSet.close();
        }
        readData();
    }

    public void close() throws SQLException {
        if (resultSet != null) {
            resultSet.close();
        }
        if (connection != null) {
            connection.close();
        }
    }
}

