public class URIBitSets {
    public static final BitSet PERCENT_ENCODED = new BitSet();
    public static final BitSet DIGITS = new BitSet();
    public static final BitSet ALPHA_LOWER = new BitSet();
    public static final BitSet ALPHA_UPPER = new BitSet();
    public static final BitSet ALPHANUMERIC = new BitSet();
    public static final BitSet HEXADECIMAL = new BitSet();
    public static final BitSet RESERVED = new BitSet();
    public static final BitSet UNRESERVED = new BitSet();
    public static final BitSet USERINFO = new BitSet();
    public static final BitSet HOST = new BitSet();
    public static final BitSet PORT = new BitSet();
    public static final BitSet AUTHORITY = new BitSet();
    public static final BitSet PATH_SEGMENT = new BitSet();
    public static final BitSet QUERY_STRING = new BitSet();
    public static final BitSet FRAGMENT = new BitSet();
    public static final BitSet DISALLOWED = new BitSet();

    static {
        // Percent-encoded characters
        for (int i = 0; i < 256; i++) {
            if (i == '%' || (i >= '0' && i <= '9') || (i >= 'A' && i <= 'F') || (i >= 'a' && i <= 'f')) {
                PERCENT_ENCODED.set(i);
            }
        }

        // Digits
        for (int i = '0'; i <= '9'; i++) {
            DIGITS.set(i);
        }

        // Alphabetic characters
        for (int i = 'a'; i <= 'z'; i++) {
            ALPHA_LOWER.set(i);
        }
        for (int i = 'A'; i <= 'Z'; i++) {
            ALPHA_UPPER.set(i);
        }

        // Alphanumeric characters
        ALPHANUMERIC.or(DIGITS);
        ALPHANUMERIC.or(ALPHA_LOWER);
        ALPHANUMERIC.or(ALPHA_UPPER);

        // Hexadecimal characters
        for (int i = '0'; i <= '9'; i++) {
            HEXADECIMAL.set(i);
        }
        for (int i = 'A'; i <= 'F'; i++) {
            HEXADECIMAL.set(i);
        }
        for (int i = 'a'; i <= 'f'; i++) {
            HEXADECIMAL.set(i);
        }

        // Reserved characters
        String reservedChars = "!*'();:@&=+$,/?#[]";
        for (char c : reservedChars.toCharArray()) {
            RESERVED.set(c);
        }

        // Unreserved characters
        UNRESERVED.or(ALPHANUMERIC);
        for (int i = '-'; i <= '_'; i++) {
            UNRESERVED.set(i);
        }

        // Userinfo characters
        String userinfoChars = "!*'();:&=+$,/?#[]";
        for (char c : userinfoChars.toCharArray()) {
            USERINFO.set(c);
        }
        USERINFO.or(ALPHANUMERIC);
        USERINFO.set('%'); // percent-encoded

        // Host characters
        for (int i = 'a'; i <= 'z'; i++) {
            HOST.set(i);
        }
        for (int i = 'A'; i <= 'Z'; i++) {
            HOST.set(i);
        }
        for (int i = '0'; i <= '9'; i++) {
            HOST.set(i);
        }
        HOST.set('-'); // hyphen
        HOST.set('.'); // dot

        // Port characters
        for (int i = '0'; i <= '9'; i++) {
            PORT.set(i);
        }

        // Authority characters
        AUTHORITY.or(USERINFO);
        AUTHORITY.or(HOST);
        AUTHORITY.or(PORT);

        // Path segment characters
        PATH_SEGMENT.or(UNRESERVED);
        PATH_SEGMENT.or(RESERVED);

        // Query string characters
        QUERY_STRING.or(PATH_SEGMENT);
        QUERY_STRING.set('?'); // question mark

        // Fragment characters
        FRAGMENT.or(QUERY_STRING);
        FRAGMENT.set('#'); // hash mark

        // Disallowed characters
        DISALLOWED.or(RESERVED);
        DISALLOWED.set(' '); // space
    }
}

