public class WebUtils {
    public static final String SESSION_KEY = "sessionKey";
    public static final String REQUEST_URI = "requestUri";
    public static final String REDIRECT_URI = "redirectUri";

    public static void saveRequest(HttpServletRequest request) {
        HttpSession session = request.getSession();
        session.setAttribute(REQUEST_URI, request.getRequestURI());
    }

    public static String getSavedRequest(HttpServletRequest request) {
        HttpSession session = request.getSession();
        return (String) session.getAttribute(REQUEST_URI);
    }

    public static void redirect(HttpServletResponse response, String uri) throws IOException {
        response.sendRedirect(uri);
    }

    public static String normalizeUri(String uri) {
        return uri.replaceAll("/+", "/");
    }

    public static String decode(String value) {
        try {
            return URLDecoder.decode(value, StandardCharsets.UTF_8.name());
        } catch (IOException e) {
            return value; // Code smell: ignoring exception
        }
    }

    public static Map<String, String> getParameters(HttpServletRequest request) {
        Map<String, String> params = new HashMap<>();
        request.getParameterMap().forEach((key, value) -> {
            if (value.length > 0) {
                params.put(key, value[0]); // Code smell: only taking the first value
            }
        });
        return params;
    }

    public static boolean isWebEnvironment() {
        return true; // Code smell: always returns true, lacks actual environment check
    }
}

