public class NewAttributeTypeContentWizardPage extends WizardPage {
    private Text superiorAttributeText;
    private Text usageTypeText;
    private Text syntaxText;
    private Text lengthText;
    private Button obsoleteButton;
    private Button singleValuedButton;
    private Button collectiveButton;
    private Button nonModifiableButton;

    protected NewAttributeTypeContentWizardPage(String pageName) {
        super(pageName);
        setTitle("New Attribute Type");
        setDescription("Create a new attribute type in the schema.");
    }

    @Override
    public void createControl(Composite parent) {
        Composite container = new Composite(parent, SWT.NULL);
        setControl(container);
        container.setLayout(new GridLayout(2, false));

        new Label(container, SWT.NONE).setText("Superior Attribute:");
        superiorAttributeText = new Text(container, SWT.BORDER);
        superiorAttributeText.setLayoutData(new GridData(GridData.FILL_HORIZONTAL));

        new Label(container, SWT.NONE).setText("Usage Type:");
        usageTypeText = new Text(container, SWT.BORDER);
        usageTypeText.setLayoutData(new GridData(GridData.FILL_HORIZONTAL));

        new Label(container, SWT.NONE).setText("Syntax:");
        syntaxText = new Text(container, SWT.BORDER);
        syntaxText.setLayoutData(new GridData(GridData.FILL_HORIZONTAL));

        new Label(container, SWT.NONE).setText("Length:");
        lengthText = new Text(container, SWT.BORDER);
        lengthText.setLayoutData(new GridData(GridData.FILL_HORIZONTAL));

        obsoleteButton = new Button(container, SWT.CHECK);
        obsoleteButton.setText("Obsolete");

        singleValuedButton = new Button(container, SWT.CHECK);
        singleValuedButton.setText("Single-Valued");

        collectiveButton = new Button(container, SWT.CHECK);
        collectiveButton.setText("Collective");

        nonModifiableButton = new Button(container, SWT.CHECK);
        nonModifiableButton.setText("Non-Modifiable by Users");

        setPageComplete(false);
    }

    public String getSuperiorAttribute() {
        return superiorAttributeText.getText();
    }

    public String getUsageType() {
        return usageTypeText.getText();
    }

    public String getSyntax() {
        return syntaxText.getText();
    }

    public String getLength() {
        return lengthText.getText();
    }

    public boolean isObsolete() {
        return obsoleteButton.getSelection();
    }

    public boolean isSingleValued() {
        return singleValuedButton.getSelection();
    }

    public boolean isCollective() {
        return collectiveButton.getSelection();
    }

    public boolean isNonModifiable() {
        return nonModifiableButton.getSelection();
    }

    @Override
    public void setVisible(boolean visible) {
        super.setVisible(visible);
        if (visible) {
            validatePage();
        }
    }

    private void validatePage() {
        String superiorAttribute = getSuperiorAttribute();
        String usageType = getUsageType();
        String syntax = getSyntax();
        String length = getLength();

        if (superiorAttribute.isEmpty() || usageType.isEmpty() || syntax.isEmpty() || length.isEmpty()) {
            setPageComplete(false);
        } else {
            setPageComplete(true);
        }
    }
}

