public class Content implements Writable {
    private String url;
    private String baseUrl;
    private byte[] content;
    private String contentType;
    private Map<String, String> metadata;

    public Content(String url, String baseUrl, byte[] content, String contentType, Map<String, String> metadata) {
        this.url = url;
        this.baseUrl = baseUrl;
        this.content = content;
        this.contentType = contentType;
        this.metadata = metadata != null ? new HashMap<>(metadata) : new HashMap<>();
    }

    public Content(String url, String baseUrl, byte[] content) {
        this(url, baseUrl, content, null, null);
    }

    public Content(String url, String baseUrl) {
        this(url, baseUrl, null, null, null);
    }

    public String getUrl() {
        return url;
    }

    public void setUrl(String url) {
        this.url = url;
    }

    public String getBaseUrl() {
        return baseUrl;
    }

    public void setBaseUrl(String baseUrl) {
        this.baseUrl = baseUrl;
    }

    public byte[] getContent() {
        return content;
    }

    public void setContent(byte[] content) {
        this.content = content;
    }

    public String getContentType() {
        return contentType;
    }

    public void setContentType(String contentType) {
        this.contentType = contentType;
    }

    public Map<String, String> getMetadata() {
        return new HashMap<>(metadata);
    }

    public void setMetadata(Map<String, String> metadata) {
        this.metadata = metadata != null ? new HashMap<>(metadata) : new HashMap<>();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Content)) return false;
        Content content1 = (Content) o;
        return Objects.equals(url, content1.url) &&
                Objects.equals(baseUrl, content1.baseUrl) &&
                Objects.equals(contentType, content1.contentType) &&
                Objects.equals(metadata, content1.metadata);
    }

