public class RutaStream {
    private Map<Integer, List<Annotation>> beginAnchors;
    private Map<Integer, List<Annotation>> endAnchors;
    private List<Annotation> annotations;
    private List<Filter> filters;

    public RutaStream() {
        this.beginAnchors = new HashMap<>();
        this.endAnchors = new HashMap<>();
        this.annotations = new ArrayList<>();
        this.filters = new ArrayList<>();
    }

    public void addAnnotation(Annotation annotation) {
        annotations.add(annotation);
        addToAnchorMaps(annotation);
    }

    public void removeAnnotation(Annotation annotation) {
        annotations.remove(annotation);
        removeFromAnchorMaps(annotation);
    }

    public void addFilter(Filter filter) {
        filters.add(filter);
    }

    public void removeFilter(Filter filter) {
        filters.remove(filter);
    }

    public List<Annotation> getAnnotations() {
        List<Annotation> filteredAnnotations = new ArrayList<>();
        for (Annotation annotation : annotations) {
            if (passesFilters(annotation)) {
                filteredAnnotations.add(annotation);
            }
        }
        return filteredAnnotations;
    }

    public List<Annotation> getOverlappingAnnotations(int begin, int end) {
        List<Annotation> overlapping = new ArrayList<>();
        for (Annotation annotation : annotations) {
            if (annotation.overlaps(begin, end)) {
                overlapping.add(annotation);
            }
        }
        return overlapping;
    }

    public List<Annotation> getAdjacentAnnotations(int position) {
        List<Annotation> adjacent = new ArrayList<>();
        for (Annotation annotation : annotations) {
            if (annotation.isAdjacentTo(position)) {
                adjacent.add(annotation);
            }
        }
        return adjacent;
    }

    private void addToAnchorMaps(Annotation annotation) {
        beginAnchors.computeIfAbsent(annotation.getBegin(), k -> new ArrayList<>()).add(annotation);
        endAnchors.computeIfAbsent(annotation.getEnd(), k -> new ArrayList<>()).add(annotation);
    }

    private void removeFromAnchorMaps(Annotation annotation) {
        List<Annotation> beginList = beginAnchors.get(annotation.getBegin());
        if (beginList != null) {
            beginList.remove(annotation);
            if (beginList.isEmpty()) {
                beginAnchors.remove(annotation.getBegin());
            }
        }
        List<Annotation> endList = endAnchors.get(annotation.getEnd());
        if (endList != null) {
            endList.remove(annotation);
            if (endList.isEmpty()) {
                endAnchors.remove(annotation.getEnd());
            }
        }
    }

    private boolean passesFilters(Annotation annotation) {
        for (Filter filter : filters) {
            if (!filter.apply(annotation)) {
                return false;
            }
        }
        return true;
    }

    public void assignFeatureValue(Annotation annotation, String feature, Object value) {
        annotation.setFeature(feature, value);
    }
}

public class QOMFormatter {
