public abstract class AbstractPredicateUtil {

    private static final Map<String, Comparator<RangerBaseModelObject>> comparatorMap = new HashMap<>();

    static {
        comparatorMap.put("serviceType", Comparator.comparing(RangerBaseModelObject::getServiceType));
        comparatorMap.put("policyName", Comparator.comparing(RangerBaseModelObject::getPolicyName));
        comparatorMap.put("timestamp", Comparator.comparing(RangerBaseModelObject::getTimestamp));
    }

    public static List<RangerBaseModelObject> applyFilter(List<RangerBaseModelObject> objects, SearchFilter filter) {
        return objects.stream()
                .filter(createPredicate(filter))
                .sorted(getComparator(filter.getSortBy()))
                .collect(Collectors.toList());
    }

    private static Predicate<RangerBaseModelObject> createPredicate(SearchFilter filter) {
        return object -> {
            boolean matches = true;
            if (filter.getServiceType() != null) {
                matches = matches && object.getServiceType().equals(filter.getServiceType());
            }
            if (filter.getPolicyName() != null) {
                matches = matches && object.getPolicyName().equals(filter.getPolicyName());
            }
            if (filter.getUserName() != null) {
                matches = matches && object.getUserName().equals(filter.getUserName());
            }
            if (filter.getGroupName() != null) {
                matches = matches && object.getGroupName().equals(filter.getGroupName());
            }
            if (filter.getResourceAttributes() != null) {
                matches = matches && object.getResourceAttributes().equals(filter.getResourceAttributes());
            }
            return matches;
        };
    }

    private static Comparator<RangerBaseModelObject> getComparator(String sortBy) {
        return comparatorMap.getOrDefault(sortBy, Comparator.naturalOrder());
    }
}

public class InterceptorPredicateProceedAndStopTest extends CamelTestSupport {

    @EndpointInject(uri = "mock:result")
    protected MockEndpoint resultEndpoint;

    @EndpointInject(uri = "mock:interceptor")
    protected MockEndpoint interceptorEndpoint;

    @Override
    protected CamelContext createCamelContext() throws Exception {
        CamelContext context = super.createCamelContext();
        context.addRoutes(new InterceptorRoute());
        return context;
    }

    @Test
    public void testInterceptorWithPredicateProceed() throws Exception {
        resultEndpoint.expectedMessageCount(1);
        interceptorEndpoint.expectedMessageCount(1);

        template.sendBody("direct:start", "Test Message");

        assertMockEndpointsSatisfied();
    }

    @Test
    public void testInterceptorWithPredicateStop() throws Exception {
        resultEndpoint.expectedMessageCount(0);
        interceptorEndpoint.expectedMessageCount(0);

        template.sendBody("direct:start", "Stop Message");

        assertMockEndpointsSatisfied();
    }

    @Test
    public void testInterceptorWithoutPredicateProceed() throws Exception {
        resultEndpoint.expectedMessageCount(1);

        template.sendBody("direct:start", "Proceed Message");

        assertMockEndpointsSatisfied();
    }

    @Test
    public void testInterceptorWithoutPredicateStop() throws Exception {
        resultEndpoint.expectedMessageCount(0);

        template.sendBody("direct:start", "Stop Message");

        assertMockEndpointsSatisfied();
    }

    private class InterceptorRoute extends RouteBuilder {
        @Override
        public void configure() throws Exception {
            from("direct:start")
                .intercept()
                    .to("mock:interceptor")
                    .choice()
                        .when(simple("${body} contains 'Stop'"))
                            .stop()
                        .otherwise()
                            .proceed()
                .end()
                .to("mock:result");
        }
    }
