class PrecisionTest {

    @Test
    public void testEqualityWithRelativeTolerance() {
        assertTrue(Precision.equalsWithRelativeTolerance(1.0, 1.00001, 0.0001));
        assertFalse(Precision.equalsWithRelativeTolerance(1.0, 1.1, 0.0001));
        assertTrue(Precision.equalsWithRelativeTolerance(0.0, 0.0, 0.0001));
        assertTrue(Precision.equalsWithRelativeTolerance(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY, 0.0001));
        assertFalse(Precision.equalsWithRelativeTolerance(Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY, 0.0001));
        assertTrue(Precision.equalsWithRelativeTolerance(Double.NaN, Double.NaN, 0.0001));
    }

    @Test
    public void testEqualityIncludingNaN() {
        assertTrue(Precision.equalsIncludingNaN(Double.NaN, Double.NaN));
        assertFalse(Precision.equalsIncludingNaN(1.0, Double.NaN));
    }

    @Test
    public void testEqualityWithAllowedDelta() {
        assertTrue(Precision.equalsWithDelta(1.0, 1.0001, 0.001));
        assertFalse(Precision.equalsWithDelta(1.0, 1.1, 0.001));
    }

    @Test
    public void testMathEdgeCases() {
        assertTrue(Precision.equalsWithRelativeTolerance(1.0 / 3.0, 0.3333, 0.0001));
        assertTrue(Precision.equalsWithRelativeTolerance(Math.sqrt(2), 1.4142, 0.0001));
    }

    @Test
    public void testComparisonWithEpsilon() {
        assertTrue(Precision.equalsWithEpsilon(1.0, 1.0 + 1e-10, 1e-9));
        assertFalse(Precision.equalsWithEpsilon(1.0, 1.0 + 1e-8, 1e-9));
    }

    @Test
    public void testRoundingFunctions() {
        assertEquals(Precision.round(1.23456, 2), 1.23, 0.0001);
        assertEquals(Precision.round(1.23556, 2), 1.24, 0.0001);
        assertEquals(Precision.round(1.23556f, 2), 1.24f, 0.0001f);
    }

    @Test
    public void testRepresentableDelta() {
        assertEquals(Precision.getRepresentableDelta(1.0), 2.220446049250313e-16, 0.0001);
    }

    @Test
    public void testSpecialCases() {
        assertTrue(Precision.equalsIncludingNaN(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY));
        assertTrue(Precision.equalsIncludingNaN(Double.NEGATIVE_INFINITY, Double.NEGATIVE_INFINITY));
        assertFalse(Precision.equalsIncludingNaN(Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY));
        assertTrue(Precision.equalsIncludingNaN(0.0, -0.0));
    }
}

public class TestDistributedAtomicLong {
    private TestingServer server;
    private CuratorFramework client;
    private DistributedAtomicLong atomicLong;

    @Before
    public void setUp() throws Exception {
        server = new TestingServer();
        client = CuratorFrameworkFactory.newClient(server.getConnectString(), new ExponentialBackoffRetry(1000, 3));
        client.start();
        atomicLong = new DistributedAtomicLong(client, "/counter", new RetryNTimes(3, 1000));
    }

    @After
    public void tearDown() throws Exception {
        CloseableUtils.closeQuietly(client);
        CloseableUtils.closeQuietly(server);
    }

    @Test
    public void testCorruptedValueHandling() throws Exception {
        // Simulate a corrupted value
        atomicLong.forceSet(-1);
        assertFalse(atomicLong.get().postValue().isPresent());
    }

    @Test
    public void testCompareAndSet() throws Exception {
        assertTrue(atomicLong.compareAndSet(0, 1).succeeded());
        assertFalse(atomicLong.compareAndSet(0, 2).succeeded());
    }

    @Test
    public void testIncrementAndConditionalLogic() throws Exception {
        atomicLong.increment();
        assertEquals(1, atomicLong.get().postValue().get().longValue());
        if (atomicLong.get().postValue().get() > 0) {
            atomicLong.increment();
        }
        assertEquals(2, atomicLong.get().postValue().get().longValue());
    }

    @Test
    public void testForceSetBehavior() throws Exception {
        atomicLong.forceSet(10);
        assertEquals(10, atomicLong.get().postValue().get().longValue());
        atomicLong.forceSet(20);
        assertEquals(20, atomicLong.get().postValue().get().longValue());
    }

    @Test
    public void testConcurrentOperations() throws Exception {
        int threadCount = 10;
        ExecutorService executor = Executors.newFixedThreadPool(threadCount);
        CountDownLatch latch = new CountDownLatch(threadCount);
        for (int i = 0; i < threadCount; i++) {
            executor.submit(() -> {
                try {
                    atomicLong.increment();
                } finally {
                    latch.countDown();
                }
            });
        }
        latch.await();
        assertEquals(threadCount, atomicLong.get().postValue().get().longValue());
        executor.shutdown();
    }

    @Test
    public void testBasicFunctionality() throws Exception {
        atomicLong.increment();
        assertEquals(1, atomicLong.get().postValue().get().longValue());
        atomicLong.decrement();
        assertEquals(0, atomicLong.get().postValue().get().longValue());
        atomicLong.add(5);
        assertEquals(5, atomicLong.get().postValue().get().longValue());
        atomicLong.subtract(3);
        assertEquals(2, atomicLong.get().postValue().get().longValue());
    }
}

