public abstract class HttpBase {
    protected String userAgent;
    protected int timeout;
    protected Proxy proxy;
    protected int contentLimit;
    protected Logger logger;
    protected Map<String, String> customHeaders;

    public HttpBase() {
        this.userAgent = "Mozilla/5.0";
        this.timeout = 5000;
        this.contentLimit = 1048576; // 1 MB
        this.logger = Logger.getLogger(HttpBase.class.getName());
        this.customHeaders = new HashMap<>();
    }

    public void setUserAgent(String userAgent) {
        this.userAgent = userAgent;
        logger.info("User-Agent set to: " + userAgent);
    }

    public void setTimeout(int timeout) {
        this.timeout = timeout;
        logger.info("Timeout set to: " + timeout + " ms");
    }

    public void setProxy(Proxy proxy) {
        this.proxy = proxy;
        logger.info("Proxy set to: " + proxy);
    }

    public void setContentLimit(int contentLimit) {
        this.contentLimit = contentLimit;
        logger.info("Content limit set to: " + contentLimit + " bytes");
    }

    public void addCustomHeader(String key, String value) {
        customHeaders.put(key, value);
        logger.info("Custom header added: " + key + " = " + value);
    }

    protected String getResponse(String urlString) throws IOException {
        HttpURLConnection connection = createConnection(urlString);
        connection.connect();
        int responseCode = connection.getResponseCode();

        if (responseCode >= 300 && responseCode < 400) {
            String newUrl = connection.getHeaderField("Location");
            logger.info("Redirecting to: " + newUrl);
            return getResponse(newUrl);
        } else if (responseCode >= 400) {
            logger.severe("Error response: " + responseCode);
            throw new IOException("HTTP error code: " + responseCode);
        }

        return readResponse(connection);
    }

    private HttpURLConnection createConnection(String urlString) throws IOException {
        URL url = new URL(urlString);
        HttpURLConnection connection = (HttpURLConnection) (proxy != null ? url.openConnection(proxy) : url.openConnection());
        connection.setRequestMethod("GET");
        connection.setRequestProperty("User-Agent", userAgent);
        for (Map.Entry<String, String> entry : customHeaders.entrySet()) {
            connection.setRequestProperty(entry.getKey(), entry.getValue());
        }
        connection.setConnectTimeout(timeout);
        connection.setReadTimeout(timeout);
        return connection;
    }

    private String readResponse(HttpURLConnection connection) throws IOException {
        String encoding = connection.getContentEncoding();
        InputStream inputStream = connection.getInputStream();
        if ("gzip".equalsIgnoreCase(encoding)) {
            inputStream = new GZIPInputStream(inputStream);
        } else if ("deflate".equalsIgnoreCase(encoding)) {
            inputStream = new InflaterInputStream(inputStream);
        }

        StringBuilder response = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
            String line;
            while ((line = reader.readLine()) != null) {
                response.append(line);
                if (response.length() > contentLimit) {
                    logger.warning("Content limit exceeded");
                    break;
                }
            }
        }
        return response.toString();
    }

    public abstract void handleRobotRules(String url);
}

