public class IntrospectionUtils {
    private static final Logger logger = Logger.getLogger(IntrospectionUtils.class.getName());
    private static final Map<String, Method> methodCache = new HashMap<>();

    public static Object invokeMethod(Object target, String methodName, Object... args) {
        try {
            Class<?> targetClass = target.getClass();
            Class<?>[] argTypes = new Class[args.length];
            for (int i = 0; i < args.length; i++) {
                argTypes[i] = args[i].getClass();
            }
            Method method = methodCache.computeIfAbsent(targetClass.getName() + methodName, key -> {
                try {
                    return targetClass.getMethod(methodName, argTypes);
                } catch (NoSuchMethodException e) {
                    logger.severe("Method not found: " + e.getMessage());
                    return null;
                }
            });
            if (method != null) {
                return method.invoke(target, args);
            }
        } catch (Exception e) {
            logger.severe("Error invoking method: " + e.getMessage());
        }
        return null;
    }

    public static void setProperty(Object target, String propertyName, Object value) {
        try {
            String methodName = "set" + capitalize(propertyName);
            invokeMethod(target, methodName, value);
        } catch (Exception e) {
            logger.severe("Error setting property: " + e.getMessage());
        }
    }

    public static Object getProperty(Object target, String propertyName) {
        try {
            String methodName = "get" + capitalize(propertyName);
            return invokeMethod(target, methodName);
        } catch (Exception e) {
            logger.severe("Error getting property: " + e.getMessage());
        }
        return null;
    }

    @Deprecated
    public static void handleAttributes() {
        // Deprecated method logic
    }

    @Deprecated
    public static void handleClassPath() {
        // Deprecated method logic
    }

    @Deprecated
    public static void handleSystemProperties() {
        // Deprecated method logic
    }

    public static int convertStringToInt(String value) {
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException e) {
            logger.severe("Error converting string to int: " + e.getMessage());
            return 0; // Default value
        }
    }

    public static boolean convertStringToBoolean(String value) {
        return Boolean.parseBoolean(value);
    }

    private static String capitalize(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }
        return str.substring(0, 1).toUpperCase() + str.substring(1);
    }
}

