public class DurationImpl extends Duration implements Serializable {
    private int years;
    private int months;
    private int days;
    private int hours;
    private int minutes;
    private int seconds;

    public DurationImpl(boolean isNegative, int years, int months, int days, int hours, int minutes, int seconds) {
        if (years < 0 || months < 0 || days < 0 || hours < 0 || minutes < 0 || seconds < 0) {
            throw new IllegalArgumentException("Duration fields must be non-negative");
        }
        this.years = isNegative ? -years : years;
        this.months = isNegative ? -months : months;
        this.days = isNegative ? -days : days;
        this.hours = isNegative ? -hours : hours;
        this.minutes = isNegative ? -minutes : minutes;
        this.seconds = isNegative ? -seconds : seconds;
    }

    public DurationImpl(long milliseconds) {
