    public DurationImpl add(DurationImpl other) {
        return new DurationImpl(
            this.years + other.years,
            this.months + other.months,
            this.days + other.days,
            this.hours + other.hours,
            this.minutes + other.minutes,
            this.seconds + other.seconds
        );
    }

    public DurationImpl subtract(DurationImpl other) {
        return new DurationImpl(
            this.years - other.years,
            this.months - other.months,
            this.days - other.days,
            this.hours - other.hours,
            this.minutes - other.minutes,
            this.seconds - other.seconds
        );
    }

    public DurationImpl multiply(int factor) {
        return new DurationImpl(
            this.years * factor,
            this.months * factor,
            this.days * factor,
            this.hours * factor,
            this.minutes * factor,
            this.seconds * factor
        );
    }

    public boolean isEqual(DurationImpl other) {
        return this.years == other.years &&
               this.months == other.months &&
               this.days == other.days &&
               this.hours == other.hours &&
               this.minutes == other.minutes &&
               this.seconds == other.seconds;
    }

    public String toString() {
        return String.format("%d years, %d months, %d days, %d hours, %d minutes, %d seconds",
                             years, months, days, hours, minutes, seconds);
    }

