public class UnflattenProcessor {
    private List<InlineArea> ilNew = new ArrayList<>();
    private Stack<InlineContainer> originalInlineParents = new Stack<>();
    private Stack<InlineContainer> newInlineParents = new Stack<>();

    public List<InlineArea> process(List<InlineArea> inlineAreas) {
        for (InlineArea area : inlineAreas) {
            processInlineArea(area);
        }
        return ilNew;
    }

    private void processInlineArea(InlineArea area) {
        if (area instanceof InlineContainer) {
            InlineContainer container = (InlineContainer) area;
            startNewInlineContainer(container);
            for (InlineArea child : container.getChildren()) {
                processInlineArea(child);
            }
            finishInlineContainer(container);
        } else {
            updateTextArea(area);
        }
    }

    private void startNewInlineContainer(InlineContainer container) {
        originalInlineParents.push(container);
        InlineContainer newContainer = new InlineContainer(container.getProperties());
        newInlineParents.push(newContainer);
        ilNew.add(newContainer);
    }

    private void finishInlineContainer(InlineContainer container) {
        newInlineParents.pop();
        originalInlineParents.pop();
    }

    private void updateTextArea(InlineArea area) {
        if (newInlineParents.isEmpty()) {
            return;
        }
        InlineContainer currentContainer = newInlineParents.peek();
        currentContainer.addChild(area);
    }
}

