public class ProcessorServiceHandler implements ServiceHandler {
    private List<Processor> processors = new ArrayList<>();

    public ProcessorServiceHandler() {
        // Initialize processors
        initializeProcessors();
    }

    private void initializeProcessors() {
        // Code smell: Hardcoded initialization, could be improved with dependency injection
        processors.add(new MetadataProcessor());
        processors.add(new ServiceDocumentProcessor());
        processors.add(new EntityProcessor());
        processors.add(new MediaStreamProcessor());
        // Add more processors as needed
    }

    @Override
    public void handleRequest(Request request) throws UnsupportedOperationException {
        switch (request.getHttpMethod()) {
            case "GET":
                handleGetRequest(request);
                break;
            case "POST":
                handlePostRequest(request);
                break;
            case "PUT":
                handlePutRequest(request);
                break;
            case "DELETE":
                handleDeleteRequest(request);
                break;
            default:
                throw new UnsupportedOperationException("HTTP method not supported: " + request.getHttpMethod());
        }
    }

    private void handleGetRequest(Request request) {
        if (request.isMetadataRequest()) {
            processMetadataRequest(request);
        } else if (request.isServiceDocumentRequest()) {
            processServiceDocumentRequest(request);
        } else {
            processEntityRequest(request);
        }
    }

    private void handlePostRequest(Request request) {
        // Code smell: Method too long, could be broken down into smaller methods
        processEntityCreation(request);
    }

    private void handlePutRequest(Request request) {
        // Code smell: Method too long, could be broken down into smaller methods
        processEntityUpdate(request);
    }

    private void handleDeleteRequest(Request request) {
        // Code smell: Method too long, could be broken down into smaller methods
        processEntityDeletion(request);
    }

    private void processMetadataRequest(Request request) {
        for (Processor processor : processors) {
            if (processor.canHandleMetadata()) {
                processor.processMetadata(request);
                return;
            }
        }
        throw new UnsupportedOperationException("No processor available for metadata requests.");
    }

    private void processServiceDocumentRequest(Request request) {
        for (Processor processor : processors) {
            if (processor.canHandleServiceDocument()) {
                processor.processServiceDocument(request);
