    public void tearDown() throws Exception {
        tempFolder.delete();
    }

    @Test
    public void testCreateFile() throws IOException {
        File file = tempFolder.newFile("testFile.txt");
        assertTrue(localFileSystem.createFile(file.getAbsolutePath()));
        assertTrue(file.exists());
    }

    @Test
    public void testReadFile() throws IOException {
        File file = tempFolder.newFile("testFile.txt");
        Files.writeString(file.toPath(), "Hello, World!");
        String content = localFileSystem.readFile(file.getAbsolutePath());
        assertEquals("Hello, World!", content);
