        File sourceFile = tempFolder.newFile("sourceFile.txt");
        Files.writeString(sourceFile.toPath(), "Copy this content");
        File destFile = new File(tempFolder.getRoot(), "destFile.txt");
        localFileSystem.copyFile(sourceFile.getAbsolutePath(), destFile.getAbsolutePath());
        assertTrue(destFile.exists());
        assertEquals("Copy this content", localFileSystem.readFile(destFile.getAbsolutePath()));
    }

    @Test
    public void testMoveFile() throws IOException {
        File sourceFile = tempFolder.newFile("sourceFile.txt");
        File destFile = new File(tempFolder.getRoot(), "destFile.txt");
        localFileSystem.moveFile(sourceFile.getAbsolutePath(), destFile.getAbsolutePath());
        assertFalse(sourceFile.exists());
        assertTrue(destFile.exists());
    }

    @Test
    public void testDeleteFile() throws IOException {
        File file = tempFolder.newFile("testFile.txt");
        localFileSystem.deleteFile(file.getAbsolutePath());
        assertFalse(file.exists());
    }

    @Test
    public void testMatchFileContent() throws IOException {
        File file = tempFolder.newFile("testFile.txt");
        Files.writeString(file.toPath(), "Match this content");
        assertTrue(localFileSystem.matchFileContent(file.getAbsolutePath(), "Match this content"));
        assertFalse(localFileSystem.matchFileContent(file.getAbsolutePath(), "Different content"));
    }

    @Test(expected = IOException.class)
    public void testReadNonExistentFile() throws IOException {
        localFileSystem.readFile("nonExistentFile.txt");
    }

    @Test(expected = IOException.class)
    public void testDeleteNonExistentFile() throws IOException {
        localFileSystem.deleteFile("nonExistentFile.txt");
    }
}

