    private NameServer nameServer;
    private NameLookupClient nameLookupClient;
    private ExecutorService executorService;

    @BeforeEach
    public void setUp() {
        try {
            nameServer = new NameServer();
            nameLookupClient = new NameLookupClient(nameServer);
            executorService = Executors.newCachedThreadPool();
        } catch (Exception e) {
            logger.severe("Failed to set up test environment: " + e.getMessage());
        }
    }

    @AfterEach
    public void tearDown() {
        try {
            nameServer.shutdown();
            nameLookupClient.shutdown();
            executorService.shutdown();
        } catch (Exception e) {
            logger.severe("Failed to tear down test environment: " + e.getMessage());
        }
    }

    @Test
    public void testRegisterAndLookup() {
        String identifier = "serviceA";
        String address = "192.168.1.1";

        nameServer.register(identifier, address);
        String result = nameLookupClient.lookup(identifier);

        assertEquals(address, result);
        logger.info("testRegisterAndLookup passed");
    }

    @Test
    public void testUnregister() {
        String identifier = "serviceB";
        String address = "192.168.1.2";

        nameServer.register(identifier, address);
        nameServer.unregister(identifier);
        String result = nameLookupClient.lookup(identifier);

        assertNull(result);
        logger.info("testUnregister passed");
    }

    @Test
    public void testConcurrentLookups() throws Exception {
        String identifier = "serviceC";
        String address = "192.168.1.3";
        nameServer.register(identifier, address);

        Future<String> future1 = executorService.submit(() -> nameLookupClient.lookup(identifier));
        Future<String> future2 = executorService.submit(() -> nameLookupClient.lookup(identifier));

        assertEquals(address, future1.get());
        assertEquals(address, future2.get());
        logger.info("testConcurrentLookups passed");
    }

    @Test
    public void testConsistency() {
        String identifier = "serviceD";
        String address1 = "192.168.1.4";
        String address2 = "192.168.1.5";

        nameServer.register(identifier, address1);
        nameServer.register(identifier, address2); // Overwrite

        String result = nameLookupClient.lookup(identifier);
        assertEquals(address2, result);
        logger.info("testConsistency passed");
    }
}

