public class ImmutableBitSetTest {

    @Test
    public void testIteration() {
        ImmutableBitSet bitSet = ImmutableBitSet.of(1, 3, 5);
        String expected = "{1, 3, 5}";
        assertEquals(expected, bitSet.toString());
    }

    @Test
    public void testConversionToList() {
        ImmutableBitSet bitSet = ImmutableBitSet.of(1, 2, 3);
        List<Integer> expectedList = Arrays.asList(1, 2, 3);
        assertEquals(expectedList, bitSet.toList());
    }

    @Test
    public void testRangeCreation() {
        ImmutableBitSet bitSet = ImmutableBitSet.range(1, 5);
        String expected = "{1, 2, 3, 4}";
        assertEquals(expected, bitSet.toString());
    }

    @Test
    public void testComparison() {
        ImmutableBitSet bitSet1 = ImmutableBitSet.of(1, 2);
        ImmutableBitSet bitSet2 = ImmutableBitSet.of(1, 2);
        assertTrue(bitSet1.equals(bitSet2));
    }

    @Test
    public void testArrayConversion() {
        ImmutableBitSet bitSet = ImmutableBitSet.of(0, 2, 4);
        int[] expectedArray = {0, 2, 4};
        assertArrayEquals(expectedArray, bitSet.toArray());
    }

    @Test
    public void testUnionAndIntersection() {
        ImmutableBitSet bitSet1 = ImmutableBitSet.of(1, 2);
        ImmutableBitSet bitSet2 = ImmutableBitSet.of(2, 3);
        assertEquals(ImmutableBitSet.of(1, 2, 3), bitSet1.union(bitSet2));
        assertEquals(ImmutableBitSet.of(2), bitSet1.intersection(bitSet2));
    }

    @Test
    public void testContainment() {
        ImmutableBitSet bitSet1 = ImmutableBitSet.of(1, 2, 3);
        ImmutableBitSet bitSet2 = ImmutableBitSet.of(2);
        assertTrue(bitSet1.contains(bitSet2));
    }

    @Test
    public void testBuilderPattern() {
        ImmutableBitSet bitSet = ImmutableBitSet.builder().add(1).add(2).build();
        String expected = "{1, 2}";
        assertEquals(expected, bitSet.toString());
    }

    @Test
    public void testIndexing() {
        ImmutableBitSet bitSet = ImmutableBitSet.of(0, 2, 4);
        assertEquals(2, bitSet.get(1));
    }

    @Test
    public void testPowerSet() {
        ImmutableBitSet bitSet = ImmutableBitSet.of(1, 2);
        Set<ImmutableBitSet> expectedPowerSet = Set.of(
            ImmutableBitSet.of(),
            ImmutableBitSet.of(1),
            ImmutableBitSet.of(2),
            ImmutableBitSet.of(1, 2)
        );
        assertEquals(expectedPowerSet, bitSet.powerSet());
    }

    @Test
    public void testLongConversion() {
        ImmutableBitSet bitSet = ImmutableBitSet.fromLong(5); // 101 in binary
        String expected = "{0, 2}";
        assertEquals(expected, bitSet.toString());
    }

    @Test
    public void testSetAndClearOperations() {
        ImmutableBitSet bitSet = ImmutableBitSet.of(1, 2);
        bitSet.set(3);
        assertTrue(bitSet.contains(3));
        bitSet.clear(2);
        assertFalse(bitSet.contains(2));
    }

    @Test
    public void testShifting() {
        ImmutableBitSet bitSet = ImmutableBitSet.of(1, 2);
        ImmutableBitSet shifted = bitSet.shiftLeft(1);
        String expected = "{2, 3}";
        assertEquals(expected, shifted.toString());
    }

    @Test
    public void testGettingSubsets() {
        ImmutableBitSet bitSet = ImmutableBitSet.of(0, 1, 2, 3);
        ImmutableBitSet subset = bitSet.subset(1, 3);
        String expected = "{1, 2}";
        assertEquals(expected, subset.toString());
    }
}

