public class ConjugateGradientTest {

    @Test(expected = NonSquareOperatorException.class)
    public void testNonSquareOperator() {
        // Setup non-square matrix
        double[][] nonSquareMatrix = {{1, 2}, {3, 4}, {5, 6}};
        double[] rhs = {1, 2, 3};
        ConjugateGradient.solve(nonSquareMatrix, rhs);
    }

    @Test(expected = DimensionMismatchException.class)
    public void testDimensionMismatch() {
        // Setup square matrix and mismatched rhs
        double[][] squareMatrix = {{1, 2}, {3, 4}};
        double[] rhs = {1, 2, 3}; // Mismatched dimensions
        ConjugateGradient.solve(squareMatrix, rhs);
    }

    @Test(expected = NonPositiveDefiniteOperatorException.class)
    public void testNonPositiveDefiniteOperator() {
        // Setup non-positive definite matrix
        double[][] nonPositiveDefiniteMatrix = {{0, 1}, {1, 0}};
        double[] rhs = {1, 2};
        ConjugateGradient.solve(nonPositiveDefiniteMatrix, rhs);
    }

    @Test
    public void testUnpreconditionedSolutions() {
        // Setup square matrix and rhs
        double[][] squareMatrix = {{4, 1}, {1, 3}};
        double[] rhs = {1, 2};
        double[] expectedSolution = {0.1, 0.5};
        double[] solution = new double[2];
        ConjugateGradient.solve(squareMatrix, rhs, solution);
        assertArrayEquals(expectedSolution, solution, 1e-5);
    }

    @Test
    public void testInPlaceSolutionsWithInitialGuesses() {
        // Setup square matrix and rhs
        double[][] squareMatrix = {{4, 1}, {1, 3}};
        double[] rhs = {1, 2};
        double[] initialGuess = {0, 0};
        double[] expectedSolution = {0.1, 0.5};
        ConjugateGradient.solve(squareMatrix, rhs, initialGuess);
        assertArrayEquals(expectedSolution, initialGuess, 1e-5);
    }

    @Test
    public void testResidualCalculations() {
        // Setup square matrix and rhs
        double[][] squareMatrix = {{4, 1}, {1, 3}};
        double[] rhs = {1, 2};
        double[] solution = new double[2];
        ConjugateGradient.solve(squareMatrix, rhs, solution);
        double[] residual = ConjugateGradient.calculateResidual(squareMatrix, rhs, solution);
        double expectedNorm = Math.sqrt(Math.pow(residual[0], 2) + Math.pow(residual[1], 2));
        assertEquals(expectedNorm, 0, 1e-5);
    }

    @Test
    public void testPreconditionedSolutions() {
        // Setup square matrix and rhs
        double[][] squareMatrix = {{4, 1}, {1, 3}};
        double[] rhs = {1, 2};
        double[] expectedSolution = {0.1, 0.5};
        double[] solution = new double[2];
        Preconditioner preconditioner = new JacobiPreconditioner(squareMatrix);
        ConjugateGradient.solve(squareMatrix, rhs, solution, preconditioner);
        assertArrayEquals(expectedSolution, solution, 1e-5);
    }

    @Test
    public void testEventManagement() {
        // Setup square matrix and rhs
        double[][] squareMatrix = {{4, 1}, {1, 3}};
        double[] rhs = {1, 2};
        double[] solution = new double[2];
        IterationListener listener = new IterationListener();
        ConjugateGradient.solve(squareMatrix, rhs, solution, listener);
        assertTrue(listener.isEventTriggered());
    }

    @Test
    public void testNormOfResidual() {
        // Setup square matrix and rhs
        double[][] squareMatrix = {{4, 1}, {1, 3}};
        double[] rhs = {1, 2};
        double[] solution = new double[2];
        ConjugateGradient.solve(squareMatrix, rhs, solution);
        double norm = ConjugateGradient.normOfResidual(squareMatrix, rhs, solution);
        assertEquals(0, norm, 1e-5);
    }
}

