        assertTrue(valuesHandler.hasVariable("var5"));
        assertTrue(valuesHandler.hasVariable("var6"));
        assertEquals("value1", valuesHandler.getVariableValue("var5"));
        assertEquals(Arrays.asList("value2", "value3"), valuesHandler.getVariableValue("var6"));
    }

    @Test
