public class MailConsumer {
    private static final Logger logger = Logger.getLogger(MailConsumer.class.getName());
    private final String host;
    private final String username;
    private final String password;
    private final String folderName;
    private final boolean fetchUnseen;
    private final boolean deleteAfterProcessing;
    private final long pollingInterval;
    private Store store;
    private Folder folder;

    public MailConsumer(String host, String username, String password, String folderName, boolean fetchUnseen, boolean deleteAfterProcessing, long pollingInterval) {
        this.host = host;
        this.username = username;
        this.password = password;
        this.folderName = folderName;
        this.fetchUnseen = fetchUnseen;
        this.deleteAfterProcessing = deleteAfterProcessing;
        this.pollingInterval = pollingInterval;
    }

    public void start() {
        Timer timer = new Timer(true);
        timer.scheduleAtFixedRate(new TimerTask() {
            @Override
            public void run() {
                try {
                    connect();
                    processMessages();
                } catch (Exception e) {
                    logger.log(Level.SEVERE, "Error during mail processing", e);
                } finally {
                    disconnect();
                }
            }
        }, 0, pollingInterval);
    }

    private void connect() throws Exception {
        Properties properties = new Properties();
        properties.put("mail.store.protocol", "imaps");
        Session session = Session.getInstance(properties);
        store = session.getStore();
        store.connect(host, username, password);
        folder = store.getFolder(folderName);
        folder.open(Folder.READ_WRITE);
    }

    private void processMessages() throws Exception {
        Message[] messages;
        if (fetchUnseen) {
            messages = folder.search(new FlagTerm(new Flags(Flags.Flag.SEEN), false));
        } else {
            messages = folder.getMessages();
        }

        for (Message message : messages) {
            processMessage(message);
            if (deleteAfterProcessing) {
                message.setFlag(Flags.Flag.DELETED, true);
            } else {
                message.setFlag(Flags.Flag.SEEN, true);
            }
        }
        folder.expunge();
    }

    private void processMessage(Message message) throws Exception {
        if (message instanceof MimeMessage) {
            String subject = message.getSubject();
            String from = message.getFrom()[0].toString();
            logger.info("Processing message from: " + from + ", subject: " + subject);
            // Add your message processing logic here
        }
    }

    private void disconnect() {
        try {
            if (folder != null && folder.isOpen()) {
                folder.close(true);
            }
            if (store != null && store.isConnected()) {
                store.close();
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error during disconnecting", e);
        }
    }

    public static void main(String[] args) {
        MailConsumer mailConsumer = new MailConsumer("imap.example.com", "user@example.com", "password", "INBOX", true, false, 60000);
        mailConsumer.start();
    }
}

public class ParquetOutputFormat<T> extends FileOutputFormat<Void, T> {

    public static final String BLOCK_SIZE = "parquet.block.size";
    public static final String PAGE_SIZE = "parquet.page.size";
    public static final String COMPRESSION = "parquet.compression";
    public static final String USE_DICTIONARY = "parquet.use.dictionary";
    public static final String VALIDATE = "parquet.validate";
    public static final String MEMORY_MANAGEMENT = "parquet.memory.management";

    private CompressionCodecName compressionCodecName;
    private boolean useDictionary;
    private boolean validate;
    private long blockSize;
    private long pageSize;

    public ParquetOutputFormat() {
        // Default values
        this.blockSize = ParquetWriter.DEFAULT_BLOCK_SIZE;
        this.pageSize = ParquetWriter.DEFAULT_PAGE_SIZE;
        this.compressionCodecName = CompressionCodecName.UNCOMPRESSED;
        this.useDictionary = true;
        this.validate = true;
    }

    public static void setBlockSize(Job job, long blockSize) {
        job.getConfiguration().setLong(BLOCK_SIZE, blockSize);
    }

    public static void setPageSize(Job job, long pageSize) {
        job.getConfiguration().setLong(PAGE_SIZE, pageSize);
    }

    public static void setCompression(Job job, CompressionCodecName codec) {
        job.getConfiguration().set(COMPRESSION, codec.name());
    }

    public static void setUseDictionary(Job job, boolean useDictionary) {
        job.getConfiguration().setBoolean(USE_DICTIONARY, useDictionary);
    }

    public static void setValidate(Job job, boolean validate) {
        job.getConfiguration().setBoolean(VALIDATE, validate);
    }

    public static void setMemoryManagement(Job job, boolean memoryManagement) {
        job.getConfiguration().setBoolean(MEMORY_MANAGEMENT, memoryManagement);
    }

    @Override
    public org.apache.hadoop.mapreduce.RecordWriter<Void, T> getRecordWriter(TaskAttemptContext context) {
        // Implementation of record writer creation
        return new ParquetRecordWriter<>(getOutputPath(context), compressionCodecName, blockSize, pageSize, useDictionary, validate);
    }

    @Override
    public Path getDefaultWorkFile(TaskAttemptContext context, String extension) {
        return new Path(getOutputPath(context), "part-" + context.getTaskAttemptID().toString() + extension);
    }

    private Path getOutputPath(TaskAttemptContext context) {
        return getOutputPath(context.getConfiguration());
    }

    private Path getOutputPath(Configuration configuration) {
        // Logic to retrieve output path from configuration
        return new Path(configuration.get("output.path"));
    }
}

