        for (int i = 0; i < array.length; i++) {
            scaledArray[i] = array[i] * factor;
        }
        return scaledArray;
    }

    public static double[] add(double[] a, double[] b) {
        checkDimensions(a, b);
        double[] result = new double[a.length];
        for (int i = 0; i < a.length; i++) {
            result[i] = a[i] + b[i];
        }
        return result;
    }

    public static double[] subtract(double[] a, double[] b) {
        checkDimensions(a, b);
        double[] result = new double[a.length];
        for (int i = 0; i < a.length; i++) {
            result[i] = a[i] - b[i];
        }
        return result;
    }

    public static double[] multiply(double[] a, double[] b) {
        checkDimensions(a, b);
        double[] result = new double[a.length];
        for (int i = 0; i < a.length; i++) {
            result[i] = a[i] * b[i];
        }
        return result;
    }

    public static double[] divide(double[] a, double[] b) {
        checkDimensions(a, b);
        double[] result = new double[a.length];
        for (int i = 0; i < a.length; i++) {
            if (b[i] == 0) {
                throw new ArithmeticException("Division by zero");
            }
            result[i] = a[i] / b[i];
        }
        return result;
    }

    public static double l1Distance(double[] a, double[] b) {
        checkDimensions(a, b);
        double sum = 0;
        for (int i = 0; i < a.length; i++) {
            sum += Math.abs(a[i] - b[i]);
        }
        return sum;
    }

    public static double l2Distance(double[] a, double[] b) {
        checkDimensions(a, b);
        double sum = 0;
        for (int i = 0; i < a.length; i++) {
            sum += Math.pow(a[i] - b[i], 2);
        }
        return Math.sqrt(sum);
    }

    public static double infinityDistance(double[] a, double[] b) {
        checkDimensions(a, b);
        double maxDiff = 0;
        for (int i = 0; i < a.length; i++) {
            maxDiff = Math.max(maxDiff, Math.abs(a[i] - b[i]));
        }
        return maxDiff;
    }

    public static boolean isMonotonicIncreasing(double[] array, boolean strict) {
        for (int i = 1; i < array.length; i++) {
            if (strict ? array[i] <= array[i - 1] : array[i] < array[i - 1]) {
                return false;
            }
        }
        return true;
    }

    public static boolean isMonotonicDecreasing(double[] array, boolean strict) {
        for (int i = 1; i < array.length; i++) {
            if (strict ? array[i] >= array[i - 1] : array[i] > array[i - 1]) {
                return false;
            }
        }
        return true;
    }

    public static void checkDimensions(double[] a, double[] b) {
        if (a.length != b.length) {
            throw new IllegalArgumentException("Array dimensions must match");
        }
    }

    public static void sort(double[] array) {
        Arrays.sort(array);
    }

    public static void sortWithAssociated(double[] array, double[] associated) {
        if (array.length != associated.length) {
            throw new IllegalArgumentException("Array dimensions must match");
        }
        Integer[] indices = new Integer[array.length];
        for (int i = 0; i < array.length; i++) {
            indices[i] = i;
        }
        Arrays.sort(indices, (i1, i2) -> Double.compare(array[i1], array[i2]));
        double[] sortedArray = new double[array.length];
        double[] sortedAssociated = new double[associated.length];
        for (int i = 0; i < indices.length; i++) {
            sortedArray[i] = array[indices[i]];
            sortedAssociated[i] = associated[indices[i]];
        }
        System.arraycopy(sortedArray, 0, array, 0, array.length);
        System.arraycopy(sortedAssociated, 0, associated, 0, associated.length);
    }

    public static double[] copy(double[] array) {
        return Arrays.copyOf(array, array.length);
    }

    public static int[] copy(int[] array) {
        return Arrays.copyOf(array, array.length);
    }

    public static double[] linearCombination(double[] a, double[] b, double alpha, double beta) {
        checkDimensions(a, b);
        double[] result = new double[a.length];
        for (int i = 0; i < a.length; i++) {
            result[i] = alpha * a[i] + beta * b[i];
        }
        return result;
    }

    public static double[] normalize(double[] array, double targetSum) {
        double currentSum = Arrays.stream(array).sum();
        if (currentSum == 0) {
            throw new ArithmeticException("Cannot normalize an array with a sum of zero");
        }
        double[] normalizedArray = new double[array.length];
        for (int i = 0; i < array.length; i++) {
            normalizedArray[i] = (array[i] / currentSum) * targetSum;
        }
        return normalizedArray;
    }

    public static double[] convolve(double[] a, double[] b) {
        double[] result = new double[a.length + b.length - 1];
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < b.length; j++) {
                result[i + j] += a[i] * b[j];
            }
        }
        return result;
    }

    public static void shuffle(double[] array, Random random) {
        for (int i = array.length - 1; i > 0; i--) {
            int j = random.nextInt(i + 1);
            double temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }

    public static double[] createArray(int length) {
        return new double[length];
    }

    public static int[] createIntArray(int length) {
        return new int[length];
    }

    public static void verifyPositive(double[] array) {
        for (double v : array) {
            if (v < 0) {
                throw new IllegalArgumentException("Array contains non-positive values");
            }
        }
    }

    public static void verifyNonEmpty(double[] array) {
        if (array.length == 0) {
            throw new IllegalArgumentException("Array must not be empty");
        }
    }

    public static void verifyDimensions(double[] array, int expectedLength) {
        if (array.length != expectedLength) {
            throw new IllegalArgumentException("Array length must be " + expectedLength);
        }
    }
}

