public class MoveImportNodeAction extends CayenneAction {
    private DefaultMutableTreeNode sourceTree;
    private DefaultMutableTreeNode targetTree;
    private Map<String, Object> includedClasses;
    private Map<String, Object> excludedClasses;

    public MoveImportNodeAction(DefaultMutableTreeNode sourceTree, DefaultMutableTreeNode targetTree) {
        this.sourceTree = sourceTree;
        this.targetTree = targetTree;
        this.includedClasses = new HashMap<>();
        this.excludedClasses = new HashMap<>();
    }

    public void moveNodes(List<DefaultMutableTreeNode> nodesToMove) {
        for (DefaultMutableTreeNode node : nodesToMove) {
            if (canInsertNode(node)) {
                targetTree.add(node);
                sourceTree.remove(node);
                updateUI();
            }
        }
    }

    private boolean canInsertNode(DefaultMutableTreeNode node) {
        String nodeName = ((NodeInfo) node.getUserObject()).getName();
        return !excludedClasses.containsKey(nodeName) && includedClasses.containsKey(nodeName);
    }

    private void updateUI() {
        // Code to refresh the user interface
    }

    public void undoMove(List<DefaultMutableTreeNode> nodesToUndo) {
        for (DefaultMutableTreeNode node : nodesToUndo) {
            targetTree.remove(node);
            sourceTree.add(node);
            updateUI();
        }
    }

    public void includeClass(String className, Object classObject) {
        includedClasses.put(className, classObject);
    }

    public void excludeClass(String className, Object classObject) {
        excludedClasses.put(className, classObject);
    }
}

