    private boolean debug = false;
    private NotificationHandler notificationHandler;

    public Telnet(Socket socket) throws Exception {
        this.inputStream = socket.getInputStream();
        this.outputStream = socket.getOutputStream();
    }

    public void setDebug(boolean debug) {
        this.debug = debug;
    }

    public void setNotificationHandler(NotificationHandler handler) {
        this.notificationHandler = handler;
    }

    public void registerOptionHandler(int option, OptionHandler handler) {
        optionHandlers.put(option, handler);
    }

    public void unregisterOptionHandler(int option) {
        optionHandlers.remove(option);
    }

    public void sendCommand(byte command, int option) throws Exception {
        outputStream.write(IAC);
        outputStream.write(command);
        outputStream.write(option);
        if (debug) {
            System.out.println("Sent: " + command + " for option " + option);
        }
    }

    public void receiveData() throws Exception {
        int ch;
        while ((ch = inputStream.read()) != -1) {
            if (ch == IAC) {
                int next = inputStream.read();
                handleCommand(next);
            } else {
                // Handle normal data
            }
        }
    }

    private void handleCommand(int command) throws Exception {
        switch (command) {
            case DO:
            case DONT:
            case WILL:
            case WONT:
                int option = inputStream.read();
                handleOption(command, option);
                break;
            default:
                // Handle unknown command
                break;
        }
    }

    private void handleOption(int command, int option) throws Exception {
        OptionHandler handler = optionHandlers.get(option);
        if (handler != null) {
            switch (command) {
                case DO:
                    handler.handleDo();
                    break;
                case DONT:
                    handler.handleDont();
                    break;
                case WILL:
                    handler.handleWill();
                    break;
                case WONT:
                    handler.handleWont();
                    break;
            }
            if (notificationHandler != null) {
                notificationHandler.notify(option, command);
            }
        }
    }

    public interface OptionHandler {
        void handleDo() throws Exception;
        void handleDont() throws Exception;
        void handleWill() throws Exception;
        void handleWont() throws Exception;
    }

    public interface NotificationHandler {
        void notify(int option, int command);
    }
}

