public class AssignmentInfo {
    private int version;
    private String[] activeTasks;
    private String[] standbyTasks;
    private String[] topicPartitions;
    private String[] hosts;

    public AssignmentInfo(int version, String[] activeTasks, String[] standbyTasks, String[] topicPartitions, String[] hosts) {
        this.version = version;
        this.activeTasks = activeTasks;
        this.standbyTasks = standbyTasks;
        this.topicPartitions = topicPartitions;
        this.hosts = hosts;
    }

    public AssignmentInfo(byte[] data) {
        decode(data);
    }

    public byte[] encode() {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        buffer.putInt(version);
        buffer.putInt(activeTasks.length);
        for (String task : activeTasks) {
            buffer.put(task.getBytes());
            buffer.put((byte) 0); // null terminator
        }
        buffer.putInt(standbyTasks.length);
        for (String task : standbyTasks) {
            buffer.put(task.getBytes());
            buffer.put((byte) 0); // null terminator
        }
        buffer.putInt(topicPartitions.length);
        for (String partition : topicPartitions) {
            buffer.put(partition.getBytes());
            buffer.put((byte) 0); // null terminator
        }
        buffer.putInt(hosts.length);
        for (String host : hosts) {
            buffer.put(host.getBytes());
            buffer.put((byte) 0); // null terminator
        }
        return Arrays.copyOf(buffer.array(), buffer.position());
    }

    public void decode(byte[] data) {
        ByteBuffer buffer = ByteBuffer.wrap(data);
        this.version = buffer.getInt();
        int activeTasksLength = buffer.getInt();
        this.activeTasks = new String[activeTasksLength];
        for (int i = 0; i < activeTasksLength; i++) {
            this.activeTasks[i] = readString(buffer);
        }
        int standbyTasksLength = buffer.getInt();
        this.standbyTasks = new String[standbyTasksLength];
        for (int i = 0; i < standbyTasksLength; i++) {
            this.standbyTasks[i] = readString(buffer);
        }
        int topicPartitionsLength = buffer.getInt();
        this.topicPartitions = new String[topicPartitionsLength];
        for (int i = 0; i < topicPartitionsLength; i++) {
            this.topicPartitions[i] = readString(buffer);
        }
        int hostsLength = buffer.getInt();
        this.hosts = new String[hostsLength];
        for (int i = 0; i < hostsLength; i++) {
            this.hosts[i] = readString(buffer);
        }
    }

    private String readString(ByteBuffer buffer) {
        StringBuilder sb = new StringBuilder();
        while (true) {
            byte b = buffer.get();
            if (b == 0) break;
            sb.append((char) b);
        }
        return sb.toString();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof AssignmentInfo)) return false;
        AssignmentInfo that = (AssignmentInfo) o;
        return version == that.version &&
                Arrays.equals(activeTasks, that.activeTasks) &&
                Arrays.equals(standbyTasks, that.standbyTasks) &&
                Arrays.equals(topicPartitions, that.topicPartitions) &&
                Arrays.equals(hosts, that.hosts);
    }

    @Override
    public int hashCode() {
        return Objects.hash(version, Arrays.hashCode(activeTasks), Arrays.hashCode(standbyTasks), Arrays.hashCode(topicPartitions), Arrays.hashCode(hosts));
    }

    @Override
    public String toString() {
        return "AssignmentInfo{" +
                "version=" + version +
                ", activeTasks=" + Arrays.toString(activeTasks) +
                ", standbyTasks=" + Arrays.toString(standbyTasks) +
                ", topicPartitions=" + Arrays.toString(topicPartitions) +
                ", hosts=" + Arrays.toString(hosts) +
                '}';
    }
}

public class DefaultVertex implements Vertex, Trimmable {
    private String id;
    private Object value;
    private List<Edge> edges;
    private boolean isHalted;

    public DefaultVertex(String id) {
        this.id = id;
        this.edges = new ArrayList<>();
        this.isHalted = false;
    }

    public String getId() {
        return id;
    }

    public Object getValue() {
        return value;
    }

    public void setValue(Object value) {
        this.value = value;
    }

    public List<Edge> getEdges() {
        return edges;
    }

    public void addEdge(Edge edge) {
        edges.add(edge);
    }

    public void removeEdge(Edge edge) {
        edges.remove(edge);
    }

    public int getEdgeCount() {
        return edges.size();
    }

    public List<Object> getEdgeValues() {
        List<Object> edgeValues = new ArrayList<>();
        for (Edge edge : edges) {
            edgeValues.add(edge.getValue());
        }
        return edgeValues;
    }

    public void halt() {
        isHalted = true;
    }

    public void activate() {
        isHalted = false;
    }

    public boolean isHalted() {
        return isHalted;
    }

    @Override
    public void trim() {
        edges.removeIf(edge -> edge.isTrimmable() && edge.shouldTrim());
    }

    @Override
    public String toString() {
        return "DefaultVertex{id='" + id + "', value=" + value + ", edges=" + edges + ", isHalted=" + isHalted + "}";
    }
}

class Base64CodecTest {

    private final Base64Codec codec = new Base64Codec();

    @Test
    public void testEncodeSimpleString() {
        String input = "Hello World";
        String expected = "SGVsbG8gV29ybGQ=";
        String actual = codec.encode(input.getBytes());
        assertEquals(expected, actual);
    }

    @Test
    public void testDecodeWithPadding() {
        String input = "SGVsbG8gV29ybGQ=";
        String expected = "Hello World";
        byte[] actual = codec.decode(input);
        assertArrayEquals(expected.getBytes(), actual);
    }

    @Test
    public void testDecodeOnlyPadding() {
        String input = "====";
        byte[] actual = codec.decode(input);
        assertArrayEquals(new byte[0], actual);
    }

    @Test
    public void testEncodeDecodeRandomBytes() {
        byte[] randomBytes = new byte[256];
        new java.util.Random().nextBytes(randomBytes);
        String encoded = codec.encode(randomBytes);
        byte[] decoded = codec.decode(encoded);
        assertArrayEquals(randomBytes, decoded);
    }

    @Test
    public void testChunkingBehavior() {
        String input = "This is a test string that exceeds the chunk size limit.";
        String expected = "VGhpcyBpcyBhIHRlc3Qgc3RyaW5nIHRoYXQgZXhjZWVkcyB0aGUgY2h1bmt\n" +
                          "zaXplIGxpbWl0Lg==";
        String actual = codec.encode(input.getBytes());
        assertEquals(expected, actual);
    }

    @Test
    public void testKnownStringEncoding() {
        String input = "Test";
        String expected = "VGVzdA==";
        String actual = codec.encode(input.getBytes());
        assertEquals(expected, actual);
    }

    @Test
    public void testIgnoreNonBase64Characters() {
        String input = "SGVsbG8gV29ybGQ!@#$%^&*()";
        String expected = "Hello World";
        byte[] actual = codec.decode(input);
        assertArrayEquals(expected.getBytes(), actual);
    }

    @Test
    public void testWhitespaceInEncodedString() {
        String input = "SGV sbG8g V29y bGQ=";
        String expected = "Hello World";
        byte[] actual = codec.decode(input.replaceAll("\\s+", ""));
        assertArrayEquals(expected.getBytes(), actual);
    }
}

