        assertEquals(new Datum(12, DatumType.INT4), int4.multiply(int8));
        assertEquals(new Datum(12, DatumType.INT8), int8.multiply(int4));
        assertEquals(new Datum(12.0f, DatumType.FLOAT4), float4.multiply(float8));
        assertEquals(new Datum(12.0, DatumType.FLOAT8), float8.multiply(float4));
