        Datum float4 = new Datum(8.0f, DatumType.FLOAT4);
        Datum float8 = new Datum(2.0, DatumType.FLOAT8);

        assertEquals(new Datum(4, DatumType.INT4), int4.divide(int8));
        assertEquals(new Datum(4, DatumType.INT8), int8.divide(int4));
        assertEquals(new Datum(4.0f, DatumType.FLOAT4), float4.divide(float8));
