public class ProfilerGenerator extends ServiceableGenerator {
    private Profiler profiler;

    public ProfilerGenerator() {
        this.profiler = new Profiler();
    }

    public String generateXML(Map<String, String> requestParams) {
        StringBuilder xmlBuilder = new StringBuilder();
        xmlBuilder.append("<profilingReport>");

        if (requestParams.containsKey("keys")) {
            String[] keys = requestParams.get("keys").split(",");
            for (String key : keys) {
                xmlBuilder.append(generateFragment(key));
            }
        } else {
            xmlBuilder.append(generateCompleteReport());
        }

        xmlBuilder.append("</profilingReport>");
        return xmlBuilder.toString();
    }

    private String generateFragment(String key) {
        StringBuilder fragmentBuilder = new StringBuilder();
        fragmentBuilder.append("<fragment key=\"").append(key).append("\">");
        fragmentBuilder.append("<result>").append(profiler.getResult(key)).append("</result>");
        fragmentBuilder.append("<averageTime>").append(profiler.getAverageTime(key)).append("</averageTime>");
        fragmentBuilder.append("</fragment>");
        return fragmentBuilder.toString();
    }

    private String generateCompleteReport() {
        StringBuilder reportBuilder = new StringBuilder();
        reportBuilder.append("<completeReport>");
        reportBuilder.append("<environment>").append(profiler.getEnvironmentInfo()).append("</environment>");
        reportBuilder.append("<requestParameters>").append(getRequestParametersXML()).append("</requestParameters>");
        reportBuilder.append("<sessionAttributes>").append(getSessionAttributesXML()).append("</sessionAttributes>");
        reportBuilder.append("</completeReport>");
        return reportBuilder.toString();
    }

    private String getRequestParametersXML() {
        // Assume this method retrieves request parameters in XML format
        return "<param name=\"example\">value</param>";
    }

    private String getSessionAttributesXML() {
        // Assume this method retrieves session attributes in XML format
        return "<sessionAttribute name=\"example\">value</sessionAttribute>";
    }

    @Override
    public void dispose() {
        if (profiler != null) {
            profiler.cleanup();
        }
    }
}

public class WebBeansInterceptorConfig {
    private static final Logger logger = Logger.getLogger(WebBeansInterceptorConfig.class.getName());

    public void configureInterceptors(List<Class<?>> interceptorClasses) {
        for (Class<?> interceptorClass : interceptorClasses) {
            if (!isValidInterceptor(interceptorClass)) {
                logger.warning("Invalid interceptor class: " + interceptorClass.getName());
                continue;
            }
            setupInterceptor(interceptorClass);
        }
    }

    private boolean isValidInterceptor(Class<?> interceptorClass) {
        return interceptorClass.isAnnotationPresent(Interceptor.class);
    }

    private void setupInterceptor(Class<?> interceptorClass) {
        // Logic to setup interceptor
        if (hasAroundInvoke(interceptorClass)) {
            // Setup AroundInvoke logic
        }
        if (hasPostConstruct(interceptorClass)) {
            // Setup PostConstruct logic
        }
        if (hasPreDestroy(interceptorClass)) {
            // Setup PreDestroy logic
        }
    }

    private boolean hasAroundInvoke(Class<?> interceptorClass) {
        return hasMethodWithAnnotation(interceptorClass, AroundInvoke.class);
    }

    private boolean hasPostConstruct(Class<?> interceptorClass) {
        return hasMethodWithAnnotation(interceptorClass, PostConstruct.class);
    }

    private boolean hasPreDestroy(Class<?> interceptorClass) {
        return hasMethodWithAnnotation(interceptorClass, PreDestroy.class);
    }

    private boolean hasMethodWithAnnotation(Class<?> clazz, Class<?> annotation) {
        for (var method : clazz.getDeclaredMethods()) {
            if (method.isAnnotationPresent(annotation)) {
                return true;
            }
        }
        return false;
    }

    public void logWarningsForBeans(List<Bean<?>> beans) {
        for (Bean<?> bean : beans) {
            if (bean.getScope() == null) {
                logger.warning("Bean " + bean.getName() + " has no defined scope.");
            }
            if (bean.isAlternative() && !bean.isEnabled()) {
                logger.warning("Alternative bean " + bean.getName() + " is not enabled.");
            }
        }
    }
}

