public class SharedThemeFromDir {
    private static final Logger logger = Logger.getLogger(SharedThemeFromDir.class.getName());
    private String themeDir;
    private String themeName;
    private String themeDescription;
    private String themeAuthor;
    private String previewImage;
    private List<String> stylesheets;
    private Map<String, String> templates;

    public SharedThemeFromDir(String themeDir) {
        this.themeDir = themeDir;
        this.templates = new HashMap<>();
        loadTheme();
    }

    private void loadTheme() {
        File themeFile = new File(themeDir, "theme.xml");
        if (!themeFile.exists()) {
            logger.log(Level.WARNING, "Theme descriptor file not found: " + themeFile.getAbsolutePath());
            return;
        }

        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            DocumentBuilder builder = factory.newDocumentBuilder();
            Document document = builder.parse(new FileInputStream(themeFile));

            themeName = document.getElementsByTagName("name").item(0).getTextContent();
            themeDescription = document.getElementsByTagName("description").item(0).getTextContent();
            themeAuthor = document.getElementsByTagName("author").item(0).getTextContent();
            previewImage = document.getElementsByTagName("previewImage").item(0).getTextContent();
            NodeList stylesheetNodes = document.getElementsByTagName("stylesheet");
            for (int i = 0; i < stylesheetNodes.getLength(); i++) {
                stylesheets.add(stylesheetNodes.item(i).getTextContent());
            }
            NodeList templateNodes = document.getElementsByTagName("template");
            for (int i = 0; i < templateNodes.getLength(); i++) {
                String name = templateNodes.item(i).getAttributes().getNamedItem("name").getNodeValue();
                String filePath = templateNodes.item(i).getTextContent();
                templates.put(name, filePath);
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error loading theme: " + e.getMessage(), e);
        }
    }

    public String getPreviewImage() {
        return previewImage;
    }

    public String getTemplate(String name) {
        return templates.get(name);
    }

    public List<String> getStylesheets() {
        return stylesheets;
    }

    public String loadTemplateFile(String name) {
        String templatePath = templates.get(name);
        if (templatePath == null) {
            logger.log(Level.WARNING, "Template not found: " + name);
            return null;
        }
        try {
            return new String(Files.readAllBytes(Paths.get(themeDir, templatePath)));
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error loading template file: " + e.getMessage(), e);
            return null;
        }
    }

    public String loadMobileTemplateFile(String name) {
        String mobileTemplatePath = templates.get(name + "_mobile");
        if (mobileTemplatePath == null) {
            logger.log(Level.WARNING, "Mobile template not found: " + name + "_mobile");
            return null;
        }
        try {
            return new String(Files.readAllBytes(Paths.get(themeDir, mobileTemplatePath)));
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error loading mobile template file: " + e.getMessage(), e);
            return null;
        }
    }
}

