public class EosTestDriver {
    private final String topic;
    private final KafkaProducer<String, Integer> producer;
    private final KafkaConsumer<String, Integer> consumer;
    private final Random random;
    private int recordsProduced;
    private int recordsConsumed;

    public EosTestDriver(String topic, String bootstrapServers) {
        this.topic = topic;
        this.producer = createProducer(bootstrapServers);
        this.consumer = createConsumer(bootstrapServers);
        this.random = new Random();
        this.recordsProduced = 0;
        this.recordsConsumed = 0;
    }

    private KafkaProducer<String, Integer> createProducer(String bootstrapServers) {
        Properties props = new Properties();
        props.put("bootstrap.servers", bootstrapServers);
        props.put("key.serializer", StringSerializer.class.getName());
        props.put("value.serializer", StringSerializer.class.getName());
        return new KafkaProducer<>(props);
    }

    private KafkaConsumer<String, Integer> createConsumer(String bootstrapServers) {
        Properties props = new Properties();
        props.put("bootstrap.servers", bootstrapServers);
        props.put("key.deserializer", StringDeserializer.class.getName());
        props.put("value.deserializer", StringDeserializer.class.getName());
        props.put(ConsumerConfig.GROUP_ID_CONFIG, "test-group");
        props.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, "earliest");
        return new KafkaConsumer<>(props);
    }

    public void produceRecords(int count) {
        for (int i = 0; i < count; i++) {
            String key = "key-" + i;
            Integer value = random.nextInt(100);
            producer.send(new ProducerRecord<>(topic, key, value));
            recordsProduced++;
        }
        producer.flush();
    }

    public void consumeRecords() {
        consumer.subscribe(List.of(topic));
        while (recordsConsumed < recordsProduced) {
            ConsumerRecords<String, Integer> records = consumer.poll(Duration.ofMillis(100));
            records.forEach(record -> {
                recordsConsumed++;
            });
        }
    }

    public void shutdown() {
        producer.close();
        consumer.close();
    }

    public boolean verifyRecords() {
        return recordsProduced == recordsConsumed;
    }

    public int getRecordsProduced() {
        return recordsProduced;
    }

    public int getRecordsConsumed() {
        return recordsConsumed;
    }

    public static void main(String[] args) {
        EosTestDriver driver = new EosTestDriver("test-topic", "localhost:9092");
        driver.produceRecords(100);
        driver.consumeRecords();
        System.out.println("Records produced: " + driver.getRecordsProduced());
        System.out.println("Records consumed: " + driver.getRecordsConsumed());
        System.out.println("Verification: " + driver.verifyRecords());
        driver.shutdown();
    }
}

