public class CreationalContextImpl<T> implements CreationalContext<T>, Serializable {
    private static final long serialVersionUID = 1L;

    private final Map<Object, Object> dependentInstances = new HashMap<>();
    private final Map<Object, Object> ejbInterceptors = new HashMap<>();
    private final T owner;

    public CreationalContextImpl(T owner) {
        this.owner = owner;
    }

    @Override
    public void push(Object dependent) {
        dependentInstances.put(dependent, dependent);
    }

    @Override
    public void addEJBInterceptor(Object interceptor) {
        ejbInterceptors.put(interceptor, interceptor);
    }

    @Override
    public Object getEJBInterceptor(Object interceptor) {
        return ejbInterceptors.get(interceptor);
    }

    @Override
    public void release() {
        for (Object dependent : dependentInstances.keySet()) {
            // Potential code smell: not handling exceptions during removal
            dependentInstances.remove(dependent);
        }
        dependentInstances.clear();
        ejbInterceptors.clear();
    }

    @Override
    public String toString() {
        return "CreationalContextImpl{" +
                "owner=" + owner +
                ", dependentInstances=" + dependentInstances +
                ", ejbInterceptors=" + ejbInterceptors +
                '}';
    }
}

