public class MapRecord implements Record {
    private Map<String, Object> values;
    private Map<String, Class<?>> schema;
    private Map<String, Object> defaultValues;

    public MapRecord(Map<String, Class<?>> schema) {
        this.schema = schema;
        this.values = new HashMap<>();
        this.defaultValues = new HashMap<>();
    }

    public void setValue(String fieldName, Object value) {
        if (!schema.containsKey(fieldName)) {
            throw new IllegalArgumentException("Field " + fieldName + " is not defined in the schema.");
        }
        if (value != null && !schema.get(fieldName).isInstance(value)) {
            throw new IllegalArgumentException("Value type mismatch for field " + fieldName);
        }
        values.put(fieldName, value);
    }

    public Object getValue(String fieldName) {
        return values.getOrDefault(fieldName, defaultValues.get(fieldName));
    }

    public void setDefaultValue(String fieldName, Object defaultValue) {
        if (!schema.containsKey(fieldName)) {
            throw new IllegalArgumentException("Field " + fieldName + " is not defined in the schema.");
        }
        defaultValues.put(fieldName, defaultValue);
    }

    public void removeField(String fieldName) {
        values.remove(fieldName);
    }

    public boolean hasField(String fieldName) {
        return values.containsKey(fieldName);
    }

    public Map<String, Object> toMap() {
        return new HashMap<>(values);
    }

    public void fromMap(Map<String, Object> map) {
        for (Map.Entry<String, Object> entry : map.entrySet()) {
            setValue(entry.getKey(), entry.getValue());
        }
    }

    public void validate() {
        for (String fieldName : schema.keySet()) {
            if (!values.containsKey(fieldName) && !defaultValues.containsKey(fieldName)) {
                throw new IllegalStateException("Field " + fieldName + " is missing.");
            }
        }
    }
}

