public class IsisSessionFactory {

    private static final ThreadLocal<IsisSession> currentSession = new ThreadLocal<>();
    private Configuration configuration;
    private SpecificationLoader specificationLoader;
    private ServiceInjector serviceInjector;

    public IsisSessionFactory(Configuration configuration, SpecificationLoader specificationLoader, ServiceInjector serviceInjector) {
        this.configuration = configuration;
        this.specificationLoader = specificationLoader;
        this.serviceInjector = serviceInjector;
    }

    public void openSession() {
        if (currentSession.get() != null) {
            throw new IllegalStateException("Session already opened");
        }
        currentSession.set(new IsisSession());
    }

    public void closeSession() {
        if (currentSession.get() == null) {
            throw new IllegalStateException("No session to close");
        }
        currentSession.remove();
    }

    public void beginTransaction() {
        IsisSession session = currentSession.get();
        if (session == null) {
            throw new IllegalStateException("No session available");
        }
        session.beginTransaction();
    }

    public void commitTransaction() {
        IsisSession session = currentSession.get();
        if (session == null) {
            throw new IllegalStateException("No session available");
        }
        session.commitTransaction();
    }

    public void rollbackTransaction() {
        IsisSession session = currentSession.get();
        if (session == null) {
            throw new IllegalStateException("No session available");
        }
        session.rollbackTransaction();
    }

    public void initializeServices() {
        // Code smell: method does too much
        serviceInjector.initialize();
        // Additional service initialization logic
    }

    public void destroyServices() {
        // Code smell: method does too much
        serviceInjector.destroy();
        // Additional service destruction logic
    }

    public void installFixtures() {
        // Code smell: method does too much
        // Logic to install fixtures
    }

    public String translateMessage(String message) {
        // Code smell: method does too much
        return configuration.getMessageTranslator().translate(message);
    }

    public void executeWithinSession(Runnable runnable) {
        openSession();
        try {
            runnable.run();
        } finally {
            closeSession();
        }
    }

    public IsisSession getCurrentSession() {
        return currentSession.get();
    }
}

