class TextLineDemarcatorTest {
    private TextLineDemarcator demarcator;

    @BeforeEach
    void setUp() {
        demarcator = new TextLineDemarcator();
    }

    @Test
    void testNullInputStream() {
        assertThrows(IllegalArgumentException.class, () -> {
            demarcator.demarcate(null);
        });
    }

    @Test
    void testIllegalBufferSize() {
        assertThrows(IllegalArgumentException.class, () -> {
            demarcator.setBufferSize(0);
        });
    }

    @Test
    void testEmptyStream() {
        InputStream inputStream = new ByteArrayInputStream("".getBytes(StandardCharsets.UTF_8));
        String[] lines = demarcator.demarcate(inputStream);
        assertArrayEquals(new String[]{}, lines);
    }

    @Test
    void testSingleLine() {
        InputStream inputStream = new ByteArrayInputStream("Hello World\n".getBytes(StandardCharsets.UTF_8));
        String[] lines = demarcator.demarcate(inputStream);
        assertArrayEquals(new String[]{"Hello World"}, lines);
    }

    @Test
    void testMultipleLines() {
        InputStream inputStream = new ByteArrayInputStream("Line 1\nLine 2\nLine 3\n".getBytes(StandardCharsets.UTF_8));
        String[] lines = demarcator.demarcate(inputStream);
        assertArrayEquals(new String[]{"Line 1", "Line 2", "Line 3"}, lines);
    }

    @Test
    void testMixedLineEndings() {
        InputStream inputStream = new ByteArrayInputStream("Line 1\rLine 2\nLine 3\r\n".getBytes(StandardCharsets.UTF_8));
        String[] lines = demarcator.demarcate(inputStream);
        assertArrayEquals(new String[]{"Line 1", "Line 2", "Line 3"}, lines);
    }

    @Test
    void testConsecutiveLineBreaks() {
        InputStream inputStream = new ByteArrayInputStream("Line 1\n\nLine 2\n".getBytes(StandardCharsets.UTF_8));
        String[] lines = demarcator.demarcate(inputStream);
        assertArrayEquals(new String[]{"Line 1", "", "Line 2"}, lines);
    }

    @Test
    void testBufferSplit() {
        InputStream inputStream = new ByteArrayInputStream("Line 1\nLine 2\nLine 3\n".getBytes(StandardCharsets.UTF_8));
        demarcator.setBufferSize(10);
        String[] lines = demarcator.demarcate(inputStream);
        assertArrayEquals(new String[]{"Line 1", "Line 2", "Line 3"}, lines);
    }

    @Test
    void testStartWithFilter() {
        demarcator.setStartWithFilter("Line");
        InputStream inputStream = new ByteArrayInputStream("Line 1\nLine 2\nNot a Line\n".getBytes(StandardCharsets.UTF_8));
        String[] lines = demarcator.demarcate(inputStream);
        assertArrayEquals(new String[]{"Line 1", "Line 2"}, lines);
    }
}

