        try (InputStream is = new ByteArrayInputStream(corruptedZipData);
             ZipArchiveInputStream zipInput = new ZipArchiveInputStream(is)) {
            assertThrows(IOException.class, zipInput::getNextZipEntry);
        }
    }

    @Test
    public void testReadWithDifferentCompression() throws IOException {
        byte[] zipData = createZipWithEntry("compressed.txt", "Compressed Content", true);
        try (InputStream is = new ByteArrayInputStream(zipData);
             ZipArchiveInputStream zipInput = new ZipArchiveInputStream(is)) {
            ZipArchiveEntry entry = zipInput.getNextZipEntry();
            assertNotNull(entry);
            assertEquals("compressed.txt", entry.getName());
            assertEquals("Compressed Content", readEntryContent(zipInput));
        }
    }

    @Test
    public void testUnknownSizeEntry() throws IOException {
        byte[] zipData = createZipWithEntry("unknownSize.txt", "Data with unknown size");
        try (InputStream is = new ByteArrayInputStream(zipData);
             ZipArchiveInputStream zipInput = new ZipArchiveInputStream(is)) {
            ZipArchiveEntry entry = zipInput.getNextZipEntry();
            assertNotNull(entry);
            assertEquals("unknownSize.txt", entry.getName());
            assertEquals("Data with unknown size", readEntryContent(zipInput));
        }
    }

    private byte[] createZipWithEntry(String entryName, String content) throws IOException {
        return createZipWithEntry(entryName, content, false);
    }

    private byte[] createZipWithEntry(String entryName, String content, boolean compress) throws IOException {
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ZipOutputStream zos = new ZipOutputStream(baos)) {
            ZipEntry entry = new ZipEntry(entryName);
            if (compress) {
                entry.setMethod(ZipEntry.DEFLATED);
            }
            zos.putNextEntry(entry);
            zos.write(content.getBytes());
            zos.closeEntry();
            zos.finish();
            return baos.toByteArray();
        }
    }

    private String readEntryContent(ZipArchiveInputStream zipInput) throws IOException {
        StringBuilder content = new StringBuilder();
        byte[] buffer = new byte[1024];
        int len;
        while ((len = zipInput.read(buffer)) != -1) {
            content.append(new String(buffer, 0, len));
        }
        return content.toString();
    }
}

