public class CharChunk implements CharSequence {
    private char[] buffer;
    private int start;
    private int end;
    private int limit;

    public CharChunk(int initialSize) {
        buffer = new char[initialSize];
        start = 0;
        end = 0;
        limit = initialSize;
    }

    public void append(char c) {
        if (end >= limit) {
            resizeBuffer();
        }
        buffer[end++] = c;
    }

    public void append(String str) {
        for (char c : str.toCharArray()) {
            append(c);
        }
    }

    public void append(CharChunk chunk) {
        for (int i = chunk.start; i < chunk.end; i++) {
            append(chunk.buffer[i]);
        }
    }

    private void resizeBuffer() {
        int newSize = limit * 2;
        char[] newBuffer = new char[newSize];
        System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
        buffer = newBuffer;
        limit = newSize;
    }

    public int length() {
        return end - start;
    }

    public boolean isNull() {
        return buffer == null;
    }

    public char charAt(int index) {
        if (index < 0 || index >= length()) {
            throw new IndexOutOfBoundsException();
        }
        return buffer[start + index];
    }

    public CharChunk subSequence(int beginIndex, int endIndex) {
        if (beginIndex < 0 || endIndex > length() || beginIndex > endIndex) {
            throw new IndexOutOfBoundsException();
        }
        CharChunk subChunk = new CharChunk(endIndex - beginIndex);
        for (int i = beginIndex; i < endIndex; i++) {
            subChunk.append(this.charAt(i));
        }
        return subChunk;
    }

    public void clear() {
        start = 0;
        end = 0;
    }

    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof CharSequence)) return false;
        CharSequence other = (CharSequence) obj;
        if (length() != other.length()) return false;
        for (int i = 0; i < length(); i++) {
            if (charAt(i) != other.charAt(i)) return false;
        }
        return true;
    }

    public int hashCode() {
        int hash = 7;
        for (int i = start; i < end; i++) {
            hash = 31 * hash + buffer[i];
        }
        return hash;
    }

    public CharChunk clone() {
        CharChunk cloned = new CharChunk(limit);
        System.arraycopy(buffer, start, cloned.buffer, 0, length());
        cloned.start = 0;
        cloned.end = length();
        return cloned;
    }

    public String toString() {
        return new String(buffer, start, length());
    }

    public void writeTo(CharBuffer charBuffer) {
        charBuffer.put(buffer, start, length());
    }
}

