public class TypedInstanceToGraphMapper {

    private Map<String, Vertex> idToVertexMap = new HashMap<>();

    public enum Operation {
        CREATE,
        UPDATE_PARTIAL,
        UPDATE_FULL
    }

    public void mapInstanceToGraph(TypedInstance instance, Operation operation) {
        switch (operation) {
            case CREATE:
                createVertex(instance);
                break;
            case UPDATE_PARTIAL:
                updatePartialVertex(instance);
                break;
            case UPDATE_FULL:
                updateFullVertex(instance);
                break;
            default:
                throw new IllegalArgumentException("Unsupported operation: " + operation);
        }
    }

    private void createVertex(TypedInstance instance) {
        Vertex vertex = new Vertex(instance.getId());
        idToVertexMap.put(instance.getId(), vertex);
        addAttributes(vertex, instance);
        addTraits(vertex, instance);
        manageCollections(vertex, instance);
        manageRelationships(vertex, instance);
    }

    private void updatePartialVertex(TypedInstance instance) {
        Vertex vertex = idToVertexMap.get(instance.getId());
        if (vertex != null) {
            addAttributes(vertex, instance);
            manageCollections(vertex, instance);
        }
    }

    private void updateFullVertex(TypedInstance instance) {
        Vertex vertex = idToVertexMap.get(instance.getId());
        if (vertex != null) {
            vertex.clearAttributes();
            addAttributes(vertex, instance);
            addTraits(vertex, instance);
            manageCollections(vertex, instance);
            manageRelationships(vertex, instance);
        }
    }

    private void addAttributes(Vertex vertex, TypedInstance instance) {
        for (Map.Entry<String, Object> entry : instance.getAttributes().entrySet()) {
            vertex.addAttribute(entry.getKey(), entry.getValue());
        }
    }

    private void addTraits(Vertex vertex, TypedInstance instance) {
        for (String trait : instance.getTraits()) {
            vertex.addTrait(trait);
        }
    }

    private void manageCollections(Vertex vertex, TypedInstance instance) {
        // Handle arrays and maps
        for (Map.Entry<String, Collection> entry : instance.getCollections().entrySet()) {
            vertex.addCollection(entry.getKey(), entry.getValue());
        }
    }

    private void manageRelationships(Vertex vertex, TypedInstance instance) {
        for (String relationshipId : instance.getRelationships()) {
            vertex.addRelationship(relationshipId);
        }
    }

    // Deprecated method
    @Deprecated
    public void clearCache() {
        idToVertexMap.clear();
    }

    // Other methods for full-text search and reverse references can be added here
}

public class FTPClientWrapper implements FtpClient {
    private static final Logger logger = Logger.getLogger(FTPClientWrapper.class.getName());
    private FTPClient ftpClient;
    private String server;
    private int port;
    private String user;
    private String password;
    private boolean connected;

    public FTPClientWrapper(String server, int port, String user, String password) {
        this.server = server;
        this.port = port;
        this.user = user;
        this.password = password;
        this.ftpClient = new FTPClient();
        this.connected = false;
    }

    public void connect() {
        try {
            ftpClient.connect(server, port);
            int replyCode = ftpClient.getReplyCode();
            if (!FTPReply.isPositiveCompletion(replyCode)) {
                throw new IOException("Failed to connect to FTP server");
            }
            ftpClient.login(user, password);
            connected = true;
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error connecting to FTP server", e);
            reconnect();
        }
    }

    public void disconnect() {
        if (connected) {
            try {
                ftpClient.logout();
                ftpClient.disconnect();
                connected = false;
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Error disconnecting from FTP server", e);
            }
        }
    }

    public void upload(String remoteFile, InputStream inputStream) {
        try {
            connectIfNeeded();
            ftpClient.storeFile(remoteFile, inputStream);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error uploading file", e);
            reconnect();
        }
    }

    public void download(String remoteFile, OutputStream outputStream) {
        try {
            connectIfNeeded();
            ftpClient.retrieveFile(remoteFile, outputStream);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error downloading file", e);
            reconnect();
        }
    }

    public void deleteFile(String remoteFile) {
        try {
            connectIfNeeded();
            ftpClient.deleteFile(remoteFile);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error deleting file", e);
            reconnect();
        }
    }

    public void appendFile(String remoteFile, InputStream inputStream) {
        try {
            connectIfNeeded();
            ftpClient.appendFile(remoteFile, inputStream);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error appending file", e);
            reconnect();
        }
    }

    public void renameFile(String oldRemoteFile, String newRemoteFile) {
        try {
            connectIfNeeded();
            ftpClient.rename(oldRemoteFile, newRemoteFile);
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error renaming file", e);
            reconnect();
        }
    }

    public List<String> listFiles(String remoteDir) {
        List<String> fileList = new ArrayList<>();
        try {
            connectIfNeeded();
            String[] files = ftpClient.listNames(remoteDir);
            if (files != null) {
                for (String file : files) {
                    fileList.add(file);
                }
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error listing files", e);
            reconnect();
        }
        return fileList;
    }

    private void connectIfNeeded() throws IOException {
        if (!connected) {
            connect();
        }
    }

    private void reconnect() {
        disconnect();
        connect();
    }
}

