public class AnnotationTypeConverterLoader {

    private final TypeConverterRegistry registry;
    private final Set<Class<?>> visitedClasses = new HashSet<>();

    public AnnotationTypeConverterLoader(TypeConverterRegistry registry) {
        this.registry = registry;
    }

    public void loadConverters(String... packageNames) {
        for (String packageName : packageNames) {
            loadConvertersFromPackage(packageName);
        }
    }

    private void loadConvertersFromPackage(String packageName) {
        Reflections reflections = new Reflections(packageName);
        Set<Class<?>> converterClasses = reflections.getTypesAnnotatedWith(Converter.class);

        for (Class<?> converterClass : converterClasses) {
            if (!visitedClasses.contains(converterClass)) {
                visitedClasses.add(converterClass);
                loadConverterMethods(converterClass);
            }
        }
    }

    private void loadConverterMethods(Class<?> converterClass) {
        Method[] methods = converterClass.getDeclaredMethods();
        for (Method method : methods) {
            if (isValidConverterMethod(method)) {
                registerConverterMethod(method);
            }
        }
    }

    private boolean isValidConverterMethod(Method method) {
        return method.getModifiers() == java.lang.reflect.Modifier.PUBLIC &&
               !java.lang.reflect.Modifier.isAbstract(method.getModifiers()) &&
               method.getParameterCount() == 1; // Assuming single parameter for conversion
    }

    private void registerConverterMethod(Method method) {
        // Logic to register the converter method with the registry
        // This is a placeholder for actual registration logic
        registry.addTypeConverter(method.getParameterTypes()[0], method.getReturnType(), method);
    }
}

public class NestedMethodAnalyzer extends BasicInterpreter {
    private static final int MAX_NESTING_LEVEL = 10;
