public class TestSplitContent {

    @Test
    public void testSplitAtLeadingPosition() {
        SplitContent processor = new SplitContent();
        byte[] input = "abc|def|ghi".getBytes();
        byte[] delimiter = "|".getBytes();
        processor.setDelimiter(delimiter);
        byte[][] result = processor.split(input);

        assertEquals(3, result.length);
        assertArrayEquals("abc".getBytes(), result[0]);
        assertArrayEquals("def".getBytes(), result[1]);
        assertArrayEquals("ghi".getBytes(), result[2]);
    }

    @Test
    public void testSplitAtTrailingPosition() {
        SplitContent processor = new SplitContent();
        byte[] input = "|abc|def|ghi".getBytes();
        byte[] delimiter = "|".getBytes();
        processor.setDelimiter(delimiter);
        byte[][] result = processor.split(input);

        assertEquals(4, result.length);
        assertArrayEquals("", result[0]);
        assertArrayEquals("abc".getBytes(), result[1]);
        assertArrayEquals("def".getBytes(), result[2]);
        assertArrayEquals("ghi".getBytes(), result[3]);
    }

    @Test
    public void testKeepDelimiter() {
        SplitContent processor = new SplitContent();
        byte[] input = "abc|def|ghi".getBytes();
        byte[] delimiter = "|".getBytes();
        processor.setDelimiter(delimiter);
        processor.setKeepDelimiter(true);
        byte[][] result = processor.split(input);

        assertEquals(4, result.length);
        assertArrayEquals("abc".getBytes(), result[0]);
        assertArrayEquals("|".getBytes(), result[1]);
        assertArrayEquals("def".getBytes(), result[2]);
        assertArrayEquals("|".getBytes(), result[3]);
        assertArrayEquals("ghi".getBytes(), result[4]);
    }

    @Test
    public void testNoSplit() {
        SplitContent processor = new SplitContent();
        byte[] input = "abcdefghi".getBytes();
        byte[] delimiter = "|".getBytes();
        processor.setDelimiter(delimiter);
        byte[][] result = processor.split(input);

        assertEquals(1, result.length);
        assertArrayEquals("abcdefghi".getBytes(), result[0]);
    }

    @Test
    public void testFragmentCountAndIDs() {
        SplitContent processor = new SplitContent();
        byte[] input = "abc|def|ghi".getBytes();
        byte[] delimiter = "|".getBytes();
        processor.setDelimiter(delimiter);
        byte[][] result = processor.split(input);

        assertEquals(3, processor.getFragmentCount());
        for (int i = 0; i < result.length; i++) {
            assertEquals("fragment-" + i, processor.getFragmentId(i));
        }
    }
