class TestGroupByContainerCount {

    @Test
    public void testEmptyTaskSet() {
        GroupByContainerCount groupByContainerCount = new GroupByContainerCount(3);
        assertThrows(IllegalArgumentException.class, () -> groupByContainerCount.groupTasks(new ArrayList<>()));
    }

    @Test
    public void testMoreContainersThanTasks() {
        GroupByContainerCount groupByContainerCount = new GroupByContainerCount(5);
        List<String> tasks = List.of("Task1", "Task2");
        assertThrows(IllegalArgumentException.class, () -> groupByContainerCount.groupTasks(tasks));
    }

    @Test
    public void testImmutabilityOfResults() {
        GroupByContainerCount groupByContainerCount = new GroupByContainerCount(3);
        List<String> tasks = List.of("Task1", "Task2", "Task3");
        List<List<String>> result = groupByContainerCount.groupTasks(tasks);
        result.get(0).add("Task4");
        assertNotEquals(result, groupByContainerCount.groupTasks(tasks));
    }

    @Test
    public void testTaskDistribution() {
        GroupByContainerCount groupByContainerCount = new GroupByContainerCount(3);
        List<String> tasks = List.of("Task1", "Task2", "Task3", "Task4", "Task5");
        List<List<String>> result = groupByContainerCount.groupTasks(tasks);
        assertEquals(3, result.size());
        assertTrue(result.stream().allMatch(container -> container.size() <= 2));
    }

    @Test
    public void testRebalancingWithIncreasedContainers() {
        GroupByContainerCount groupByContainerCount = new GroupByContainerCount(2);
        List<String> tasks = List.of("Task1", "Task2", "Task3", "Task4");
        List<List<String>> result = groupByContainerCount.groupTasks(tasks);
        assertEquals(2, result.size());

        groupByContainerCount = new GroupByContainerCount(4);
        List<List<String>> newResult = groupByContainerCount.groupTasks(tasks);
        assertEquals(4, newResult.size());
        assertTrue(newResult.stream().allMatch(container -> container.size() <= 1));
    }

    @Test
    public void testCustomTaskToContainerMapping() {
        GroupByContainerCount groupByContainerCount = new GroupByContainerCount(3);
        List<String> tasks = List.of("Task1", "Task2", "Task3", "Task4", "Task5", "Task6");
        List<List<String>> result = groupByContainerCount.groupTasks(tasks);
        assertEquals(3, result.size());
        assertEquals(2, result.get(0).size() + result.get(1).size() + result.get(2).size());
    }

    @Test
    public void testInvalidConfiguration() {
        assertThrows(IllegalArgumentException.class, () -> new GroupByContainerCount(0));
        assertThrows(IllegalArgumentException.class, () -> new GroupByContainerCount(-1));
    }
}

public class OrderLookupServices {

    public static OrderResult findOrders(DispatchContext context, Map<String, Object> criteria) {
        // Code smell: Long method, could be broken down into smaller methods
        String orderId = (String) criteria.get("orderId");
        String orderType = (String) criteria.get("orderType");
        String orderStatus = (String) criteria.get("orderStatus");
        String startDate = (String) criteria.get("startDate");
        String endDate = (String) criteria.get("endDate");
        String userPermissions = (String) criteria.get("userPermissions");

        StringBuilder query = new StringBuilder("SELECT * FROM orders WHERE 1=1");

        if (orderId != null) {
            query.append(createCondition("orderId", orderId));
        }
        if (orderType != null) {
            query.append(createCondition("orderType", orderType));
        }
        if (orderStatus != null) {
            query.append(createCondition("orderStatus", orderStatus));
        }
        if (startDate != null) {
            query.append(createDateCondition("orderDate", startDate, ">="));
        }
        if (endDate != null) {
            query.append(createDateCondition("orderDate", endDate, "<="));
        }
        if (userPermissions != null) {
            query.append(createCondition("userPermissions", userPermissions));
        }

        // Code smell: Direct database access in service layer
        List<Order> orders = Database.executeQuery(query.toString());

        // Code smell: Pagination logic could be handled elsewhere
        int totalOrders = orders.size();
        int pageSize = (int) criteria.getOrDefault("pageSize", 10);
        int pageNumber = (int) criteria.getOrDefault("pageNumber", 1);
        int startIndex = (pageNumber - 1) * pageSize;
        int endIndex = Math.min(startIndex + pageSize, totalOrders);

        List<Order> paginatedOrders = orders.subList(startIndex, endIndex);

        return new OrderResult(paginatedOrders, totalOrders);
    }

    private static String createCondition(String field, String value) {
        return " AND " + field + " = '" + value + "'";
    }

    private static String createDateCondition(String field, String date, String operator) {
        return " AND " + field + " " + operator + " '" + date + "'";
    }

    public static List<Order> filterInventoryProblems(List<Order> orders) {
        // Code smell: Method does not handle empty list case
        return orders.stream()
                .filter(order -> order.hasInventoryIssues())
                .toList();
    }
}

