    public void testValidISBN10() {
        assertTrue(validator.isValidISBN10("0306406152"));
        assertTrue(validator.isValidISBN10("0486650888"));
        assertTrue(validator.isValidISBN10("0074625428"));
    }

    @Test
    public void testInvalidISBN10() {
        assertFalse(validator.isValidISBN10("030640615X"));
        assertFalse(validator.isValidISBN10("1234567890"));
        assertFalse(validator.isValidISBN10("123456789"));
    }

    @Test
    public void testValidISBN13() {
        assertTrue(validator.isValidISBN13("978-3-16-148410-0"));
        assertTrue(validator.isValidISBN13("9783161484100"));
        assertTrue(validator.isValidISBN13("978-0-306-40615-7"));
    }

    @Test
    public void testInvalidISBN13() {
        assertFalse(validator.isValidISBN13("978-3-16-148410-X"));
        assertFalse(validator.isValidISBN13("9783161484101"));
        assertFalse(validator.isValidISBN13("978-0-306-40615-8"));
    }

    @Test
    public void testISBN10ValidationMethod() {
        assertTrue(validator.validateISBN10("0306406152"));
        assertFalse(validator.validateISBN10("1234567890"));
    }

    @Test
    public void testISBN13ValidationMethod() {
        assertTrue(validator.validateISBN13("978-3-16-148410-0"));
        assertFalse(validator.validateISBN13("978-3-16-148410-X"));
    }

    @Test
    public void testNullInput() {
        assertFalse(validator.isValidISBN10(null));
        assertFalse(validator.isValidISBN13(null));
    }

    @Test
    public void testConvertISBN10ToISBN13() {
        assertEquals("978-0-306-40615-7", validator.convertISBN10ToISBN13("0-306-40615-2"));
