    }

    @Test
    public void testInvalidConversion() {
        assertThrows(IllegalArgumentException.class, () -> {
            validator.convertISBN10ToISBN13("1234567890");
        });
        assertThrows(IllegalArgumentException.class, () -> {
            validator.convertISBN10ToISBN13(null);
        });
    }
