public class FieldRotationDSTest {

    @Test
    public void testIdentityRotation() {
        FieldRotation rotation = FieldRotation.identity();
        DerivativeStructure vector = new DerivativeStructure(3, 1, new double[]{1.0, 0.0, 0.0});
        DerivativeStructure result = rotation.apply(vector);
        assertEquals(vector, result);
        assertEquals(0.0, rotation.getAngle(), 1e-10);
    }

    @Test
    public void testAxisAngleRotation() {
        double angle = Math.PI / 2;
        double[] axis = {0, 0, 1};
        FieldRotation rotation = new FieldRotation(axis, angle);
        assertArrayEquals(axis, rotation.getAxis(), 1e-10);
        assertEquals(angle, rotation.getAngle(), 1e-10);
    }

    @Test
    public void testReversion() {
        FieldRotation rotation = new FieldRotation(new double[]{0, 0, 1}, Math.PI / 2);
        FieldRotation reverted = rotation.revert();
        DerivativeStructure vector = new DerivativeStructure(3, 1, new double[]{1.0, 0.0, 0.0});
        DerivativeStructure result = reverted.apply(rotation.apply(vector));
        assertEquals(vector, result);
    }

    @Test
    public void testVectorPairRotations() {
        DerivativeStructure v1 = new DerivativeStructure(3, 1, new double[]{1.0, 0.0, 0.0});
        DerivativeStructure v2 = new DerivativeStructure(3, 1, new double[]{0.0, 1.0, 0.0});
        FieldRotation rotation = FieldRotation.fromVectors(v1, v2);
        DerivativeStructure result = rotation.apply(v1);
        assertEquals(v2, result);
    }

    @Test
    public void testMatrixRepresentation() {
        double[][] matrix = {{0, -1, 0}, {1, 0, 0}, {0, 0, 1}};
        FieldRotation rotation = FieldRotation.fromMatrix(matrix);
        DerivativeStructure vector = new DerivativeStructure(3, 1, new double[]{1.0, 0.0, 0.0});
        DerivativeStructure result = rotation.apply(vector);
        assertArrayEquals(new double[]{0.0, 1.0, 0.0}, result.getComponents(), 1e-10);
    }

    @Test
    public void testAngleCalculations() {
        FieldRotation rotation = new FieldRotation(new double[]{0, 0, 1}, Math.PI / 2);
        assertEquals(Math.PI / 2, rotation.getAngle(), 1e-10);
        assertTrue(rotation.hasSingularity());
    }

    @Test
    public void testQuaternionRepresentation() {
        FieldRotation rotation = new FieldRotation(new double[]{0, 0, 1}, Math.PI / 2);
        Quaternion quaternion = rotation.toQuaternion();
        DerivativeStructure vector = new DerivativeStructure(3, 1, new double[]{1.0, 0.0, 0.0});
        DerivativeStructure result = quaternion.apply(vector);
        assertArrayEquals(new double[]{0.0, 1.0, 0.0}, result.getComponents(), 1e-10);
    }

    @Test
    public void testCompositionOfRotations() {
        FieldRotation rotation1 = new FieldRotation(new double[]{0, 0, 1}, Math.PI / 2);
        FieldRotation rotation2 = new FieldRotation(new double[]{1, 0, 0}, Math.PI / 2);
        FieldRotation composition = rotation1.compose(rotation2);
        DerivativeStructure vector = new DerivativeStructure(3, 1, new double[]{1.0, 0.0, 0.0});
        DerivativeStructure result = composition.apply(vector);
        assertNotEquals(vector, result);
    }

    @Test
    public void testDerivatives() {
        FieldRotation rotation = new FieldRotation(new double[]{0, 0, 1}, Math.PI / 2);
        DerivativeStructure vector = new DerivativeStructure(3, 1, new double[]{1.0, 0.0, 0.0});
        DerivativeStructure derivative = rotation.applyDerivative(vector);
        assertNotNull(derivative);
    }

    @Test
    public void testArrayOperations() {
        DerivativeStructure[] vectors = new DerivativeStructure[]{
            new DerivativeStructure(3, 1, new double[]{1.0, 0.0, 0.0}),
            new DerivativeStructure(3, 1, new double[]{0.0, 1.0, 0.0})
        };
        FieldRotation rotation = new FieldRotation(new double[]{0, 0, 1}, Math.PI / 2);
        DerivativeStructure[] results = rotation.apply(vectors);
        assertArrayEquals(new double[]{0.0, 1.0, 0.0}, results[0].getComponents(), 1e-10);
        assertArrayEquals(new double[]{-1.0, 0.0, 0.0}, results[1].getComponents(), 1e-10);
    }
}

