        logger.info("Testing next scheduled time for hour cron expression");
        LocalDateTime nextTime = cronParser.getNextScheduledTime(currentTime, cronExpression);
        assertEquals(expectedTime, nextTime);
    }

    @Test
    public void testGetNextScheduledTime_Day() {
        LocalDateTime currentTime = LocalDateTime.of(2023, 10, 1, 12, 0);
        String cronExpression = "0 12 * * *";
        LocalDateTime expectedTime = LocalDateTime.of(2023, 10, 2, 12, 0);

        logger.info("Testing next scheduled time for day cron expression");
        LocalDateTime nextTime = cronParser.getNextScheduledTime(currentTime, cronExpression);
        assertEquals(expectedTime, nextTime);
    }

    @Test
    public void testGetNextScheduledTime_Month() {
        LocalDateTime currentTime = LocalDateTime.of(2023, 10, 1, 12, 0);
        String cronExpression = "0 0 1 * *";
        LocalDateTime expectedTime = LocalDateTime.of(2023, 11, 1, 0, 0);

        logger.info("Testing next scheduled time for month cron expression");
        LocalDateTime nextTime = cronParser.getNextScheduledTime(currentTime, cronExpression);
        assertEquals(expectedTime, nextTime);
    }

    @Test
    public void testInvalidCronExpression() {
        String invalidCron = "invalid cron";

        logger.info("Testing invalid cron expression");
        assertThrows(IllegalArgumentException.class, () -> {
            cronParser.getNextScheduledTime(LocalDateTime.now(), invalidCron);
        });
    }

    @Test
    public void testTokenization() {
        String cronExpression = "0 0 * * *";
        String[] expectedTokens = {"0", "0", "*", "*", "*"};

        logger.info("Testing cron expression tokenization");
        String[] tokens = cronParser.tokenize(cronExpression);
        assertArrayEquals(expectedTokens, tokens);
    }
}

