public class ProtocolConverter {
    private ConnectionFactory connectionFactory;
    private Connection connection;
    private Session session;
    private MessageProducer producer;
    private Map<String, CommandHandler> commandHandlers;
    private String brokerUrl;

    public ProtocolConverter(String brokerUrl) {
        this.brokerUrl = brokerUrl;
        this.commandHandlers = new HashMap<>();
        initializeActiveMQ();
        registerCommandHandlers();
    }

    private void initializeActiveMQ() {
        try {
            connectionFactory = new ActiveMQConnectionFactory(brokerUrl);
            connection = connectionFactory.createConnection();
            connection.start();
            session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
            producer = session.createProducer(null);
        } catch (JMSException e) {
            logError("Failed to initialize ActiveMQ: " + e.getMessage());
        }
    }

    private void registerCommandHandlers() {
        commandHandlers.put("message", new MessageHandler());
        commandHandlers.put("presence", new PresenceHandler());
        commandHandlers.put("iq", new IQHandler());
    }

    public void handleXMPPMessage(Message xmppMessage) {
        String commandType = xmppMessage.getType().toString();
        CommandHandler handler = commandHandlers.get(commandType);
        if (handler != null) {
            handler.handle(xmppMessage);
