public class ValueHelper {

    public static <T> T convertValue(Object sourceValue, Class<T> targetType, ValueFactory valueFactory) {
        try {
            if (sourceValue == null) {
                return null;
            }
            if (targetType.isInstance(sourceValue)) {
                return targetType.cast(sourceValue);
            }
            if (sourceValue instanceof String) {
                return valueFactory.createValue((String) sourceValue, targetType);
            }
            if (sourceValue instanceof InputStream) {
                return valueFactory.createValue((InputStream) sourceValue, targetType);
            }
            if (sourceValue instanceof Value) {
                return valueFactory.createValue((Value) sourceValue, targetType);
            }
            throw new IllegalArgumentException("Unsupported source type: " + sourceValue.getClass());
        } catch (Exception e) {
            throw new ConversionException("Error converting value: " + e.getMessage(), e);
        }
    }

    public static <T> T[] convertArray(Object[] sourceArray, Class<T> targetType, ValueFactory valueFactory) {
        return Arrays.stream(sourceArray)
                .map(sourceValue -> convertValue(sourceValue, targetType, valueFactory))
                .toArray(size -> (T[]) java.lang.reflect.Array.newInstance(targetType, size));
    }

    public static String serializeValue(Object value) {
        if (value == null) {
            return null;
        }
        return value.toString();
    }

    public static <T> T deserializeValue(String valueString, Class<T> targetType, ValueFactory valueFactory) {
        if (valueString == null) {
            return null;
        }
        return valueFactory.createValue(valueString, targetType);
    }

    public static <T> T copyValue(T value) {
        if (value == null) {
            return null;
        }
        // Assuming a simple clone method for demonstration; actual implementation may vary
        return value;
    }

    public static class ConversionException extends RuntimeException {
        public ConversionException(String message, Throwable cause) {
            super(message, cause);
        }
    }

    public interface ValueFactory {
        <T> T createValue(String valueString, Class<T> targetType);
