public class DBHelper {
    private DataSource dataSource;

    public DBHelper(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public List<Object[]> select(String table, String[] columns) throws SQLException {
        List<Object[]> results = new ArrayList<>();
        String sql = "SELECT " + String.join(", ", columns) + " FROM " + table;
        try (Connection conn = getConnection(); Statement stmt = conn.createStatement(); ResultSet rs = stmt.executeQuery(sql)) {
            while (rs.next()) {
                Object[] row = new Object[columns.length];
                for (int i = 0; i < columns.length; i++) {
                    row[i] = rs.getObject(columns[i]);
                }
                results.add(row);
            }
        }
        return results;
    }

    public int insert(String table, Object[] values) throws SQLException {
        String sql = "INSERT INTO " + table + " VALUES (" + String.join(", ", new String[new Object[values.length].length]).replace("\0", "?") + ")";
        try (Connection conn = getConnection(); PreparedStatement pstmt = conn.prepareStatement(sql)) {
            for (int i = 0; i < values.length; i++) {
                pstmt.setObject(i + 1, values[i]);
            }
            return pstmt.executeUpdate();
        }
    }

    public void delete(String table) throws SQLException {
        String sql = "DELETE FROM " + table;
        try (Connection conn = getConnection(); Statement stmt = conn.createStatement()) {
            stmt.executeUpdate(sql);
        }
    }

    public UpdateBuilder update(String table) {
        return new UpdateBuilder(table);
    }

    public int rowCount(String table) throws SQLException {
        String sql = "SELECT COUNT(*) FROM " + table;
        try (Connection conn = getConnection(); Statement stmt = conn.createStatement(); ResultSet rs = stmt.executeQuery(sql)) {
            if (rs.next()) {
                return rs.getInt(1);
            }
        }
        return 0;
    }

    public String getString(String table, String column) throws SQLException {
        String sql = "SELECT " + column + " FROM " + table;
        try (Connection conn = getConnection(); Statement stmt = conn.createStatement(); ResultSet rs = stmt.executeQuery(sql)) {
            if (rs.next()) {
                return rs.getString(column);
            }
        }
        return null;
    }

    private Connection getConnection() throws SQLException {
        Connection conn = dataSource.getConnection();
        conn.setAutoCommit(false);
        return conn;
    }

    public class UpdateBuilder {
        private String table;
        private StringBuilder setClause = new StringBuilder();
        private StringBuilder whereClause = new StringBuilder();

        public UpdateBuilder(String table) {
            this.table = table;
        }

        public UpdateBuilder set(String column, Object value) {
            if (setClause.length() > 0) {
                setClause.append(", ");
            }
            setClause.append(column).append(" = ?");
            return this;
        }

        public UpdateBuilder where(String condition) {
            if (whereClause.length() > 0) {
                whereClause.append(" AND ");
            }
            whereClause.append(condition);
            return this;
        }

        public int execute() throws SQLException {
            String sql = "UPDATE " + table + " SET " + setClause + (whereClause.length() > 0 ? " WHERE " + whereClause : "");
            try (Connection conn = getConnection(); PreparedStatement pstmt = conn.prepareStatement(sql)) {
                int index = 1;
                for (String column : setClause.toString().split(",")) {
                    pstmt.setObject(index++, column.split("=")[1].trim());
                }
                return pstmt.executeUpdate();
            }
        }
    }
}

public class finnishStemmer extends AbstractSnowballStemmer {
    private static final String[] suffixes = { "lla", "ltä", "sta", "s", "t", "n", "i", "a", "e", "o" };
    private int cursor;
    private int limit;
    private int limitBackward;
    private boolean hasRemovedEnding;

    public finnishStemmer() {
        this.cursor = 0;
        this.limit = 0;
        this.limitBackward = 0;
        this.hasRemovedEnding = false;
    }

    @Override
    public String stem(String word) {
        this.cursor = word.length();
        this.limit = this.cursor;
        this.limitBackward = this.cursor;
        this.hasRemovedEnding = false;

        applyStemmingRules(word);
        return word.substring(0, limit);
    }

    private void applyStemmingRules(String word) {
        for (String suffix : suffixes) {
            if (word.endsWith(suffix)) {
                limit -= suffix.length();
                hasRemovedEnding = true;
                break;
            }
        }
        // Additional rules can be added here
    }

    @Override
    public boolean equals(Object obj) {
        return obj instanceof finnishStemmer;
    }

    @Override
    public int hashCode() {
        return 31 * getClass().hashCode();
    }
}

