public class IOUtils {
    public static final int EOF = -1;
    public static final String DIRECTORY_SEPARATOR = File.separator;
    public static final String LINE_SEPARATOR = System.lineSeparator();

    public static void closeQuietly(Closeable closeable) {
        if (closeable != null) {
            try {
                closeable.close();
            } catch (IOException e) {
                // Ignore
            }
        }
    }

    public static BufferedInputStream toBufferedInputStream(InputStream inputStream) {
        return inputStream instanceof BufferedInputStream ? (BufferedInputStream) inputStream : new BufferedInputStream(inputStream);
    }

    public static BufferedReader toBufferedReader(Reader reader) {
        return reader instanceof BufferedReader ? (BufferedReader) reader : new BufferedReader(reader);
    }

    public static void copy(InputStream input, OutputStream output) throws IOException {
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = input.read(buffer)) != EOF) {
            output.write(buffer, 0, bytesRead);
        }
    }

    public static void copy(Reader input, Writer output) throws IOException {
        char[] buffer = new char[1024];
        int charsRead;
        while ((charsRead = input.read(buffer)) != EOF) {
            output.write(buffer, 0, charsRead);
        }
    }

    public static byte[] readBytes(InputStream input) throws IOException {
        ByteArrayOutputStream output = new ByteArrayOutputStream();
        copy(input, output);
        return output.toByteArray();
    }

    public static char[] readChars(Reader input) throws IOException {
        StringWriter output = new StringWriter();
        copy(input, output);
        return output.toString().toCharArray();
    }

    public static void write(OutputStream output, byte[] data) throws IOException {
        output.write(data);
    }

    public static void write(Writer output, char[] data) throws IOException {
        output.write(data);
    }

    public static void write(OutputStream output, String data) throws IOException {
        output.write(data.getBytes());
    }

    public static void write(Writer output, String data) throws IOException {
        output.write(data);
    }

    public static long skip(InputStream input, long n) throws IOException {
        return input.skip(n);
    }

    public static long skip(Reader input, long n) throws IOException {
        long skipped = 0;
        while (skipped < n) {
            long result = input.skip(n - skipped);
            if (result == EOF) {
                break;
            }
            skipped += result;
        }
        return skipped;
    }

    public static boolean contentEquals(InputStream input1, InputStream input2) throws IOException {
        byte[] buffer1 = new byte[1024];
        byte[] buffer2 = new byte[1024];
        int bytesRead1, bytesRead2;
        do {
            bytesRead1 = input1.read(buffer1);
            bytesRead2 = input2.read(buffer2);
            if (bytesRead1 != bytesRead2) {
                return false;
            }
            if (bytesRead1 == EOF) {
                break;
            }
            if (!java.util.Arrays.equals(buffer1, buffer2)) {
                return false;
            }
        } while (bytesRead1 != EOF);
        return true;
    }

    public static String readLine(BufferedReader reader) throws IOException {
        return reader.readLine();
    }
}

