public class JSONWriter {
    private final Writer writer;
    private final Stack<Boolean> contextStack = new Stack<>();
    private boolean isFirstElement = true;
    private boolean isInObject = false;

    public JSONWriter(Writer writer) {
        this.writer = writer;
    }

    public void startObject() throws IOException {
        if (!isFirstElement) {
            writer.write(",");
        }
        writer.write("{");
        contextStack.push(true);
        isInObject = true;
        isFirstElement = true;
    }

    public void endObject() throws IOException {
        if (contextStack.isEmpty() || !isInObject) {
            throw new IllegalStateException("Mismatched endObject call");
        }
        writer.write("}");
        contextStack.pop();
        isInObject = false;
        isFirstElement = false;
    }

    public void startArray() throws IOException {
        if (!isFirstElement) {
            writer.write(",");
        }
        writer.write("[");
        contextStack.push(false);
        isInObject = false;
        isFirstElement = true;
    }

    public void endArray() throws IOException {
        if (contextStack.isEmpty() || isInObject) {
            throw new IllegalStateException("Mismatched endArray call");
        }
        writer.write("]");
        contextStack.pop();
        isFirstElement = false;
    }

    public void writeKey(String key) throws IOException {
        if (!isInObject) {
            throw new IllegalStateException("writeKey can only be called inside an object");
        }
        if (!isFirstElement) {
            writer.write(",");
        }
        writer.write("\"" + key + "\":");
        isFirstElement = false;
    }

    public void writeValue(Object value) throws IOException {
        if (contextStack.isEmpty()) {
            throw new IllegalStateException("writeValue can only be called after startObject or startArray");
        }
        if (!isFirstElement) {
            writer.write(",");
        }
        if (value instanceof String) {
            writer.write("\"" + value + "\"");
        } else if (value instanceof Number || value instanceof Boolean) {
            writer.write(value.toString());
        } else {
            writer.write("\"" + value.toString() + "\"");
        }
        isFirstElement = false;
    }
}

