public class DfpMath {

    public Dfp exp(Dfp x) {
        // Implementation of exponential function using series expansion
        Dfp result = Dfp.ONE;
        Dfp term = x;
        int n = 1;
        while (term.abs().compareTo(Dfp.ZERO) > 0) {
            result = result.add(term);
            n++;
            term = term.multiply(x).divide(new Dfp(n));
        }
        return result;
    }

    public Dfp log(Dfp x) {
        // Implementation of logarithm using series expansion
        if (x.compareTo(Dfp.ZERO) <= 0) {
            return Dfp.NaN; // Handle special case for log
        }
        Dfp result = Dfp.ZERO;
        Dfp term = x.subtract(Dfp.ONE);
        Dfp n = Dfp.ONE;
        while (term.abs().compareTo(Dfp.ZERO) > 0) {
            result = result.add(term.divide(n));
            term = term.multiply(x.subtract(Dfp.ONE));
            n = n.add(Dfp.ONE);
        }
        return result;
    }

    public Dfp sin(Dfp x) {
        // Implementation of sine function using series expansion
        Dfp result = Dfp.ZERO;
        Dfp term = x;
        int n = 1;
        while (term.abs().compareTo(Dfp.ZERO) > 0) {
            result = result.add(term);
            n += 2;
            term = term.multiply(x.multiply(x)).divide(new Dfp(n * (n - 1)));
        }
        return result;
    }

    public Dfp cos(Dfp x) {
        // Implementation of cosine function using series expansion
        Dfp result = Dfp.ZERO;
        Dfp term = Dfp.ONE;
        int n = 0;
        while (term.abs().compareTo(Dfp.ZERO) > 0) {
            result = result.add(term);
            n += 2;
            term = term.multiply(x.multiply(x)).divide(new Dfp(n * (n - 1)));
        }
        return result;
    }

    public Dfp tan(Dfp x) {
        // Implementation of tangent function
        return sin(x).divide(cos(x));
    }

    public Dfp arcsin(Dfp x) {
        // Implementation of arcsine function using series expansion
        if (x.compareTo(Dfp.ONE) > 0 || x.compareTo(Dfp.NEG_ONE) < 0) {
            return Dfp.NaN; // Handle special case for arcsin
        }
        Dfp result = x;
        Dfp term = x;
        int n = 1;
        while (term.abs().compareTo(Dfp.ZERO) > 0) {
            term = term.multiply(x.multiply(x)).multiply(new Dfp(2 * n - 1)).divide(new Dfp(2 * n));
            result = result.add(term);
            n++;
        }
        return result;
    }

    public Dfp arccos(Dfp x) {
        // Implementation of arccosine function
        return Dfp.PI.divide(Dfp.TWO).subtract(arcsin(x));
    }

    public Dfp arctan(Dfp x) {
        // Implementation of arctangent function using series expansion
        Dfp result = x;
        Dfp term = x;
        int n = 1;
        while (term.abs().compareTo(Dfp.ZERO) > 0) {
            term = term.multiply(x.multiply(x)).divide(new Dfp(2 * n + 1));
            result = result.add(term);
            n++;
        }
        return result;
    }

    public Dfp split(Dfp x) {
        // Implementation of split for improved precision
        // Placeholder for split logic
        return x; // Simplified for demonstration
    }

    public Dfp multiply(Dfp x, Dfp y) {
        return x.multiply(y);
    }

    public Dfp divide(Dfp x, Dfp y) {
        return x.divide(y);
    }
}

public class LeaderLatch {
    private final CuratorFramework client;
    private final String latchPath;
    private String currentLeader;
    private final Set<LeaderChangeListener> listeners = new HashSet<>();
    private boolean isLeader = false;

    public LeaderLatch(String connectionString, String latchPath) {
        this.client = CuratorFrameworkFactory.newClient(connectionString, new ExponentialBackoffRetry(1000, 3));
        this.latchPath = latchPath;
        this.client.getConnectionStateListenable().addListener(this::connectionStateChanged);
    }

    public void start() {
        client.start();
        try {
            client.create().creatingParentsIfNeeded().withMode(CreateMode.EPHEMERAL).forPath(latchPath);
            electLeader();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void close() {
        try {
            if (isLeader) {
                client.delete().forPath(latchPath);
            }
            client.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void addLeaderChangeListener(LeaderChangeListener listener) {
        listeners.add(listener);
    }

    public void removeLeaderChangeListener(LeaderChangeListener listener) {
        listeners.remove(listener);
    }

    public void awaitLeadership() {
        while (!isLeader) {
            // Busy waiting - code smell
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public String getCurrentLeader() {
        return currentLeader;
    }

    public Set<String> getParticipants() {
        try {
            return new HashSet<>(client.getChildren().forPath(latchPath));
        } catch (Exception e) {
            e.printStackTrace();
            return new HashSet<>();
        }
    }

    private void electLeader() {
        try {
            currentLeader = client.create().withMode(CreateMode.EPHEMERAL_SEQUENTIAL).forPath(latchPath + "/node-");
            isLeader = true;
            notifyListeners();
        } catch (KeeperException.NodeExistsException e) {
            isLeader = false;
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void notifyListeners() {
        for (LeaderChangeListener listener : listeners) {
            listener.onLeadershipChange(isLeader);
        }
    }

    private void connectionStateChanged(CuratorFramework client, ConnectionState newState) {
        if (newState == ConnectionState.LOST) {
            isLeader = false;
            notifyListeners();
        } else if (newState == ConnectionState.RECONNECTED) {
            electLeader();
        }
    }

    public interface LeaderChangeListener {
        void onLeadershipChange(boolean isLeader);
    }
}

