public class CustomCoordinateSequence implements CoordinateSequence, Serializable {
    private static final long serialVersionUID = 1L;
    private double[][] coordinates;
    private int dimension;

    public CustomCoordinateSequence(int size, int dimension) {
        this.coordinates = new double[size][dimension];
        this.dimension = dimension;
    }

    public CustomCoordinateSequence(double[][] coords) {
        this.coordinates = coords;
        this.dimension = coords[0].length;
    }

    public double[] getCoordinate(int index) {
        return coordinates[index];
    }

    public void setCoordinate(int index, double[] coord) {
        coordinates[index] = coord;
    }

    public int getDimension() {
        return dimension;
    }

    public int size() {
        return coordinates.length;
    }

    public double[] toCoordinateArray() {
        double[] flatArray = new double[size() * dimension];
        for (int i = 0; i < size(); i++) {
            System.arraycopy(coordinates[i], 0, flatArray, i * dimension, dimension);
        }
        return flatArray;
    }

    public void expandEnvelope(Envelope envelope) {
        for (double[] coord : coordinates) {
            for (int i = 0; i < dimension; i++) {
                if (coord[i] < envelope.getMin(i)) {
                    envelope.expandToInclude(coord[i], i);
                }
                if (coord[i] > envelope.getMax(i)) {
                    envelope.expandToInclude(coord[i], i);
                }
            }
        }
    }

    public String toString() {
        return Arrays.deepToString(coordinates);
    }

    public CustomCoordinateSequence copy() {
        return new CustomCoordinateSequence(Arrays.copyOf(coordinates, coordinates.length));
    }
}

