class AgeFileFilterTest {
    private File oldFile;
    private File currentFile;
    private File newFile;
    private AgeFileFilter filter;

    @Before
    public void setUp() throws IOException {
        oldFile = createTempFile("oldFile.txt", System.currentTimeMillis() - 1000 * 60 * 60 * 24 * 10); // 10 days old
        currentFile = createTempFile("currentFile.txt", System.currentTimeMillis()); // current
        newFile = createTempFile("newFile.txt", System.currentTimeMillis() - 1000 * 60 * 60 * 24); // 1 day old
        filter = new AgeFileFilter();
    }

    @After
    public void tearDown() {
        oldFile.delete();
        currentFile.delete();
        newFile.delete();
    }

    private File createTempFile(String fileName, long lastModified) throws IOException {
        File tempFile = File.createTempFile(fileName, null);
        tempFile.setLastModified(lastModified);
        return tempFile;
    }

    @Test
    public void testAcceptOldFile() {
        assertTrue(filter.accept(oldFile));
    }

    @Test
    public void testAcceptCurrentFile() {
        assertTrue(filter.accept(currentFile));
    }

    @Test
    public void testRejectNewFile() {
        assertFalse(filter.accept(newFile));
    }

    @Test
    public void testInclusiveFiltering() {
        filter.setInclusive(true);
        assertTrue(filter.accept(oldFile));
        assertTrue(filter.accept(currentFile));
        assertFalse(filter.accept(newFile));
    }

    @Test
    public void testExclusiveFiltering() {
        filter.setInclusive(false);
        assertFalse(filter.accept(oldFile));
        assertFalse(filter.accept(currentFile));
        assertTrue(filter.accept(newFile));
    }
}

