public class NettyWorkerClientRequestProcessor implements WorkerClientRequestProcessor {
    private final Map<String, Object> vertexCache = new HashMap<>();
    private final Map<String, Object> edgeCache = new HashMap<>();
    private final Map<String, Object> mutationCache = new HashMap<>();
    private final int maxVerticesPerWorker;
    private final int maxEdgesPerWorker;
    private final int maxMutationsPerWorker;

    public NettyWorkerClientRequestProcessor(int maxVertices, int maxEdges, int maxMutations) {
        this.maxVerticesPerWorker = maxVertices;
        this.maxEdgesPerWorker = maxEdges;
        this.maxMutationsPerWorker = maxMutations;
    }

    @Override
    public void sendVertex(String vertexId, Object vertexData) {
        if (vertexCache.size() >= maxVerticesPerWorker) {
            flushVertices();
        }
        vertexCache.put(vertexId, vertexData);
    }

    @Override
    public void sendEdge(String edgeId, Object edgeData) {
        if (edgeCache.size() >= maxEdgesPerWorker) {
            flushEdges();
        }
        edgeCache.put(edgeId, edgeData);
    }

    @Override
    public void sendMutation(String mutationId, Object mutationData) {
        if (mutationCache.size() >= maxMutationsPerWorker) {
            flushMutations();
        }
        mutationCache.put(mutationId, mutationData);
    }

    public void flushVertices() {
        // Logic to send vertices to worker
        vertexCache.clear();
    }

    public void flushEdges() {
        // Logic to send edges to worker
        edgeCache.clear();
    }

    public void flushMutations() {
        // Logic to send mutations to worker
        mutationCache.clear();
    }

    public void flushAll() {
        flushVertices();
        flushEdges();
        flushMutations();
    }
}

