public class UserSync {
    private static final Logger logger = Logger.getLogger(UserSync.class.getName());
    private final String ldapUrl;
    private final String baseDn;
    private final String userDn;
    private final String password;
    private final Hashtable<String, String> env;

    public UserSync(String ldapUrl, String baseDn, String userDn, String password) {
        this.ldapUrl = ldapUrl;
        this.baseDn = baseDn;
        this.userDn = userDn;
        this.password = password;
        this.env = new Hashtable<>();
        initLdapEnvironment();
    }

    private void initLdapEnvironment() {
        env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory");
        env.put(Context.PROVIDER_URL, ldapUrl);
        env.put(Context.SECURITY_AUTHENTICATION, "simple");
        env.put(Context.SECURITY_PRINCIPAL, userDn);
        env.put(Context.SECURITY_CREDENTIALS, password);
    }

    public void syncUsersAndGroups() {
        try {
            DirContext ctx = new InitialDirContext(env);
            List<String> users = retrieveAllUsers(ctx);
            List<String> groups = retrieveAllGroups(ctx);
            logger.info("Synchronization complete. Users: " + users.size() + ", Groups: " + groups.size());
            ctx.close();
        } catch (NamingException e) {
            logger.severe("Error during synchronization: " + e.getMessage());
        }
    }

    private List<String> retrieveAllUsers(DirContext ctx) throws NamingException {
        List<String> users = new ArrayList<>();
        String searchFilter = "(objectClass=person)";
        NamingEnumeration<SearchResult> results = ctx.search(baseDn, searchFilter, getSearchControls());

        while (results.hasMore()) {
            SearchResult result = results.next();
            String user = result.getNameInNamespace();
            users.add(user);
            logger.info("Found user: " + user);
        }
        return users;
    }

    private List<String> retrieveAllGroups(DirContext ctx) throws NamingException {
        List<String> groups = new ArrayList<>();
        String searchFilter = "(objectClass=groupOfNames)";
        NamingEnumeration<SearchResult> results = ctx.search(baseDn, searchFilter, getSearchControls());

        while (results.hasMore()) {
            SearchResult result = results.next();
            String group = result.getNameInNamespace();
            groups.add(group);
            logger.info("Found group: " + group);
        }
        return groups;
    }

    private SearchControls getSearchControls() {
        SearchControls searchControls = new SearchControls();
        searchControls.setSearchScope(SearchControls.SUBTREE_SCOPE);
        return searchControls;
    }

    public static void main(String[] args) {
        UserSync userSync = new UserSync("ldap://localhost:389", "dc=example,dc=com", "cn=admin,dc=example,dc=com", "password");
        userSync.syncUsersAndGroups();
    }
}

