public class RequestParser {
    private static final Logger logger = LoggerFactory.getLogger(RequestParser.class);

    private KeyRequirements keyRequirements;
    private TokenRequirements tokenRequirements;

    public RequestParser() {
        this.keyRequirements = new KeyRequirements();
        this.tokenRequirements = new TokenRequirements();
    }

    public void parse(RequestSecurityTokenType request) {
        try {
            logger.info("Parsing RequestSecurityTokenType...");
            extractKeyRequirements(request);
            extractTokenRequirements(request);
        } catch (Exception e) {
            logger.error("Error parsing RequestSecurityTokenType: {}", e.getMessage());
        }
    }

    private void extractKeyRequirements(RequestSecurityTokenType request) {
        for (Element keyElement : request.getKeyElements()) {
            String keyType = keyElement.getAttribute("KeyType");
            if (keyType == null || keyType.isEmpty()) {
                logger.warn("Unknown KeyType in key element.");
                continue;
            }
            keyRequirements.addKeyType(keyType);
            logger.info("Extracted KeyType: {}", keyType);
        }
    }

    private void extractTokenRequirements(RequestSecurityTokenType request) {
        for (Element tokenElement : request.getTokenElements()) {
            String tokenType = tokenElement.getAttribute("TokenType");
            if (tokenType == null || tokenType.isEmpty()) {
                logger.warn("Unknown TokenType in token element.");
                continue;
            }
            tokenRequirements.addTokenType(tokenType);
            logger.info("Extracted TokenType: {}", tokenType);
        }
    }

    public KeyRequirements getKeyRequirements() {
        return keyRequirements;
