public class SSLUtils {
    private static final String DEFAULT_KEYSTORE_TYPE = "JKS";
    private static final String DEFAULT_TRUSTSTORE_TYPE = "JKS";
    private static final String DEFAULT_PROTOCOL = "TLSv1.2";
    private static final Logger logger = Logger.getLogger(SSLUtils.class.getName());

    public static KeyStore loadKeyStore(String path, String password) throws Exception {
        KeyStore keyStore = KeyStore.getInstance(DEFAULT_KEYSTORE_TYPE);
        try (FileInputStream fis = new FileInputStream(path)) {
            keyStore.load(fis, password.toCharArray());
        }
        return keyStore;
    }

    public static KeyStore loadTrustStore(String path, String password) throws Exception {
        KeyStore trustStore = KeyStore.getInstance(DEFAULT_TRUSTSTORE_TYPE);
        try (FileInputStream fis = new FileInputStream(path)) {
            trustStore.load(fis, password.toCharArray());
        }
        return trustStore;
    }

    public static SSLContext createSSLContext(KeyStore keyStore, String keyPassword, KeyStore trustStore) throws Exception {
        KeyManagerFactory keyManagerFactory = KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());
        keyManagerFactory.init(keyStore, keyPassword.toCharArray());

        TrustManagerFactory trustManagerFactory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        trustManagerFactory.init(trustStore);

        SSLContext sslContext = SSLContext.getInstance(DEFAULT_PROTOCOL);
        sslContext.init(keyManagerFactory.getKeyManagers(), trustManagerFactory.getTrustManagers(), null);
        return sslContext;
    }

    public static void logUnsupportedSSLPolicy(String policy) {
        logger.log(Level.WARNING, "Unsupported SSL Policy: " + policy);
    }

    public static void configureCipherSuites(SSLParameters sslParameters, String[] cipherSuites) {
        sslParameters.setCipherSuites(cipherSuites);
    }

    public static void handleClientAuthentication(SSLParameters sslParameters, boolean requireClientAuth) {
        sslParameters.setNeedClientAuth(requireClientAuth);
    }

    public static void validateKeyStoreParameters(String path, String password) throws IOException {
        if (path == null || path.isEmpty()) {
            throw new IllegalArgumentException("Key store path cannot be null or empty");
        }
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Key store password cannot be null or empty");
        }
