    public static void validateTrustStoreParameters(String path, String password) throws IOException {
        if (path == null || path.isEmpty()) {
            throw new IllegalArgumentException("Trust store path cannot be null or empty");
        }
        if (password == null || password.isEmpty()) {
            throw new IllegalArgumentException("Trust store password cannot be null or empty");
        }
    }
