public class FileSystems {
    private static final Map<String, FileSystem> fileSystemMap = new HashMap<>();
    private static final Set<String> schemes = new HashSet<>();
    private static final String DEFAULT_SCHEME = "file";

    public static void registerFileSystem(String scheme, FileSystem fileSystem) {
        if (schemes.contains(scheme)) {
            throw new IllegalArgumentException("Scheme already registered: " + scheme);
        }
        schemes.add(scheme);
        fileSystemMap.put(scheme, fileSystem);
    }

    public static FileSystem getFileSystem(String scheme) {
        return fileSystemMap.getOrDefault(scheme, fileSystemMap.get(DEFAULT_SCHEME));
    }

    public static List<Path> matchFiles(String scheme, String globPattern) throws IOException {
        FileSystem fs = getFileSystem(scheme);
        PathMatcher matcher = fs.getPathMatcher("glob:" + globPattern);
        List<Path> matchedPaths = new ArrayList<>();

        Files.walk(fs.getPath("/")).forEach(path -> {
            if (matcher.matches(path.getFileName())) {
                matchedPaths.add(path);
            }
        });

        return matchedPaths;
    }

    public static void copyResource(String scheme, Path source, Path target) throws IOException {
        FileSystem fs = getFileSystem(scheme);
        Files.copy(source, target, StandardCopyOption.REPLACE_EXISTING);
    }

    public static void renameResource(String scheme, Path source, Path target) throws IOException {
        FileSystem fs = getFileSystem(scheme);
        Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
    }

    public static void deleteResource(String scheme, Path path) throws IOException {
        FileSystem fs = getFileSystem(scheme);
        Files.delete(path);
    }

    public static void validateResourceId(String resourceId) {
        if (resourceId == null || resourceId.isEmpty()) {
            throw new IllegalArgumentException("Resource ID cannot be null or empty");
        }
    }

    public static void setDefaultPipelineOptions(String scheme, Map<String, String> options) {
        // Implementation for setting default options based on scheme
    }

    public static boolean isUniqueScheme(String scheme) {
        return !schemes.contains(scheme);
    }
}

public class MediaType implements Comparable<MediaType>, Serializable {
    private static final long serialVersionUID = 1L;

    private final String type;
    private final String subtype;
    private final Map<String, String> parameters;

    public MediaType(String type, String subtype) {
        this.type = type;
        this.subtype = subtype;
        this.parameters = new HashMap<>();
    }

    public static MediaType parse(String mediaType) {
        String[] parts = mediaType.split(";");
        String[] typeSubtype = parts[0].trim().split("/");
        if (typeSubtype.length != 2) {
            throw new IllegalArgumentException("Invalid media type format");
        }
        MediaType media = new MediaType(typeSubtype[0].trim(), typeSubtype[1].trim());
        for (int i = 1; i < parts.length; i++) {
            String[] param = parts[i].trim().split("=");
            if (param.length == 2) {
                media.parameters.put(param[0].trim(), param[1].trim());
            }
        }
        return media;
    }

    public String getType() {
        return type;
    }

    public String getSubtype() {
        return subtype;
    }

    public Map<String, String> getParameters() {
        return new HashMap<>(parameters);
    }

    @Override
    public int compareTo(MediaType other) {
        int typeComparison = this.type.compareTo(other.type);
        return typeComparison != 0 ? typeComparison : this.subtype.compareTo(other.subtype);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof MediaType)) return false;
        MediaType mediaType = (MediaType) o;
        return type.equals(mediaType.type) && subtype.equals(mediaType.subtype) && parameters.equals(mediaType.parameters);
    }

    @Override
    public int hashCode() {
        return Objects.hash(type, subtype, parameters);
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder(type).append("/").append(subtype);
        parameters.forEach((key, value) -> sb.append("; ").append(key).append("=").append(value));
        return sb.toString();
    }

    public static MediaType applicationOctetStream() {
        return new MediaType("application", "octet-stream");
    }

    public static MediaType textPlain() {
        return new MediaType("text", "plain");
    }

    // Additional predefined media types can be added here
}

