public class UrlValidator implements Serializable {
    private static final long serialVersionUID = 1L;

    private final Pattern urlPattern;
    private final boolean allowLocal;
    private final boolean allowMultipleSlashes;
    private final boolean allowFragments;

    public UrlValidator() {
        this(true, true, true);
    }

    public UrlValidator(boolean allowLocal, boolean allowMultipleSlashes, boolean allowFragments) {
        this.allowLocal = allowLocal;
        this.allowMultipleSlashes = allowMultipleSlashes;
        this.allowFragments = allowFragments;
        this.urlPattern = createUrlPattern();
    }

    private Pattern createUrlPattern() {
        String scheme = "https?"; // http or https
        String authority = "([\\w.-]+(:\\d+)?|localhost)";
        String path = "(/[^\\s]*)?";
        String query = "(\\?[^#]*)?";
        String fragment = allowFragments ? "(#.*)?" : "";

        return Pattern.compile(scheme + "://" + authority + path + query + fragment);
    }

    public boolean isValid(String url) {
        if (url == null || url.isEmpty()) {
            return false;
        }
        if (!allowLocal && url.startsWith("file://")) {
            return false;
        }
        if (!allowMultipleSlashes && url.contains("//")) {
            return false;
        }
        return urlPattern.matcher(url).matches();
    }

    public boolean isValidScheme(String scheme) {
        return scheme.equals("http") || scheme.equals("https");
    }

    public boolean isValidAuthority(String authority) {
        return authority.matches("([\\w.-]+(:\\d+)?|localhost)");
    }

    public boolean isValidPath(String path) {
        return path.matches("(/[^\\s]*)?");
    }

    public boolean isValidQuery(String query) {
        return query.matches("(\\?[^#]*)?");
    }

    public boolean isValidFragment(String fragment) {
        return allowFragments && fragment.matches("(#.*)?");
    }
}

