public class SAMLProtocolResponseValidator {

    private SAMLResponseValidator samlResponseValidator;
    private SAMLAssertionValidator samlAssertionValidator;
    private SignatureValidator signatureValidator;
    private DecryptionUtility decryptionUtility;

    public SAMLProtocolResponseValidator(SAMLResponseValidator samlResponseValidator,
                                         SAMLAssertionValidator samlAssertionValidator,
                                         SignatureValidator signatureValidator,
                                         DecryptionUtility decryptionUtility) {
        this.samlResponseValidator = samlResponseValidator;
        this.samlAssertionValidator = samlAssertionValidator;
        this.signatureValidator = signatureValidator;
        this.decryptionUtility = decryptionUtility;
    }

    public void validateResponse(Document samlResponse) throws ValidationException {
        if (!samlResponseValidator.isSuccess(samlResponse)) {
            throw new ValidationException("SAML response indicates failure.");
        }

        if (!samlResponseValidator.validateSchema(samlResponse)) {
            throw new ValidationException("SAML response does not conform to the schema.");
        }

        if (!signatureValidator.validateSignature(samlResponse)) {
            throw new ValidationException("SAML response signature validation failed.");
        }

        Document decryptedAssertions = decryptionUtility.decryptAssertions(samlResponse);
        samlAssertionValidator.validateAssertions(decryptedAssertions);
    }
}

