public class SimplePrincipalMap implements PrincipalMap {
    private final Map<String, Map<String, Principal>> realmPrincipals = new HashMap<>();
    private Set<Principal> combinedPrincipals;

    @Override
    public void addPrincipal(String realm, String name, Principal principal) {
        realmPrincipals.computeIfAbsent(realm, k -> new HashMap<>()).put(name, principal);
        combinedPrincipals = null; // Invalidate combined principals
    }

    @Override
    public Principal getPrincipal(String realm, String name) {
        Map<String, Principal> principals = realmPrincipals.get(realm);
        return principals != null ? principals.get(name) : null;
    }

    @Override
    public void removePrincipal(String realm, String name) {
        Map<String, Principal> principals = realmPrincipals.get(realm);
        if (principals != null) {
            principals.remove(name);
            combinedPrincipals = null; // Invalidate combined principals
        }
    }

    @Override
    public int size() {
        return getCombinedPrincipals().size();
    }

    @Override
    public Set<Principal> getCombinedPrincipals() {
        if (combinedPrincipals == null) {
            combinedPrincipals = new HashSet<>();
            for (Map<String, Principal> principals : realmPrincipals.values()) {
                combinedPrincipals.addAll(principals.values());
            }
        }
        return Collections.unmodifiableSet(combinedPrincipals);
    }

    @Override
    public List<Principal> getPrincipalsAsList() {
        return new ArrayList<>(getCombinedPrincipals());
    }

    @Override
    public Set<Principal> getPrincipalsByType(Class<? extends Principal> type) {
        Set<Principal> result = new HashSet<>();
        for (Principal principal : getCombinedPrincipals()) {
            if (type.isInstance(principal)) {
                result.add(principal);
            }
        }
        return Collections.unmodifiableSet(result);
    }

    @Override
    public Map<String, Principal> getRealmPrincipals(String realm) {
        return Collections.unmodifiableMap(realmPrincipals.getOrDefault(realm, Collections.emptyMap()));
    }
}

class SecuredStatementTest {

    private SecurityEvaluator securityEvaluator;
    private SecuredStatement securedStatement;

    @Before
    public void setUp() {
        securityEvaluator = mock(SecurityEvaluator.class);
        securedStatement = new SecuredStatement(securityEvaluator);
    }

    @Test(expected = UpdateDeniedException.class)
    public void testChangeLiteralObjectDenied() {
        when(securityEvaluator.canUpdate(any())).thenReturn(false);
        securedStatement.changeLiteralObject("newValue");
    }

    @Test
    public void testChangeLiteralObjectAllowed() {
        when(securityEvaluator.canUpdate(any())).thenReturn(true);
        securedStatement.changeLiteralObject("newValue");
        assertEquals("newValue", securedStatement.getLiteralObject());
    }

    @Test(expected = AccessDeniedException.class)
    public void testCreateReifiedStatementDenied() {
        when(securityEvaluator.canCreateReifiedStatement(any())).thenReturn(false);
        securedStatement.createReifiedStatement();
    }

    @Test
    public void testCreateReifiedStatementAllowed() {
        when(securityEvaluator.canCreateReifiedStatement(any())).thenReturn(true);
        ReifiedStatement reifiedStatement = securedStatement.createReifiedStatement();
        assertNotNull(reifiedStatement);
    }

    @Test(expected = ReadDeniedException.class)
    public void testGetPropertyDenied() {
        when(securityEvaluator.canRead(any())).thenReturn(false);
        securedStatement.getProperty("propertyName");
    }

    @Test
    public void testGetPropertyAllowed() {
        when(securityEvaluator.canRead(any())).thenReturn(true);
        Property property = securedStatement.getProperty("propertyName");
        assertNotNull(property);
    }

    @Test
    public void testGetters() {
        when(securityEvaluator.canRead(any())).thenReturn(true);
        assertNotNull(securedStatement.getSubject());
        assertNotNull(securedStatement.getPredicate());
        assertNotNull(securedStatement.getObject());
    }
}

