public class SelectTypesDialogCheck extends TitleAreaDialog implements Listener {
    private TypeSystemDescription typeSystemDescription;
    private Map<String, Boolean> selectedTypes;
    private Tree typeTree;
    private String filterText;

    public SelectTypesDialogCheck(Shell parentShell, TypeSystemDescription typeSystemDescription) {
        super(parentShell);
        this.typeSystemDescription = typeSystemDescription;
        this.selectedTypes = new HashMap<>();
    }

    @Override
    protected void configureShell(Shell newShell) {
        super.configureShell(newShell);
        newShell.setText("Select Types");
    }

    @Override
    protected Composite createDialogArea(Composite parent) {
        Composite container = (Composite) super.createDialogArea(parent);
        createTypeTree(container);
        return container;
    }

    private void createTypeTree(Composite parent) {
        typeTree = new Tree(parent, SWT.CHECK | SWT.BORDER);
        List<Type> types = typeSystemDescription.getTypes();
        for (Type type : types) {
            TreeItem item = new TreeItem(typeTree, SWT.NONE);
            item.setText(type.getName());
            selectedTypes.put(type.getName(), false);
            item.addListener(SWT.Selection, this);
        }
    }

    @Override
    public void handleEvent(Event event) {
        if (event.item instanceof TreeItem) {
            TreeItem item = (TreeItem) event.item;
            selectedTypes.put(item.getText(), item.getChecked());
        }
    }

    public Map<String, Boolean> getSelectedTypes() {
        return selectedTypes;
    }

    public void filterTypes(String filter) {
        this.filterText = filter;
        for (TreeItem item : typeTree.getItems()) {
            item.setVisible(item.getText().toLowerCase().contains(filter.toLowerCase()));
        }
    }
}

