public class NumberUtils {
    public static final Long ZERO_LONG = 0L;
    public static final Integer ZERO_INT = 0;
    public static final Short ZERO_SHORT = 0;
    public static final Byte ZERO_BYTE = 0;
    public static final Double ZERO_DOUBLE = 0.0;
    public static final Float ZERO_FLOAT = 0.0f;

    public static final Long ONE_LONG = 1L;
    public static final Integer ONE_INT = 1;
    public static final Short ONE_SHORT = 1;
    public static final Byte ONE_BYTE = 1;
    public static final Double ONE_DOUBLE = 1.0;
    public static final Float ONE_FLOAT = 1.0f;

    public static final Long NEGATIVE_ONE_LONG = -1L;
    public static final Integer NEGATIVE_ONE_INT = -1;
    public static final Short NEGATIVE_ONE_SHORT = -1;
    public static final Byte NEGATIVE_ONE_BYTE = -1;
    public static final Double NEGATIVE_ONE_DOUBLE = -1.0;
    public static final Float NEGATIVE_ONE_FLOAT = -1.0f;

    public static int parseInt(String value, int defaultValue) {
        try {
            return Integer.parseInt(value);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public static long parseLong(String value, long defaultValue) {
        try {
            return Long.parseLong(value);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public static float parseFloat(String value, float defaultValue) {
        try {
            return Float.parseFloat(value);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public static double parseDouble(String value, double defaultValue) {
        try {
            return Double.parseDouble(value);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public static byte parseByte(String value, byte defaultValue) {
        try {
            return Byte.parseByte(value);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public static short parseShort(String value, short defaultValue) {
        try {
            return Short.parseShort(value);
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public static boolean isValidNumber(String value) {
        if (value == null || value.isEmpty()) {
            return false;
        }
        try {
            Double.parseDouble(value);
            return true;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    public static boolean isDigits(String value) {
        if (value == null || value.isEmpty()) {
            return false;
        }
        for (char c : value.toCharArray()) {
            if (!Character.isDigit(c)) {
                return false;
            }
        }
        return true;
    }

    public static BigInteger createBigInteger(String value) {
        return new BigInteger(value);
    }

    public static BigDecimal createBigDecimal(String value) {
        return new BigDecimal(value);
    }

    public static int min(int... values) {
        if (values.length == 0) throw new IllegalArgumentException("Array cannot be empty");
        int min = values[0];
        for (int value : values) {
            if (value < min) {
                min = value;
            }
        }
        return min;
    }

    public static long min(long... values) {
        if (values.length == 0) throw new IllegalArgumentException("Array cannot be empty");
        long min = values[0];
        for (long value : values) {
            if (value < min) {
                min = value;
            }
        }
        return min;
    }

    public static double min(double... values) {
        if (values.length == 0) throw new IllegalArgumentException("Array cannot be empty");
        double min = values[0];
        for (double value : values) {
            if (value < min) {
                min = value;
            }
        }
        return min;
    }

    public static int max(int... values) {
        if (values.length == 0) throw new IllegalArgumentException("Array cannot be empty");
        int max = values[0];
        for (int value : values) {
            if (value > max) {
                max = value;
            }
        }
        return max;
    }

    public static long max(long... values) {
        if (values.length == 0) throw new IllegalArgumentException("Array cannot be empty");
        long max = values[0];
        for (long value : values) {
            if (value > max) {
                max = value;
            }
        }
        return max;
    }

    public static double max(double... values) {
        if (values.length == 0) throw new IllegalArgumentException("Array cannot be empty");
        double max = values[0];
        for (double value : values) {
            if (value > max) {
                max = value;
            }
        }
        return max;
    }
