public class LoadBalanceTest {

    private BrokerService broker1;
    private BrokerService broker2;
    private PooledConnectionFactory connectionFactory1;
    private PooledConnectionFactory connectionFactory2;
    private CountDownLatch latch1;
    private CountDownLatch latch2;
    private int messageCount = 50;

    @Before
    public void setUp() throws Exception {
        broker1 = new BrokerService();
        broker2 = new BrokerService();

        broker1.setBrokerName("Broker1");
        broker2.setBrokerName("Broker2");

        TransportConnector connector1 = broker1.addConnector("tcp://localhost:61616");
        TransportConnector connector2 = broker2.addConnector("tcp://localhost:61617");

        broker1.start();
        broker2.start();

        connectionFactory1 = new PooledConnectionFactory("tcp://localhost:61616");
        connectionFactory2 = new PooledConnectionFactory("tcp://localhost:61617");

        latch1 = new CountDownLatch(messageCount / 2);
        latch2 = new CountDownLatch(messageCount / 2);

        createMessageListener(connectionFactory1, latch1);
        createMessageListener(connectionFactory2, latch2);

        waitForNetworkBridge();
    }

    private void createMessageListener(PooledConnectionFactory connectionFactory, CountDownLatch latch) {
        try {
            Connection connection = connectionFactory.createConnection();
