public class TransactionContext implements XAResource {
    private static final Logger logger = Logger.getLogger(TransactionContext.class.getName());
    private List<XASynchronization> synchronizations = new ArrayList<>();
    private String transactionId;
    private boolean isActive = false;

    public void begin() throws XAException {
        if (isActive) {
            throw new XAException(XAException.XAER_PROTO);
        }
        transactionId = generateTransactionId();
        isActive = true;
        logger.info("Transaction started: " + transactionId);
    }

    public void commit(Xid xid, boolean onePhase) throws XAException {
        if (!isActive) {
            throw new XAException(XAException.XAER_NOTA);
        }
        try {
            for (XASynchronization sync : synchronizations) {
                sync.beforeCompletion();
            }
            // Commit logic here
            isActive = false;
            logger.info("Transaction committed: " + transactionId);
        } catch (Exception e) {
            logger.severe("Commit failed: " + e.getMessage());
            throw new XAException(XAException.XAER_RMERR);
        }
    }

    public void rollback(Xid xid) throws XAException {
        if (!isActive) {
            throw new XAException(XAException.XAER_NOTA);
        }
        try {
            for (XASynchronization sync : synchronizations) {
                sync.afterCompletion(XAResource.XA_ROLLBACK);
            }
            // Rollback logic here
            isActive = false;
            logger.info("Transaction rolled back: " + transactionId);
        } catch (Exception e) {
            logger.severe("Rollback failed: " + e.getMessage());
            throw new XAException(XAException.XAER_RMERR);
        }
    }

    public void prepare(Xid xid) throws XAException {
        if (!isActive) {
            throw new XAException(XAException.XAER_NOTA);
        }
        // Prepare logic here
        logger.info("Transaction prepared: " + transactionId);
    }

    public void registerSynchronization(XASynchronization synchronization) {
        synchronizations.add(synchronization);
    }

    private String generateTransactionId() {
        return String.valueOf(System.currentTimeMillis());
    }

    // XAResource methods
    public void commit(Xid xid, boolean onePhase) throws XAException {}
    public void end(Xid xid, int flags) throws XAException {}
    public void forget(Xid xid) throws XAException {}
    public int getTransactionTimeout() throws XAException { return 0; }
    public boolean isSameRM(XAResource xaResource) throws XAException { return false; }
    public int prepare(Xid xid) throws XAException { return 0; }
    public Xid[] recover(int flag) throws XAException { return new Xid[0]; }
    public void rollback(Xid xid) throws XAException {}
    public boolean setTransactionTimeout(int seconds) throws XAException { return false; }
    public void start(Xid xid, int flags) throws XAException {}
}

public class IntegerArray {
    private int[] array;
    private int size;
    private int capacity;

    public IntegerArray(int initialCapacity) {
        this.capacity = initialCapacity;
        this.array = new int[capacity];
        this.size = 0;
    }

    public void add(int value) {
        if (size >= capacity) {
            increaseCapacity();
        }
        array[size++] = value;
    }

    private void increaseCapacity() {
        capacity += 10;
        int[] newArray = new int[capacity];
        for (int i = 0; i < size; i++) {
            newArray[i] = array[i];
        }
        array = newArray;
    }

    public int[] toArray() {
        int[] result = new int[size];
        for (int i = 0; i < size; i++) {
            result[i] = array[i];
        }
        return result;
    }
}

