public class BOMInputStream extends ProxyInputStream {
    private static final byte[] BOM_UTF_8 = new byte[]{(byte) 0xEF, (byte) 0xBB, (byte) 0xBF};
    private static final byte[] BOM_UTF_16LE = new byte[]{(byte) 0xFF, (byte) 0xFE};
    private static final byte[] BOM_UTF_16BE = new byte[]{(byte) 0xFE, (byte) 0xFF};

    private byte[] bom;
    private boolean bomIncluded;
    private boolean bomDetected;

    public BOMInputStream(InputStream in) throws IOException {
        super(in);
        detectBOM();
    }

    private void detectBOM() throws IOException {
        mark(BOM_UTF_8.length);
        byte[] header = new byte[BOM_UTF_8.length];
        int bytesRead = read(header);
        reset();

        if (bytesRead >= BOM_UTF_8.length && matchesBOM(header, BOM_UTF_8)) {
            bom = BOM_UTF_8;
            bomDetected = true;
        } else if (bytesRead >= BOM_UTF_16LE.length && matchesBOM(header, BOM_UTF_16LE)) {
            bom = BOM_UTF_16LE;
            bomDetected = true;
        } else if (bytesRead >= BOM_UTF_16BE.length && matchesBOM(header, BOM_UTF_16BE)) {
            bom = BOM_UTF_16BE;
            bomDetected = true;
        }
    }

    private boolean matchesBOM(byte[] header, byte[] bom) {
        for (int i = 0; i < bom.length; i++) {
            if (header[i] != bom[i]) {
                return false;
            }
        }
        return true;
    }

    public boolean isBOMDetected() {
        return bomDetected;
    }

    public String getCharsetName() {
        if (bom == BOM_UTF_8) {
            return "UTF-8";
        } else if (bom == BOM_UTF_16LE) {
            return "UTF-16LE";
        } else if (bom == BOM_UTF_16BE) {
            return "UTF-16BE";
        }
        return null;
    }

    @Override
    public int read() throws IOException {
        if (bomIncluded && bom != null) {
            bomIncluded = false;
            return bom[0]; // Return the first byte of BOM
        }
        return super.read();
    }

    @Override
    public int read(byte[] b, int off, int len) throws IOException {
        if (bomIncluded && bom != null) {
            System.arraycopy(bom, 0, b, off, bom.length);
            bomIncluded = false;
            return bom.length + super.read(b, off + bom.length, len - bom.length);
        }
        return super.read(b, off, len);
    }

    public void includeBOM() {
        this.bomIncluded = true;
    }

    public void resetBOM() {
        this.bomIncluded = false;
    }
}

public class KahaPersistenceAdapter extends BrokerFilter {
    private final KahaDB kahaDB;
    private final ConcurrentHashMap<String, MessageStore> messageStores = new ConcurrentHashMap<>();
    private final File dataDirectory;

    public KahaPersistenceAdapter(Broker next, File dataDirectory) {
        super(next);
        this.dataDirectory = dataDirectory;
        this.kahaDB = new KahaDB(dataDirectory);
    }

    public void createQueue(String queueName) {
        if (!messageStores.containsKey(queueName)) {
            MessageStore store = kahaDB.createQueueStore(queueName);
            messageStores.put(queueName, store);
        }
    }

    public void removeQueue(String queueName) {
        MessageStore store = messageStores.remove(queueName);
        if (store != null) {
            kahaDB.removeQueueStore(store);
        }
    }

    public void createTopic(String topicName) {
        if (!messageStores.containsKey(topicName)) {
            MessageStore store = kahaDB.createTopicStore(topicName);
            messageStores.put(topicName, store);
        }
    }

    public void removeTopic(String topicName) {
        MessageStore store = messageStores.remove(topicName);
        if (store != null) {
            kahaDB.removeTopicStore(store);
        }
    }

    public void beginTransaction() {
        kahaDB.beginTransaction();
    }

    public void commitTransaction() {
        kahaDB.commitTransaction();
    }

    public void rollbackTransaction() {
        kahaDB.rollbackTransaction();
    }

    public void initialize() {
        kahaDB.start();
    }

    public void checkpoint() {
        kahaDB.checkpoint();
    }

    public void deleteAllMessages() {
        for (String key : messageStores.keySet()) {
            messageStores.get(key).deleteAllMessages();
        }
    }

    public Destination getDestination(String destinationName) {
        return messageStores.containsKey(destinationName) ? messageStores.get(destinationName) : null;
    }

    public void stop() {
        kahaDB.stop();
    }
}

