    }

    public abstract void restore(Node node, String versionName) throws RepositoryException;

    public abstract void restore(Node node, Version version) throws RepositoryException;

    public abstract void restore(Node node, String versionLabel, boolean removeExisting) throws RepositoryException;

    protected void checkVersionable(Node node) throws RepositoryException {
        if (!node.isNodeType("mix:versionable")) {
            throw new RepositoryException("Node is not versionable.");
        }
    }

    protected VersionHistory getVersionHistory(Node node) throws RepositoryException {
        return node.getVersionHistory();
    }

    protected void restoreFrozenNode(Node node, Version version) throws RepositoryException {
        // Logic to restore frozen node
    }

    protected void manageChildNodes(Node node, Version version) throws RepositoryException {
        // Logic to manage child nodes during restoration
    }

    protected void handleWriteOperation(Runnable operation) throws RepositoryException {
        try {
            operation.run();
            session.save();
        } catch (RepositoryException e) {
            throw new RepositoryException("Error during write operation.", e);
        }
    }

    protected void validateVersionCompatibility(Node node, Version version) throws RepositoryException {
        VersionHistory history = getVersionHistory(node);
        if (!history.isNodeInHistory(version.getNode())) {
            throw new RepositoryException("Version is not compatible with the node's version history.");
        }
    }

    protected void restoreNode(Node node, Version version) throws RepositoryException {
        checkVersionable(node);
        validateVersionCompatibility(node, version);
        handleWriteOperation(() -> {
            restoreFrozenNode(node, version);
            manageChildNodes(node, version);
        });
    }
}

