public class JdbmTable<K, V> extends AbstractTable<K, V> {
    private static final Logger logger = Logger.getLogger(JdbmTable.class.getName());
    private RecordManager recordManager;
    private BTree<K, V> primaryBTree;
    private BTree<K, V> duplicateBTree;
    private Serializer<K> keySerializer;
    private Serializer<V> valueSerializer;

    public JdbmTable(RecordManager recordManager, Serializer<K> keySerializer, Serializer<V> valueSerializer) {
        this.recordManager = recordManager;
        this.keySerializer = keySerializer;
        this.valueSerializer = valueSerializer;
        this.primaryBTree = new BTree<>();
        this.duplicateBTree = new BTree<>();
    }

    public void insert(K key, V value) {
        logger.info("Inserting key: " + key + ", value: " + value);
        if (primaryBTree.contains(key)) {
            duplicateBTree.insert(key, value);
        } else {
            primaryBTree.insert(key, value);
        }
    }

    public void remove(K key, V value) {
        logger.info("Removing key: " + key + ", value: " + value);
        if (duplicateBTree.contains(key)) {
            duplicateBTree.remove(key, value);
        } else {
            primaryBTree.remove(key);
        }
    }

    public V retrieve(K key) {
        logger.info("Retrieving key: " + key);
        if (primaryBTree.contains(key)) {
            return primaryBTree.get(key);
        } else {
            return duplicateBTree.get(key);
        }
    }

    public int countOccurrences(K key) {
        logger.info("Counting occurrences for key: " + key);
        int count = 0;
        if (primaryBTree.contains(key)) {
            count++;
        }
        count += duplicateBTree.count(key);
        return count;
    }

    public boolean checkCondition(K key, V value, String condition) {
        logger.info("Checking condition for key: " + key + ", value: " + value + ", condition: " + condition);
        V storedValue = retrieve(key);
        if (storedValue == null) {
            return false;
        }
        switch (condition) {
            case ">":
                return compare(storedValue, value) > 0;
            case "<":
                return compare(storedValue, value) < 0;
            default:
                return false;
        }
    }

    private int compare(V v1, V v2) {
        // Assuming V implements Comparable
        return ((Comparable<V>) v1).compareTo(v2);
    }

    // Additional methods for persistence and synchronization can be added here
}

