class MicroKernelImplTest {
    private MicroKernelImpl microKernel;

    @BeforeEach
    void setUp() {
        microKernel = new MicroKernelImpl();
    }

    @Test
    void testCommitClashHandling() {
        String commitId1 = microKernel.commit("Initial commit");
        String commitId2 = microKernel.commit("Second commit");

        assertNotEquals(commitId1, commitId2, "Commit IDs should be unique");
    }

    @Test
    void testDiffWithDepth() {
        microKernel.commit("Initial commit");
        microKernel.addNode("node1", "value1");
        microKernel.commit("Add node1");

        String diff = microKernel.diff(1);
        assertTrue(diff.contains("node1"), "Diff should contain changes for node1");
    }

    @Test
    void testRebaseBranchWithChanges() {
        microKernel.commit("Initial commit");
        microKernel.addNode("node1", "value1");
        String branchId = microKernel.createBranch("feature-branch");

        microKernel.addNode("node2", "value2");
        microKernel.commit("Add node2 on feature branch");

        microKernel.rebase(branchId);
        assertTrue(microKernel.hasNode("node2"), "Node2 should exist after rebase");
    }

    @Test
    void testRebaseBranchWithoutChanges() {
        microKernel.commit("Initial commit");
        String branchId = microKernel.createBranch("feature-branch");

        microKernel.rebase(branchId);
        assertEquals(1, microKernel.getCommitCount(), "Commit count should remain the same");
    }

    @Test
    void testMergeRebasedBranch() {
        microKernel.commit("Initial commit");
        String branchId = microKernel.createBranch("feature-branch");

        microKernel.addNode("node1", "value1");
        microKernel.commit("Add node1 on feature branch");

        microKernel.rebase(branchId);
        microKernel.merge(branchId);

        assertTrue(microKernel.hasNode("node1"), "Node1 should exist after merging");
    }

    @Test
    void testIntegrityAfterOperations() {
        microKernel.commit("Initial commit");
        microKernel.addNode("node1", "value1");
        microKernel.commit("Add node1");

        microKernel.addNode("node2", "value2");
        microKernel.removeNode("node1");
        microKernel.commit("Remove node1 and add node2");

        assertFalse(microKernel.hasNode("node1"), "Node1 should not exist after removal");
        assertTrue(microKernel.hasNode("node2"), "Node2 should exist after addition");
    }
}

public class AtlasTransientTypeRegistry extends AtlasTypeRegistry {
    private Map<String, AtlasTypeDefinition> typeDefinitions = new HashMap<>();
    private List<AtlasTypeDefinition> addedTypes = new ArrayList<>();
    private List<AtlasTypeDefinition> updatedTypes = new ArrayList<>();
    private List<AtlasTypeDefinition> deletedTypes = new ArrayList<>();

    public void addType(AtlasTypeDefinition typeDefinition) {
        typeDefinitions.put(typeDefinition.getName(), typeDefinition);
        addedTypes.add(typeDefinition);
        logOperation("Added type: " + typeDefinition.getName());
    }

    public void updateTypeByGuid(String guid, AtlasTypeDefinition updatedDefinition) {
        if (typeDefinitions.containsKey(updatedDefinition.getName())) {
            typeDefinitions.put(updatedDefinition.getName(), updatedDefinition);
            updatedTypes.add(updatedDefinition);
            logOperation("Updated type: " + updatedDefinition.getName());
        }
    }

    public void updateTypeByName(String name, AtlasTypeDefinition updatedDefinition) {
        if (typeDefinitions.containsKey(name)) {
            typeDefinitions.put(name, updatedDefinition);
            updatedTypes.add(updatedDefinition);
            logOperation("Updated type: " + name);
        }
    }

    public void removeTypeByGuid(String guid) {
        AtlasTypeDefinition removedType = typeDefinitions.remove(guid);
        if (removedType != null) {
            deletedTypes.add(removedType);
            logOperation("Removed type by GUID: " + guid);
        }
    }

    public void removeTypeByName(String name) {
        AtlasTypeDefinition removedType = typeDefinitions.remove(name);
        if (removedType != null) {
            deletedTypes.add(removedType);
            logOperation("Removed type by name: " + name);
        }
    }

    public void clearRegistry() {
        typeDefinitions.clear();
        addedTypes.clear();
        updatedTypes.clear();
        deletedTypes.clear();
        logOperation("Cleared registry");
    }

    public List<AtlasTypeDefinition> getAddedTypes() {
        return addedTypes;
    }

    public List<AtlasTypeDefinition> getUpdatedTypes() {
        return updatedTypes;
    }

    public List<AtlasTypeDefinition> getDeletedTypes() {
        return deletedTypes;
    }

    private void logOperation(String message) {
        System.out.println(message); // Placeholder for actual logging
    }
}

public class UserReportlet extends AbstractReportlet {
    private static final Logger logger = Logger.getLogger(UserReportlet.class.getName());
    private UserReportletConf config;
    private UserDAO userDAO;
    private AttributeDAO attributeDAO;
    private RelationshipDAO relationshipDAO;
    private MembershipDAO membershipDAO;

    public UserReportlet(UserReportletConf config, UserDAO userDAO, AttributeDAO attributeDAO, 
                         RelationshipDAO relationshipDAO, MembershipDAO membershipDAO) {
        this.config = config;
        this.userDAO = userDAO;
        this.attributeDAO = attributeDAO;
        this.relationshipDAO = relationshipDAO;
        this.membershipDAO = membershipDAO;
    }

    public String generateReport() {
        StringBuilder xmlReport = new StringBuilder();
        xmlReport.append("<UserReport>");

        List<User> users = userDAO.getUsers(config.getPagination());
        for (User user : users) {
            xmlReport.append("<User>");
            appendUserData(xmlReport, user);
            xmlReport.append("</User>");
        }

        xmlReport.append("</UserReport>");
        return xmlReport.toString();
    }

    private void appendUserData(StringBuilder xmlReport, User user) {
        xmlReport.append("<UserId>").append(user.getId()).append("</UserId>");
        appendAttributes(xmlReport, user);
        appendRelationships(xmlReport, user);
        appendMemberships(xmlReport, user);
    }

    private void appendAttributes(StringBuilder xmlReport, User user) {
        List<Attribute> attributes = attributeDAO.getAttributesForUser(user.getId());
        if (attributes.isEmpty()) {
            logger.warning("No attributes found for user: " + user.getId());
        }
        for (Attribute attribute : attributes) {
            xmlReport.append("<Attribute>");
            xmlReport.append("<Name>").append(attribute.getName()).append("</Name>");
            xmlReport.append("<Value>").append(attribute.getValue()).append("</Value>");
            xmlReport.append("</Attribute>");
        }
    }

    private void appendRelationships(StringBuilder xmlReport, User user) {
        List<Relationship> relationships = relationshipDAO.getRelationshipsForUser(user.getId());
        if (relationships.isEmpty()) {
            logger.warning("No relationships found for user: " + user.getId());
        }
        for (Relationship relationship : relationships) {
            xmlReport.append("<Relationship>");
            xmlReport.append("<Type>").append(relationship.getType()).append("</Type>");
            xmlReport.append("<RelatedUserId>").append(relationship.getRelatedUserId()).append("</RelatedUserId>");
            xmlReport.append("</Relationship>");
        }
    }

    private void appendMemberships(StringBuilder xmlReport, User user) {
        List<Membership> memberships = membershipDAO.getMembershipsForUser(user.getId());
        if (memberships.isEmpty()) {
            logger.warning("No memberships found for user: " + user.getId());
        }
        for (Membership membership : memberships) {
            xmlReport.append("<Membership>");
            xmlReport.append("<GroupId>").append(membership.getGroupId()).append("</GroupId>");
            xmlReport.append("<Role>").append(membership.getRole()).append("</Role>");
            xmlReport.append("</Membership>");
        }
    }
}

