public class DockerClient {
    private final String dockerHost;
    private final ObjectMapper objectMapper;

    public DockerClient(String dockerHost) {
        this.dockerHost = dockerHost;
        this.objectMapper = new ObjectMapper();
    }

    public String getServerVersion() throws IOException {
        return sendRequest("/version", "GET");
    }

    public List<Container> listContainers() throws IOException {
        String response = sendRequest("/containers/json", "GET");
        return objectMapper.readValue(response, objectMapper.getTypeFactory().constructCollectionType(List.class, Container.class));
    }

    public void createContainer(ContainerConfig config) throws IOException {
        sendRequest("/containers/create", "POST", config);
    }

    public void startContainer(String containerId) throws IOException {
        sendRequest("/containers/" + containerId + "/start", "POST");
    }

    public void stopContainer(String containerId) throws IOException {
        sendRequest("/containers/" + containerId + "/stop", "POST");
    }

    public void restartContainer(String containerId) throws IOException {
        sendRequest("/containers/" + containerId + "/restart", "POST");
    }

    public void pauseContainer(String containerId) throws IOException {
        sendRequest("/containers/" + containerId + "/pause", "POST");
    }

    public void unpauseContainer(String containerId) throws IOException {
        sendRequest("/containers/" + containerId + "/unpause", "POST");
    }

    public void renameContainer(String containerId, String newName) throws IOException {
        sendRequest("/containers/" + containerId + "/rename?name=" + newName, "POST");
    }

    public void removeContainer(String containerId) throws IOException {
        sendRequest("/containers/" + containerId, "DELETE");
    }

    public String getContainerLogs(String containerId) throws IOException {
        return sendRequest("/containers/" + containerId + "/logs", "GET");
    }

    public void commitContainer(String containerId, String repository) throws IOException {
        sendRequest("/commit?container=" + containerId + "&repo=" + repository, "POST");
    }

    public void pullImage(String imageName) throws IOException {
        sendRequest("/images/create?fromImage=" + imageName, "POST");
    }

    public void pushImage(String imageName) throws IOException {
        sendRequest("/images/" + imageName + "/push", "POST");
    }

    public void tagImage(String imageName, String tag) throws IOException {
        sendRequest("/images/" + imageName + "/tag?tag=" + tag, "POST");
    }

    public void removeImage(String imageName) throws IOException {
        sendRequest("/images/" + imageName, "DELETE");
    }

    public List<Image> searchImages(String term) throws IOException {
        String response = sendRequest("/images/search?term=" + term, "GET");
        return objectMapper.readValue(response, objectMapper.getTypeFactory().constructCollectionType(List.class, Image.class));
    }

    public Image getImageDetails(String imageId) throws IOException {
        String response = sendRequest("/images/" + imageId + "/json", "GET");
        return objectMapper.readValue(response, Image.class);
    }

    public List<ImageHistory> getImageHistory(String imageId) throws IOException {
        String response = sendRequest("/images/" + imageId + "/history", "GET");
        return objectMapper.readValue(response, objectMapper.getTypeFactory().constructCollectionType(List.class, ImageHistory.class));
    }

    private String sendRequest(String endpoint, String method) throws IOException {
        return sendRequest(endpoint, method, null);
    }

    private String sendRequest(String endpoint, String method, Object body) throws IOException {
        URL url = new URL(dockerHost + endpoint);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod(method);
        connection.setRequestProperty("Content-Type", "application/json");
        connection.setDoOutput(true);

        if (body != null) {
            String jsonBody = objectMapper.writeValueAsString(body);
            connection.getOutputStream().write(jsonBody.getBytes());
        }

        int responseCode = connection.getResponseCode();
        if (responseCode != HttpURLConnection.HTTP_OK && responseCode != HttpURLConnection.HTTP_CREATED) {
            throw new IOException("Failed : HTTP error code : " + responseCode);
        }

        return new String(connection.getInputStream().readAllBytes());
    }
}

