public class GraphCentricQueryBuilder {
    private List<String> conditions;
    private List<String> orderBy;
    private int limit;

    public GraphCentricQueryBuilder() {
        this.conditions = new ArrayList<>();
        this.orderBy = new ArrayList<>();
        this.limit = -1; // Default no limit
    }

    public GraphCentricQueryBuilder addEqualityCondition(String property, String value) {
        conditions.add(property + " = '" + value + "'");
        return this;
    }

    public GraphCentricQueryBuilder addInequalityCondition(String property, String value) {
        conditions.add(property + " != '" + value + "'");
        return this;
    }

    public GraphCentricQueryBuilder addRangeCondition(String property, String minValue, String maxValue) {
        conditions.add(property + " >= '" + minValue + "' AND " + property + " <= '" + maxValue + "'");
        return this;
    }

    public GraphCentricQueryBuilder addOrderBy(String property, boolean ascending) {
        orderBy.add(property + (ascending ? " ASC" : " DESC"));
        return this;
    }

    public GraphCentricQueryBuilder setLimit(int limit) {
        this.limit = limit;
        return this;
    }

    public String buildQuery() {
        StringBuilder query = new StringBuilder("SELECT * FROM graph WHERE ");
        query.append(String.join(" AND ", conditions));

        if (!orderBy.isEmpty()) {
            query.append(" ORDER BY ").append(String.join(", ", orderBy));
        }

        if (limit > 0) {
            query.append(" LIMIT ").append(limit);
        }

        return query.toString();
    }

