public class RCFileAppender extends FileAppender {
    private List<byte[]> columnBuffers;
    private int rowCount;
    private long byteSize;
    private boolean isClosed;
    private String filePath;

    public RCFileAppender(String filePath) {
        this.filePath = filePath;
        this.columnBuffers = new ArrayList<>();
        this.rowCount = 0;
        this.byteSize = 0;
        this.isClosed = false;
        initializeFileHeader();
    }

    private void initializeFileHeader() {
        // Write magic number and metadata to the file
        try (FileOutputStream fos = new FileOutputStream(filePath, true)) {
            fos.write("RCF".getBytes()); // Magic number
            // Additional metadata initialization
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public synchronized void appendRecord(Object[] record) {
        if (isClosed) {
            throw new IllegalStateException("Cannot append to a closed appender.");
        }
        // Serialize record into column buffers
        for (int i = 0; i < record.length; i++) {
            byte[] serializedData = serialize(record[i]);
            columnBuffers.add(serializedData);
            byteSize += serializedData.length;
        }
        rowCount++;
    }

    private byte[] serialize(Object data) {
        // Implement serialization logic
        return data.toString().getBytes(); // Simplified for example
    }

    public synchronized void flush() {
        if (isClosed) {
            throw new IllegalStateException("Cannot flush a closed appender.");
        }
        // Write column buffers to the output stream
        try (FileOutputStream fos = new FileOutputStream(filePath, true)) {
            for (byte[] buffer : columnBuffers) {
                fos.write(buffer);
            }
            columnBuffers.clear();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public synchronized void close() {
        if (!isClosed) {
            flush();
            // Finalize file footer and close resources
            isClosed = true;
        }
    }

    public int getRowCount() {
        return rowCount;
    }

    public long getByteSize() {
        return byteSize;
    }
}

