class TestNonStringMapKeys {

    @Test
    public void testNonStringMapKeys() throws Exception {
        Company company = createCompany();
        byte[] serializedData = serialize(company);
        Company deserializedCompany = deserialize(serializedData, Company.class);
        assertEquals(company, deserializedCompany);
    }

    @Test
    public void testNonStringMapKeysInNestedMaps() throws Exception {
        Company2 company2 = createCompany2();
        byte[] serializedData = serialize(company2);
        Company2 deserializedCompany2 = deserialize(serializedData, Company2.class);
        assertEquals(company2, deserializedCompany2);
    }

    @Test
    public void testRecordNameInvariance() throws Exception {
        SameMapSignature sameMapSignature = createSameMapSignature();
        byte[] serializedData = serialize(sameMapSignature);
        SameMapSignature deserializedSignature = deserialize(serializedData, SameMapSignature.class);
        assertEquals(sameMapSignature, deserializedSignature);
    }

    private <T> byte[] serialize(T object) throws Exception {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        DatumWriter<T> writer = new SpecificDatumWriter<>(object.getClass());
        Encoder encoder = EncoderFactory.get().binaryEncoder(outputStream, null);
        writer.write(object, encoder);
        encoder.flush();
        return outputStream.toByteArray();
    }

    private <T> T deserialize(byte[] data, Class<T> clazz) throws Exception {
        DatumReader<T> reader = new SpecificDatumReader<>(clazz);
        Decoder decoder = DecoderFactory.get().binaryDecoder(data, null);
        return reader.read(null, decoder);
    }

    private Company createCompany() {
        Map<EmployeeId, Employee> employees = new HashMap<>();
        // Populate employees map
        return new Company(employees);
    }

    private Company2 createCompany2() {
        Map<EmployeeId, Map<EmployeeId, Employee>> nestedMap = new HashMap<>();
        // Populate nestedMap
        return new Company2(nestedMap);
    }

    private SameMapSignature createSameMapSignature() {
        Map<EmployeeId, Employee> map1 = new HashMap<>();
        Map<EmployeeId, Employee> map2 = new HashMap<>();
        // Populate maps
        return new SameMapSignature(map1, map2);
    }
}

