public class KahaDBMessageStore extends AbstractMessageStore {
    private ConcurrentHashMap<String, List<Message>> messageMap;
    private Semaphore semaphore;

    public KahaDBMessageStore() {
        this.messageMap = new ConcurrentHashMap<>();
        this.semaphore = new Semaphore(1);
    }

    public void addMessage(String destination, Message message) {
        try {
            semaphore.acquire();
            messageMap.computeIfAbsent(destination, k -> new ArrayList<>()).add(message);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            semaphore.release();
        }
    }

    public void removeMessage(String destination, Message message) {
        try {
            semaphore.acquire();
            List<Message> messages = messageMap.get(destination);
            if (messages != null) {
                messages.remove(message);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            semaphore.release();
        }
    }

    public List<Message> retrieveMessages(String destination) {
        try {
            semaphore.acquire();
            return new ArrayList<>(messageMap.getOrDefault(destination, new ArrayList<>()));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return new ArrayList<>();
        } finally {
            semaphore.release();
        }
    }

    public int countMessages(String destination) {
        try {
            semaphore.acquire();
            return messageMap.getOrDefault(destination, new ArrayList<>()).size();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return 0;
        } finally {
            semaphore.release();
        }
    }

    public boolean isEmpty(String destination) {
        try {
            semaphore.acquire();
            return messageMap.getOrDefault(destination, new ArrayList<>()).isEmpty();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return true;
        } finally {
            semaphore.release();
        }
    }

    public void batchAddMessages(String destination, List<Message> messages) {
        try {
            semaphore.acquire();
            messageMap.computeIfAbsent(destination, k -> new ArrayList<>()).addAll(messages);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            semaphore.release();
        }
    }
}

