    private ServletRequest request;
    private ServletResponse response;
    private JspWriter out;
    private ServletContext application;
    private HttpSession session;
    private Map<String, Object> pageAttributes = new HashMap<>();

    public PageContextImpl(ServletRequest request, ServletResponse response, JspWriter out, 
                           ServletContext application, HttpSession session) {
        this.request = request;
        this.response = response;
        this.out = out;
        this.application = application;
        this.session = session;
    }

    public Object getAttribute(String name) {
        Object value = pageAttributes.get(name);
        if (value == null) {
            value = request.getAttribute(name);
            if (value == null) {
                value = session.getAttribute(name);
                if (value == null) {
                    value = application.getAttribute(name);
                }
            }
        }
        return value;
    }

    public void setAttribute(String name, Object value) {
        if (value == null) {
            removeAttribute(name);
        } else {
            pageAttributes.put(name, value);
        }
    }

    public void removeAttribute(String name) {
        pageAttributes.remove(name);
    }

