public class TestSnapshotDeletion {
    private MiniDFSCluster cluster;
    private FSNamesystem fsn;

    @Before
    public void setUp() throws Exception {
        MiniDFSCluster.Builder builder = new MiniDFSCluster.Builder(new Configuration());
        cluster = builder.build();
        fsn = cluster.getNamesystem();
    }

    @After
    public void tearDown() throws Exception {
        if (cluster != null) {
            cluster.shutdown();
        }
    }

    @Test(expected = SnapshotException.class)
    public void testDeleteSnapshottableDirectory() throws IOException {
        String dirPath = "/testDir";
        cluster.getFileSystem().mkdirs(new Path(dirPath));
        cluster.getFileSystem().allowSnapshot(new Path(dirPath));
        cluster.getFileSystem().createSnapshot(new Path(dirPath), "snapshot1");
        cluster.getFileSystem().delete(new Path(dirPath), true);
    }

    @Test
    public void testSnapshotCreationAndDeletion() throws IOException {
        String dirPath = "/testDir";
        cluster.getFileSystem().mkdirs(new Path(dirPath));
        cluster.getFileSystem().allowSnapshot(new Path(dirPath));
        cluster.getFileSystem().createSnapshot(new Path(dirPath), "snapshot1");

        Assert.assertTrue(cluster.getFileSystem().exists(new Path(dirPath + "/.snapshot/snapshot1")));

        cluster.getFileSystem().deleteSnapshot(new Path(dirPath), "snapshot1");
        Assert.assertFalse(cluster.getFileSystem().exists(new Path(dirPath + "/.snapshot/snapshot1")));
    }

    @Test
    public void testDirectoryModificationImpactOnSnapshots() throws IOException {
        String dirPath = "/testDir";
        cluster.getFileSystem().mkdirs(new Path(dirPath));
        cluster.getFileSystem().allowSnapshot(new Path(dirPath));
        cluster.getFileSystem().createSnapshot(new Path(dirPath), "snapshot1");

        cluster.getFileSystem().createNewFile(new Path(dirPath + "/file1"));
        Assert.assertTrue(cluster.getFileSystem().exists(new Path(dirPath + "/file1")));

        // Check snapshot state
        Assert.assertFalse(cluster.getFileSystem().exists(new Path(dirPath + "/.snapshot/snapshot1/file1")));

        cluster.getFileSystem().delete(new Path(dirPath + "/file1"));
        Assert.assertFalse(cluster.getFileSystem().exists(new Path(dirPath + "/file1")));
    }

    @Test
    public void testPermissionsAndOwnershipChanges() throws IOException {
        String dirPath = "/testDir";
        cluster.getFileSystem().mkdirs(new Path(dirPath));
        cluster.getFileSystem().allowSnapshot(new Path(dirPath));
        cluster.getFileSystem().createSnapshot(new Path(dirPath), "snapshot1");

        // Change permissions
        cluster.getFileSystem().setPermission(new Path(dirPath), new FsPermission(FsAction.READ_WRITE, FsAction.READ_WRITE, FsAction.READ_WRITE));

        // Check if permissions are reflected in snapshot
        Assert.assertEquals(new FsPermission(FsAction.READ_WRITE, FsAction.READ_WRITE, FsAction.READ_WRITE), 
                            cluster.getFileSystem().getFileStatus(new Path(dirPath)).getPermission());
    }

    @Test
    public void testCombineSnapshotDifferences() throws IOException {
        String dirPath = "/testDir";
        cluster.getFileSystem().mkdirs(new Path(dirPath));
        cluster.getFileSystem().allowSnapshot(new Path(dirPath));
        cluster.getFileSystem().createSnapshot(new Path(dirPath), "snapshot1");

        cluster.getFileSystem().createNewFile(new Path(dirPath + "/file1"));
        cluster.getFileSystem().createSnapshot(new Path(dirPath), "snapshot2");

        // Check differences
        Assert.assertTrue(cluster.getFileSystem().exists(new Path(dirPath + "/.snapshot/snapshot2/file1")));

        cluster.getFileSystem().delete(new Path(dirPath + "/file1"));
        Assert.assertFalse(cluster.getFileSystem().exists(new Path(dirPath + "/file1")));
    }
}

