public class CpioArchiveOutputStream extends ArchiveOutputStream implements CpioConstants {
    private OutputStream out;
    private Charset charset;
    private boolean closed = false;

    public CpioArchiveOutputStream(OutputStream out, Charset charset) {
        this.out = out;
        this.charset = charset;
    }

    public void putArchiveEntry(CpioArchiveEntry entry) throws IOException {
        if (closed) {
            throw new IOException("Stream is closed");
        }
        // Write entry header
        writeEntryHeader(entry);
    }

    public void write(byte[] b, int off, int len) throws IOException {
        if (closed) {
            throw new IOException("Stream is closed");
        }
        // Write data to the current entry
        out.write(b, off, len);
    }

    public void closeArchiveEntry() throws IOException {
        if (closed) {
            throw new IOException("Stream is closed");
        }
        // Finalize the current entry
        finalizeEntry();
    }

    public void finish() throws IOException {
        if (closed) {
            throw new IOException("Stream is closed");
        }
        // Finalize the archive
        out.flush();
    }

    public void close() throws IOException {
        if (!closed) {
            out.close();
            closed = true;
        }
    }

    private void writeEntryHeader(CpioArchiveEntry entry) throws IOException {
        // Logic to write the entry header based on CPIO format
    }

    private void finalizeEntry() throws IOException {
        // Logic to finalize the current entry
    }

