}

public class UrlValidatorTest {

    private final UrlValidator urlValidator = new UrlValidator();

    @Test
    public void testBasicUrlValidity() {
        assertTrue(urlValidator.isValid("http://www.example.com"));
        assertFalse(urlValidator.isValid("htp://invalid-url"));
        assertTrue(urlValidator.isValid("ftp://ftp.example.com"));
        assertFalse(urlValidator.isValid("http://.com"));
    }

    @Test
    public void testSchemeValidation() {
        assertTrue(urlValidator.isValid("http://example.com"));
        assertTrue(urlValidator.isValid("ftp://example.com"));
        assertFalse(urlValidator.isValid("file://example.com"));
    }

    @Test
    public void testPathAndAuthorityValidation() {
        assertTrue(urlValidator.isValid("http://example.com/path/to/resource"));
        assertFalse(urlValidator.isValid("http://example.com//double-slash"));
        assertTrue(urlValidator.isValid("http://user:pass@example.com"));
    }

    @Test
    public void testInternationalizedDomainNames() {
        assertTrue(urlValidator.isValid("http://xn--ls8h.XN--zfr164B"));
        assertFalse(urlValidator.isValid("http://invalid-域名.com"));
    }

    @Test
    public void testLocalUrlsAndSpecificPortHandling() {
        assertTrue(urlValidator.isValid("http://localhost:8080"));
        assertFalse(urlValidator.isValid("http://localhost:abc"));
        assertTrue(urlValidator.isValid("http://127.0.0.1:80"));
    }

    @Test
    public void testSpecialCharactersAndFormats() {
        assertTrue(urlValidator.isValid("http://example.com/path?query=value#fragment"));
        assertFalse(urlValidator.isValid("http://example.com/path#"));
        assertTrue(urlValidator.isValid("http://example.com/path;params"));
    }

    @Test
    public void testIncrementalTesting() {
        String[] validUrls = {
            "http://example.com",
            "https://example.com",
            "ftp://example.com/resource",
            "http://example.com:8080/path",
            "http://user:pass@example.com"
        };

        for (String url : validUrls) {
            assertTrue(urlValidator.isValid(url));
        }

        String[] invalidUrls = {
            "htp://example.com",
            "http://.com",
            "http://example.com//double-slash",
            "http://localhost:abc"
        };

        for (String url : invalidUrls) {
            assertFalse(urlValidator.isValid(url));
        }
    }
}

public class PrimitiveType extends Type {
    public enum PrimitiveTypeName {
        INT32, INT64, BOOLEAN, FLOAT, DOUBLE, BINARY, FIXED_LEN_BYTE_ARRAY, INT96
    }

    private final PrimitiveTypeName typeName;
    private final int typeLength;
    private final int decimalMetadata;

    public PrimitiveType(PrimitiveTypeName typeName, int typeLength, int decimalMetadata) {
        this.typeName = typeName;
        this.typeLength = typeLength;
        this.decimalMetadata = decimalMetadata;
    }

    public PrimitiveTypeName getTypeName() {
        return typeName;
    }

    public int getTypeLength() {
        return typeLength;
    }

    public int getDecimalMetadata() {
        return decimalMetadata;
    }

    public boolean isCompatible(PrimitiveType other) {
        return this.typeName == other.typeName;
    }

    public PrimitiveType merge(PrimitiveType other) {
        if (!isCompatible(other)) {
            throw new IllegalArgumentException("Incompatible types");
        }
        return new PrimitiveType(this.typeName, Math.max(this.typeLength, other.typeLength), Math.max(this.decimalMetadata, other.decimalMetadata));
    }

    public void addToRecordConsumer(RecordConsumer consumer, Object value) {
        // Implementation for adding value to consumer
    }

    public String toString() {
        return "PrimitiveType{" +
                "typeName=" + typeName +
                ", typeLength=" + typeLength +
                ", decimalMetadata=" + decimalMetadata +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof PrimitiveType)) return false;
        PrimitiveType that = (PrimitiveType) o;
        return typeLength == that.typeLength &&
                decimalMetadata == that.decimalMetadata &&
                typeName == that.typeName;
    }

    @Override
    public int hashCode() {
        return Objects.hash(typeName, typeLength, decimalMetadata);
    }

    public void accept(TypeVisitor visitor) {
        visitor.visit(this);
    }
}

