    private List<Exchange> receivedExchanges = new ArrayList<>();
    private int expectedCount = 0;
    private CountDownLatch latch;

    public MockEndpoint(String uri) {
        super(uri);
    }

    public void setExpectedMessageCount(int count) {
        this.expectedCount = count;
        this.latch = new CountDownLatch(count);
    }

    public void assertIsSatisfied() throws InterruptedException {
        if (!latch.await(5, java.util.concurrent.TimeUnit.SECONDS)) {
            throw new AssertionError("Expected message count not satisfied: " + expectedCount);
        }
    }

    public void process(Exchange exchange) {
        receivedExchanges.add(exchange);
        latch.countDown();
        // Log received exchange for debugging
        System.out.println("Received exchange: " + exchange);
    }

    public List<Exchange> getReceivedExchanges() {
        return receivedExchanges;
    }

    public void clear() {
        receivedExchanges.clear();
        expectedCount = 0;
        if (latch != null) {
            latch = new CountDownLatch(expectedCount);
        }
    }

    public int getReceivedCount() {
        return receivedExchanges.size();
    }

    public void assertHeader(String headerName, Object expectedValue) {
        for (Exchange exchange : receivedExchanges) {
            Object actualValue = exchange.getIn().getHeader(headerName);
            if (!expectedValue.equals(actualValue)) {
                throw new AssertionError("Header assertion failed for " + headerName + ": expected " + expectedValue + ", but was " + actualValue);
            }
        }
    }

    public void assertBody(Object expectedBody) {
        for (Exchange exchange : receivedExchanges) {
            Object actualBody = exchange.getIn().getBody();
            if (!expectedBody.equals(actualBody)) {
