public class ObjectPropertyReprRenderer extends AbstractObjectMemberReprRenderer {

    @Override
    public String render(ObjectProperty property, RenderingContext context) {
        StringBuilder jsonBuilder = new StringBuilder();
        jsonBuilder.append("{");

        // Render property value
        jsonBuilder.append("\"value\":").append(renderValue(property.getValue()));

        // Render choices if available
        List<String> choices = property.getChoices();
        if (choices != null && !choices.isEmpty()) {
            jsonBuilder.append(",\"choices\":").append(renderChoices(choices));
        }

        // Render mutator links
        jsonBuilder.append(",\"mutatorLinks\":").append(renderMutatorLinks(property.getMutatorLinks()));

        // Render links to the formal domain model
        jsonBuilder.append(",\"domainLinks\":").append(renderDomainLinks(property.getDomainLinks()));

        jsonBuilder.append("}");
        return jsonBuilder.toString();
    }

    private String renderValue(Object value) {
        if (value instanceof BigDecimal) {
            return ((BigDecimal) value).toString();
        } else if (value instanceof BigInteger) {
            return ((BigInteger) value).toString();
        } else {
            return "\"" + value.toString() + "\"";
        }
    }

    private String renderChoices(List<String> choices) {
        StringBuilder choicesBuilder = new StringBuilder();
        choicesBuilder.append("[");
        for (int i = 0; i < choices.size(); i++) {
            choicesBuilder.append("\"").append(choices.get(i)).append("\"");
            if (i < choices.size() - 1) {
                choicesBuilder.append(",");
            }
        }
        choicesBuilder.append("]");
        return choicesBuilder.toString();
    }

    private String renderMutatorLinks(List<String> mutatorLinks) {
        return renderLinks(mutatorLinks);
    }

    private String renderDomainLinks(List<String> domainLinks) {
        return renderLinks(domainLinks);
    }

    private String renderLinks(List<String> links) {
        StringBuilder linksBuilder = new StringBuilder();
        linksBuilder.append("[");
        for (int i = 0; i < links.size(); i++) {
            linksBuilder.append("\"").append(links.get(i)).append("\"");
            if (i < links.size() - 1) {
                linksBuilder.append(",");
            }
        }
        linksBuilder.append("]");
        return linksBuilder.toString();
    }
}

