public abstract class RangerDaoManagerBase {
    private Map<Class<?>, Object> daoMap = new HashMap<>();
    private RESTErrorUtil restErrorUtil;

    public RangerDaoManagerBase(RESTErrorUtil restErrorUtil) {
        this.restErrorUtil = restErrorUtil;
    }

    protected <T> void registerDao(Class<T> clazz, T dao) {
        daoMap.put(clazz, dao);
    }

    @SuppressWarnings("unchecked")
    public <T> T getDao(Class<T> clazz) {
        T dao = (T) daoMap.get(clazz);
        if (dao == null) {
            logError(clazz);
            throw restErrorUtil.createNotFoundError("DAO not found for class: " + clazz.getName());
        }
        return dao;
    }

    public Object getDao(String className) {
        try {
            Class<?> clazz = Class.forName(className);
            return getDao(clazz);
        } catch (ClassNotFoundException e) {
            logError(className);
            throw restErrorUtil.createNotFoundError("DAO not found for class name: " + className);
        }
    }

    private void logError(Object identifier) {
        System.err.println("Error: DAO not found for identifier: " + identifier);
    }
}

