public class DetachedStateManager extends AttachStrategy implements OpenJPAStateManager, Serializable {
    private static final long serialVersionUID = 1L;

    private final Lock lock = new ReentrantLock();
    private PersistenceCapable entity;
    private boolean[] loadedFields;
    private boolean[] dirtyFields;
    private Object identifier;
    private int version;
    private boolean isNew;
    private boolean isDeleted;

    public DetachedStateManager(PersistenceCapable entity) {
        this.entity = entity;
        this.loadedFields = new boolean[entity.getFieldCount()];
        this.dirtyFields = new boolean[entity.getFieldCount()];
        this.isNew = false;
        this.isDeleted = false;
    }

    public void attach() {
        lock.lock();
        try {
            // Logic to attach the entity back to the persistence context
            // Code smell: Potentially long-running operation in a lock
        } finally {
            lock.unlock();
        }
    }

    public void setField(int fieldIndex, Object value) {
        lock.lock();
        try {
            entity.setField(fieldIndex, value);
            dirtyFields[fieldIndex] = true;
        } finally {
            lock.unlock();
        }
    }

    public Object getField(int fieldIndex) {
        lock.lock();
        try {
            return entity.getField(fieldIndex);
        } finally {
            lock.unlock();
        }
    }

    public boolean isDirty() {
        for (boolean dirty : dirtyFields) {
            if (dirty) {
                return true;
            }
        }
        return false;
    }

    public boolean isPersistent() {
