public class ParameterTool implements Serializable, Cloneable {
    private final Map<String, String> parameters;

    public ParameterTool(Map<String, String> parameters) {
        this.parameters = new HashMap<>(parameters);
    }

    public static ParameterTool fromArgs(String[] args) {
        Map<String, String> params = new HashMap<>();
        for (String arg : args) {
            String[] split = arg.split("=");
            if (split.length == 2) {
                params.put(split[0], split[1]);
            }
        }
        return new ParameterTool(params);
    }

    public String get(String key) {
        return parameters.get(key);
    }

    public String get(String key, String defaultValue) {
        return parameters.getOrDefault(key, defaultValue);
    }

    public int getInt(String key) {
        return Integer.parseInt(get(key, "0"));
    }

    public int getInt(String key, int defaultValue) {
        try {
            return Integer.parseInt(get(key, String.valueOf(defaultValue)));
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public long getLong(String key) {
        return Long.parseLong(get(key, "0"));
    }

    public long getLong(String key, long defaultValue) {
        try {
            return Long.parseLong(get(key, String.valueOf(defaultValue)));
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public float getFloat(String key) {
        return Float.parseFloat(get(key, "0.0"));
    }

    public float getFloat(String key, float defaultValue) {
        try {
            return Float.parseFloat(get(key, String.valueOf(defaultValue)));
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }

    public boolean getBoolean(String key) {
        return Boolean.parseBoolean(get(key, "false"));
    }

    public boolean getBoolean(String key, boolean defaultValue) {
        return Boolean.parseBoolean(get(key, String.valueOf(defaultValue)));
    }

    public boolean exists(String key) {
        return parameters.containsKey(key);
    }

    public void mergeWith(ParameterTool other) {
        this.parameters.putAll(other.parameters);
    }

    public Properties toProperties() {
        Properties props = new Properties();
        props.putAll(parameters);
        return props;
    }

    @Override
    protected Object clone() throws CloneNotSupportedException {
        return super.clone();
    }
}

