public class ApplyTransformVisitor implements OpVisitorByTypeAndExpr, ExprVisitor {
    private Deque<Op> opStack = new ArrayDeque<>();
    private Deque<Expr> exprStack = new ArrayDeque<>();
    private Transform opTransform;
    private ExprTransform exprTransform;

    public ApplyTransformVisitor(Transform opTransform, ExprTransform exprTransform) {
        this.opTransform = opTransform;
        this.exprTransform = exprTransform;
    }

    @Override
    public void visit(OpOrder opOrder) {
        checkNull(opOrder);
        opStack.push(opOrder);
        // Apply transformation logic
        List<Expr> expressions = opOrder.getExpressions();
        for (Expr expr : expressions) {
            expr.accept(this);
        }
        opOrder.setExpressions(transformExpressions(expressions));
        opStack.pop();
    }

    @Override
    public void visit(OpAssign opAssign) {
        checkNull(opAssign);
        opStack.push(opAssign);
        // Apply transformation logic
        Expr expr = opAssign.getExpr();
        expr.accept(this);
        opAssign.setExpr(exprTransform.transform(expr));
        opStack.pop();
    }

    @Override
    public void visit(OpExtend opExtend) {
        checkNull(opExtend);
        opStack.push(opExtend);
        // Apply transformation logic
        List<Expr> expressions = opExtend.getExpressions();
        for (Expr expr : expressions) {
            expr.accept(this);
        }
        opExtend.setExpressions(transformExpressions(expressions));
        opStack.pop();
    }

    @Override
    public void visit(ExprFunction exprFunction) {
        checkNull(exprFunction);
        exprStack.push(exprFunction);
        // Apply transformation logic
        List<Expr> args = exprFunction.getArgs();
        for (Expr arg : args) {
            arg.accept(this);
        }
        exprFunction.setArgs(transformExpressions(args));
        exprStack.pop();
    }

    @Override
    public void visit(ExprVar exprVar) {
        checkNull(exprVar);
        exprStack.push(exprVar);
        // Apply transformation logic
        exprStack.pop();
    }

    private List<Expr> transformExpressions(List<Expr> expressions) {
        List<Expr> transformed = new ArrayList<>();
        for (Expr expr : expressions) {
            transformed.add(exprTransform.transform(expr));
        }
        return transformed;
    }

    private void checkNull(Object obj) {
        if (obj == null) {
            System.err.println("Warning: Null value pushed to stack");
        }
    }
}

