public class FieldVector3D<T extends RealFieldElement<T>> {
    private final T x;
    private final T y;
    private final T z;

    public FieldVector3D(T x, T y, T z) {
        if (x == null || y == null || z == null) {
            throw new NullArgumentException();
        }
        this.x = x;
        this.y = y;
        this.z = z;
    }

    public FieldVector3D(T[] components) {
        if (components == null || components.length != 3) {
            throw new NullArgumentException();
        }
        this.x = components[0];
        this.y = components[1];
        this.z = components[2];
    }

    public FieldVector3D(FieldVector3D<T> vector) {
        if (vector == null) {
            throw new NullArgumentException();
        }
        this.x = vector.x;
        this.y = vector.y;
        this.z = vector.z;
    }

    public FieldVector3D<T> add(FieldVector3D<T> vector) {
        if (vector == null) {
            throw new NullArgumentException();
        }
        return new FieldVector3D<>(this.x.add(vector.x), this.y.add(vector.y), this.z.add(vector.z));
    }

    public FieldVector3D<T> subtract(FieldVector3D<T> vector) {
        if (vector == null) {
            throw new NullArgumentException();
        }
        return new FieldVector3D<>(this.x.subtract(vector.x), this.y.subtract(vector.y), this.z.subtract(vector.z));
    }

    public FieldVector3D<T> scalarMultiply(T scalar) {
        if (scalar == null) {
            throw new NullArgumentException();
        }
        return new FieldVector3D<>(this.x.multiply(scalar), this.y.multiply(scalar), this.z.multiply(scalar));
    }

    public FieldVector3D<T> normalize() {
        T norm = this.getNorm();
        if (norm.isZero()) {
            throw new MathArithmeticException();
        }
        return this.scalarMultiply(norm.reciprocal());
    }

    public T getNorm() {
        return this.x.multiply(this.x).add(this.y.multiply(this.y)).add(this.z.multiply(this.z)).sqrt();
    }

    public T dotProduct(FieldVector3D<T> vector) {
        if (vector == null) {
            throw new NullArgumentException();
        }
        return this.x.multiply(vector.x).add(this.y.multiply(vector.y)).add(this.z.multiply(vector.z));
    }

    public FieldVector3D<T> crossProduct(FieldVector3D<T> vector) {
        if (vector == null) {
            throw new NullArgumentException();
        }
        return new FieldVector3D<>(
            this.y.multiply(vector.z).subtract(this.z.multiply(vector.y)),
            this.z.multiply(vector.x).subtract(this.x.multiply(vector.z)),
            this.x.multiply(vector.y).subtract(this.y.multiply(vector.x))
        );
    }

    public T distance(FieldVector3D<T> vector) {
        if (vector == null) {
            throw new NullArgumentException();
        }
        return this.subtract(vector).getNorm();
    }

    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof FieldVector3D)) return false;
        FieldVector3D<?> other = (FieldVector3D<?>) obj;
        return this.x.equals(other.x) && this.y.equals(other.y) && this.z.equals(other.z);
    }

    public int hashCode() {
        int result = x.hashCode();
        result = 31 * result + y.hashCode();
        result = 31 * result + z.hashCode();
        return result;
    }

    public String toString() {
        return "FieldVector3D{" + "x=" + x + ", y=" + y + ", z=" + z + '}';
    }
}

public class TestTFileByteArrays {

    private Writer writer;
    private Reader reader;

    @Before
    public void setUp() {
        writer = new Writer();
        reader = new Reader();
    }

    @After
    public void tearDown() {
        writer.close();
        reader.close();
    }

    @Test
    public void testWriteAndReadSingleRecord() {
        byte[] key = new byte[]{1};
        byte[] value = new byte[]{10};
        writer.write(key, value);
        byte[] readValue = reader.read(key);
        assertArrayEquals(value, readValue);
    }

    @Test
    public void testWriteAndReadMultipleRecords() {
        for (int i = 0; i < 10; i++) {
            byte[] key = new byte[]{(byte) i};
            byte[] value = new byte[]{(byte) (i * 10)};
            writer.write(key, value);
        }
        for (int i = 0; i < 10; i++) {
            byte[] key = new byte[]{(byte) i};
            byte[] expectedValue = new byte[]{(byte) (i * 10)};
            byte[] readValue = reader.read(key);
            assertArrayEquals(expectedValue, readValue);
        }
    }

    @Test(expected = IllegalArgumentException.class)
    public void testWriteNullKey() {
        writer.write(null, new byte[]{1});
    }

    @Test(expected = IllegalArgumentException.class)
    public void testWriteNullValue() {
        writer.write(new byte[]{1}, null);
    }

    @Test
    public void testHandleBlockIndices() {
        // Simulate writing records that span multiple blocks
        for (int i = 0; i < 100; i++) {
            byte[] key = new byte[]{(byte) i};
            byte[] value = new byte[1024]; // Large value to ensure block handling
            writer.write(key, value);
        }
        // Verify that the block indices are managed correctly
        assertTrue(writer.getBlockCount() > 1);
    }

    @Test
    public void testSortKeys() {
        // Write unsorted keys
        for (int i = 9; i >= 0; i--) {
            byte[] key = new byte[]{(byte) i};
            byte[] value = new byte[]{(byte) (i * 10)};
            writer.write(key, value);
        }
        byte[][] sortedKeys = writer.getSortedKeys();
        for (int i = 0; i < sortedKeys.length - 1; i++) {
            assertTrue(sortedKeys[i][0] <= sortedKeys[i + 1][0]);
        }
    }

    @Test
    public void testLocateKey() {
        byte[] key = new byte[]{5};
        byte[] value = new byte[]{50};
        writer.write(key, value);
        assertTrue(writer.locateKey(key));
        assertFalse(writer.locateKey(new byte[]{10}));
    }

    @Test
    public void testMetadataBlockHandling() {
        // Write some records and check metadata
        for (int i = 0; i < 5; i++) {
            byte[] key = new byte[]{(byte) i};
            byte[] value = new byte[]{(byte) (i * 10)};
            writer.write(key, value);
        }
        assertNotNull(writer.getMetadataBlock());
    }
}

public class ChmItspHeader implements ChmAccessor {
    private static final int SIGNATURE_LENGTH = 4;
    private static final int VERSION_LENGTH = 2;
    private static final int HEADER_LENGTH_LENGTH = 2;
    private static final int BLOCK_LENGTH_LENGTH = 2;
    private static final int INDEX_LENGTH_LENGTH = 4;
    private static final int LANGUAGE_ID_LENGTH = 2;
    private static final int UUID_LENGTH = 16;

    private byte[] signature;
    private short version;
    private short headerLength;
    private short blockLength;
    private int indexLength;
    private short languageId;
    private byte[] uuid;

    public ChmItspHeader() {
        this.signature = new byte[SIGNATURE_LENGTH];
        this.uuid = new byte[UUID_LENGTH];
    }

    public void parse(byte[] data) {
        int position = 0;

        System.arraycopy(data, position, signature, 0, SIGNATURE_LENGTH);
        position += SIGNATURE_LENGTH;

        version = (short) ((data[position++] & 0xFF) << 8 | (data[position++] & 0xFF));
        headerLength = (short) ((data[position++] & 0xFF) << 8 | (data[position++] & 0xFF));
        blockLength = (short) ((data[position++] & 0xFF) << 8 | (data[position++] & 0xFF));
        indexLength = (data[position++] & 0xFF) << 24 | (data[position++] & 0xFF) << 16 |
                      (data[position++] & 0xFF) << 8 | (data[position++] & 0xFF);
        languageId = (short) ((data[position++] & 0xFF) << 8 | (data[position++] & 0xFF));
        System.arraycopy(data, position, uuid, 0, UUID_LENGTH);
    }

    public boolean validate() {
        return new String(signature).equals("ITSP") && headerLength > 0 && blockLength > 0;
    }

    public String toString() {
        return "ChmItspHeader{" +
                "signature=" + new String(signature) +
                ", version=" + version +
                ", headerLength=" + headerLength +
                ", blockLength=" + blockLength +
                ", indexLength=" + indexLength +
                ", languageId=" + languageId +
                ", uuid=" + bytesToHex(uuid) +
                '}';
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}

public abstract class DelegateEntry implements IEntry {
    private String connectionId;
    private String distinguishedName;
    private IEntry delegateEntry;
    private Map<String, Object> attributesCache = new HashMap<>();
    private boolean isConnected;

    public DelegateEntry(String connectionId, String distinguishedName, IEntry delegateEntry) {
        this.connectionId = connectionId;
        this.distinguishedName = distinguishedName;
        this.delegateEntry = delegateEntry;
        this.isConnected = true; // Assume connected on initialization
    }

    public String getConnectionId() {
        return connectionId;
    }

    public String getDistinguishedName() {
        return distinguishedName;
    }

    public boolean isConnected() {
        return isConnected;
    }

    public void setConnected(boolean connected) {
        isConnected = connected;
    }

    public Object getAttribute(String attributeName) {
        if (!isConnected || delegateEntry == null) {
            return getDefaultAttribute(attributeName);
        }
        return attributesCache.computeIfAbsent(attributeName, k -> delegateEntry.getAttribute(attributeName));
    }

    protected Object getDefaultAttribute(String attributeName) {
        // Provide default behavior for missing attributes
        return null; // or some default value
    }

    public void addChildEntry(IEntry childEntry) {
        if (isConnected && delegateEntry != null) {
            delegateEntry.addChildEntry(childEntry);
        }
    }

    public void removeChildEntry(IEntry childEntry) {
        if (isConnected && delegateEntry != null) {
            delegateEntry.removeChildEntry(childEntry);
        }
    }

    public IEntry getChildEntry(String childDistinguishedName) {
        if (!isConnected || delegateEntry == null) {
            return null; // or handle accordingly
        }
        return delegateEntry.getChildEntry(childDistinguishedName);
    }

    public void clearCache() {
        attributesCache.clear();
    }
}

