public class Update {
    private ChangeLog changeLog;
    private Lock lock;
    private boolean isActive;

    public Update(ChangeLog changeLog) {
        this.changeLog = changeLog;
        this.lock = new ReentrantLock();
        this.isActive = false;
    }

    public void begin() {
        lock.lock();
        try {
            if (isActive) {
                throw new IllegalStateException("Update already in progress");
            }
            isActive = true;
            // Additional logic to initialize the update
        } finally {
            lock.unlock();
        }
    }

    public void end() {
        lock.lock();
        try {
            if (!isActive) {
                throw new IllegalStateException("No active update to end");
            }
            // Logic to finalize the update
            isActive = false;
        } finally {
            lock.unlock();
        }
    }

    public void cancel() {
        lock.lock();
        try {
            if (!isActive) {
                throw new IllegalStateException("No active update to cancel");
            }
            // Logic to cancel the update
            isActive = false;
        } finally {
            lock.unlock();
        }
    }

    public void addItem(ItemState itemState) {
        lock.lock();
        try {
            if (!isActive) {
                throw new IllegalStateException("Update not started");
            }
            changeLog.add(itemState);
            // Logic to handle referential integrity
        } finally {
            lock.unlock();
        }
    }

    public void modifyItem(ItemState itemState) {
        lock.lock();
        try {
            if (!isActive) {
                throw new IllegalStateException("Update not started");
            }
            changeLog.modify(itemState);
            // Logic to handle referential integrity
        } finally {
