public class CommentServlet extends HttpServlet {
    private CommentAuthenticator authenticator;
    private CommentValidationManager validationManager;

    @Override
    public void init() throws ServletException {
        authenticator = new CommentAuthenticator();
        validationManager = new CommentValidationManager();
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String ipAddress = request.getRemoteAddr();
        if (isThrottled(ipAddress)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Too many comments from this IP address.");
            return;
        }

        String email = request.getParameter("email");
        String url = request.getParameter("url");
        String comment = request.getParameter("comment");

        if (!validationManager.isValidEmail(email) || !validationManager.isValidURL(url)) {
            request.setAttribute("error", "Invalid email or URL.");
            request.getRequestDispatcher("/error.jsp").forward(request, response);
            return;
        }

        if (!authenticator.authenticateUser(request)) {
            request.setAttribute("error", "User authentication failed.");
            request.getRequestDispatcher("/error.jsp").forward(request, response);
            return;
        }

        CommentStatus status = validationManager.validateComment(comment);
        if (status == CommentStatus.SPAM) {
            request.setAttribute("error", "Comment marked as spam.");
            request.getRequestDispatcher("/error.jsp").forward(request, response);
            return;
        }

        // Save comment logic here
        sendEmailNotification(email, comment);
        response.sendRedirect("/success.jsp");
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        response.sendError(HttpServletResponse.SC_NOT_FOUND);
    }

    private boolean isThrottled(String ipAddress) {
        // Throttling logic here
        return false;
    }

    private void sendEmailNotification(String email, String comment) {
        // Email sending logic here
    }
