public class TestStatistics {

    @Test
    public void testNullCount() {
        IntStatistics intStats = new IntStatistics();
        intStats.addValue(null);
        assertEquals(1, intStats.getNullCount());
    }

    @Test
    public void testIntegerStatistics() {
        IntStatistics intStats = new IntStatistics();
        intStats.addValue(5);
        intStats.addValue(10);
        intStats.addValue(3);
        assertEquals(3, intStats.getMin());
        assertEquals(10, intStats.getMax());
        assertArrayEquals(new byte[]{0, 0, 0, 5}, intStats.toByteArray());

        IntStatistics mergedStats = new IntStatistics();
        mergedStats.merge(intStats);
        assertEquals(3, mergedStats.getMin());
        assertEquals(10, mergedStats.getMax());
    }

    @Test
    public void testLongStatistics() {
        LongStatistics longStats = new LongStatistics();
        longStats.addValue(100L);
        longStats.addValue(200L);
        assertEquals(100L, longStats.getMin());
        assertEquals(200L, longStats.getMax());
        assertArrayEquals(new byte[]{0, 0, 0, 0, 0, 0, 0, 100}, longStats.toByteArray());
    }

    @Test
    public void testFloatStatistics() {
        FloatStatistics floatStats = new FloatStatistics();
        floatStats.addValue(1.5f);
        floatStats.addValue(2.5f);
        assertEquals(1.5f, floatStats.getMin());
        assertEquals(2.5f, floatStats.getMax());
        assertArrayEquals(new byte[]{63, -128, 0, 0}, floatStats.toByteArray());
    }

    @Test
    public void testDoubleStatistics() {
        DoubleStatistics doubleStats = new DoubleStatistics();
        doubleStats.addValue(1.5);
        doubleStats.addValue(2.5);
        assertEquals(1.5, doubleStats.getMin());
        assertEquals(2.5, doubleStats.getMax());
        assertArrayEquals(new byte[]{63, -16, 0, 0, 0, 0, 0, 0}, doubleStats.toByteArray());
    }

    @Test
    public void testBooleanStatistics() {
        BooleanStatistics booleanStats = new BooleanStatistics();
        booleanStats.addValue(true);
        booleanStats.addValue(false);
        assertFalse(booleanStats.getMin());
        assertTrue(booleanStats.getMax());
    }

    @Test
    public void testBinaryStatistics() {
        BinaryStatistics binaryStats = new BinaryStatistics();
        binaryStats.addValue("hello".getBytes());
        binaryStats.addValue("world".getBytes());
        assertArrayEquals("hello".getBytes(), binaryStats.getMin());
        assertArrayEquals("world".getBytes(), binaryStats.getMax());
        assertArrayEquals(new byte[]{104, 101, 108, 108, 111}, binaryStats.toByteArray());
    }

    @Test
    public void testMergingStatistics() {
        IntStatistics intStats1 = new IntStatistics();
        intStats1.addValue(1);
        intStats1.addValue(2);

        IntStatistics intStats2 = new IntStatistics();
        intStats2.addValue(3);
        intStats2.addValue(4);

        IntStatistics mergedStats = new IntStatistics();
        mergedStats.merge(intStats1);
        mergedStats.merge(intStats2);

        assertEquals(1, mergedStats.getMin());
        assertEquals(4, mergedStats.getMax());
    }
}

