        logger.info("Releasing component for markup: " + markup);
        componentCache.remove(markup);
    }

    public void removeComponent(String markup) {
        logger.info("Removing component for markup: " + markup);
        componentCache.remove(markup);
    }

    public void preloadComponents(String[] markups, String language) {
        logger.info("Preloading components.");
        for (String markup : markups) {
            loadComponent(markup, language);
        }
    }

    public void dispose() {
        logger.info("Disposing resources.");
        componentCache.clear();
    }

