public class CrossOriginResourceSharingFilter implements RequestHandler, ResponseHandler {
    private List<String> allowedOrigins;
    private List<String> allowedHeaders;
    private boolean allowCredentials;
    private long maxAge;

    public CrossOriginResourceSharingFilter() {
        this.allowedOrigins = new ArrayList<>();
        this.allowedHeaders = new ArrayList<>();
        this.allowCredentials = false;
        this.maxAge = 3600; // Default max age
    }

    public void addAllowedOrigin(String origin) {
        allowedOrigins.add(origin);
    }

    public void addAllowedHeader(String header) {
        allowedHeaders.add(header);
    }

    public void setAllowCredentials(boolean allow) {
        this.allowCredentials = allow;
    }

    public void setMaxAge(long age) {
        this.maxAge = age;
    }

    @Override
    public void handleRequest(HttpRequest request) {
        if (isPreflightRequest(request)) {
            handlePreflight(request);
        } else {
            handleSimpleRequest(request);
        }
    }

    private boolean isPreflightRequest(HttpRequest request) {
        return "OPTIONS".equalsIgnoreCase(request.getMethod());
    }

    private void handlePreflight(HttpRequest request) {
        HttpResponse response = new HttpResponse();
        String origin = request.getHeader("Origin");
        if (isOriginAllowed(origin)) {
            response.setHeader("Access-Control-Allow-Origin", origin);
            response.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
            response.setHeader("Access-Control-Allow-Headers", String.join(", ", allowedHeaders));
            if (allowCredentials) {
                response.setHeader("Access-Control-Allow-Credentials", "true");
            }
            response.setHeader("Access-Control-Max-Age", String.valueOf(maxAge));
            response.setStatus(204); // No Content
        } else {
            response.setStatus(403); // Forbidden
        }
        sendResponse(response);
    }

    private void handleSimpleRequest(HttpRequest request) {
        HttpResponse response = new HttpResponse();
        String origin = request.getHeader("Origin");
        if (isOriginAllowed(origin)) {
            response.setHeader("Access-Control-Allow-Origin", origin);
            if (allowCredentials) {
                response.setHeader("Access-Control-Allow-Credentials", "true");
            }
        }
        sendResponse(response);
    }

    private boolean isOriginAllowed(String origin) {
        return allowedOrigins.contains(origin);
    }

    @Override
    public void sendResponse(HttpResponse response) {
        // Implementation to send the response back to the client
    }
}

