    public void testEdgeCaseClaims() {
        assertTrue(tracker.claimKey(new byte[]{0}));
        assertTrue(tracker.claimKey(new byte[]{10}));
    }

    @Test
    public void testMonotonicClaims() {
        tracker.claimKey(new byte[]{1});
        tracker.claimKey(new byte[]{2});
        assertFalse(tracker.claimKey(new byte[]{1})); // Should not allow re-claiming
