        tracker.claimKey(new byte[]{8});
        tracker.claimKey(new byte[]{9});
        assertFalse(tracker.checkDone());
        tracker.claimKey(new byte[]{10});
        assertTrue(tracker.checkDone());
    }

    @Test
    public void testGenerateNextByteKey() {
        byte[] nextKey = tracker.generateNextByteKey();
        assertArrayEquals(new byte[]{0}, nextKey);
        tracker.claimKey(new byte[]{0});
        nextKey = tracker.generateNextByteKey();
        assertArrayEquals(new byte[]{1}, nextKey);
    }
}

