    public void setUp() {
        outputStream = new BufferedElementCountingOutputStream();
    }

    @Test
    public void testWriteEmptyValue() {
        outputStream.write(new byte[0]);
        assertEquals(0, outputStream.getElementCount());
    }

    @Test
    public void testWriteSingleValue() {
        byte[] data = {1};
        outputStream.write(data);
        assertEquals(1, outputStream.getElementCount());
    }

    @Test
    public void testWriteMultipleValues() {
        byte[] data1 = {1};
        byte[] data2 = {2};
        outputStream.write(data1);
        outputStream.write(data2);
        assertEquals(2, outputStream.getElementCount());
    }

    @Test
    public void testFlushWhileWriting() {
        byte[] data = {1, 2, 3};
        outputStream.write(data);
        outputStream.flush();
        assertEquals(3, outputStream.getElementCount());
    }

    @Test(expected = IllegalStateException.class)
    public void testWriteAfterFinish() {
        outputStream.finish();
        outputStream.write(new byte[]{1});
    }

    @Test(expected = IllegalStateException.class)
    public void testFlushAfterFinish() {
        outputStream.finish();
        outputStream.flush();
    }

