public abstract class UnsafeReads implements ExtendedDataInput {
    protected byte[] buffer;
    protected int position;
    protected int bufferLength;

    public UnsafeReads(byte[] buffer) {
        this.buffer = buffer;
        this.bufferLength = buffer.length;
        this.position = 0;
    }

    public boolean hasBytes(int numBytes) {
        return (bufferLength - position) >= numBytes;
    }

    public void skipBytes(int numBytes) throws IOException {
        if (!hasBytes(numBytes)) {
            throw new IOException("Not enough bytes to skip");
        }
        position += numBytes;
    }

    public String readLine() throws IOException {
        StringBuilder line = new StringBuilder();
        while (hasBytes(1)) {
            byte b = buffer[position++];
            if (b == '\n') {
                break;
            }
            line.append((char) b);
        }
        return line.toString();
    }

    public String readUTF() throws IOException {
        int utfLength = readUnsignedShort();
        if (!hasBytes(utfLength)) {
            throw new IOException("Not enough bytes to read UTF string");
        }
        String result = new String(buffer, position, utfLength, Charset.forName("UTF-8"));
        position += utfLength;
        return result;
    }

    protected abstract int readUnsignedShort() throws IOException;
}

