public class TreeWordList implements RutaWordList {
    private TextNode root;
    private boolean ignoreCase;
    private boolean ignoreWhitespace;
    private Set<Character> ignoredCharacters;

    public TreeWordList() {
        this.root = new TextNode();
        this.ignoreCase = false;
        this.ignoreWhitespace = false;
        this.ignoredCharacters = new HashSet<>();
    }

    public void addWord(String word) {
        if (word == null || word.isEmpty()) return;
        if (ignoreCase) word = word.toLowerCase();
        root.addWord(word);
    }

    public boolean containsWord(String word) {
        if (word == null) return false;
        if (ignoreCase) word = word.toLowerCase();
        return root.containsWord(word);
    }

    public List<String> findAnnotations(String text) {
        List<String> annotations = new ArrayList<>();
        if (text == null) return annotations;
        String processedText = processText(text);
        // Logic to find annotations based on processedText
        return annotations;
    }

    private String processText(String text) {
        if (ignoreWhitespace) text = text.replaceAll("\\s+", "");
        for (Character ch : ignoredCharacters) {
            text = text.replace(ch.toString(), "");
        }
        return text;
    }

    public void readFromXML(File file) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(file);
        NodeList wordNodes = doc.getElementsByTagName("word");
        for (int i = 0; i < wordNodes.getLength(); i++) {
            String word = wordNodes.item(i).getTextContent();
            addWord(word);
        }
    }

    public void writeToXML(File file) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.newDocument();
        Element rootElement = doc.createElement("words");
        doc.appendChild(rootElement);
        root.writeToXML(doc, rootElement);
        TransformerFactory transformerFactory = TransformerFactory.newInstance();
        Transformer transformer = transformerFactory.newTransformer();
        DOMSource source = new DOMSource(doc);
        StreamResult result = new StreamResult(file);
        transformer.transform(source, result);
    }

    public void readFromCompressedXML(File file) throws IOException, Exception {
        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(file))) {
            ZipEntry entry = zis.getNextEntry();
            if (entry != null) {
                readFromXML(new File(entry.getName()));
            }
        }
    }

    public void writeToCompressedXML(File file) throws IOException, Exception {
        try (ZipOutputStream zos = new ZipOutputStream(new FileOutputStream(file))) {
            ZipEntry entry = new ZipEntry("words.xml");
            zos.putNextEntry(entry);
            writeToXML(new File("words.xml")); // Temporary file
            zos.closeEntry();
        }
    }

    // Inner class for TextNode
    private class TextNode {
        private Map<Character, TextNode> children;
        private boolean isEndOfWord;

        public TextNode() {
            this.children = new HashMap<>();
            this.isEndOfWord = false;
        }

        public void addWord(String word) {
            TextNode currentNode = this;
            for (char ch : word.toCharArray()) {
                currentNode = currentNode.children.computeIfAbsent(ch, c -> new TextNode());
            }
            currentNode.isEndOfWord = true;
        }

        public boolean containsWord(String word) {
            TextNode currentNode = this;
            for (char ch : word.toCharArray()) {
                currentNode = currentNode.children.get(ch);
                if (currentNode == null) return false;
            }
            return currentNode.isEndOfWord;
        }

        public void writeToXML(Document doc, Element parentElement) {
            if (isEndOfWord) {
                Element wordElement = doc.createElement("word");
                parentElement.appendChild(wordElement);
            }
            for (Map.Entry<Character, TextNode> entry : children.entrySet()) {
                entry.getValue().writeToXML(doc, parentElement);
            }
        }
    }
}

public class FieldRotation<T extends RealFieldElement<T>> {
    private T q0, q1, q2, q3;

    public FieldRotation(T q0, T q1, T q2, T q3) {
        this.q0 = q0;
        this.q1 = q1;
        this.q2 = q2;
        this.q3 = q3;
        normalize();
    }

    public FieldRotation(Vector3D axis, double angle) {
        double halfAngle = angle / 2.0;
        double sinHalfAngle = FastMath.sin(halfAngle);
        this.q0 = (T) RealFieldElement.of(FastMath.cos(halfAngle));
        this.q1 = (T) RealFieldElement.of(axis.getX() * sinHalfAngle);
        this.q2 = (T) RealFieldElement.of(axis.getY() * sinHalfAngle);
        this.q3 = (T) RealFieldElement.of(axis.getZ() * sinHalfAngle);
        normalize();
    }

    public FieldRotation(double[][] rotationMatrix) {
        // Code smells: Hardcoded matrix size, no error handling
        double trace = rotationMatrix[0][0] + rotationMatrix[1][1] + rotationMatrix[2][2];
        if (trace > 0) {
            double s = FastMath.sqrt(trace + 1.0) * 2; // S=4*qw
            this.q0 = (T) RealFieldElement.of(0.25 * s);
            this.q1 = (T) RealFieldElement.of((rotationMatrix[2][1] - rotationMatrix[1][2]) / s);
            this.q2 = (T) RealFieldElement.of((rotationMatrix[0][2] - rotationMatrix[2][0]) / s);
            this.q3 = (T) RealFieldElement.of((rotationMatrix[1][0] - rotationMatrix[0][1]) / s);
        } else {
            // Code smells: Nested if-else, could be simplified
            if (rotationMatrix[0][0] > rotationMatrix[1][1] && rotationMatrix[0][0] > rotationMatrix[2][2]) {
                double s = FastMath.sqrt(1.0 + rotationMatrix[0][0] - rotationMatrix[1][1] - rotationMatrix[2][2]) * 2; // S=4*qx
                this.q0 = (T) RealFieldElement.of((rotationMatrix[2][1] - rotationMatrix[1][2]) / s);
                this.q1 = (T) RealFieldElement.of(0.25 * s);
                this.q2 = (T) RealFieldElement.of((rotationMatrix[0][1] + rotationMatrix[1][0]) / s);
                this.q3 = (T) RealFieldElement.of((rotationMatrix[0][2] + rotationMatrix[2][0]) / s);
            } else if (rotationMatrix[1][1] > rotationMatrix[2][2]) {
                double s = FastMath.sqrt(1.0 + rotationMatrix[1][1] - rotationMatrix[0][0] - rotationMatrix[2][2]) * 2; // S=4*qy
                this.q0 = (T) RealFieldElement.of((rotationMatrix[0][2] - rotationMatrix[2][0]) / s);
                this.q1 = (T) RealFieldElement.of((rotationMatrix[0][1] + rotationMatrix[1][0]) / s);
                this.q2 = (T) RealFieldElement.of(0.25 * s);
                this.q3 = (T) RealFieldElement.of((rotationMatrix[1][2] + rotationMatrix[2][1]) / s);
            } else {
                double s = FastMath.sqrt(1.0 + rotationMatrix[2][2] - rotationMatrix[0][0] - rotationMatrix[1][1]) * 2; // S=4*qz
                this.q0 = (T) RealFieldElement.of((rotationMatrix[1][0] - rotationMatrix[0][1]) / s);
                this.q1 = (T) RealFieldElement.of((rotationMatrix[0][2] + rotationMatrix[2][0]) / s);
                this.q2 = (T) RealFieldElement.of((rotationMatrix[1][2] + rotationMatrix[2][1]) / s);
                this.q3 = (T) RealFieldElement.of(0.25 * s);
            }
        }
        normalize();
    }

    public void normalize() {
        double norm = FastMath.sqrt(q0.multiply(q0).add(q1.multiply(q1)).add(q2.multiply(q2)).add(q3.multiply(q3)).getReal());
        if (norm > 0) {
            q0 = q0.divide(norm);
            q1 = q1.divide(norm);
            q2 = q2.divide(norm);
            q3 = q3.divide(norm);
        }
    }

    public FieldRotation<T> revert() {
        return new FieldRotation<>(q0, -q1, -q2, -q3);
    }

    public T[] getQuaternionComponents() {
        return (T[]) new RealFieldElement[]{q0, q1, q2, q3};
    }

    public Vector3D getRotationAxis() {
        double sinHalfAngle = FastMath.sqrt(q1.multiply(q1).add(q2.multiply(q2)).add(q3.multiply(q3)).getReal());
        if (sinHalfAngle > 0) {
            return new Vector3D(q1.divide(sinHalfAngle).getReal(), q2.divide(sinHalfAngle).getReal(), q3.divide(sinHalfAngle).getReal());
        }
        return new Vector3D(1, 0, 0); // Default axis
    }

    public double getRotationAngle() {
        return 2 * FastMath.acos(q0.getReal());
    }

    public double[][] toRotationMatrix() {
        double[][] matrix = new double[3][3];
        matrix[0][0] = 1 - 2 * (q2.multiply(q2).add(q3.multiply(q3))).getReal();
        matrix[0][1] = 2 * (q1.multiply(q2).subtract(q0.multiply(q3))).getReal();
        matrix[0][2] = 2 * (q1.multiply(q3).add(q0.multiply(q2))).getReal();
        matrix[1][0] = 2 * (q1.multiply(q2).add(q0.multiply(q3))).getReal();
        matrix[1][1] = 1 - 2 * (q1.multiply(q1).add(q3.multiply(q3))).getReal();
        matrix[1][2] = 2 * (q2.multiply(q3).subtract(q0.multiply(q1))).getReal();
        matrix[2][0] = 2 * (q1.multiply(q3).subtract(q0.multiply(q2))).getReal();
        matrix[2][1] = 2 * (q2.multiply(q3).add(q0.multiply(q1))).getReal();
        matrix[2][2] = 1 - 2 * (q1.multiply(q1).add(q2.multiply(q2))).getReal();
        return matrix;
    }

    public Vector3D applyTo(Vector3D vector) {
        FieldRotation<T> vectorRotation = new FieldRotation<>(0, vector.getX(), vector.getY(), vector.getZ());
        FieldRotation<T> result = this.compose(vectorRotation).compose(this.revert());
        return new Vector3D(result.q1.getReal(), result.q2.getReal(), result.q3.getReal());
    }

    public FieldRotation<T> compose(FieldRotation<T> rotation) {
        return new FieldRotation<>(
            q0.multiply(rotation.q0).subtract(q1.multiply(rotation.q1).add(q2.multiply(rotation.q2)).add(q3.multiply(rotation.q3))),
            q0.multiply(rotation.q1).add(q1.multiply(rotation.q0)).add(q2.multiply(rotation.q3)).subtract(q3.multiply(rotation.q2)),
            q0.multiply(rotation.q2).subtract(q1.multiply(rotation.q3)).add(q2.multiply(rotation.q0)).add(q3.multiply(rotation.q1)),
            q0.multiply(rotation.q3).add(q1.multiply(rotation.q2)).subtract(q2.multiply(rotation.q1)).add(q3.multiply(rotation.q0))
        );
    }

    public double distance(FieldRotation<T> rotation) {
        return FastMath.acos(FastMath.abs(q0.multiply(rotation.q0).add(q1.multiply(rotation.q1).add(q2.multiply(rotation.q2).add(q3.multiply(rotation.q3)))).getReal()));
    }
}

