@Processor
@CapabilityDescription("Writes records to a Kudu table.")
public class PutKudu extends AbstractProcessor {

    public static final PropertyDescriptor KUDU_MASTERS = new PropertyDescriptor.Builder()
            .name("Kudu Masters")
            .description("Comma-separated list of Kudu master servers.")
            .required(true)
            .addValidator(StandardValidators.NON_EMPTY_VALIDATOR)
            .build();

    public static final PropertyDescriptor TABLE_NAME = new PropertyDescriptor.Builder()
            .name("Table Name")
            .description("The name of the Kudu table to write to.")
            .required(true)
            .addValidator(StandardValidators.NON_EMPTY_VALIDATOR)
            .build();

    public static final PropertyDescriptor RECORD_READER = new PropertyDescriptor.Builder()
            .name("Record Reader")
            .description("Service to read records from incoming FlowFiles.")
            .required(true)
            .identifiesControllerService(RecordReader.class)
            .build();

    public static final Relationship SUCCESS = new Relationship.Builder()
            .name("success")
            .description("FlowFiles that were successfully written to Kudu.")
            .build();

    public static final Relationship FAILURE = new Relationship.Builder()
            .name("failure")
            .description("FlowFiles that failed to be written to Kudu.")
            .build();

    private List<PropertyDescriptor> properties;
    private Set<Relationship> relationships;
    private KuduClient kuduClient;

    @Override
    protected void init(ProcessorInitializationContext context) {
        List<PropertyDescriptor> props = new ArrayList<>();
        props.add(KUDU_MASTERS);
        props.add(TABLE_NAME);
        props.add(RECORD_READER);
        this.properties = Collections.unmodifiableList(props);

        Set<Relationship> rels = new HashSet<>();
        rels.add(SUCCESS);
        rels.add(FAILURE);
        this.relationships = Collections.unmodifiableSet(rels);
    }

    @OnScheduled
    public void onScheduled(ProcessorContext context) {
        String masters = context.getProperty(KUDU_MASTERS).getValue();
        kuduClient = new KuduClient.KuduClientBuilder(masters).build();
    }

    @OnStopped
    public void onStopped() {
        if (kuduClient != null) {
            kuduClient.shutdown();
        }
    }

    @Override
    public Set<Relationship> getRelationships() {
        return relationships;
    }

    @Override
    public List<PropertyDescriptor> getSupportedPropertyDescriptors() {
        return properties;
    }

    @Override
    public void onTrigger(ProcessContext context, ProcessSession session) throws ProcessException {
        FlowFile flowFile = session.get();
        if (flowFile == null) {
            return;
        }

        RecordReader reader = context.getProperty(RECORD_READER).asControllerService(RecordReader.class);
        KuduTable table = kuduClient.openTable(context.getProperty(TABLE_NAME).getValue());
        KuduSession session = kuduClient.newSession();
        session.setFlushMode(SessionConfiguration.FlushMode.AUTO_FLUSH_BACKGROUND);

        int recordCount = 0;
        try {
            RecordSchema schema = reader.getSchema();
            while (reader.next()) {
                Record record = reader.getRecord();
                Insert insert = table.newInsert();
                RowResult row = insert.getRow();
                // Populate row with record data
                // Example: row.addString("column_name", record.getString("record_field"));
                session.apply(insert);
                recordCount++;
            }
            session.flush();
            flowFile = session.putAttribute(flowFile, "records_written", String.valueOf(recordCount));
            session.transfer(flowFile, SUCCESS);
        } catch (KuduException e) {
            getLogger().error("Failed to write records to Kudu", e);
            session.transfer(flowFile, FAILURE);
        } finally {
            session.close();
        }
    }
}

public class ActionVerbalizer {

    private RutaVerbalizer rutaVerbalizer;

    public ActionVerbalizer(RutaVerbalizer rutaVerbalizer) {
        this.rutaVerbalizer = rutaVerbalizer;
    }

    public String verbalizeName(AbstractRutaAction action) {
        if (action instanceof AddAction) {
            return "ADD";
        } else if (action instanceof AssignAction) {
            return "ASSIGN";
        } else if (action instanceof ExecAction) {
            return "EXEC";
        } else {
            return "UNKNOWN ACTION";
        }
    }

    public String verbalize(AbstractRutaAction action) {
        StringBuilder result = new StringBuilder();
        result.append(verbalizeName(action)).append(": ");

        if (action instanceof AddAction) {
            AddAction addAction = (AddAction) action;
            result.append("Adding ").append(rutaVerbalizer.verbalize(addAction.getParameter()));
        } else if (action instanceof AssignAction) {
            AssignAction assignAction = (AssignAction) action;
            result.append("Assigning ").append(rutaVerbalizer.verbalize(assignAction.getValue()));
        } else if (action instanceof ExecAction) {
            ExecAction execAction = (ExecAction) action;
            result.append("Executing ").append(rutaVerbalizer.verbalize(execAction.getCommand()));
        } else {
            result.append("No details available for this action.");
        }

        return result.toString();
    }
}

