public abstract class CodecSupport {

    protected static final String DEFAULT_ENCODING = "UTF-8";

    public byte[] encode(String data) {
        return encode(data, DEFAULT_ENCODING);
    }

    public byte[] encode(String data, String encoding) {
        try {
            return data.getBytes(encoding);
        } catch (IOException e) {
            throw new RuntimeException("Unsupported encoding: " + encoding, e);
        }
    }

    public String decode(byte[] data) {
        return decode(data, DEFAULT_ENCODING);
    }

    public String decode(byte[] data, String encoding) {
        try {
            return new String(data, encoding);
        } catch (IOException e) {
            throw new RuntimeException("Unsupported encoding: " + encoding, e);
        }
    }

    protected boolean isValidByteSource(Object source) {
        return source instanceof byte[] || source instanceof String || source instanceof InputStream || source instanceof File;
    }

    protected byte[] toBytes(Object source) {
        if (source instanceof byte[]) {
            return (byte[]) source;
        } else if (source instanceof String) {
            return encode((String) source);
        } else if (source instanceof InputStream) {
            // Code smell: InputStream handling not implemented
            throw new UnsupportedOperationException("InputStream conversion not implemented");
        } else if (source instanceof File) {
            // Code smell: File handling not implemented
            throw new UnsupportedOperationException("File conversion not implemented");
        } else {
            throw new IllegalArgumentException("Unsupported object type: " + source.getClass());
        }
    }

    protected String toString(Object source) {
        if (source instanceof byte[]) {
            return decode((byte[]) source);
        } else if (source instanceof String) {
            return (String) source;
        } else {
            throw new IllegalArgumentException("Unsupported object type: " + source.getClass());
        }
    }

    protected abstract void handleUnsupportedType(Object source);
}

public class NotInExpressionUnitTest {

    @Test
    public void testNotInString() {
        ColumnExpression left = new ColumnExpression("name", DataType.STRING);
        ColumnExpression right = new ColumnExpression("values", DataType.STRING);
        RowImpl row = new RowImpl();
        row.put("name", "Alice");
        row.put("values", new String[]{"Bob", "Charlie"});

        NotInExpression notInExpression = new NotInExpression(left, right);
        assertFalse(notInExpression.evaluate(row));
    }

    @Test
    public void testNotInShort() {
        ColumnExpression left = new ColumnExpression("age", DataType.SHORT);
        ColumnExpression right = new ColumnExpression("ages", DataType.SHORT);
        RowImpl row = new RowImpl();
        row.put("age", (short) 30);
        row.put("ages", new Short[]{(short) 25, (short) 28});

        NotInExpression notInExpression = new NotInExpression(left, right);
        assertTrue(notInExpression.evaluate(row));
    }

