        ColumnExpression left = new ColumnExpression("timestamp", DataType.LONG);
        ColumnExpression right = new ColumnExpression("timestamps", DataType.LONG);
        RowImpl row = new RowImpl();
        row.put("timestamp", 1620000000000L);
        row.put("timestamps", new Long[]{1619999999999L, 1620000000001L});

        NotInExpression notInExpression = new NotInExpression(left, right);
        assertFalse(notInExpression.evaluate(row));
    }

