public class NexmarkConfiguration implements Serializable {
    private static final long serialVersionUID = 1L;

    private boolean debug;
    private String queryType;
    private String sourceType;
    private String sinkType;
    private int eventGenerationRate;

    // Default configuration instance
    public static final NexmarkConfiguration DEFAULT = new NexmarkConfiguration();

    public NexmarkConfiguration() {
        this.debug = false;
        this.queryType = "default";
        this.sourceType = "defaultSource";
        this.sinkType = "defaultSink";
        this.eventGenerationRate = 1;
    }

    public void overrideFrom(NexmarkOptions options) {
        if (options.isDebugSet()) {
            this.debug = options.isDebug();
        }
        if (options.getQueryType() != null) {
            this.queryType = options.getQueryType();
        }
        if (options.getSourceType() != null) {
            this.sourceType = options.getSourceType();
        }
        if (options.getSinkType() != null) {
            this.sinkType = options.getSinkType();
        }
        if (options.getEventGenerationRate() > 0) {
            this.eventGenerationRate = options.getEventGenerationRate();
        }
    }

    public NexmarkConfiguration copy() {
        NexmarkConfiguration copy = new NexmarkConfiguration();
        copy.debug = this.debug;
        copy.queryType = this.queryType;
        copy.sourceType = this.sourceType;
        copy.sinkType = this.sinkType;
        copy.eventGenerationRate = this.eventGenerationRate;
        return copy;
    }

    @Override
    public String toString() {
        return "NexmarkConfiguration{" +
                "debug=" + debug +
                ", queryType='" + queryType + '\'' +
                ", sourceType='" + sourceType + '\'' +
                ", sinkType='" + sinkType + '\'' +
                ", eventGenerationRate=" + eventGenerationRate +
                '}';
    }

    public String toJson() throws JsonProcessingException {
        ObjectMapper objectMapper = new ObjectMapper();
        return objectMapper.writeValueAsString(this);
    }

    public static NexmarkConfiguration fromJson(String json) throws JsonProcessingException {
        ObjectMapper objectMapper = new ObjectMapper();
        return objectMapper.readValue(json, NexmarkConfiguration.class);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof NexmarkConfiguration)) return false;
        NexmarkConfiguration that = (NexmarkConfiguration) o;
        return debug == that.debug &&
                eventGenerationRate == that.eventGenerationRate &&
                queryType.equals(that.queryType) &&
                sourceType.equals(that.sourceType) &&
                sinkType.equals(that.sinkType);
    }

    @Override
    public int hashCode() {
        int result = Boolean.hashCode(debug);
        result = 31 * result + queryType.hashCode();
        result = 31 * result + sourceType.hashCode();
        result = 31 * result + sinkType.hashCode();
        result = 31 * result + Integer.hashCode(eventGenerationRate);
        return result;
    }
}

