public class CommunicationGroupClientImpl implements CommunicationGroupServiceClient {
    private static final Logger logger = Logger.getLogger(CommunicationGroupClientImpl.class.getName());
    private Map<String, CommunicationOperator> operatorRegistry;
    private Map<String, SlaveTask> activeSlaveTasks;

    public CommunicationGroupClientImpl() {
        this.operatorRegistry = new HashMap<>();
        this.activeSlaveTasks = new HashMap<>();
        initializeCommunicationOperators();
    }

    private void initializeCommunicationOperators() {
        // Code smell: Hardcoded initialization
        operatorRegistry.put("broadcast", new BroadcastOperator());
        operatorRegistry.put("scatter", new ScatterOperator());
        operatorRegistry.put("gather", new GatherOperator());
        operatorRegistry.put("reduce", new ReduceOperator());
        logger.info("Communication operators initialized.");
    }

    public void sendMessage(String operatorType, Message message) {
        CommunicationOperator operator = operatorRegistry.get(operatorType);
        if (operator != null) {
            try {
                operator.send(message);
                logger.info("Message sent using operator: " + operatorType);
            } catch (Exception e) {
                logger.severe("Error sending message: " + e.getMessage());
            }
        } else {
            logger.warning("Operator type not found: " + operatorType);
        }
    }

    public void receiveMessage(String operatorType) {
        CommunicationOperator operator = operatorRegistry.get(operatorType);
        if (operator != null) {
            try {
                Message message = operator.receive();
                logger.info("Message received using operator: " + operatorType);
            } catch (Exception e) {
                logger.severe("Error receiving message: " + e.getMessage());
            }
        } else {
            logger.warning("Operator type not found: " + operatorType);
        }
    }

    public void registerSlaveTask(String taskId, SlaveTask task) {
        activeSlaveTasks.put(taskId, task);
        logger.info("Slave task registered: " + taskId);
    }

    public void deregisterSlaveTask(String taskId) {
        activeSlaveTasks.remove(taskId);
        logger.info("Slave task deregistered: " + taskId);
    }

    public CommunicationOperator getOperator(String operatorType) {
        return operatorRegistry.get(operatorType);
    }
}

public class GiftCertificateServices {
    private static final Logger logger = Logger.getLogger(GiftCertificateServices.class.getName());
    private Dispatcher dispatcher;
    private Delegator delegator;

    public GiftCertificateServices(Dispatcher dispatcher, Delegator delegator) {
        this.dispatcher = dispatcher;
        this.delegator = delegator;
    }

    public void createGiftCertificate(String userId, double initialAmount) {
        try {
            // Code smell: Method does too much
            if (initialAmount <= 0) {
                logger.warning("Initial amount must be greater than zero.");
                return;
            }
            GiftCertificate certificate = new GiftCertificate(userId, initialAmount);
            delegator.saveGiftCertificate(certificate);
            logger.info("Gift certificate created successfully.");
        } catch (Exception e) {
            logger.severe("Error creating gift certificate: " + e.getMessage());
        }
    }

    public void addFunds(String certificateId, double amount) {
        try {
            if (amount <= 0) {
                logger.warning("Amount to add must be greater than zero.");
                return;
            }
            GiftCertificate certificate = delegator.getGiftCertificate(certificateId);
            certificate.addFunds(amount);
            delegator.updateGiftCertificate(certificate);
            logger.info("Funds added successfully.");
        } catch (Exception e) {
            logger.severe("Error adding funds: " + e.getMessage());
        }
    }

    public void redeem(String certificateId, double amount, String pin) {
        try {
            GiftCertificate certificate = delegator.getGiftCertificate(certificateId);
            if (!certificate.validatePin(pin)) {
                logger.warning("Invalid PIN.");
                return;
            }
            if (amount > certificate.getBalance()) {
                logger.warning("Insufficient balance.");
                return;
            }
            certificate.redeem(amount);
            delegator.updateGiftCertificate(certificate);
            logger.info("Gift certificate redeemed successfully.");
        } catch (Exception e) {
            logger.severe("Error redeeming gift certificate: " + e.getMessage());
        }
    }

    public double checkBalance(String certificateId) {
        try {
            GiftCertificate certificate = delegator.getGiftCertificate(certificateId);
            return certificate.getBalance();
        } catch (Exception e) {
            logger.severe("Error checking balance: " + e.getMessage());
            return 0;
        }
    }

    public void authorizeTransaction(String certificateId, double amount) {
        try {
            GiftCertificate certificate = delegator.getGiftCertificate(certificateId);
            if (amount > certificate.getBalance()) {
                logger.warning("Transaction not authorized due to insufficient balance.");
                return;
            }
            // Code smell: Method does too much
            Transaction transaction = new Transaction(certificateId, amount);
            dispatcher.dispatch(transaction);
            logger.info("Transaction authorized successfully.");
        } catch (Exception e) {
            logger.severe("Error authorizing transaction: " + e.getMessage());
        }
    }

    public void refund(String certificateId, double amount) {
        try {
            GiftCertificate certificate = delegator.getGiftCertificate(certificateId);
            certificate.addFunds(amount);
            delegator.updateGiftCertificate(certificate);
            logger.info("Refund processed successfully.");
        } catch (Exception e) {
            logger.severe("Error processing refund: " + e.getMessage());
        }
    }

    public void reload(String certificateId, double amount) {
        try {
            if (amount <= 0) {
                logger.warning("Amount to reload must be greater than zero.");
                return;
            }
            GiftCertificate certificate = delegator.getGiftCertificate(certificateId);
            certificate.addFunds(amount);
            delegator.updateGiftCertificate(certificate);
            logger.info("Gift certificate reloaded successfully.");
        } catch (Exception e) {
            logger.severe("Error reloading gift certificate: " + e.getMessage());
        }
    }
}

