public class StringUtilsTest {

    @Test
    public void testIsEmpty() {
        assertTrue(StringUtils.isEmpty(null));
        assertTrue(StringUtils.isEmpty(""));
        assertFalse(StringUtils.isEmpty(" "));
        assertFalse(StringUtils.isEmpty("Hello"));
    }

    @Test
    public void testTrim() {
        assertEquals("", StringUtils.trim("   "));
        assertEquals("Hello", StringUtils.trim("  Hello  "));
        assertEquals("Hello", StringUtils.trim("Hello"));
        assertNull(StringUtils.trim(null));
    }

    @Test
    public void testJoin() {
        String[] parts = {"Hello", "World"};
        assertEquals("Hello,World", StringUtils.join(parts, ","));
        assertEquals("Hello World", StringUtils.join(parts, " "));
        assertEquals("", StringUtils.join(new String[]{}, ","));
    }

    @Test
    public void testSplit() {
        String str = "Hello,World";
        String[] result = StringUtils.split(str, ",");
        assertArrayEquals(new String[]{"Hello", "World"}, result);
        assertArrayEquals(new String[]{"Hello"}, StringUtils.split("Hello", ","));
        assertArrayEquals(new String[]{}, StringUtils.split("", ","));
    }

    @Test
    public void testPad() {
        assertEquals("Hello  ", StringUtils.pad("Hello", 7));
        assertEquals("  Hello", StringUtils.pad("Hello", 7, true));
        assertEquals("Hello", StringUtils.pad("Hello", 5));
        assertNull(StringUtils.pad(null, 5));
    }

    @Test
    public void testToUpperCase() {
        assertEquals("HELLO", StringUtils.toUpperCase("hello"));
        assertEquals("HELLO", StringUtils.toUpperCase("Hello"));
        assertNull(StringUtils.toUpperCase(null));
    }

    @Test
    public void testToLowerCase() {
        assertEquals("hello", StringUtils.toLowerCase("HELLO"));
        assertEquals("hello", StringUtils.toLowerCase("Hello"));
        assertNull(StringUtils.toLowerCase(null));
    }

    @Test
    public void testReplace() {
        assertEquals("Hella", StringUtils.replace("Hello", "o", "a"));
        assertEquals("Hello", StringUtils.replace("Hello", "x", "y"));
        assertNull(StringUtils.replace(null, "o", "a"));
    }

    @Test
    public void testCompare() {
        assertTrue(StringUtils.compare("abc", "abc") == 0);
        assertTrue(StringUtils.compare("abc", "ABC") != 0);
        assertTrue(StringUtils.compare(null, "abc") < 0);
        assertTrue(StringUtils.compare("abc", null) > 0);
    }

    @Test
    public void testNormalize() {
        assertEquals("Hello World", StringUtils.normalize("  Hello   World  "));
        assertNull(StringUtils.normalize(null));
    }

    @Test
    public void testAbbreviate() {
        assertEquals("Hello...", StringUtils.abbreviate("Hello World", 8));
        assertEquals("Hello", StringUtils.abbreviate("Hello", 10));
        assertEquals("", StringUtils.abbreviate("", 5));
    }
}

public class DefaultTraversal<S, E> implements Traversal.Admin<S, E> {
    private final List<TraversalStep<S, E>> steps;
    private final Lock lock;
    private boolean isLocked;

    public DefaultTraversal() {
        this.steps = new ArrayList<>();
        this.lock = new ReentrantLock();
        this.isLocked = false;
    }

    @Override
    public void addStep(TraversalStep<S, E> step) {
        if (isLocked) {
            throw new IllegalStateException("Traversal is locked.");
        }
        steps.add(step);
    }

    @Override
    public void removeStep(TraversalStep<S, E> step) {
        if (isLocked) {
            throw new IllegalStateException("Traversal is locked.");
        }
        steps.remove(step);
    }

    @Override
    public void lock() {
        lock.lock();
        isLocked = true;
    }

    @Override
    public void unlock() {
        isLocked = false;
        lock.unlock();
    }

    @Override
    public Traverser<S, E> next() {
        if (steps.isEmpty()) {
            throw new IllegalStateException("No steps in traversal.");
        }
        // Logic to generate the next traverser based on the steps
        return generateNextTraverser();
    }

    private Traverser<S, E> generateNextTraverser() {
        // Placeholder for actual traverser generation logic
        return new Traverser<>();
    }

    @Override
    public boolean hasNext() {
        // Logic to check if there are more elements to traverse
        return !steps.isEmpty(); // Simplified check
    }

    @Override
    public DefaultTraversal<S, E> clone() {
        DefaultTraversal<S, E> clonedTraversal = new DefaultTraversal<>();
        clonedTraversal.steps.addAll(this.steps);
        return clonedTraversal;
    }

    // Additional methods for side effects and strategies can be added here
}

class XmlConverter {

    public DOMSource toDOMSource(Document document) {
        return new DOMSource(document);
    }

    public SAXSource toSAXSource(InputSource inputSource) {
        return new SAXSource(inputSource);
    }

    public StreamSource toStreamSource(String xml) {
        return new StreamSource(new StringReader(xml));
    }

    public Document toDocument(String xml) throws ParserConfigurationException, IOException {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        return factory.newDocumentBuilder().parse(new ByteArrayInputStream(xml.getBytes()));
    }

    public String toString(Source source) throws TransformerException {
        StringWriter writer = new StringWriter();
        Transformer transformer = TransformerFactory.newInstance().newTransformer();
        transformer.setOutputProperty(OutputKeys.OMIT_XML_DECLARATION, "yes");
        transformer.transform(source, new StreamResult(writer));
        return writer.toString();
    }

    public String toString(Document document) throws TransformerException {
        return toString(toDOMSource(document));
    }

    public String toString(byte[] xmlBytes) throws TransformerException {
        return toString(toStreamSource(new String(xmlBytes)));
    }

    public String toString(InputSource inputSource) throws TransformerException {
        return toString(toSAXSource(inputSource));
    }

    public DocumentBuilderFactory createDocumentBuilderFactory() {
        return DocumentBuilderFactory.newInstance();
    }

    public TransformerFactory createTransformerFactory() {
        return TransformerFactory.newInstance();
    }

    public void configureTransformer(Transformer transformer) {
        transformer.setOutputProperty(OutputKeys.INDENT, "yes");
        transformer.setOutputProperty(OutputKeys.METHOD, "xml");
    }
}

public class CSVParserTest {

    @Test
    public void testSimpleCSV() {
        String csv = "name,age\nAlice,30\nBob,25";
        CSVParser parser = new CSVParser();
        List<String[]> result = parser.parse(new ByteArrayInputStream(csv.getBytes()));
        assertEquals(2, result.size());
        assertArrayEquals(new String[]{"name", "age"}, result.get(0));
        assertArrayEquals(new String[]{"Alice", "30"}, result.get(1));
    }

    @Test
    public void testCSVWithEscapedCharacters() {
        String csv = "name,age\n\"Al,ice\",30\n\"Bo\"b,25";
        CSVParser parser = new CSVParser();
        List<String[]> result = parser.parse(new ByteArrayInputStream(csv.getBytes()));
        assertEquals(2, result.size());
        assertArrayEquals(new String[]{"name", "age"}, result.get(0));
        assertArrayEquals(new String[]{"Al,ice", "30"}, result.get(1));
        assertArrayEquals(new String[]{"Bo\"b", "25"}, result.get(2));
    }

    @Test
    public void testEmptyLines() {
        String csv = "name,age\n\nAlice,30\n\nBob,25\n";
        CSVParser parser = new CSVParser();
        List<String[]> result = parser.parse(new ByteArrayInputStream(csv.getBytes()));
        assertEquals(3, result.size());
        assertArrayEquals(new String[]{"name", "age"}, result.get(0));
        assertArrayEquals(new String[]{"", ""}, result.get(1));
        assertArrayEquals(new String[]{"Alice", "30"}, result.get(2));
        assertArrayEquals(new String[]{"", ""}, result.get(3));
        assertArrayEquals(new String[]{"Bob", "25"}, result.get(4));
    }

    @Test
    public void testCSVWithHeaders() {
        String csv = "name,age\nAlice,30\nBob,25";
        CSVParser parser = new CSVParser();
        List<String[]> result = parser.parse(new ByteArrayInputStream(csv.getBytes()), true);
        assertEquals(3, result.size());
        assertArrayEquals(new String[]{"name", "age"}, result.get(0));
        assertArrayEquals(new String[]{"Alice", "30"}, result.get(1));
        assertArrayEquals(new String[]{"Bob", "25"}, result.get(2));
    }

    @Test
    public void testCSVWithBOM() {
        String csv = "\uFEFFname,age\nAlice,30\nBob,25";
        CSVParser parser = new CSVParser();
        List<String[]> result = parser.parse(new ByteArrayInputStream(csv.getBytes()));
        assertEquals(2, result.size());
        assertArrayEquals(new String[]{"name", "age"}, result.get(0));
        assertArrayEquals(new String[]{"Alice", "30"}, result.get(1));
        assertArrayEquals(new String[]{"Bob", "25"}, result.get(2));
    }

    @Test
    public void testInvalidCSV() {
        String csv = "name,age\nAlice,30\nBob";
        CSVParser parser = new CSVParser();
        Exception exception = assertThrows(CSVParseException.class, () -> {
            parser.parse(new ByteArrayInputStream(csv.getBytes()));
        });
        assertEquals("Invalid CSV format", exception.getMessage());
    }

    @Test
    public void testDifferentLineEndings() {
        String csv = "name,age\r\nAlice,30\rBob,25\n";
        CSVParser parser = new CSVParser();
        List<String[]> result = parser.parse(new ByteArrayInputStream(csv.getBytes()));
        assertEquals(3, result.size());
        assertArrayEquals(new String[]{"name", "age"}, result.get(0));
        assertArrayEquals(new String[]{"Alice", "30"}, result.get(1));
        assertArrayEquals(new String[]{"Bob", "25"}, result.get(2));
    }
}

public class QueryTreeDump implements QueryNodeVisitor {
    private StringBuffer output;
    private int indentLevel;

    public QueryTreeDump(StringBuffer output) {
        this.output = output;
        this.indentLevel = 0;
    }

    @Override
    public void visitRootNode(RootNode node) {
        appendIndented("Root Node: " + node.getName());
        traverseChildren(node);
    }

    @Override
    public void visitAndNode(AndNode node) {
        appendIndented("AND Node");
        traverseChildren(node);
    }

    @Override
    public void visitOrNode(OrNode node) {
        appendIndented("OR Node");
        traverseChildren(node);
    }

    @Override
    public void visitNotNode(NotNode node) {
        appendIndented("NOT Node");
        traverseChildren(node);
    }

    @Override
    public void visitExactMatchNode(ExactMatchNode node) {
        appendIndented("Exact Match: " + node.getMatchText());
    }

    @Override
    public void visitTextSearchNode(TextSearchNode node) {
        appendIndented("Text Search: " + node.getSearchText());
    }

    @Override
    public void visitPathNode(PathNode node) {
        appendIndented("Path: " + node.getPath());
    }

    @Override
    public void visitOrderNode(OrderNode node) {
        appendIndented("Order: " + node.getOrder());
    }

    private void traverseChildren(QueryNode node) {
        indentLevel++;
        for (QueryNode child : node.getChildren()) {
            child.accept(this);
        }
        indentLevel--;
    }

    private void appendIndented(String text) {
        for (int i = 0; i < indentLevel; i++) {
            output.append("  ");
        }
        output.append(text).append("\n");
    }
}

class DateUtil {

    public static final String ISO_8601_FORMAT = "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'";
    public static final String RFC_822_FORMAT = "EEE, dd MMM yyyy HH:mm:ss Z";

    public static Date getStartOfDay(Date date) {
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(date);
        calendar.set(Calendar.HOUR_OF_DAY, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        calendar.set(Calendar.MILLISECOND, 0);
        return calendar.getTime();
    }

    public static Date getEndOfDay(Date date) {
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(date);
        calendar.set(Calendar.HOUR_OF_DAY, 23);
        calendar.set(Calendar.MINUTE, 59);
        calendar.set(Calendar.SECOND, 59);
        calendar.set(Calendar.MILLISECOND, 999);
        return calendar.getTime();
    }

    public static Date getStartOfMonth(Date date) {
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(date);
        calendar.set(Calendar.DAY_OF_MONTH, 1);
        return getStartOfDay(calendar.getTime());
    }

    public static Date getEndOfMonth(Date date) {
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(date);
        calendar.set(Calendar.DAY_OF_MONTH, calendar.getActualMaximum(Calendar.DAY_OF_MONTH));
        return getEndOfDay(calendar.getTime());
    }

    public static String formatDate(Date date, String format) {
        SimpleDateFormat sdf = new SimpleDateFormat(format);
        return sdf.format(date);
    }

    public static Date parseDate(String dateString, String format) throws ParseException {
        SimpleDateFormat sdf = new SimpleDateFormat(format);
        return sdf.parse(dateString);
    }

    public static boolean isDateInRange(Date date, Date startDate, Date endDate) {
        return (date.equals(startDate) || date.after(startDate)) && (date.equals(endDate) || date.before(endDate));
    }

    public static Date getCurrentTimestamp() {
        return new Date();
    }

    public static String formatDateToISO(Date date) {
        return formatDate(date, ISO_8601_FORMAT);
    }

    public static String formatDateToRFC822(Date date) {
        return formatDate(date, RFC_822_FORMAT);
    }
}

public class RegExpRule extends AbstractRule {
    private IStringExpression regexExpression;
    private Map<String, Integer> typeMappings = new HashMap<>();
    private Map<String, String> featureAssignments = new HashMap<>();

    public RegExpRule(IStringExpression regexExpression) {
        this.regexExpression = regexExpression;
    }

    public void setRegexExpression(IStringExpression regexExpression) {
        this.regexExpression = regexExpression;
    }

    public IStringExpression getRegexExpression() {
        return regexExpression;
    }

    public void addTypeMapping(String type, Integer value) {
        typeMappings.put(type, value);
    }

    public void addFeatureAssignment(String feature, String value) {
        featureAssignments.put(feature, value);
    }

    public Map<String, String> generateFeatureAssignmentMap(Matcher matcher) {
        Map<String, String> featureMap = new HashMap<>();
        for (Map.Entry<String, String> entry : featureAssignments.entrySet()) {
            featureMap.put(entry.getKey(), entry.getValue());
        }
        for (int i = 0; i <= matcher.groupCount(); i++) {
            featureMap.put("group" + i, matcher.group(i));
        }
        return featureMap;
    }

    public void apply(String text) {
        Pattern pattern = Pattern.compile(regexExpression.getValue());
        Matcher matcher = pattern.matcher(text);
        while (matcher.find()) {
            Map<String, String> features = generateFeatureAssignmentMap(matcher);
            createAnnotation(matcher, features);
        }
    }

    private void createAnnotation(Matcher matcher, Map<String, String> features) {
        // Logic to create an annotation based on matcher and features
        // This method may contain code smells due to its complexity
    }

    public Map<String, Integer> getTypeMappings() {
        return typeMappings;
    }
}

