public class SecuredStatementImpl implements SecuredStatement {
    private final ItemHolder itemHolder;
    private final SecuredModel securedModel;

    public SecuredStatementImpl(ItemHolder itemHolder, SecuredModel securedModel) {
        this.itemHolder = itemHolder;
        this.securedModel = securedModel;
    }

    @Override
    public void addLiteral(String property, String value) {
        checkPermission("update");
        itemHolder.addLiteral(property, value);
    }

    @Override
    public void remove() {
        checkPermission("delete");
        itemHolder.remove();
    }

    @Override
    public String getLiteral(String property) {
        checkPermission("read");
        return itemHolder.getLiteral(property);
    }

    @Override
    public void updateLiteral(String property, String newValue) {
        checkPermission("update");
        itemHolder.updateLiteral(property, newValue);
    }

    @Override
    public ReifiedStatement createReifiedStatement() {
        checkPermission("create");
        return new ReifiedStatementImpl(itemHolder);
    }

    private void checkPermission(String action) {
        if (!securedModel.hasPermission(action)) {
            throw new SecurityException("Permission denied for action: " + action);
        }
    }
}

