public class ClassExtensions {

    public static <T> T createInstance(Class<T> clazz, Class<?>[] paramTypes, Object[] args) throws Exception {
        Constructor<T> constructor = clazz.getConstructor(paramTypes);
        return constructor.newInstance(args);
    }

    public static String getSuperclassName(Class<?> clazz) {
        Class<?> superclass = clazz.getSuperclass();
        return superclass != null ? superclass.getName() : null;
    }

    public static boolean isAbstract(Class<?> clazz) {
        return java.lang.reflect.Modifier.isAbstract(clazz.getModifiers());
    }

    public static boolean isFinal(Class<?> clazz) {
        return java.lang.reflect.Modifier.isFinal(clazz.getModifiers());
    }

    public static boolean isPublic(Class<?> clazz) {
        return java.lang.reflect.Modifier.isPublic(clazz.getModifiers());
    }

    public static boolean isStandardClass(Class<?> clazz) {
        return clazz.getPackage() != null && clazz.getPackage().getName().startsWith("java.");
    }

    public static Method findMethod(Class<?> clazz, String methodName, Class<?>[] paramTypes) {
        try {
            return clazz.getMethod(methodName, paramTypes);
        } catch (NoSuchMethodException e) {
            return null;
        }
    }

    public static Properties loadProperties(Class<?> clazz, String resourceName) throws Exception {
        Properties properties = new Properties();
        try (InputStream input = clazz.getResourceAsStream(resourceName)) {
            if (input != null) {
                properties.load(input);
            }
        }
        return properties;
    }

    public static String readResourceAsString(Class<?> clazz, String resourceName) throws Exception {
        StringBuilder content = new StringBuilder();
        try (InputStream input = clazz.getResourceAsStream(resourceName)) {
            if (input != null) {
                int ch;
                while ((ch = input.read()) != -1) {
                    content.append((char) ch);
                }
            }
        }
        return content.toString();
    }

    public static boolean resourceExists(Class<?> clazz, String resourceName) {
        return clazz.getResourceAsStream(resourceName) != null;
    }

    public static Class<?> convertPrimitiveToWrapper(Class<?> clazz) {
        if (clazz.isPrimitive()) {
            if (clazz == boolean.class) return Boolean.class;
            if (clazz == byte.class) return Byte.class;
            if (clazz == char.class) return Character.class;
            if (clazz == double.class) return Double.class;
            if (clazz == float.class) return Float.class;
            if (clazz == int.class) return Integer.class;
            if (clazz == long.class) return Long.class;
            if (clazz == short.class) return Short.class;
        }
        return clazz;
    }

    public static Object getDefaultValue(Class<?> clazz) {
        if (clazz == boolean.class) return false;
        if (clazz == byte.class) return (byte) 0;
        if (clazz == char.class) return '\u0000';
        if (clazz == double.class) return 0.0;
        if (clazz == float.class) return 0.0f;
        if (clazz == int.class) return 0;
        if (clazz == long.class) return 0L;
        if (clazz == short.class) return (short) 0;
        return null;
    }

    public static boolean isReturnTypeCompatible(Method method, Class<?> returnType) {
        return convertPrimitiveToWrapper(method.getReturnType()).isAssignableFrom(convertPrimitiveToWrapper(returnType));
    }
}

