public class FSDirectory {
    private final ReentrantLock lock = new ReentrantLock();
    private final FSImage fsImage;
    private final Map<String, FileMetadata> fileSystem = new HashMap<>();
    private final Map<String, DirectoryMetadata> directories = new HashMap<>();
    private final DirectoryMetadata rootDirectory;

    public FSDirectory(FSImage fsImage) {
        this.fsImage = fsImage;
        this.rootDirectory = new DirectoryMetadata("/");
        directories.put("/", rootDirectory);
    }

    public void createDirectory(String path) {
        lock.lock();
        try {
            if (directories.containsKey(path)) {
                throw new IllegalArgumentException("Directory already exists: " + path);
            }
            DirectoryMetadata newDir = new DirectoryMetadata(path);
            directories.put(path, newDir);
            rootDirectory.addChild(newDir);
            fsImage.logChange("Created directory: " + path);
        } finally {
            lock.unlock();
        }
    }

    public void addFile(String path, FileMetadata file) {
        lock.lock();
        try {
            if (fileSystem.containsKey(path)) {
                throw new IllegalArgumentException("File already exists: " + path);
            }
            fileSystem.put(path, file);
            DirectoryMetadata parentDir = getParentDirectory(path);
            parentDir.addFile(file);
            fsImage.logChange("Added file: " + path);
        } finally {
            lock.unlock();
        }
    }

    public void rename(String oldPath, String newPath) {
        lock.lock();
        try {
            if (!fileSystem.containsKey(oldPath) && !directories.containsKey(oldPath)) {
                throw new IllegalArgumentException("Path does not exist: " + oldPath);
            }
            if (fileSystem.containsKey(newPath) || directories.containsKey(newPath)) {
                throw new IllegalArgumentException("Path already exists: " + newPath);
            }
            if (fileSystem.containsKey(oldPath)) {
                FileMetadata file = fileSystem.remove(oldPath);
                fileSystem.put(newPath, file);
            } else {
                DirectoryMetadata dir = directories.remove(oldPath);
                directories.put(newPath, dir);
            }
            fsImage.logChange("Renamed from " + oldPath + " to " + newPath);
        } finally {
            lock.unlock();
        }
    }

    public void delete(String path) {
        lock.lock();
        try {
            if (!fileSystem.containsKey(path) && !directories.containsKey(path)) {
                throw new IllegalArgumentException("Path does not exist: " + path);
            }
            if (fileSystem.containsKey(path)) {
                fileSystem.remove(path);
            } else {
                directories.remove(path);
            }
            fsImage.logChange("Deleted path: " + path);
        } finally {
            lock.unlock();
        }
    }

    public void setPermissions(String path, String permissions) {
        lock.lock();
        try {
            if (fileSystem.containsKey(path)) {
                FileMetadata file = fileSystem.get(path);
                file.setPermissions(permissions);
            } else if (directories.containsKey(path)) {
                DirectoryMetadata dir = directories.get(path);
                dir.setPermissions(permissions);
            } else {
                throw new IllegalArgumentException("Path does not exist: " + path);
            }
            fsImage.logChange("Set permissions for path: " + path);
        } finally {
            lock.unlock();
        }
    }

    private DirectoryMetadata getParentDirectory(String path) {
        String parentPath = path.substring(0, path.lastIndexOf('/'));
        return directories.get(parentPath);
    }
}

