public class IntervalDatum {
    private static final Pattern TIME_PATTERN = Pattern.compile("(\\d+)M(\\d+)ms");
    private final long months;
    private final long milliseconds;

    public IntervalDatum(long months, long milliseconds) {
        this.months = months;
        this.milliseconds = milliseconds;
    }

    public static IntervalDatum fromString(String intervalString) {
        Matcher matcher = TIME_PATTERN.matcher(intervalString);
        if (matcher.matches()) {
            long months = Long.parseLong(matcher.group(1));
            long milliseconds = Long.parseLong(matcher.group(2));
            return new IntervalDatum(months, milliseconds);
        }
        throw new IllegalArgumentException("Invalid interval string format");
    }

    public String toString() {
        return months + "M" + milliseconds + "ms";
    }

    public long toMilliseconds() {
        return months * 30L * 24 * 60 * 60 * 1000 + milliseconds; // Approximation
    }

    public IntervalDatum add(IntervalDatum other) {
        return new IntervalDatum(this.months + other.months, this.milliseconds + other.milliseconds);
    }

    public IntervalDatum subtract(IntervalDatum other) {
        return new IntervalDatum(this.months - other.months, this.milliseconds - other.milliseconds);
    }

    public IntervalDatum multiply(long factor) {
        return new IntervalDatum(this.months * factor, this.milliseconds * factor);
    }

    public IntervalDatum divide(long divisor) {
        return new IntervalDatum(this.months / divisor, this.milliseconds / divisor);
    }

    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof IntervalDatum)) return false;
        IntervalDatum that = (IntervalDatum) o;
        return months == that.months && milliseconds == that.milliseconds;
    }

    public int hashCode() {
        return Objects.hash(months, milliseconds);
    }

    public int compareTo(IntervalDatum other) {
        int monthComparison = Long.compare(this.months, other.months);
        return monthComparison != 0 ? monthComparison : Long.compare(this.milliseconds, other.milliseconds);
    }
}

