        this.bundleContext = bundleContext;
        this.packageAdmin = packageAdmin;
        this.startLevel = startLevel;
    }

    public void installBundle(String location) {
        try {
            Bundle bundle = bundleContext.installBundle(location);
            bundle.start();
        } catch (BundleException e) {
            logError("Failed to install bundle: " + location, e);
        }
    }

    public void updateBundle(Bundle bundle) {
        try {
            bundle.update();
        } catch (BundleException e) {
            logError("Failed to update bundle: " + bundle.getLocation(), e);
        }
    }

    public void uninstallBundle(Bundle bundle) {
        try {
            bundle.uninstall();
        } catch (BundleException e) {
            logError("Failed to uninstall bundle: " + bundle.getLocation(), e);
        }
    }

    public void startBundle(Bundle bundle) {
        try {
            bundle.start();
        } catch (BundleException e) {
            logError("Failed to start bundle: " + bundle.getLocation(), e);
        }
    }

    public void stopBundle(Bundle bundle) {
        try {
            bundle.stop();
        } catch (BundleException e) {
            logError("Failed to stop bundle: " + bundle.getLocation(), e);
        }
    }

    public void refreshPackages() {
        packageAdmin.refreshPackages(null);
    }

    public void registerResolverHook(String name, ResolverHook hook) {
        resolverHooks.put(name, hook);
    }

    public void unregisterResolverHook(String name) {
        resolverHooks.remove(name);
    }

    public void setStartLevel(int level) {
        startLevel.setStartLevel(level);
    }

    public String getFrameworkInfo() {
        return "Framework: " + bundleContext.getBundle(0).getSymbolicName();
    }

    private void logError(String message, Exception e) {
        // Logging implementation here
        System.err.println(message);
        e.printStackTrace();
    }
}

