public class QueryExecutor {

    private CatalogService catalogService;
    private DistributedQueryHookManager hookManager;
    private DDLExecutor ddlExecutor;
    private QueryManager queryManager;
    private SessionManager sessionManager;

    public QueryExecutor(CatalogService catalogService, DistributedQueryHookManager hookManager,
                         DDLExecutor ddlExecutor, QueryManager queryManager, SessionManager sessionManager) {
        this.catalogService = catalogService;
        this.hookManager = hookManager;
        this.ddlExecutor = ddlExecutor;
        this.queryManager = queryManager;
        this.sessionManager = sessionManager;
    }

    public QueryResult executeQuery(LogicalPlan logicalPlan, UserSession userSession) {
        sessionManager.validateSession(userSession);
        String queryType = logicalPlan.getQueryType();

        switch (queryType) {
            case "DDL":
                return executeDDL(logicalPlan, userSession);
            case "SET":
                return handleSessionVariables(logicalPlan, userSession);
            case "SELECT":
            case "INSERT":
            case "UPDATE":
            case "DELETE":
                return executeStandardQuery(logicalPlan, userSession);
            case "EXPLAIN":
                return explainQuery(logicalPlan);
            default:
                throw new UnsupportedOperationException("Unsupported query type: " + queryType);
        }
    }

    private QueryResult executeDDL(LogicalPlan logicalPlan, UserSession userSession) {
        if (ddlExecutor.tableExists(logicalPlan.getTableName())) {
            throw new IllegalStateException("Table already exists: " + logicalPlan.getTableName());
        }
        hookManager.applyHooks(logicalPlan, userSession);
        return ddlExecutor.execute(logicalPlan);
    }

    private QueryResult handleSessionVariables(LogicalPlan logicalPlan, UserSession userSession) {
        Map<String, String> variables = logicalPlan.getSessionVariables();
        sessionManager.setSessionVariables(userSession, variables);
        return new QueryResult("Session variables set successfully.");
    }

    private QueryResult executeStandardQuery(LogicalPlan logicalPlan, UserSession userSession) {
        hookManager.applyHooks(logicalPlan, userSession);
        return queryManager.execute(logicalPlan, userSession);
    }

    private QueryResult explainQuery(LogicalPlan logicalPlan) {
        return queryManager.explain(logicalPlan);
    }

    public void insertData(LogicalPlan logicalPlan, UserSession userSession) {
        hookManager.applyHooks(logicalPlan, userSession);
        queryManager.insertData(logicalPlan, userSession);
    }

    public void compileMasterPlan(LogicalPlan logicalPlan) {
        queryManager.compileMasterPlan(logicalPlan);
    }

    public List<QueryResult> getQueryResults(String queryId) {
        return queryManager.getQueryResults(queryId);
    }
}

