        Root<Customer> customerRoot = query.from(Customer.class);
        query.select(customerRoot).where(criteriaBuilder.like(customerRoot.get("name"), "%John%"));

        String jpql = "SELECT c FROM Customer c WHERE c.name LIKE '%John%'";
        assertEquals(jpql, query.toString());
    }

    @Test
    public void testOrderCriteriaQuery() {
        CriteriaQuery<Order> query = criteriaBuilder.createQuery(Order.class);
        Root<Order> orderRoot = query.from(Order.class);
        query.select(orderRoot).where(criteriaBuilder.greaterThan(orderRoot.get("total"), 100));

        String jpql = "SELECT o FROM Order o WHERE o.total > 100";
        assertEquals(jpql, query.toString());
    }

    @Test
    public void testJoinCriteriaQuery() {
        CriteriaQuery<Order> query = criteriaBuilder.createQuery(Order.class);
        Root<Order> orderRoot = query.from(Order.class);
        Root<Customer> customerRoot = query.from(Customer.class);
        query.select(orderRoot).where(criteriaBuilder.equal(orderRoot.get("customer"), customerRoot));

        String jpql = "SELECT o FROM Order o JOIN o.customer c";
        assertEquals(jpql, query.toString());
    }

    @Test
    public void testSubquery() {
        CriteriaQuery<Customer> query = criteriaBuilder.createQuery(Customer.class);
        Root<Customer> customerRoot = query.from(Customer.class);
        CriteriaQuery<Long> subquery = criteriaBuilder.createQuery(Long.class);
        Root<Order> orderRoot = subquery.from(Order.class);
