        query.select(customerRoot).where(criteriaBuilder.greaterThan(subquery, 0L));

        String jpql = "SELECT c FROM Customer c WHERE (SELECT COUNT(o) FROM Order o WHERE o.customer = c) > 0";
        assertEquals(jpql, query.toString());
    }

