class DupsCursorTest {
    private Database db;
    private Table table;

    @Before
    public void setUp() {
        db = new Database();
        table = db.createTable("testTable", true); // true indicates duplicates are allowed
    }

    @Test
    public void testEmptyTable() {
        Cursor cursor = table.openCursor();
        assertFalse(cursor.moveNext());
        cursor.close();
    }

    @Test
    public void testInsertAndRetrieveDuplicates() {
        table.insert("key1", "value1");
        table.insert("key1", "value2");
        table.insert("key1", "value3");

        Cursor cursor = table.openCursor();
        assertTrue(cursor.moveNext());
        assertEquals("value1", cursor.getValue());
        assertTrue(cursor.moveNext());
        assertEquals("value2", cursor.getValue());
        assertTrue(cursor.moveNext());
        assertEquals("value3", cursor.getValue());
        assertFalse(cursor.moveNext());
        cursor.close();
    }

    @Test
    public void testCursorBehaviorWithDuplicates() {
        table.insert("key2", "valueA");
        table.insert("key2", "valueB");

        Cursor cursor = table.openCursor();
        assertTrue(cursor.moveNext());
        assertEquals("valueA", cursor.getValue());
        assertTrue(cursor.moveNext());
        assertEquals("valueB", cursor.getValue());
        assertFalse(cursor.moveNext());
        cursor.close();
    }

    @Test
    public void testInsertAndRetrieveDifferentKeys() {
        table.insert("key3", "valueX");
        table.insert("key4", "valueY");

        Cursor cursor = table.openCursor();
        assertTrue(cursor.moveNext());
        assertEquals("valueX", cursor.getValue());
        assertTrue(cursor.moveNext());
        assertEquals("valueY", cursor.getValue());
        assertFalse(cursor.moveNext());
        cursor.close();
    }

    @Test
    public void testCursorOnEmptyAfterInsertions() {
        table.insert("key5", "valueZ");
        table.delete("key5");

        Cursor cursor = table.openCursor();
        assertFalse(cursor.moveNext());
        cursor.close();
    }
}

