public class Duration {
    public static final Duration ONE_MILLISECOND = new Duration(1);
    public static final Duration ONE_SECOND = new Duration(1000);
    public static final Duration ONE_MINUTE = new Duration(60000);
    public static final Duration ONE_HOUR = new Duration(3600000);
    public static final Duration ONE_DAY = new Duration(86400000);

    private long milliseconds;

    public Duration(long milliseconds) {
        this.milliseconds = milliseconds;
    }

    public static Duration fromMilliseconds(long milliseconds) {
        return new Duration(milliseconds);
    }

    public static Duration fromSeconds(long seconds) {
        return new Duration(TimeUnit.SECONDS.toMillis(seconds));
    }

    public static Duration fromMinutes(long minutes) {
        return new Duration(TimeUnit.MINUTES.toMillis(minutes));
    }

    public static Duration fromHours(long hours) {
        return new Duration(TimeUnit.HOURS.toMillis(hours));
    }

    public static Duration fromDays(long days) {
        return new Duration(TimeUnit.DAYS.toMillis(days));
    }

    public long toMilliseconds() {
        return milliseconds;
    }

    public long toSeconds() {
        return TimeUnit.MILLISECONDS.toSeconds(milliseconds);
    }

    public long toMinutes() {
        return TimeUnit.MILLISECONDS.toMinutes(milliseconds);
    }

    public long toHours() {
        return TimeUnit.MILLISECONDS.toHours(milliseconds);
    }

    public long toDays() {
        return TimeUnit.MILLISECONDS.toDays(milliseconds);
    }

    public Duration add(Duration other) {
        return new Duration(this.milliseconds + other.milliseconds);
    }

    public Duration subtract(Duration other) {
        return new Duration(this.milliseconds - other.milliseconds);
    }

    public void sleep() throws InterruptedException {
        Thread.sleep(milliseconds);
    }

    public void waitOn(Object obj) throws InterruptedException {
        obj.wait(milliseconds);
    }

    @Override
    public String toString() {
        long seconds = toSeconds();
        long minutes = toMinutes();
        long hours = toHours();
        long days = toDays();
        return String.format("%d days, %d hours, %d minutes, %d seconds, %d milliseconds",
                days, hours % 24, minutes % 60, seconds % 60, milliseconds % 1000);
    }

    public static Duration parse(String durationString) {
        // Simple parsing logic (could be improved)
        String[] parts = durationString.split(" ");
        long totalMilliseconds = 0;
        for (String part : parts) {
            if (part.endsWith("ms")) {
                totalMilliseconds += Long.parseLong(part.replace("ms", ""));
            } else if (part.endsWith("s")) {
                totalMilliseconds += fromSeconds(Long.parseLong(part.replace("s", ""))).toMilliseconds();
            } else if (part.endsWith("m")) {
                totalMilliseconds += fromMinutes(Long.parseLong(part.replace("m", ""))).toMilliseconds();
            } else if (part.endsWith("h")) {
                totalMilliseconds += fromHours(Long.parseLong(part.replace("h", ""))).toMilliseconds();
            } else if (part.endsWith("d")) {
                totalMilliseconds += fromDays(Long.parseLong(part.replace("d", ""))).toMilliseconds();
            }
        }
        return new Duration(totalMilliseconds);
    }
}

public class Util {

    public static boolean equals(KeyStore ks1, KeyStore ks2) {
        // Compare aliases, certificate entries, and key entries
        // Code smells: No null checks, potential NPE
        return Arrays.equals(ks1.aliases(), ks2.aliases()) &&
               Arrays.equals(ks1.getCertificateEntries(), ks2.getCertificateEntries()) &&
               Arrays.equals(ks1.getKeyEntries(), ks2.getKeyEntries());
    }

    public static boolean isYes(String value) {
        return "yes".equalsIgnoreCase(value);
    }

    public static String trim(String str) {
        return str == null ? null : str.trim();
    }

    public static String pad(String str, int length) {
        if (str == null) return null;
        return String.format("%-" + length + "s", str);
    }

    public static boolean hasWhitespace(String str) {
        return str != null && str.chars().anyMatch(Character::isWhitespace);
    }

    public static void pipe(InputStream in, OutputStream out) throws IOException {
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = in.read(buffer)) != -1) {
            out.write(buffer, 0, bytesRead);
        }
    }

    public static byte[] toByteArray(File file) throws IOException {
        try (InputStream in = new FileInputStream(file)) {
            return toByteArray(in);
        }
    }

    public static byte[] toByteArray(InputStream in) throws IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        pipe(in, out);
        return out.toByteArray();
    }

    public static void fillByteArray(InputStream in, byte[] array) throws IOException {
        int bytesRead = in.read(array);
        if (bytesRead < array.length) {
            throw new IOException("Not enough data to fill the array");
        }
    }

    public static byte[] resizeArray(byte[] array, int newSize) {
        return Arrays.copyOf(array, newSize);
    }

    public static HostPort parseHostPort(String str) {
        String[] parts = str.split(":");
        return new HostPort(parts[0], Integer.parseInt(parts[1]));
    }

    public static InetAddress parseInetAddress(String str) throws IOException {
        return InetAddress.getByName(str);
    }

    public static String convertCipherToAuthType(String cipher) {
        // Code smells: No validation on cipher input
        return cipher.replace("AES", "AuthTypeAES");
    }

    public static void main(String[] args) throws IOException {
        byte[] inputData = "Hello, World!\nThis is a test.".getBytes();
        InputStream inputStream = new ByteArrayInputStream(inputData);
        BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println(line);
        }
    }
}

