public class StandardConnectionDAO {
    private FlowController flowController;
    private Authorizer authorizer;

    public StandardConnectionDAO(FlowController flowController, Authorizer authorizer) {
        this.flowController = flowController;
        this.authorizer = authorizer;
    }

    public void createConnection(Connection connection) {
        validateConnection(connection);
        flowController.addConnection(connection);
    }

    public Connection getConnection(String id) {
        Connection connection = flowController.findConnectionById(id);
        if (connection == null) {
            throw new ResourceNotFoundException("Connection not found with id: " + id);
        }
        return connection;
    }

    public void updateConnection(Connection connection) {
        validateConnection(connection);
        flowController.updateConnection(connection);
    }

    public void deleteConnection(String id) {
        Connection connection = getConnection(id);
        flowController.removeConnection(connection);
    }

    public List<Connection> listConnections() {
        return flowController.getAllConnections();
    }

    public void dropFlowFile(String connectionId, FlowFile flowFile) {
        Connection connection = getConnection(connectionId);
        if (connection.isBackPressureEnabled() && connection.isBackPressureExceeded()) {
            throw new BackPressureException("Back pressure exceeded for connection: " + connectionId);
        }
        connection.dropFlowFile(flowFile);
    }

    private void validateConnection(Connection connection) {
        if (connection == null || connection.getId() == null || connection.getName() == null) {
            throw new IllegalArgumentException("Connection must have a valid id and name.");
        }
        if (!authorizer.isAuthorized(connection)) {
            throw new AuthorizationException("Unauthorized access to connection: " + connection.getId());
        }
    }
}

