public class SecureBankService {
    private final Map<String, BankAccount> accounts = new HashMap<>();
    private final Logger logger = Logger.getLogger(SecureBankService.class.getName());

    public synchronized void createAccount(String accountId, String owner) {
        if (accounts.containsKey(accountId)) {
            logger.warning("Account creation failed: Account ID already exists.");
            return;
        }
        accounts.put(accountId, new BankAccount(accountId, owner));
        logger.info("Account created: " + accountId);
    }

    public synchronized BankAccount getAccount(String accountId) {
        return accounts.get(accountId);
    }

    public synchronized void deposit(String accountId, double amount) {
        BankAccount account = accounts.get(accountId);
        if (account == null) {
            logger.warning("Deposit failed: Account not found.");
            return;
        }
        account.deposit(amount);
        logger.info("Deposited " + amount + " to account: " + accountId);
    }

    public synchronized void withdraw(String accountId, double amount) {
        BankAccount account = accounts.get(accountId);
        if (account == null) {
            logger.warning("Withdrawal failed: Account not found.");
            return;
        }
        if (!account.withdraw(amount)) {
            logger.warning("Withdrawal failed: Insufficient funds in account: " + accountId);
        } else {
            logger.info("Withdrew " + amount + " from account: " + accountId);
        }
    }

    public synchronized void closeAccount(String accountId) {
        if (!accounts.containsKey(accountId)) {
            logger.warning("Account closure failed: Account not found.");
            return;
        }
        accounts.remove(accountId);
        logger.info("Account closed: " + accountId);
    }

    public synchronized boolean checkAccountStatus(String accountId) {
        return accounts.containsKey(accountId);
    }

    private class BankAccount {
        private final String accountId;
        private final String owner;
        private double balance;

        public BankAccount(String accountId, String owner) {
            this.accountId = accountId;
            this.owner = owner;
            this.balance = 0.0;
        }

        public void deposit(double amount) {
            balance += amount;
        }

        public boolean withdraw(double amount) {
            if (balance >= amount) {
                balance -= amount;
                return true;
            }
            return false;
        }
    }
}

public class SourceRepositoryImpl {
    private static final Logger logger = Logger.getLogger(SourceRepositoryImpl.class.getName());
    private final SourceResolver sourceResolver;
    private final RepositoryInterceptor repositoryInterceptor;
    private final Lock lock = new ReentrantLock();

    public SourceRepositoryImpl(SourceResolver sourceResolver, RepositoryInterceptor repositoryInterceptor) {
        this.sourceResolver = sourceResolver;
        this.repositoryInterceptor = repositoryInterceptor;
    }

    public void save(Source source) {
        lock.lock();
        try {
            if (source.isNonModifiable()) {
                logger.warning("Attempted to modify a non-modifiable source: " + source.getUri());
                throw new IllegalStateException("Cannot modify non-modifiable source");
            }
            repositoryInterceptor.preSave(source);
            // Logic to save the source
            logger.info("Source saved: " + source.getUri());
            repositoryInterceptor.postSave(source);
        } catch (Exception e) {
            logger.severe("Error saving source: " + e.getMessage());
        } finally {
            lock.unlock();
            sourceResolver.release(source);
        }
    }

    public void remove(Source source) {
        lock.lock();
        try {
            repositoryInterceptor.preRemove(source);
            // Logic to remove the source
            logger.info("Source removed: " + source.getUri());
            repositoryInterceptor.postRemove(source);
        } catch (Exception e) {
            logger.severe("Error removing source: " + e.getMessage());
        } finally {
            lock.unlock();
            sourceResolver.release(source);
        }
    }

    public void copy(Source source, String newUri) {
        lock.lock();
        try {
            if (sourceExists(newUri)) {
                logger.warning("Resource already exists: " + newUri);
                throw new IllegalStateException("Resource already exists");
            }
            repositoryInterceptor.preCopy(source, newUri);
            // Logic to copy the source
            logger.info("Source copied from " + source.getUri() + " to " + newUri);
            repositoryInterceptor.postCopy(source, newUri);
        } catch (Exception e) {
            logger.severe("Error copying source: " + e.getMessage());
        } finally {
            lock.unlock();
            sourceResolver.release(source);
        }
    }

    public void createCollection(String collectionUri) {
        lock.lock();
        try {
            if (parentExists(collectionUri)) {
                logger.warning("Parent exists for collection: " + collectionUri);
                throw new IllegalStateException("Parent exists");
            }
            repositoryInterceptor.preCreateCollection(collectionUri);
            // Logic to create the collection
            logger.info("Collection created: " + collectionUri);
            repositoryInterceptor.postCreateCollection(collectionUri);
        } catch (Exception e) {
            logger.severe("Error creating collection: " + e.getMessage());
        } finally {
            lock.unlock();
        }
    }

