public class ConcurrentLongLongHashMapTest {
    private ConcurrentLongLongHashMap map;

    @BeforeEach
    public void setUp() {
        map = new ConcurrentLongLongHashMap(16);
    }

    @Test
    public void testConstructorWithInvalidCapacity() {
        assertThrows(IllegalArgumentException.class, () -> new ConcurrentLongLongHashMap(0));
        assertThrows(IllegalArgumentException.class, () -> new ConcurrentLongLongHashMap(-1));
    }

    @Test
    public void testPutAndGet() {
        map.put(1L, 100L);
        assertEquals(100L, map.get(1L));
    }

    @Test
    public void testRemove() {
        map.put(1L, 100L);
        map.remove(1L);
        assertNull(map.get(1L));
        assertTrue(map.isEmpty());
    }

    @Test
    public void testCountUsedBuckets() {
        map.put(1L, 100L);
        map.put(2L, 200L);
        assertEquals(2, map.size());
        map.remove(1L);
        assertEquals(1, map.size());
    }

    @Test
    public void testRehashing() {
        for (long i = 0; i < 20; i++) {
            map.put(i, i * 10);
        }
        for (long i = 0; i < 20; i++) {
            assertEquals(i * 10, map.get(i));
        }
    }

    @Test
    public void testConcurrentInsertionsAndReads() throws InterruptedException {
        Thread writer = new Thread(() -> {
            for (long i = 0; i < 1000; i++) {
                map.put(i, i);
            }
        });

        Thread reader = new Thread(() -> {
            for (long i = 0; i < 1000; i++) {
                assertNotNull(map.get(i));
            }
        });

        writer.start();
        reader.start();
        writer.join();
        reader.join();
    }

    @Test
    public void testIteration() {
        map.put(1L, 100L);
        map.put(2L, 200L);
        map.put(3L, 300L);

        assertEquals(3, map.size());

        for (long key : map.keySet()) {
            assertTrue(key >= 1 && key <= 3);
        }

        for (long value : map.values()) {
            assertTrue(value % 100 == 0);
        }
    }

    @Test
    public void testHashConflictDeletion() {
        map.put(1L, 100L);
        map.put(17L, 200L); // Assuming 17 collides with 1
        map.remove(1L);
        assertNull(map.get(1L));
        assertEquals(200L, map.get(17L));
    }

    @Test
    public void testAtomicOperations() {
        map.putIfAbsent(1L, 100L);
        assertEquals(100L, map.get(1L));

        map.computeIfAbsent(1L, k -> 200L);
        assertEquals(100L, map.get(1L)); // Should not change

        long newValue = map.addAndGet(1L, 50L);
        assertEquals(150L, newValue);
    }

    @Test
    public void testConditionalRemoval() {
        map.put(1L, 100L);
        assertTrue(map.remove(1L, 100L));
        assertFalse(map.remove(1L, 200L));
    }

    @Test
    public void testInvalidKeys() {
        assertThrows(IllegalArgumentException.class, () -> map.put(null, 100L));
        assertThrows(IllegalArgumentException.class, () -> map.get(null));
        assertThrows(IllegalArgumentException.class, () -> map.remove(null));
    }

    @Test
    public void testToMapConversion() {
        map.put(1L, 100L);
        map.put(2L, 200L);
        Map<Long, Long> standardMap = map.toMap();
        assertEquals(2, standardMap.size());
        assertEquals(100L, standardMap.get(1L));
        assertEquals(200L, standardMap.get(2L));
    }
}

