public class Sheet implements Model {
    private int rows;
    private int columns;
    private List<List<Cell>> cells;
    private List<MergedRegion> mergedRegions;
    private PrintSettings printSettings;
    private String header;
    private String footer;
    private Margin margins;

    public Sheet(int rows, int columns) {
        this.rows = rows;
        this.columns = columns;
        this.cells = new ArrayList<>(rows);
        for (int i = 0; i < rows; i++) {
            List<Cell> row = new ArrayList<>(columns);
            for (int j = 0; j < columns; j++) {
                row.add(new Cell());
            }
            cells.add(row);
        }
        this.mergedRegions = new ArrayList<>();
        this.printSettings = new PrintSettings();
        this.header = "";
        this.footer = "";
        this.margins = new Margin();
    }

    public void addRow() {
        List<Cell> newRow = new ArrayList<>(columns);
        for (int j = 0; j < columns; j++) {
            newRow.add(new Cell());
        }
        cells.add(newRow);
        rows++;
    }

    public void removeRow(int index) {
        if (index >= 0 && index < rows) {
            cells.remove(index);
            rows--;
        }
    }

    public void setCellValue(int row, int column, Object value) {
        if (isValidCell(row, column)) {
            cells.get(row).get(column).setValue(value);
        }
    }

    public Object getCellValue(int row, int column) {
        if (isValidCell(row, column)) {
            return cells.get(row).get(column).getValue();
        }
        return null;
    }

    public void mergeCells(int startRow, int startColumn, int endRow, int endColumn) {
        mergedRegions.add(new MergedRegion(startRow, startColumn, endRow, endColumn));
    }

    public void setPrintSettings(PrintSettings settings) {
        this.printSettings = settings;
    }

    public void setHeader(String header) {
        this.header = header;
    }

    public void setFooter(String footer) {
        this.footer = footer;
    }

    public void setMargins(Margin margins) {
        this.margins = margins;
    }

    private boolean isValidCell(int row, int column) {
        return row >= 0 && row < rows && column >= 0 && column < columns;
    }

    // Serialization and cloning methods would go here
}

