public class NamingContext implements Context {
    private Map<String, Object> bindings = new HashMap<>();
    private Hashtable<String, Object> environment;
    private boolean writable = true;

    public NamingContext(Hashtable<String, Object> env) {
        this.environment = env;
    }

    @Override
    public Object lookup(String name) throws NamingException {
        if (!bindings.containsKey(name)) {
            throw new NameNotFoundException("Name not found: " + name);
        }
        return bindings.get(name);
    }

    @Override
    public void bind(String name, Object obj) throws NamingException {
        if (!writable) {
            throw new NamingException("Context is not writable");
        }
        if (bindings.containsKey(name)) {
            throw new NameAlreadyBoundException("Name already bound: " + name);
        }
        bindings.put(name, obj);
    }

    @Override
    public void rebind(String name, Object obj) throws NamingException {
        if (!writable) {
            throw new NamingException("Context is not writable");
        }
        bindings.put(name, obj);
    }

    @Override
    public void unbind(String name) throws NamingException {
        if (!writable) {
            throw new NamingException("Context is not writable");
        }
        if (!bindings.containsKey(name)) {
            throw new NameNotFoundException("Name not found: " + name);
        }
        bindings.remove(name);
    }

    @Override
    public void rename(String oldName, String newName) throws NamingException {
        if (!writable) {
            throw new NamingException("Context is not writable");
        }
        if (!bindings.containsKey(oldName)) {
            throw new NameNotFoundException("Old name not found: " + oldName);
        }
        if (bindings.containsKey(newName)) {
            throw new NameAlreadyBoundException("New name already bound: " + newName);
        }
        Object obj = bindings.remove(oldName);
        bindings.put(newName, obj);
    }

    @Override
    public NamingEnumeration<Binding> list(String name) throws NamingException {
        // Implementation omitted for brevity
        return null;
    }

    @Override
    public Context createSubcontext(String name) throws NamingException {
        if (!writable) {
            throw new NamingException("Context is not writable");
        }
        NamingContext subContext = new NamingContext(environment);
        bind(name, subContext);
        return subContext;
    }

    @Override
    public void destroySubcontext(String name) throws NamingException {
        if (!writable) {
            throw new NamingException("Context is not writable");
        }
        unbind(name);
    }

    // Other methods from Context interface omitted for brevity
}

