public class AvlTableDupsCursor<K, V> extends AbstractCursor<Tuple<K, V>> {
    private static final Logger logger = Logger.getLogger(AvlTableDupsCursor.class.getName());
    private AvlTree<K, V> avlTree;
    private Cursor<Tuple<K, V>> wrappedCursor;
    private Cursor<V> duplicateCursor;
    private K currentKey;

    public AvlTableDupsCursor(AvlTree<K, V> avlTree) {
        this.avlTree = avlTree;
        this.wrappedCursor = avlTree.cursor();
        this.duplicateCursor = null;
        logger.info("AvlTableDupsCursor initialized.");
    }

    @Override
    public boolean hasNext() {
        if (duplicateCursor != null && duplicateCursor.hasNext()) {
            return true;
        }
        return wrappedCursor.hasNext();
    }

    @Override
    public Tuple<K, V> next() {
        if (duplicateCursor != null && duplicateCursor.hasNext()) {
            V value = duplicateCursor.next();
            return new Tuple<>(currentKey, value);
        }
        Tuple<K, V> entry = wrappedCursor.next();
        currentKey = entry.getKey();
        duplicateCursor = avlTree.getDuplicates(currentKey).cursor();
        return entry;
    }

    public boolean moveToKey(K key) {
        if (avlTree.containsKey(key)) {
            wrappedCursor.moveTo(key);
            currentKey = key;
            duplicateCursor = avlTree.getDuplicates(key).cursor();
            logger.info("Moved to key: " + key);
            return true;
        }
        logger.warning("Key not found: " + key);
        return false;
    }

    public boolean moveToValue(V value) {
        while (hasNext()) {
            Tuple<K, V> entry = next();
            if (entry.getValue().equals(value)) {
                logger.info("Moved to value: " + value);
                return true;
            }
        }
        logger.warning("Value not found: " + value);
        return false;
    }

    @Override
    public void close() {
        wrappedCursor.close();
        if (duplicateCursor != null) {
            duplicateCursor.close();
        }
        logger.info("Cursor closed.");
    }

    @Override
    public boolean isAvailable() {
        return wrappedCursor.isAvailable() || (duplicateCursor != null && duplicateCursor.isAvailable());
    }
}

class ColumnSelectTest {

    private ColumnSelect<Artist> columnSelect;

    @BeforeEach
    void setUp() {
        columnSelect = new ColumnSelect<>(Artist.class);
    }

    @Test
    void testDefaultValues() {
        assertTrue(columnSelect.getColumns().isEmpty());
        assertNull(columnSelect.getHavingClause());
        assertNull(columnSelect.getWhereClause());
    }

    @Test
    void testSingleColumnSelection() {
        columnSelect.select("name");
        assertEquals(1, columnSelect.getColumns().size());
        assertTrue(columnSelect.getColumns().contains("name"));
    }

    @Test
    void testMultipleColumnSelection() {
        columnSelect.select("name", "age");
        assertEquals(2, columnSelect.getColumns().size());
        assertTrue(columnSelect.getColumns().contains("name"));
        assertTrue(columnSelect.getColumns().contains("age"));
    }

    @Test
    void testAggregateFunctions() {
        columnSelect.count("id");
        assertEquals(1, columnSelect.getColumns().size());
        assertTrue(columnSelect.getColumns().contains("COUNT(id)"));

        columnSelect.min("age");
        assertEquals(2, columnSelect.getColumns().size());
        assertTrue(columnSelect.getColumns().contains("MIN(age)"));
    }

    @Test
    void testAddColumnsIndividually() {
        columnSelect.select("name");
        columnSelect.select("age");
        assertEquals(2, columnSelect.getColumns().size());
    }

    @Test
    void testAddColumnsCollectively() {
        columnSelect.select("name", "age", "genre");
        assertEquals(3, columnSelect.getColumns().size());
        assertTrue(columnSelect.getColumns().contains("name"));
        assertTrue(columnSelect.getColumns().contains("age"));
        assertTrue(columnSelect.getColumns().contains("genre"));
    }

    @Test
    void testHavingClause() {
        columnSelect.having("COUNT(id) > 1");
        assertEquals("COUNT(id) > 1", columnSelect.getHavingClause());
    }

    @Test
    void testWhereClause() {
        columnSelect.where("age > 20");
        assertEquals("age > 20", columnSelect.getWhereClause());
    }

    @Test
    void testLogicalOperationsInWhereClause() {
        columnSelect.where("age > 20 AND genre = 'Rock'");
        assertEquals("age > 20 AND genre = 'Rock'", columnSelect.getWhereClause());
    }

    @Test
    void testDistinctSelection() {
        columnSelect.distinct();
        assertTrue(columnSelect.isDistinct());
    }
}

