public final class ByteUtil {
    public static final int BYTE_SIZE = 1;
    public static final int SHORT_SIZE = 2;
    public static final int INT_SIZE = 4;
    public static final int LONG_SIZE = 8;
    public static final int FLOAT_SIZE = 4;
    public static final int DOUBLE_SIZE = 8;

    private ByteUtil() {
        // Prevent instantiation
    }

    public static byte[] intToBytes(int value) {
        return ByteBuffer.allocate(INT_SIZE).putInt(value).array();
    }

    public static int bytesToInt(byte[] bytes) {
        return ByteBuffer.wrap(bytes).getInt();
    }

    public static byte[] shortToBytes(short value) {
        return ByteBuffer.allocate(SHORT_SIZE).putShort(value).array();
    }

    public static short bytesToShort(byte[] bytes) {
        return ByteBuffer.wrap(bytes).getShort();
    }

    public static byte[] longToBytes(long value) {
        return ByteBuffer.allocate(LONG_SIZE).putLong(value).array();
    }

    public static long bytesToLong(byte[] bytes) {
        return ByteBuffer.wrap(bytes).getLong();
    }

    public static byte[] floatToBytes(float value) {
        return ByteBuffer.allocate(FLOAT_SIZE).putFloat(value).array();
    }

    public static float bytesToFloat(byte[] bytes) {
        return ByteBuffer.wrap(bytes).getFloat();
    }

    public static byte[] doubleToBytes(double value) {
        return ByteBuffer.allocate(DOUBLE_SIZE).putDouble(value).array();
    }

    public static double bytesToDouble(byte[] bytes) {
        return ByteBuffer.wrap(bytes).getDouble();
    }

    public static boolean compareByteArrays(byte[] array1, byte[] array2) {
        return Arrays.equals(array1, array2);
    }

    public static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xFF & b);
            if (hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    public static byte[] stringToUtf8Bytes(String str) {
        return str.getBytes(StandardCharsets.UTF_8);
    }

    public static String utf8BytesToString(byte[] bytes) {
        return new String(bytes, StandardCharsets.UTF_8);
    }

    public static byte[] xorBytes(byte[] bytes1, byte[] bytes2) {
        int length = Math.min(bytes1.length, bytes2.length);
        byte[] result = new byte[length];
        for (int i = 0; i < length; i++) {
            result[i] = (byte) (bytes1[i] ^ bytes2[i]);
        }
        return result;
    }

    public static byte[] flattenByteArray(byte[][] arrays) {
        int totalLength = 0;
        for (byte[] array : arrays) {
            totalLength += array.length;
        }
        byte[] flatArray = new byte[totalLength];
        int currentIndex = 0;
        for (byte[] array : arrays) {
            System.arraycopy(array, 0, flatArray, currentIndex, array.length);
            currentIndex += array.length;
        }
        return flatArray;
    }
}

public class QueryParserTokenManager implements QueryParserConstants {
    private char currentChar;
    private int currentPosition;
    private String matchedToken;
    private InputStream inputStream;
    private boolean debug;

    public QueryParserTokenManager(InputStream inputStream) {
        this.inputStream = inputStream;
        this.currentPosition = 0;
        this.debug = false;
    }

    public void setDebug(boolean debug) {
        this.debug = debug;
    }

    private void readChar() throws IOException {
        currentChar = (char) inputStream.read();
        currentPosition++;
        if (debug) {
            System.out.println("Read char: " + currentChar + " at position: " + currentPosition);
        }
    }

    public String nextToken() throws IOException {
        matchedToken = "";
        while (currentChar != -1) {
            if (Character.isWhitespace(currentChar)) {
                readChar();
                continue;
            }
            if (isTokenStart(currentChar)) {
                matchedToken += currentChar;
                readChar();
                while (isTokenPart(currentChar)) {
                    matchedToken += currentChar;
                    readChar();
                }
                return matchedToken;
            }
            throw new RuntimeException("Unexpected character: " + currentChar);
        }
        return null;
    }

    private boolean isTokenStart(char c) {
        return Character.isLetter(c);
    }

    private boolean isTokenPart(char c) {
        return Character.isLetterOrDigit(c) || c == '_';
    }

    public void reset() throws IOException {
        inputStream.reset();
        currentPosition = 0;
        readChar();
    }
}

