    }

    @Test
    public void testMultiRun() throws Exception {
        runTest("input/multiRun1.txt", "output/multiRun1");
        runTest("input/multiRun2.txt", "output/multiRun2");
    }

    private void runTest(String inputPath, String outputPath) throws Exception {
        Configuration conf = new Configuration();
        Job job = Job.getInstance(conf, "TF-IDF Calculation");
        job.setJarByClass(TfIdfIT.class);
        job.setMapperClass(TfIdfMapper.class);
        job.setReducerClass(TfIdfReducer.class);
        job.setOutputKeyClass(Text.class);
        job.setOutputValueClass(Text.class);
        job.setOutputFormatClass(TextOutputFormat.class);

        FileInputFormat.addInputPath(job, new Path(inputPath));
        FileOutputFormat.setOutputPath(job, new Path(outputPath));

        if (job.waitForCompletion(true)) {
            verifyResults(outputPath);
        } else {
            throw new IOException("Job failed");
        }
    }

    private void verifyResults(String outputPath) throws IOException {
        Map<String, Double> expectedResults = new HashMap<>();
        // Populate expectedResults with expected TF-IDF values

        Files.lines(Paths.get(outputPath + "/part-r-00000")).forEach(line -> {
            String[] parts = line.split("\t");
            String term = parts[0];
            double tfidfValue = Double.parseDouble(parts[1]);
            Assert.assertTrue(expectedResults.containsKey(term));
            Assert.assertEquals(expectedResults.get(term), tfidfValue, 0.001);
        });
    }

    private void cleanUp() {
        File tempDir = new File(TEMP_DIR);
        if (tempDir.exists()) {
            for (File file : tempDir.listFiles()) {
                file.delete();
            }
            tempDir.delete();
        }
    }
}

