public class StatusTransformer {
    private HttpServletResponse response;
    private String mode;

    public StatusTransformer(HttpServletResponse response, String mode) {
        this.response = response;
        this.mode = mode;
    }

    public void setContentType() {
        if ("xml".equalsIgnoreCase(mode)) {
            response.setContentType("application/xml");
        } else {
            response.setContentType("text/html");
        }
    }

    public void writeHeader() {
        PrintWriter writer = getWriter();
        if ("xml".equalsIgnoreCase(mode)) {
            writer.println("<status>");
        } else {
            writer.println("<html><head><title>Status</title></head><body>");
        }
    }

    public void writeBody() {
        PrintWriter writer = getWriter();
        writer.println("<body>");
        writer.println("<memory>" + formatSize(Runtime.getRuntime().totalMemory()) + "</memory>");
        writer.println("<threads>" + Thread.activeCount() + "</threads>");
        writer.println("<os>" + System.getProperty("os.name") + "</os>");
        writer.println("<jvm>" + System.getProperty("java.version") + "</jvm>");
        writer.println("</body>");
    }

    public void writeFooter() {
        PrintWriter writer = getWriter();
        if ("xml".equalsIgnoreCase(mode)) {
            writer.println("</status>");
        } else {
            writer.println("</body></html>");
        }
    }

    public void writeDetailedInfo() {
        PrintWriter writer = getWriter();
        writer.println("<details>");
        writer.println("<uptime>" + formatTime(System.currentTimeMillis()) + "</uptime>");
        writer.println("</details>");
    }

    private PrintWriter getWriter() {
        try {
            return response.getWriter();
        } catch (Exception e) {
            throw new RuntimeException("Error getting writer", e);
        }
    }

    private String formatSize(long size) {
        return size + " bytes";
    }

    private String formatTime(long time) {
        return time + " ms";
    }

    public void generateResponse() {
        setContentType();
        writeHeader();
        writeBody();
        writeDetailedInfo();
        writeFooter();
    }
}

