public class FaultRouteTest extends CamelTestSupport {

    @Override
    protected void setUp() throws Exception {
        super.setUp();
        // Setup mock endpoints
        getMockEndpoint("mock:a").expectedMessageCount(1);
        getMockEndpoint("mock:b").expectedMessageCount(1);
        getMockEndpoint("mock:c").expectedMessageCount(0);
        getMockEndpoint("mock:err").expectedMessageCount(0);
    }

    @Override
    protected RouteBuilder createRouteBuilder() {
        return new RouteBuilder() {
            @Override
            public void configure() {
                onException(Exception.class)
                    .to("mock:err");

                from("direct:start")
                    .to("mock:a")
                    .process(exchange -> {
                        // Simulate processing
                    })
                    .to("mock:b")
                    .process(exchange -> {
                        // Simulate processing
                    })
                    .to("mock:c");
            }
        };
    }

    @Test
    public void testWithOut() throws Exception {
        template.sendBody("direct:start", "Test Message");
        assertMockEndpointsSatisfied();
    }

    @Test
    public void testWithFault() throws Exception {
        getMockEndpoint("mock:a").whenAnyExchangeReceived(exchange -> {
            throw new RuntimeException("Simulated Fault");
        });

        template.sendBody("direct:start", "Test Message");
        assertMockEndpointsSatisfied();
    }

    @Test
    public void testWithThrowFaultMessage() throws Exception {
        throwFaultTest("mock:a", "Simulated Fault Message");
    }

    @Test
    public void testWithThrowFaultException() throws Exception {
        throwFaultTest("mock:a", new RuntimeException("Simulated Fault Exception"));
    }

    @Test
    public void testWithThrowFaultMessageUnhandled() throws Exception {
        getMockEndpoint("mock:a").whenAnyExchangeReceived(exchange -> {
            throw new IllegalArgumentException("Unhandled Fault");
        });

        template.sendBody("direct:start", "Test Message");
        assertMockEndpointsSatisfied();
    }

    @Test
    public void testWithHandleFaultMessage() throws Exception {
        getMockEndpoint("mock:a").whenAnyExchangeReceived(exchange -> {
            throw new Exception("Handled Fault");
        });

        template.sendBody("direct:start", "Test Message");
        assertMockEndpointsSatisfied();
    }

    private void throwFaultTest(String endpoint, Object fault) throws Exception {
        getMockEndpoint(endpoint).whenAnyExchangeReceived(exchange -> {
            if (fault instanceof String) {
                throw new RuntimeException((String) fault);
            } else if (fault instanceof Exception) {
                throw (Exception) fault;
            }
        });

        template.sendBody("direct:start", "Test Message");
        assertMockEndpointsSatisfied();
    }
}

