public class Metadata extends AbstractMetadataElement {
    private static final Logger LOGGER = Logger.getLogger(Metadata.class.getName());
    private Map<String, Schema> schemas = new HashMap<>();

    public void parse(XMLStreamReader xmlStreamReader) {
        try {
            while (xmlStreamReader.hasNext()) {
                int event = xmlStreamReader.next();
                if (event == XMLStreamReader.START_ELEMENT) {
                    String localName = xmlStreamReader.getLocalName();
                    if ("Schema".equals(localName)) {
                        addSchema(xmlStreamReader);
                    }
                }
            }
        } catch (XMLStreamException e) {
            LOGGER.log(Level.SEVERE, "Error parsing XML", e);
        }
    }

    private void addSchema(XMLStreamReader xmlStreamReader) throws XMLStreamException {
        String schemaName = xmlStreamReader.getAttributeValue(null, "Name");
        Schema schema = new Schema(schemaName);
        schemas.put(schemaName, schema);
        while (xmlStreamReader.hasNext()) {
            int event = xmlStreamReader.next();
            if (event == XMLStreamReader.END_ELEMENT && "Schema".equals(xmlStreamReader.getLocalName())) {
                break;
            }
            if (event == XMLStreamReader.START_ELEMENT && "EntityType".equals(xmlStreamReader.getLocalName())) {
                schema.addEntityType(xmlStreamReader);
            }
        }
    }

    public EntitySet getEntitySet(String name) {
        for (Schema schema : schemas.values()) {
            EntitySet entitySet = schema.getEntitySet(name);
            if (entitySet != null) {
                return entitySet;
            }
        }
        return null;
    }

    public NavigationProperty getNavigationProperty(String entityTypeName, String propertyName) {
        for (Schema schema : schemas.values()) {
            NavigationProperty navigationProperty = schema.getNavigationProperty(entityTypeName, propertyName);
            if (navigationProperty != null) {
                return navigationProperty;
            }
        }
        return null;
    }
}

class SecurePackageResourceGuardTest {

    private SecurePackageResourceGuard guard = new SecurePackageResourceGuard();

    @Test
    public void testAcceptGifFile() {
        assertTrue(guard.accept("images/picture.gif"));
    }

    @Test
    public void testRejectNonGifFile() {
        assertFalse(guard.accept("images/picture.png"));
    }

    @Test
    public void testAcceptAbsoluteGifPath() {
        assertTrue(guard.acceptAbsolutePath("/absolute/path/to/images/picture.gif"));
    }

    @Test
    public void testRejectAbsoluteNonGifPath() {
        assertFalse(guard.acceptAbsolutePath("/absolute/path/to/images/picture.png"));
    }

    @Test
    public void testAcceptGifInSubdirectory() {
        assertTrue(guard.accept("images/subdir/picture.gif"));
    }

    @Test
    public void testRejectNonGifInSubdirectory() {
        assertFalse(guard.accept("images/subdir/picture.jpg"));
    }

    @Test
    public void testAcceptGifWithComplexPattern() {
        guard.addPattern("images/**/*.gif");
        assertTrue(guard.accept("images/complex/path/picture.gif"));
    }

    @Test
    public void testRejectNonGifWithComplexPattern() {
        guard.addPattern("images/**/*.gif");
        assertFalse(guard.accept("images/complex/path/picture.bmp"));
    }

    @Test
    public void testRejectPathNotInRoot() {
        guard.setRootResourceAccess(false);
        assertFalse(guard.accept("images/picture.gif"));
    }

    @Test
    public void testAcceptPathInRoot() {
        guard.setRootResourceAccess(true);
        assertTrue(guard.accept("images/picture.gif"));
    }
}

