public class SortedColumnReaderTest {
    private File testDir;

    @Before
    public void setUp() throws IOException {
        testDir = new File("testDir");
        if (!testDir.exists()) {
            testDir.mkdir();
        }
        createTestFiles();
    }

    @After
    public void tearDown() throws IOException {
        for (File file : testDir.listFiles()) {
            file.delete();
        }
        testDir.delete();
    }

    @Test
    public void testReadStringColumn() throws IOException {
        List<String> result = SortedColumnReader.readColumn(testDir.getPath() + "/stringFile.txt", 0);
        assertEquals("Expected string value", "testString", result.get(0));
    }

    @Test
    public void testReadIntegerColumn() throws IOException {
        List<Integer> result = SortedColumnReader.readColumn(testDir.getPath() + "/intFile.txt", 0);
        assertEquals("Expected integer value", Integer.valueOf(42), result.get(0));
    }

    @Test
    public void testReadDoubleColumn() throws IOException {
        List<Double> result = SortedColumnReader.readColumn(testDir.getPath() + "/doubleFile.txt", 0);
        assertEquals("Expected double value", Double.valueOf(3.14), result.get(0));
    }

    private void createTestFiles() throws IOException {
        createStringFile();
        createIntegerFile();
        createDoubleFile();
    }

    private void createStringFile() throws IOException {
        Files.write(Paths.get(testDir.getPath() + "/stringFile.txt"), "testString\n".getBytes());
    }

    private void createIntegerFile() throws IOException {
        Files.write(Paths.get(testDir.getPath() + "/intFile.txt"), "42\n".getBytes());
    }

    private void createDoubleFile() throws IOException {
        Files.write(Paths.get(testDir.getPath() + "/doubleFile.txt"), "3.14\n".getBytes());
    }

    @Test
    public void testEmptyDirectory() throws IOException {
        tearDown();
        assertEquals(0, SortedColumnReader.readColumn(testDir.getPath(), 0).size());
    }

    @Test
    public void testEmptyFile() throws IOException {
        Files.write(Paths.get(testDir.getPath() + "/emptyFile.txt"), "".getBytes());
        assertEquals(0, SortedColumnReader.readColumn(testDir.getPath() + "/emptyFile.txt", 0).size());
    }
}

