public class ExpressionResult implements Comparable<ExpressionResult> {
    private Object value;
    private List<ExpressionResult> results;

    public ExpressionResult(Object value) {
        this.value = value;
        this.results = new ArrayList<>();
    }

    public void addResult(ExpressionResult result) {
        results.add(result);
    }

    public Integer toInteger() throws FilterIllegalMemberException {
        if (value instanceof Integer) {
            return (Integer) value;
        }
        throw new FilterIllegalMemberException("Cannot convert to Integer");
    }

    public Short toShort() throws FilterIllegalMemberException {
        if (value instanceof Short) {
            return (Short) value;
        }
        throw new FilterIllegalMemberException("Cannot convert to Short");
    }

    public String toStringValue() throws FilterIllegalMemberException {
        if (value instanceof String) {
            return (String) value;
        }
        throw new FilterIllegalMemberException("Cannot convert to String");
    }

    public Double toDouble() throws FilterIllegalMemberException {
        if (value instanceof Double) {
            return (Double) value;
        }
        throw new FilterIllegalMemberException("Cannot convert to Double");
    }

    public Long toLong() throws FilterIllegalMemberException {
        if (value instanceof Long) {
            return (Long) value;
        }
        throw new FilterIllegalMemberException("Cannot convert to Long");
    }

    public BigDecimal toBigDecimal() throws FilterIllegalMemberException {
        if (value instanceof BigDecimal) {
            return (BigDecimal) value;
        }
        throw new FilterIllegalMemberException("Cannot convert to BigDecimal");
    }

    public Boolean toBoolean() throws FilterIllegalMemberException {
        if (value instanceof Boolean) {
            return (Boolean) value;
        }
        throw new FilterIllegalMemberException("Cannot convert to Boolean");
    }

    public boolean isNull() {
        return value == null;
    }

    @Override
    public int compareTo(ExpressionResult other) {
        if (this.value instanceof Comparable && other.value instanceof Comparable) {
            return ((Comparable) this.value).compareTo(other.value);
        }
        throw new ClassCastException("Cannot compare values");
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof ExpressionResult)) return false;
        ExpressionResult other = (ExpressionResult) obj;
        return value != null ? value.equals(other.value) : other.value == null;
    }

    @Override
    public int hashCode() {
        return value != null ? value.hashCode() : 0;
    }
}

class FilterIllegalMemberException extends Exception {
    public FilterIllegalMemberException(String message) {
        super(message);
    }
}

