public class WebRuleSet extends RuleSetBase {
    private String prefix;
    private boolean isFragment;

    public WebRuleSet(String prefix, boolean isFragment) {
        this.prefix = prefix;
        this.isFragment = isFragment;
    }

    public void addRuleInstances(Digester digester) {
        // Add rules for error pages
        digester.addObjectCreate(prefix + "error-page", "com.example.ErrorPage");
        digester.addSetProperties(prefix + "error-page");
        digester.addSetNext(prefix + "error-page", "addErrorPage");

        // Add rules for filters
        digester.addObjectCreate(prefix + "filter", "com.example.Filter");
        digester.addSetProperties(prefix + "filter");
        digester.addSetNext(prefix + "filter", "addFilter");

        // Add rules for servlets
        digester.addObjectCreate(prefix + "servlet", "com.example.Servlet");
        digester.addSetProperties(prefix + "servlet");
        digester.addSetNext(prefix + "servlet", "addServlet");

        // Add rules for security constraints
        digester.addObjectCreate(prefix + "security-constraint", "com.example.SecurityConstraint");
        digester.addSetProperties(prefix + "security-constraint");
