public class DbAttributeTableModel extends CayenneTableModel {
    private DbEntity dbEntity;
    private List<DbAttribute> attributes;

    public DbAttributeTableModel(DbEntity dbEntity) {
        this.dbEntity = dbEntity;
        this.attributes = new ArrayList<>(dbEntity.getAttributes());
    }

    @Override
    public int getRowCount() {
        return attributes.size();
    }

    @Override
    public int getColumnCount() {
        return 7; // Name, Type, PK, Mandatory, Max Length, Scale, Comments
    }

    @Override
    public String getColumnName(int columnIndex) {
        switch (columnIndex) {
            case 0: return "Name";
            case 1: return "Type";
            case 2: return "Primary Key";
            case 3: return "Mandatory";
            case 4: return "Max Length";
            case 5: return "Scale";
            case 6: return "Comments";
            default: return "";
        }
    }

    @Override
    public Class<?> getColumnClass(int columnIndex) {
        switch (columnIndex) {
            case 0: return String.class;
            case 1: return String.class;
            case 2: return Boolean.class;
            case 3: return Boolean.class;
            case 4: return Integer.class;
            case 5: return Integer.class;
            case 6: return String.class;
            default: return Object.class;
        }
    }

    @Override
    public Object getValueAt(int rowIndex, int columnIndex) {
        DbAttribute attribute = attributes.get(rowIndex);
        switch (columnIndex) {
            case 0: return attribute.getName();
            case 1: return attribute.getType();
            case 2: return attribute.isPrimaryKey();
            case 3: return attribute.isMandatory();
            case 4: return attribute.getMaxLength();
            case 5: return attribute.getScale();
            case 6: return attribute.getComment();
            default: return null;
        }
    }

    @Override
    public void setValueAt(Object aValue, int rowIndex, int columnIndex) {
        DbAttribute attribute = attributes.get(rowIndex);
        switch (columnIndex) {
            case 0: attribute.setName((String) aValue); break;
            case 1: attribute.setType((String) aValue); break;
            case 2: attribute.setPrimaryKey((Boolean) aValue); break;
            case 3: attribute.setMandatory((Boolean) aValue); break;
            case 4: attribute.setMaxLength((Integer) aValue); break;
            case 5: attribute.setScale((Integer) aValue); break;
            case 6: attribute.setComment((String) aValue); break;
        }
        fireTableCellUpdated(rowIndex, columnIndex);
    }

    public void sortByName() {
        attributes.sort(Comparator.comparing(DbAttribute::getName));
        fireTableDataChanged();
    }

    public void sortByType() {
        attributes.sort(Comparator.comparing(DbAttribute::getType));
        fireTableDataChanged();
    }

    public void sortByPrimaryKey() {
        attributes.sort(Comparator.comparing(DbAttribute::isPrimaryKey));
        fireTableDataChanged();
    }

    public void sortByMandatory() {
        attributes.sort(Comparator.comparing(DbAttribute::isMandatory));
        fireTableDataChanged();
    }
}

