public class JsonReaderImplTest {

    private JsonReader jsonReader = new JsonReaderImpl(); // Assuming JsonReaderImpl is your implementation

    @Test
    public void testReadSimpleJsonObject() {
        String json = "{\"name\":\"John\", \"age\":30}";
        JsonObject result = jsonReader.read(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
        assertEquals("John", result.getString("name"));
        assertEquals(30, result.getInt("age"));
    }

    @Test
    public void testReadJsonArray() {
        String json = "[{\"name\":\"John\"}, {\"name\":\"Jane\"}]";
        JsonArray result = jsonReader.read(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
        assertEquals(2, result.size());
        assertEquals("John", result.getJsonObject(0).getString("name"));
        assertEquals("Jane", result.getJsonObject(1).getString("name"));
    }

    @Test
    public void testReadJsonWithUnicodeCharacters() {
        String json = "{\"message\":\"Hello, 世界\"}";
        JsonObject result = jsonReader.read(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
        assertEquals("Hello, 世界", result.getString("message"));
    }

    @Test
    public void testReadInvalidJson() {
        String json = "{\"name\":\"John\", \"age\":30,}";
        assertThrows(JsonParseException.class, () -> {
            jsonReader.read(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
        });
    }

    @Test
    public void testReadJsonWithSpecialCharacters() {
        String json = "{\"message\":\"Hello\\nWorld!\"}";
        JsonObject result = jsonReader.read(new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8)));
        assertEquals("Hello\nWorld!", result.getString("message"));
    }

    @Test
    public void testReadLargeJsonFile() {
        StringBuilder jsonBuilder = new StringBuilder("[");
        for (int i = 0; i < 1000; i++) {
            jsonBuilder.append("{\"index\":").append(i).append("},");
        }
        jsonBuilder.setLength(jsonBuilder.length() - 1); // Remove last comma
        jsonBuilder.append("]");

        JsonArray result = jsonReader.read(new ByteArrayInputStream(jsonBuilder.toString().getBytes(StandardCharsets.UTF_8)));
        assertEquals(1000, result.size());
    }

    @Test
    public void testReadJsonWithDifferentBufferSizes() {
        String json = "{\"name\":\"John\", \"age\":30}";
        byte[] jsonBytes = json.getBytes(StandardCharsets.UTF_8);

        for (int bufferSize : new int[]{10, 20, 30}) {
            InputStream inputStream = new ByteArrayInputStream(jsonBytes);
            JsonObject result = jsonReader.read(inputStream);
            assertEquals("John", result.getString("name"));
            assertEquals(30, result.getInt("age"));
        }
    }
}

