    private String ldapUrl;
    private String searchBase;
    private String userDn;
    private String password;
    private String roleAttribute;
    private String adminRole;
    private String readRole;
    private String writeRole;

    public LDAPAuthorizationMap(String ldapUrl, String searchBase, String userDn, String password) {
        this.ldapUrl = ldapUrl;
        this.searchBase = searchBase;
        this.userDn = userDn;
        this.password = password;
    }

    public void setRoleAttribute(String roleAttribute) {
        this.roleAttribute = roleAttribute;
    }

    public void setAdminRole(String adminRole) {
        this.adminRole = adminRole;
    }

    public void setReadRole(String readRole) {
        this.readRole = readRole;
    }

    public void setWriteRole(String writeRole) {
        this.writeRole = writeRole;
    }

    public List<String> getACLs(String destination) {
        // Implementation to retrieve ACLs from LDAP
        return null; // Placeholder for actual implementation
    }

    public boolean isAdmin(String user) {
        return hasRole(user, adminRole);
    }

    public boolean canRead(String user, String destination) {
        return hasRole(user, readRole);
    }

    public boolean canWrite(String user, String destination) {
        return hasRole(user, writeRole);
    }

    private boolean hasRole(String user, String role) {
        try {
            DirContext ctx = openLDAPContext();
            String searchFilter = String.format("(&(objectClass=person)(uid=%s)(%s=%s))", user, roleAttribute, role);
            SearchControls searchControls = new SearchControls();
            searchControls.setSearchScope(SearchControls.SUBTREE_SCOPE);
            SearchResult result = ctx.search(searchBase, searchFilter, searchControls).next();
            ctx.close();
            return result != null;
        } catch (Exception e) {
            // Handle exceptions (e.g., logging)
            return false;
        }
    }

    private DirContext openLDAPContext() throws Exception {
        Hashtable<String, String> env = new Hashtable<>();
        env.put("java.naming.factory.initial", "com.sun.jndi.ldap.LdapCtxFactory");
        env.put("java.naming.provider.url", ldapUrl);
        env.put("java.naming.security.principal", userDn);
        env.put("java.naming.security.credentials", password);
        return new InitialDirContext(env);
    }
}

public class EigenDecompositionTest {

    private EigenDecomposition eigenDecomposition;

    @BeforeEach
    public void setUp() {
        eigenDecomposition = new EigenDecomposition();
    }

    @AfterEach
    public void tearDown() {
        eigenDecomposition = null;
    }

    @Test
    public void testEigenDecomposition1x1() {
        double[][] matrix = {{4}};
        double[] expectedEigenvalues = {4};
        double[][] expectedEigenvectors = {{1}};

        eigenDecomposition.decompose(matrix);
        assertArrayEquals(expectedEigenvalues, eigenDecomposition.getEigenvalues(), 1e-10);
        assertArrayEquals(expectedEigenvectors, eigenDecomposition.getEigenvectors());
    }

    @Test
    public void testEigenDecomposition2x2Distinct() {
        double[][] matrix = {{4, 2}, {1, 3}};
        double[] expectedEigenvalues = {5, 2};
        double[][] expectedEigenvectors = {{0.894427, -0.707107}, {0.447214, 0.707107}};

        eigenDecomposition.decompose(matrix);
        assertArrayEquals(expectedEigenvalues, eigenDecomposition.getEigenvalues(), 1e-10);
        assertArrayEquals(expectedEigenvectors, eigenDecomposition.getEigenvectors(), 1e-6);
    }

    @Test
    public void testEigenDecomposition3x3Repeated() {
        double[][] matrix = {{2, 1, 0}, {1, 2, 1}, {0, 1, 2}};
        double[] expectedEigenvalues = {3, 2, 1};
        double[][] expectedEigenvectors = {
            {0.57735, -0.57735, 0.57735},
            {0.57735, 0.57735, -0.57735},
            {0.57735, 0.57735, 0.57735}
        };

        eigenDecomposition.decompose(matrix);
        assertArrayEquals(expectedEigenvalues, eigenDecomposition.getEigenvalues(), 1e-10);
        assertArrayEquals(expectedEigenvectors, eigenDecomposition.getEigenvectors(), 1e-5);
    }

    @Test
    public void testEigenDecomposition4x4Symmetric() {
        double[][] matrix = {
            {6, 2, 1, 0},
            {2, 6, 2, 1},
            {1, 2, 6, 2},
            {0, 1, 2, 6}
        };
        double[] expectedEigenvalues = {8, 6, 4, 4};
        double[][] expectedEigenvectors = {
            {0.5, -0.5, 0.5, 0.5},
            {0.5, 0.5, -0.5, -0.5},
            {0.5, 0.5, 0.5, -0.5},
            {0.5, 0.5, 0.5, 0.5}
        };

        eigenDecomposition.decompose(matrix);
        assertArrayEquals(expectedEigenvalues, eigenDecomposition.getEigenvalues(), 1e-10);
        assertArrayEquals(expectedEigenvectors, eigenDecomposition.getEigenvectors(), 1e-5);
    }

    @Test
    public void testEigenDecompositionPositiveDefinite() {
        double[][] matrix = {
            {2, -1, 0},
            {-1, 2, -1},
            {0, -1, 2}
        };
        double[] expectedEigenvalues = {3, 2, 1};
        double[][] expectedEigenvectors = {
            {0.57735, -0.57735, 0.57735},
            {0.57735, 0.57735, -0.57735},
            {0.57735, 0.57735, 0.57735}
        };

        eigenDecomposition.decompose(matrix);
        assertArrayEquals(expectedEigenvalues, eigenDecomposition.getEigenvalues(), 1e-10);
        assertArrayEquals(expectedEigenvectors, eigenDecomposition.getEigenvectors(), 1e-5);
    }

    private boolean isSymmetric(double[][] matrix) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] != matrix[j][i]) {
                    return false;
                }
            }
        }
        return true;
    }
}

