public class StarVertex extends StarElement implements Vertex {
    private Set<Edge> outgoingEdges;
    private Set<Edge> incomingEdges;
    private Map<String, Object> properties;

    public StarVertex() {
        this.outgoingEdges = new HashSet<>();
        this.incomingEdges = new HashSet<>();
        this.properties = new HashMap<>();
    }

    @Override
    public void addOutgoingEdge(Edge edge) {
        outgoingEdges.add(edge);
    }

    @Override
    public void addIncomingEdge(Edge edge) {
        incomingEdges.add(edge);
    }

    public void dropEdge(Edge edge, Direction direction) {
        if (direction == Direction.OUTGOING) {
            outgoingEdges.remove(edge);
        } else if (direction == Direction.INCOMING) {
            incomingEdges.remove(edge);
        }
    }

    public void dropEdge(Edge edge) {
        outgoingEdges.remove(edge);
        incomingEdges.remove(edge);
    }

    public void setProperty(String key, Object value) {
        properties.put(key, value);
    }

    public Object getProperty(String key) {
        return properties.get(key);
    }

    public Set<Edge> filterEdges(GraphFilter filter) {
        Set<Edge> filteredEdges = new HashSet<>();
        for (Edge edge : outgoingEdges) {
            if (filter.accept(edge)) {
                filteredEdges.add(edge);
            }
        }
        for (Edge edge : incomingEdges) {
            if (filter.accept(edge)) {
                filteredEdges.add(edge);
            }
        }
        return filteredEdges;
    }

    @Override
    public String toString() {
        return "StarVertex{" +
                "properties=" + properties +
                '}';
    }

    // Prevent removal of the vertex from the graph
    public void remove() {
        throw new UnsupportedOperationException("Vertex cannot be removed from the graph.");
    }

    public Set<Edge> getOutgoingEdges() {
        return Collections.unmodifiableSet(outgoingEdges);
    }

    public Set<Edge> getIncomingEdges() {
        return Collections.unmodifiableSet(incomingEdges);
    }
}

