public class LinkedDeque<E> extends AbstractCollection<E> {
    private Node<E> first;
    private Node<E> last;
    private int size;

    private static class Node<E> {
        E item;
        Node<E> next;
        Node<E> prev;

        Node(E item) {
            this.item = item;
        }
    }

    public LinkedDeque() {
        first = null;
        last = null;
        size = 0;
    }

    public void addFirst(E e) {
        Node<E> newNode = new Node<>(e);
        if (first == null) {
            first = last = newNode;
        } else {
            newNode.next = first;
            first.prev = newNode;
            first = newNode;
        }
        size++;
    }

    public void addLast(E e) {
        Node<E> newNode = new Node<>(e);
        if (last == null) {
            first = last = newNode;
        } else {
            newNode.prev = last;
            last.next = newNode;
            last = newNode;
        }
        size++;
    }

    public E removeFirst() {
        if (first == null) throw new NoSuchElementException();
        E item = first.item;
        first = first.next;
        if (first == null) last = null;
        else first.prev = null;
        size--;
        return item;
    }

    public E removeLast() {
        if (last == null) throw new NoSuchElementException();
        E item = last.item;
        last = last.prev;
        if (last == null) first = null;
        else last.next = null;
        size--;
        return item;
    }

    public E peekFirst() {
        if (first == null) return null;
        return first.item;
    }

    public E peekLast() {
        if (last == null) return null;
        return last.item;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
    }

    public void clear() {
        first = last = null;
        size = 0;
    }

    @Override
    public Iterator<E> iterator() {
        return new Iterator<E>() {
            private Node<E> current = first;

            public boolean hasNext() {
                return current != null;
            }

            public E next() {
                if (!hasNext()) throw new NoSuchElementException();
                E item = current.item;
                current = current.next;
                return item;
            }
        };
    }

    public Iterator<E> reverseIterator() {
        return new Iterator<E>() {
            private Node<E> current = last;

            public boolean hasNext() {
                return current != null;
            }

            public E next() {
                if (!hasNext()) throw new NoSuchElementException();
                E item = current.item;
                current = current.prev;
                return item;
            }
        };
    }
}

