public class Terminal {
    private final int width;
    private final int height;
    private final char[][] screen;
    private int cursorX;
    private int cursorY;
    private boolean insertMode;
    private boolean lineWrap;

    public Terminal(int width, int height) {
        this.width = width;
        this.height = height;
        this.screen = new char[height][width];
        for (char[] row : screen) {
            Arrays.fill(row, ' ');
        }
        this.cursorX = 0;
        this.cursorY = 0;
        this.insertMode = false;
        this.lineWrap = true;
    }

    public void write(String input) {
        for (char c : input.toCharArray()) {
            processCharacter(c);
        }
    }

    private void processCharacter(char c) {
        if (c == '\n') {
            cursorY++;
            if (lineWrap && cursorY >= height) {
                scrollUp();
            }
            cursorX = 0;
        } else if (c == '\r') {
            cursorX = 0;
        } else if (c == '\b') {
            moveCursor(-1, 0);
            if (cursorX < 0) {
                cursorX = 0;
            }
            if (insertMode) {
                screen[cursorY][cursorX] = ' ';
            }
        } else if (c == '\033') {
            // Handle escape sequences here
        } else {
            insertCharacter(c);
        }
    }

    private void insertCharacter(char c) {
        if (insertMode) {
            for (int i = width - 1; i > cursorX; i--) {
                screen[cursorY][i] = screen[cursorY][i - 1];
            }
        }
        screen[cursorY][cursorX] = c;
        moveCursor(1, 0);
    }

    private void moveCursor(int dx, int dy) {
        cursorX += dx;
        cursorY += dy;
        if (cursorX >= width) {
            cursorX = lineWrap ? 0 : width - 1;
            cursorY++;
        }
        if (cursorY >= height) {
            cursorY = height - 1;
            scrollUp();
        }
    }

    private void scrollUp() {
        for (int i = 1; i < height; i++) {
            screen[i - 1] = screen[i];
        }
        Arrays.fill(screen[height - 1], ' ');
    }

    public String readOutput() {
        StringBuilder output = new StringBuilder();
        for (char[] row : screen) {
            output.append(row);
            output.append('\n');
        }
        return output.toString();
    }

    public void setInsertMode(boolean insertMode) {
        this.insertMode = insertMode;
    }

    public void setLineWrap(boolean lineWrap) {
        this.lineWrap = lineWrap;
    }

    public void clearScreen() {
        for (char[] row : screen) {
            Arrays.fill(row, ' ');
        }
        cursorX = 0;
        cursorY = 0;
    }
}

public abstract class JcaCipherService implements CipherService {
    private static final Logger logger = LoggerFactory.getLogger(JcaCipherService.class);
    private int keySize;
    private int ivSize;
    private int bufferSize;
    private SecureRandom secureRandom;

    public JcaCipherService(int keySize, int ivSize, int bufferSize) {
        this.keySize = keySize;
        this.ivSize = ivSize;
        this.bufferSize = bufferSize;
        this.secureRandom = new SecureRandom();
    }

    protected abstract String getAlgorithm();

    public byte[] encrypt(byte[] data, byte[] key) {
        try {
            Cipher cipher = Cipher.getInstance(getAlgorithm());
            SecretKeySpec secretKey = new SecretKeySpec(key, "AES");
            byte[] iv = generateIv();
            AlgorithmParameterSpec paramSpec = new IvParameterSpec(iv);
            cipher.init(Cipher.ENCRYPT_MODE, secretKey, paramSpec);
            byte[] encryptedData = cipher.doFinal(data);
            logger.info("Encryption successful");
            return encryptedData;
        } catch (Exception e) {
            logger.error("Encryption failed", e);
            throw new RuntimeException("Encryption failed", e);
        }
    }

    public byte[] decrypt(byte[] encryptedData, byte[] key, byte[] iv) {
        try {
            Cipher cipher = Cipher.getInstance(getAlgorithm());
            SecretKeySpec secretKey = new SecretKeySpec(key, "AES");
            AlgorithmParameterSpec paramSpec = new IvParameterSpec(iv);
            cipher.init(Cipher.DECRYPT_MODE, secretKey, paramSpec);
            byte[] decryptedData = cipher.doFinal(encryptedData);
            logger.info("Decryption successful");
            return decryptedData;
        } catch (Exception e) {
            logger.error("Decryption failed", e);
            throw new RuntimeException("Decryption failed", e);
        }
    }

    private byte[] generateIv() {
        byte[] iv = new byte[ivSize];
        secureRandom.nextBytes(iv);
        return iv;
    }

    public int getKeySize() {
        return keySize;
    }

    public int getIvSize() {
        return ivSize;
    }

    public int getBufferSize() {
        return bufferSize;
    }
}

