public class DataflowPipelineJob implements PipelineResult {
    private static final Logger logger = Logger.getLogger(DataflowPipelineJob.class.getName());
    private final DataflowClient dataflowClient;
    private final String jobId;
    private JobState currentState;
    private boolean isCancelled;

    public DataflowPipelineJob(DataflowClient dataflowClient, String jobId) {
        this.dataflowClient = dataflowClient;
        this.jobId = jobId;
        this.currentState = JobState.UNKNOWN;
        this.isCancelled = false;
    }

    public void waitForCompletion() {
        while (!isCancelled && !isTerminalState(currentState)) {
            try {
                currentState = dataflowClient.getJobState(jobId);
                logger.info("Current job state: " + currentState);
                TimeUnit.SECONDS.sleep(10); // Polling interval
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                logger.warning("Job waiting interrupted");
            } catch (Exception e) {
                logger.severe("Error while polling job state: " + e.getMessage());
            }
        }
    }

    public void cancel() {
        if (!isCancelled) {
            dataflowClient.cancelJob(jobId);
            isCancelled = true;
            logger.info("Job " + jobId + " has been cancelled.");
        }
    }

    public JobState getCurrentState() {
        return currentState;
    }

    private boolean isTerminalState(JobState state) {
        return state == JobState.DONE || state == JobState.FAILED || state == JobState.CANCELLED;
    }

    public void handleJobMessages() {
        while (!isCancelled) {
            try {
                JobMessage message = dataflowClient.getJobMessage(jobId);
                if (message != null) {
                    logger.info("Job message: " + message.getText());
                }
                TimeUnit.SECONDS.sleep(5); // Polling interval for messages
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                logger.warning("Message handling interrupted");
            } catch (Exception e) {
                logger.severe("Error while retrieving job messages: " + e.getMessage());
            }
        }
    }

    public Metrics getMetrics() {
        return dataflowClient.getJobMetrics(jobId);
    }
}

