public class DefaultDistributedBuildManager implements BuildManager, Contextualizable, Initializable {
    private final Map<String, BuildQueue> buildQueues = Collections.synchronizedMap(new HashMap<>());
    private final AgentService agentService;
    private final ProjectService projectService;

    public DefaultDistributedBuildManager(AgentService agentService, ProjectService projectService) {
        this.agentService = agentService;
        this.projectService = projectService;
    }

    @Override
    public void contextualize(Context context) {
        // Contextualization logic
    }

    @Override
    public void initialize() {
        // Initialization logic
    }

    public void createBuildQueue(String agentId) {
        if (!agentService.isAgentEnabled(agentId)) {
            throw new IllegalArgumentException("Agent is not enabled: " + agentId);
        }
        buildQueues.put(agentId, new BuildQueue(agentId));
    }

    public void manageBuild(String agentId, BuildProject project) {
        BuildQueue queue = buildQueues.get(agentId);
        if (queue != null) {
            queue.addProject(project);
        } else {
            throw new IllegalStateException("No build queue found for agent: " + agentId);
        }
    }

    public void cancelBuild(String agentId, BuildProject project) {
        BuildQueue queue = buildQueues.get(agentId);
        if (queue != null) {
            queue.removeProject(project);
        } else {
            throw new IllegalStateException("No build queue found for agent: " + agentId);
        }
    }

    public BuildProject getProjectStatus(String agentId, String projectId) {
        BuildQueue queue = buildQueues.get(agentId);
        if (queue != null) {
            return queue.getProjectStatus(projectId);
        }
        return null;
    }

    public void removeBuildQueue(String agentId) {
        buildQueues.remove(agentId);
    }

    public boolean isAgentAvailable(String agentId) {
        return agentService.isAgentAvailable(agentId);
    }
}

