public class DBInterfaceHSQLDB extends Database implements IDBInterface {
    private static String dbUrl;
    private static String username;
    private static String password;
    private static Connection connection;

    public DBInterfaceHSQLDB(String dbUrl, String username, String password) {
        this.dbUrl = dbUrl;
        this.username = username;
        this.password = password;
    }

    public void connect() throws SQLException {
        if (connection == null || connection.isClosed()) {
            connection = DriverManager.getConnection(dbUrl, username, password);
        }
    }

    public void disconnect() throws SQLException {
        if (connection != null && !connection.isClosed()) {
            connection.close();
        }
    }

    public void executeUpdate(String sql) throws SQLException {
        Statement stmt = connection.createStatement();
        stmt.executeUpdate(sql);
        stmt.close();
    }

    public ResultSet executeQuery(String sql) throws SQLException {
        Statement stmt = connection.createStatement();
        return stmt.executeQuery(sql);
    }

    public void createTable(String tableName, String columns) throws SQLException {
        String sql = "CREATE TABLE " + tableName + " (" + columns + ")";
        executeUpdate(sql);
    }

    public void deleteTable(String tableName) throws SQLException {
        String sql = "DROP TABLE " + tableName;
        executeUpdate(sql);
    }

    public void beginTransaction() throws SQLException {
        connection.setAutoCommit(false);
    }

    public void commitTransaction() throws SQLException {
        connection.commit();
        connection.setAutoCommit(true);
    }

    public void rollbackTransaction() throws SQLException {
        connection.rollback();
        connection.setAutoCommit(true);
    }

    public void createUser(String username, String password) throws SQLException {
        String sql = "CREATE USER " + username + " PASSWORD '" + password + "'";
        executeUpdate(sql);
    }

    public void deleteUser(String username) throws SQLException {
        String sql = "DROP USER " + username;
        executeUpdate(sql);
    }

    public ResultSet getTableSchema(String tableName) throws SQLException {
        String sql = "SELECT * FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = '" + tableName + "'";
        return executeQuery(sql);
    }

    public ResultSet getIndexes(String tableName) throws SQLException {
        String sql = "SELECT * FROM INFORMATION_SCHEMA.INDEXES WHERE TABLE_NAME = '" + tableName + "'";
        return executeQuery(sql);
    }

    public void modifyData(String sql) throws SQLException {
        executeUpdate(sql);
    }

    public void handleException(SQLException e) {
        System.err.println("SQL Exception: " + e.getMessage());
    }
}

