public class NettyServer {
    private final int port;
    private final EventLoopGroup bossGroup;
    private final EventLoopGroup workerGroup;
    private ChannelFuture channelFuture;
    private final Set<SocketChannel> activeChannels;
    private final AtomicLong inboundByteCount;
    private final AtomicLong outboundByteCount;

    public NettyServer(int port) {
        this.port = port;
        this.bossGroup = new NioEventLoopGroup(1);
        this.workerGroup = new NioEventLoopGroup();
        this.activeChannels = ConcurrentHashMap.newKeySet();
        this.inboundByteCount = new AtomicLong();
        this.outboundByteCount = new AtomicLong();
    }

    public void start() {
        try {
            ServerBootstrap bootstrap = new ServerBootstrap();
            bootstrap.group(bossGroup, workerGroup)
                    .channel(NioServerSocketChannel.class)
                    .option(ChannelOption.SO_BACKLOG, 128)
                    .handler(new LoggingHandler(LogLevel.INFO))
                    .childHandler(new ChannelInitializer<SocketChannel>() {
                        @Override
                        protected void initChannel(SocketChannel ch) {
                            ch.pipeline().addLast(new HttpServerCodec());
                            ch.pipeline().addLast(new ChunkedWriteHandler());
                            // Add additional handlers for compression and authorization
                            // ch.pipeline().addLast(new CompressionHandler());
                            // ch.pipeline().addLast(new AuthHandler());
                            activeChannels.add(ch);
                        }
                    });

            channelFuture = bootstrap.bind(new InetSocketAddress(port)).sync();
            System.out.println("Server started on port: " + port);
            channelFuture.channel().closeFuture().addListener(future -> {
                activeChannels.forEach(SocketChannel::close);
                bossGroup.shutdownGracefully();
                workerGroup.shutdownGracefully();
            });
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Server interrupted: " + e.getMessage());
        }
    }

    public void stop() {
        if (channelFuture != null) {
            channelFuture.channel().close();
        }
        bossGroup.shutdownGracefully();
        workerGroup.shutdownGracefully();
    }

    public long getInboundByteCount() {
        return inboundByteCount.get();
    }

    public long getOutboundByteCount() {
        return outboundByteCount.get();
    }
}

