    private Map<String, Vertex> vertexCache;
    private Map<String, Edge> edgeCache;
    private int messageSizeLimit;
    private int requestCount;
    private CentralizedServiceWorker serviceWorker;

    public NettyWorkerClientRequestProcessor(int messageSizeLimit, CentralizedServiceWorker serviceWorker) {
        this.vertexCache = new HashMap<>();
        this.edgeCache = new HashMap<>();
        this.messageSizeLimit = messageSizeLimit;
        this.requestCount = 0;
        this.serviceWorker = serviceWorker;
