    public void addVertex(Vertex vertex) {
        vertexCache.put(vertex.getId(), vertex);
        incrementRequestCount();
    }

    public void removeVertex(String vertexId) {
        vertexCache.remove(vertexId);
        incrementRequestCount();
    }

    public void addEdge(Edge edge) {
        edgeCache.put(edge.getId(), edge);
        incrementRequestCount();
    }

    public void removeEdge(String edgeId) {
        edgeCache.remove(edgeId);
        incrementRequestCount();
    }

    public void flushVertices() {
        for (Vertex vertex : vertexCache.values()) {
            sendMessageToVertex(vertex);
        }
        vertexCache.clear();
    }

    public void flushEdges() {
        for (Edge edge : edgeCache.values()) {
            sendMessageToEdge(edge);
        }
        edgeCache.clear();
    }

    public void sendMessageToVertex(Vertex vertex) {
        if (calculateMessageSize(vertex) <= messageSizeLimit) {
            serviceWorker.sendMessage(vertex);
            incrementRequestCount();
        }
    }

    public void sendMessageToAllVertices(String message) {
        for (Vertex vertex : vertexCache.values()) {
            sendMessageToVertex(vertex);
        }
    }

