public class Parser {
    private String repositoryUrl;
    private String groupId;
    private String artifactId;
    private String version;
    private String type;
    private String classifier;

    public Parser(String path) {
        parsePath(path);
    }

    private void parsePath(String path) {
        // Code smells: No validation on input path, potential for ArrayIndexOutOfBoundsException
        String[] parts = path.split("/");
        if (parts.length < 5) {
            throw new IllegalArgumentException("Invalid path format");
        }
        this.repositoryUrl = parts[0];
        this.groupId = parts[1];
        this.artifactId = parts[2];
        this.version = parts[3];
        this.type = parts[4];
        if (parts.length > 5) {
            this.classifier = parts[5];
        }
    }

    public URI toUri() {
        try {
            return new URI(repositoryUrl + "/" + groupId + "/" + artifactId + "/" + version + "/" + artifactId + "-" + version + (classifier != null ? "-" + classifier : "") + "." + type);
        } catch (URISyntaxException e) {
            throw new RuntimeException("Invalid URI", e);
        }
    }

    public String getMetadataPath() {
        return repositoryUrl + "/" + groupId + "/" + artifactId + "/" + version + "/maven-metadata.xml";
    }

    public String getLocalPath() {
        return System.getProperty("user.home") + "/.m2/repository/" + groupId.replace(".", "/") + "/" + artifactId + "/" + version + "/" + artifactId + "-" + version + (classifier != null ? "-" + classifier : "") + "." + type;
    }

    public String getRemotePath() {
        return repositoryUrl + "/" + groupId.replace(".", "/") + "/" + artifactId + "/" + version + "/" + artifactId + "-" + version + (classifier != null ? "-" + classifier : "") + "." + type;
    }

    public boolean isSnapshot() {
        return version.endsWith("SNAPSHOT");
    }
}

