public class FailoverConsumerOutstandingCommitTest {

    private BrokerService broker;
    private Connection connection;
    private Session session;
    private MessageProducer producer;
    private MessageConsumer consumer;
    private ActiveMQQueue queue;
    private CountDownLatch latch;

    @Before
    public void setUp() throws Exception {
        broker = new BrokerService();
        broker.setPersistent(false);
        broker.start();

        ActiveMQConnectionFactory connectionFactory = new ActiveMQConnectionFactory("vm://localhost");
        connection = connectionFactory.createConnection();
        connection.start();

        session = connection.createSession(true, Session.SESSION_TRANSACTED);
        queue = new ActiveMQQueue("test.queue");
        producer = session.createProducer(queue);
        consumer = session.createConsumer(queue);
        latch = new CountDownLatch(1);
    }

    @After
    public void tearDown() throws Exception {
        if (producer != null) {
            producer.close();
        }
        if (consumer != null) {
            consumer.close();
        }
        if (session != null) {
            session.close();
        }
        if (connection != null) {
            connection.close();
        }
        if (broker != null) {
            broker.stop();
        }
    }

    @Test
    public void testFailoverWithOutstandingCommit() throws Exception {
        // Produce messages
        for (int i = 0; i < 10; i++) {
            TextMessage message = session.createTextMessage("Message " + i);
            producer.send(message);
        }
        session.commit();

        // Simulate broker failover
        broker.stop();
        broker.start();

        // Consume messages
        for (int i = 0; i < 10; i++) {
            latch.await(5, TimeUnit.SECONDS);
            TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
            if (receivedMessage != null) {
                assertEquals("Message " + i, receivedMessage.getText());
                session.commit();
            }
        }
    }

    @Test
    public void testRollbackOnFailover() throws Exception {
        // Produce messages
        for (int i = 0; i < 5; i++) {
            TextMessage message = session.createTextMessage("Message " + i);
            producer.send(message);
        }
        session.commit();

        // Simulate broker failover
        broker.stop();
        broker.start();

        // Attempt to consume messages
        for (int i = 0; i < 5; i++) {
            latch.await(5, TimeUnit.SECONDS);
            TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
            if (receivedMessage != null) {
                session.rollback(); // Rollback to simulate failure
            }
        }

        // Verify that messages are still available
        for (int i = 0; i < 5; i++) {
            TextMessage receivedMessage = (TextMessage) consumer.receive(1000);
            assertEquals("Message " + i, receivedMessage.getText());
            session.commit();
        }
    }
}

