        assertNotNull(realMatrix);
        assertEquals(2, realMatrix.getRowDimension());
        assertEquals(2, realMatrix.getColumnDimension());
    }

    @Test
    public void testSolveLowerTriangularSystem() {
        RealMatrix lowerTriangular = MatrixUtils.createRealMatrix(new double[][] {
            {2, 0},
            {3, 4}
        });
        double[] b = {2, 11};
        double[] solution = MatrixUtils.solve(lowerTriangular, b);
        assertNotNull(solution);
        assertEquals(2, solution.length);
        assertEquals(1.0, solution[0], 1e-10);
        assertEquals(2.0, solution[1], 1e-10);
    }

    @Test
    public void testSolveUpperTriangularSystem() {
        RealMatrix upperTriangular = MatrixUtils.createRealMatrix(new double[][] {
            {4, 2},
