public class ExpressionVerbalizer {

    private RutaVerbalizer rutaVerbalizer;

    public ExpressionVerbalizer(RutaVerbalizer rutaVerbalizer) {
        this.rutaVerbalizer = rutaVerbalizer;
    }

    public String verbalize(IRutaExpression expression) {
        if (expression instanceof GenericFeature) {
            return verbalize((GenericFeature) expression);
        } else if (expression instanceof Annotation) {
            return verbalize((Annotation) expression);
        } else if (expression instanceof Type) {
            return verbalize((Type) expression);
        } else if (expression instanceof BooleanExpression) {
            return verbalize((BooleanExpression) expression);
        } else if (expression instanceof NumberExpression) {
            return verbalize((NumberExpression) expression);
        } else if (expression instanceof ListExpression) {
            return verbalize((ListExpression) expression);
        } else {
            return expression.getClass().getSimpleName();
        }
    }

    public String verbalize(GenericFeature feature) {
