public class TarArchiveOutputStream extends ArchiveOutputStream {
    private static final int DEFAULT_BUFFER_SIZE = 1024;
    private OutputStream out;
    private TarEntry currentEntry;
    private long writtenBytes;
    private boolean closed;
    private Charset encoding;
    private int longFileMode;
    private int bigNumberMode;

    public TarArchiveOutputStream(OutputStream out) {
        this(out, Charset.defaultCharset());
    }

    public TarArchiveOutputStream(OutputStream out, Charset encoding) {
        this.out = out;
        this.encoding = encoding;
        this.longFileMode = TarConstants.LONGFILE_GNU;
        this.bigNumberMode = TarConstants.BIGNUMBER_GNU;
    }

    public void setLongFileMode(int mode) {
        this.longFileMode = mode;
    }

    public void setBigNumberMode(int mode) {
        this.bigNumberMode = mode;
    }

    public void putArchiveEntry(TarEntry entry) throws IOException {
        if (currentEntry != null) {
            closeArchiveEntry();
        }
        currentEntry = entry;
        writtenBytes = 0;
        writeEntryHeader(entry);
    }

    public void closeArchiveEntry() throws IOException {
        if (currentEntry == null) {
            throw new IOException("No current entry to close");
        }
        writeEndOfEntry();
        currentEntry = null;
    }

    public void finish() throws IOException {
        if (closed) {
            throw new IOException("Stream already closed");
        }
        if (currentEntry != null) {
            closeArchiveEntry();
        }
        writeEndOfFile();
        closed = true;
    }

    private void writeEntryHeader(TarEntry entry) throws IOException {
        // Logic to write the TAR entry header
    }

    private void writeEndOfEntry() throws IOException {
        // Logic to write the end of the current entry
    }

    private void writeEndOfFile() throws IOException {
        // Logic to write the end of the TAR archive
    }

    public void write(byte[] b, int off, int len) throws IOException {
        if (currentEntry == null) {
            throw new IOException("No current entry open");
        }
        if (writtenBytes + len > currentEntry.getSize()) {
            throw new IOException("Written bytes exceed entry size");
        }
        out.write(b, off, len);
        writtenBytes += len;
    }

    public void close() throws IOException {
        finish();
        out.close();
    }
}

