public class AclAttributeDialog extends AddEditDialog {
    private JRadioButton attributeButton;
    private JRadioButton entryButton;
    private JRadioButton childrenButton;
    private JRadioButton objectClassButton;
    private JRadioButton objectClassExclusionButton;
    private JTextField attributeValueField;
    private JButton okButton;
    private AclAttributeWrapper aclAttributeWrapper;

    public AclAttributeDialog(AclAttributeWrapper aclAttributeWrapper) {
        this.aclAttributeWrapper = aclAttributeWrapper;
        initializeDialog();
        populateFields();
        addListeners();
    }

    private void initializeDialog() {
        setTitle("Edit ACL Attribute");
        setLayout(new GridLayout(0, 1));

        attributeButton = new JRadioButton("Attribute");
        entryButton = new JRadioButton("Entry");
        childrenButton = new JRadioButton("Children");
        objectClassButton = new JRadioButton("ObjectClass");
        objectClassExclusionButton = new JRadioButton("ObjectClass Exclusion");

        ButtonGroup group = new ButtonGroup();
        group.add(attributeButton);
        group.add(entryButton);
        group.add(childrenButton);
        group.add(objectClassButton);
        group.add(objectClassExclusionButton);

        attributeValueField = new JTextField();
        okButton = new JButton("OK");
        okButton.setEnabled(false);

        add(attributeButton);
        add(entryButton);
        add(childrenButton);
        add(objectClassButton);
        add(objectClassExclusionButton);
        add(attributeValueField);
        add(okButton);

        pack();
        setLocationRelativeTo(null);
    }

    private void populateFields() {
        if (aclAttributeWrapper != null) {
            // Assuming AclAttributeWrapper has a method to get the type and value
            String type = aclAttributeWrapper.getType();
            String value = aclAttributeWrapper.getValue();
            attributeValueField.setText(value);
            switch (type) {
                case "Attribute":
                    attributeButton.setSelected(true);
                    break;
                case "Entry":
                    entryButton.setSelected(true);
                    break;
                case "Children":
                    childrenButton.setSelected(true);
                    break;
                case "ObjectClass":
                    objectClassButton.setSelected(true);
                    break;
                case "ObjectClass Exclusion":
                    objectClassExclusionButton.setSelected(true);
                    break;
            }
        }
    }

    private void addListeners() {
        ActionListener radioButtonListener = e -> updateAttributeValueFieldState();
        attributeButton.addActionListener(radioButtonListener);
        entryButton.addActionListener(radioButtonListener);
        childrenButton.addActionListener(radioButtonListener);
        objectClassButton.addActionListener(radioButtonListener);
        objectClassExclusionButton.addActionListener(radioButtonListener);

        attributeValueField.addKeyListener(new java.awt.event.KeyAdapter() {
            public void keyReleased(java.awt.event.KeyEvent evt) {
                validateInput();
            }
        });

        okButton.addActionListener(e -> saveAclAttribute());
    }

    private void updateAttributeValueFieldState() {
        boolean isEnabled = attributeButton.isSelected() || entryButton.isSelected();
        attributeValueField.setEnabled(isEnabled);
        if (!isEnabled) {
            attributeValueField.setText("");
        }
        validateInput();
    }

    private void validateInput() {
        boolean isValid = !attributeValueField.getText().trim().isEmpty();
        okButton.setEnabled(isValid);
    }

    private void saveAclAttribute() {
        // Assuming AclAttributeWrapper has a method to set the type and value
        String type = getSelectedType();
        String value = attributeValueField.getText().trim();
        aclAttributeWrapper.setType(type);
        aclAttributeWrapper.setValue(value);
        dispose();
    }

    private String getSelectedType() {
        if (attributeButton.isSelected()) return "Attribute";
        if (entryButton.isSelected()) return "Entry";
        if (childrenButton.isSelected()) return "Children";
        if (objectClassButton.isSelected()) return "ObjectClass";
        if (objectClassExclusionButton.isSelected()) return "ObjectClass Exclusion";
        return null;
    }
}

