public abstract class QueryAssemblerHelper {

    protected QueryAssembler queryAssembler;

    public QueryAssemblerHelper(QueryAssembler queryAssembler) {
        this.queryAssembler = queryAssembler;
    }

    public void appendSelect(String... columns) {
        for (String column : columns) {
            queryAssembler.addSelectColumn(quoteIdentifier(column));
        }
    }

    public void appendFrom(String table) {
        queryAssembler.setFrom(quoteIdentifier(table));
    }

    public void appendWhere(String condition) {
        queryAssembler.addWhereCondition(condition);
    }

    public void appendJoin(String joinType, String table, String onCondition) {
        queryAssembler.addJoin(joinType, quoteIdentifier(table), onCondition);
    }

    public void appendOrderBy(String... columns) {
        for (String column : columns) {
            queryAssembler.addOrderBy(quoteIdentifier(column));
        }
    }

    public void appendLiteral(String literal) {
        queryAssembler.addLiteral(literal);
    }

    public void appendLikeCondition(String column, String value) {
        String escapedValue = escapeLike(value);
        queryAssembler.addWhereCondition(quoteIdentifier(column) + " LIKE '" + escapedValue + "'");
    }

    protected String quoteIdentifier(String identifier) {
        return "\"" + identifier.replace("\"", "\"\"") + "\"";
    }

    protected String escapeLike(String value) {
        return value.replace("%", "\\%").replace("_", "\\_");
    }

    public void processRelationship(String relationshipType, String relatedEntity) {
        switch (relationshipType) {
            case "oneToOne":
                handleOneToOne(relatedEntity);
                break;
            case "oneToMany":
                handleOneToMany(relatedEntity);
                break;
            case "manyToOne":
                handleManyToOne(relatedEntity);
                break;
            case "manyToMany":
                handleManyToMany(relatedEntity);
                break;
            default:
                throw new IllegalArgumentException("Unknown relationship type: " + relationshipType);
        }
    }

    protected abstract void handleOneToOne(String relatedEntity);
    protected abstract void handleOneToMany(String relatedEntity);
    protected abstract void handleManyToOne(String relatedEntity);
    protected abstract void handleManyToMany(String relatedEntity);
}

