public class UnixPermissions {
    private boolean ownerRead;
    private boolean ownerWrite;
    private boolean ownerExecute;
    private boolean groupRead;
    private boolean groupWrite;
    private boolean groupExecute;
    private boolean othersRead;
    private boolean othersWrite;
    private boolean othersExecute;

    public UnixPermissions(String permissionString) {
        parsePermissions(permissionString);
    }

    private void parsePermissions(String permissionString) {
        if (permissionString.matches("^[0-7]{3}$")) {
            parseOctal(permissionString);
        } else if (permissionString.matches("^[rwx-]{9}$")) {
            parseSymbolic(permissionString);
        } else {
            throw new IllegalArgumentException("Invalid permission string");
        }
    }

    private void parseOctal(String permissionString) {
        int octal = Integer.parseInt(permissionString, 8);
        ownerRead = (octal & 0b100000) != 0;
        ownerWrite = (octal & 0b10000) != 0;
        ownerExecute = (octal & 0b1000) != 0;
        groupRead = (octal & 0b100) != 0;
        groupWrite = (octal & 0b10) != 0;
        groupExecute = (octal & 0b1) != 0;
        othersRead = (octal & 0b10000000) != 0;
        othersWrite = (octal & 0b1000000) != 0;
        othersExecute = (octal & 0b100000) != 0;
    }

    private void parseSymbolic(String permissionString) {
        ownerRead = permissionString.charAt(0) == 'r';
        ownerWrite = permissionString.charAt(1) == 'w';
        ownerExecute = permissionString.charAt(2) == 'x';
        groupRead = permissionString.charAt(3) == 'r';
        groupWrite = permissionString.charAt(4) == 'w';
        groupExecute = permissionString.charAt(5) == 'x';
        othersRead = permissionString.charAt(6) == 'r';
        othersWrite = permissionString.charAt(7) == 'w';
        othersExecute = permissionString.charAt(8) == 'x';
    }

    public String toOctal() {
        return String.format("%o", 
            (ownerRead ? 4 : 0) + (ownerWrite ? 2 : 0) + (ownerExecute ? 1 : 0) << 6 |
            (groupRead ? 4 : 0) + (groupWrite ? 2 : 0) + (groupExecute ? 1 : 0) << 3 |
            (othersRead ? 4 : 0) + (othersWrite ? 2 : 0) + (othersExecute ? 1 : 0));
    }

    public String toSymbolic() {
        return (ownerRead ? "r" : "-") + (ownerWrite ? "w" : "-") + (ownerExecute ? "x" : "-") +
               (groupRead ? "r" : "-") + (groupWrite ? "w" : "-") + (groupExecute ? "x" : "-") +
               (othersRead ? "r" : "-") + (othersWrite ? "w" : "-") + (othersExecute ? "x" : "-");
    }

    // Getters and Setters
    public boolean isOwnerRead() { return ownerRead; }
    public void setOwnerRead(boolean ownerRead) { this.ownerRead = ownerRead; }

    public boolean isOwnerWrite() { return ownerWrite; }
    public void setOwnerWrite(boolean ownerWrite) { this.ownerWrite = ownerWrite; }

    public boolean isOwnerExecute() { return ownerExecute; }
    public void setOwnerExecute(boolean ownerExecute) { this.ownerExecute = ownerExecute; }

    public boolean isGroupRead() { return groupRead; }
    public void setGroupRead(boolean groupRead) { this.groupRead = groupRead; }

    public boolean isGroupWrite() { return groupWrite; }
    public void setGroupWrite(boolean groupWrite) { this.groupWrite = groupWrite; }

    public boolean isGroupExecute() { return groupExecute; }
    public void setGroupExecute(boolean groupExecute) { this.groupExecute = groupExecute; }

    public boolean isOthersRead() { return othersRead; }
    public void setOthersRead(boolean othersRead) { this.othersRead = othersRead; }

    public boolean isOthersWrite() { return othersWrite; }
    public void setOthersWrite(boolean othersWrite) { this.othersWrite = othersWrite; }

    public boolean isOthersExecute() { return othersExecute; }
    public void setOthersExecute(boolean othersExecute) { this.othersExecute = othersExecute; }
}

