public abstract class ServerContext implements EventContext {
    protected DirContext dirContext;
    protected Hashtable<String, String> environment;
    protected List<NamingListener> listeners;

    public ServerContext(Hashtable<String, String> env) {
        this.environment = env;
        this.listeners = new ArrayList<>();
        initializeContext();
    }

    private void initializeContext() {
        try {
            dirContext = new InitialDirContext(environment);
        } catch (NamingException e) {
            e.printStackTrace();
        }
    }

    public void addEntry(String name, Attributes attrs) throws NamingException {
        dirContext.createSubcontext(name, attrs);
    }

    public void deleteEntry(String name) throws NamingException {
        dirContext.destroySubcontext(name);
    }

    public void modifyEntry(String name, ModificationItem[] mods) throws NamingException {
        dirContext.modifyAttributes(name, mods);
    }

    public NamingEnumeration<SearchResult> searchEntries(String name, String filter, SearchControls controls) throws NamingException {
        return dirContext.search(name, filter, controls);
    }

    public void bind(String name, Object obj, Attributes attrs) throws NamingException {
        dirContext.bind(name, obj, attrs);
    }

    public Object lookup(String name) throws NamingException {
        return dirContext.lookup(name);
    }

    public void registerListener(NamingListener listener) {
        listeners.add(listener);
    }

    public void unregisterListener(NamingListener listener) {
        listeners.remove(listener);
    }

    public void notifyListeners() {
        for (NamingListener listener : listeners) {
            // Notify logic here (omitted for brevity)
        }
    }

    public void close() {
        try {
            if (dirContext != null) {
                dirContext.close();
            }
        } catch (NamingException e) {
            e.printStackTrace();
        }
    }

    // Abstract methods from EventContext interface to be implemented by subclasses
    public abstract void someAbstractMethod();
}

class RangeFilterProcessorTest {

    private FilterOptimizer filterOptimizer;

    @Before
    public void setUp() {
        filterOptimizer = new FilterOptimizer();
    }

    @After
    public void tearDown() {
        filterOptimizer = null;
    }

    @Test
    public void testOptimizeSingleCondition() {
        FilterExpression expression = new FilterExpression("field1", Operator.GREATER_THAN, 10);
        FilterExpression optimized = filterOptimizer.optimize(expression);
        assertEquals("Expected optimized expression", optimized, new FilterExpression("field1", Operator.GREATER_THAN, 10));
    }

    @Test
    public void testOptimizeMultipleConditions() {
        FilterExpression expression = new FilterExpression("field1", Operator.GREATER_THAN, 10)
                .and(new FilterExpression("field1", Operator.LESS_THAN, 20));
        FilterExpression optimized = filterOptimizer.optimize(expression);
        assertEquals("Expected optimized expression", optimized, new FilterExpression("field1", Operator.BETWEEN, 10, 20));
    }

    @Test
    public void testScanRequired() {
        Block block = new Block(5, 15);
        boolean scanRequired = filterOptimizer.isScanRequired(block, 10, 20);
        assertTrue("Scan should be required", scanRequired);
    }

    @Test
    public void testNoScanRequired() {
        Block block = new Block(10, 15);
        boolean scanRequired = filterOptimizer.isScanRequired(block, 5, 10);
        assertFalse("Scan should not be required", scanRequired);
    }

    @Test
    public void testOptimizeWithNullExpression() {
        FilterExpression optimized = filterOptimizer.optimize(null);
        assertNull("Optimized expression should be null", optimized);
    }
}

class PubsubUnboundedSourceTest {
    private PubsubUnboundedSource source;
    private PubsubClient mockClient;
    private SubscriptionManager mockSubscriptionManager;

    @Before
    public void setUp() {
        mockClient = mock(PubsubClient.class);
        mockSubscriptionManager = mock(SubscriptionManager.class);
        source = new PubsubUnboundedSource(mockClient, mockSubscriptionManager);
    }

    @After
    public void tearDown() {
        source.close();
    }

    @Test
    public void testReadMessages() {
        when(mockClient.pullMessages(anyString())).thenReturn(Collections.singletonList("message1"));

        List<String> messages = source.readMessages("test-subscription");

        assertEquals(1, messages.size());
        assertEquals("message1", messages.get(0));
    }

    @Test
    public void testAcknowledgeMessage() {
        String messageId = "msg1";
        source.acknowledgeMessage(messageId);
        verify(mockClient).acknowledgeMessage(messageId);
    }

    @Test
    public void testHandleAcknowledgmentTimeout() {
        String messageId = "msg2";
        source.acknowledgeMessage(messageId);
        source.handleAcknowledgmentTimeout(messageId);
        verify(mockClient, times(1)).acknowledgeMessage(messageId);
    }

    @Test
    public void testCheckpointManagement() {
        source.startCheckpoint("checkpoint1");
        source.finalizeCheckpoint("checkpoint1");

        assertTrue(source.isCheckpointFinalized("checkpoint1"));
    }

    @Test
    public void testMultipleReaders() {
        when(mockClient.pullMessages(anyString())).thenReturn(Collections.singletonList("message1"), Collections.singletonList("message2"));

        List<String> messagesReader1 = source.readMessages("test-subscription");
        List<String> messagesReader2 = source.readMessages("test-subscription");

        assertEquals(1, messagesReader1.size());
        assertEquals("message1", messagesReader1.get(0));
        assertEquals(1, messagesReader2.size());
        assertEquals("message2", messagesReader2.get(0));
    }

    @Test
    public void testGenerateSubscriptionsWhenNoneProvided() {
        List<String> subscriptions = source.generateSubscriptions();

        assertFalse(subscriptions.isEmpty());
        assertTrue(subscriptions.contains("default-subscription"));
    }

    @Test
    public void testFinalizeActiveCheckpointsOnClose() {
        source.startCheckpoint("checkpoint2");
        source.close();

        assertTrue(source.isCheckpointFinalized("checkpoint2"));
    }
}
